insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','ACT',1,1,null,$b$Hơi Y-Thêôphil ơi, tâm ndrom sămƀŭt tal nguay, gâp ngơi jêh ma lĕ rngôch nau Brah Yêsu ntơm ƀư jêh ri nti ntơm sa ơm,$b$,true),
('bunong-vn','ACT',1,2,null,$b$tât ta nar Brah Ndu chông Păng hao klơ, jêh Păng ntăm ma Brah Huêng Ueh ma phung kôranh oh mon Păng săch jêh.$b$,false),
('bunong-vn','ACT',1,3,null,$b$Jêh Păng dơn nau nđêh nji, Păng tâm mpơl Păng nơm dâk rêh ma khân păng âk nau tâm mbên. Tâm puăn jât nar Păng ăn bu saơ Păng jêh ri Păng ngơi ma phung nây ma ƀon bri hađăch Brah Ndu.$b$,false),
('bunong-vn','ACT',1,4,null,$b$Dôl Păng gŭ ndrel ma phung nây, Păng ntăm ma phung nây, lơi luh du tă bơh ƀon Yêrusalem, ƀiă lah gŭ kâp ta nây, ăn tât nau Mbơ̆ hŏ ton jêh. Păng lah: “Nau nây gâp nkoch jêh ma khân may.$b$,true),
('bunong-vn','ACT',1,5,null,$b$Yor lah Y-Yôhan ƀư jêh ƀaptem ma dak, ƀiă lah ăt hôm djê̆ khân may mra dơn ƀaptem ma Brah Huêng Ueh.”$b$,false),
('bunong-vn','ACT',1,6,null,$b$Rnôk nây lĕ rngôch phung tâm rƀŭn ta nây ôp Păng pô aơ: “Ơ Kôranh Brah, di lĕ rnôk aơ may mra njêng tay ƀon bri hađăch Israel?”$b$,false),
('bunong-vn','ACT',1,7,null,$b$Brah Yêsu plơ̆ lah ma khân păng: “Ma rnôk mâu lah nar mông Mbơ̆ nơm tâm nal jêh tĭng nâm Păng ŭch, mâu di nau khân may ŭch gĭt ôh.$b$,false),
('bunong-vn','ACT',1,8,null,$b$Ƀiă lah tơ lah Brah Huêng Ueh jŭr ta khân may, khân may mra sŏk dơn nau brah; jêh ri khân may mra jêng phung mbơh gâp tâm ƀon Yêrusalem, tâm n'gor Yuđa, tâm n'gor Samari, jêh ri lam bri neh.”$b$,false),
('bunong-vn','ACT',1,9,null,$b$Jêh Păng ngơi nau nây, Brah Ndu chông Păng ta klơ, dôl phung oh mon gŭ uănh jêh ri geh ndâr tŭk nkŭm jŭm Păng, jêh ri bu mâu hôm saơ Păng ôh.$b$,false),
('bunong-vn','ACT',1,10,null,$b$Dôl khân păng gŭ uănh mâu mƀrêh măt, ma Brah Yêsu leo hao ta klơ trôk, aơ, geh bar hê bunuyh soh ao nglang tâm mpơl ta năp khân păng,$b$,false),
('bunong-vn','ACT',1,11,null,$b$jêh ri lah ma khân păng: “Hơi phung bunuyh n'gor Galilê, Mâm ƀư khân may n'gơr uănh ta klơ trôk ri? Brah Yêsu aơ, Brah Ndu chông hao ta klơ trôk jêh, tă bơh phung khân may, Păng mra plơ̆ văch tâm ban ma khân may saơ Păng hao ta klơ trôk nây lĕ.”$b$,false),
('bunong-vn','ACT',1,12,null,$b$Dôl nây khân păng sĭt ta ƀon Yêrusalem bơh yôk bu rnha yôk Ôlivơ. Yôk nây dăch ta ƀon Yêrusalem du kilômet n'gul, hăn trong tâm nar Saƀat.$b$,true),
('bunong-vn','ACT',1,13,null,$b$Lah khân păng tât ta ƀon, khân păng hao tâm jrô klơ ta ntŭk phung Y-Pêtrôs, Y-Yôhan, Y-Yakơ, Y-Andrê, Y-Philip, Y-Thômas, Y-Ƀartêlômi, Y-Mathiơ, Y-Yakơ kon Y-Alphê, Y-Simôn, nơm jêng hŭch rhŭl, jêh ri Y-Yut kon Y-Yakơ vay gŭ.$b$,false),
('bunong-vn','ACT',1,14,null,$b$Lĕ rngôch phung nây nsrôih du ai nau gŭ mbơh sơm ndrel ma phung bu ur, ndrel ma H'Mari mê̆ Brah Yêsu, jêh ri ndrel ma phung oh Păng.$b$,true),
('bunong-vn','ACT',1,15,null,$b$Dôl nây Y-Pêtrôs dâk ta nklang phung oh nâu gŭ rƀŭn ta nây, geh klăp lah tâm du rhiăng bar jât nuyh, jêh ri păng lah pô aơ:$b$,true),
('bunong-vn','ACT',1,16,null,$b$“Hơi phung oh nâu, geh nau khlay ƀư nanê̆ nau nchih, nâm bu ntĭt nau Brah Huêng Ueh mbơh lor jêh ma bâr mbung Y-Đavit ma nau Y-Yuđas, nơm leo trong ma bu nhŭp Brah Yêsu, tât ngăn jêh.$b$,false),
('bunong-vn','ACT',1,17,null,$b$Yor lah păng jêng du huê tâm phung he jêh ri păng pah du ntil kan ndrel ma he.$b$,false),
('bunong-vn','ACT',1,18,null,$b$(Păng nây, ma prăk nkhôm nau tih, păng rvăt geh du lôk mir lŏ, jêh ri păng tŭp nkŭp, ndŭl păng prek ta nklang jêh ri lĕ rngôch proch klơm păng luh pa dih.$b$,false),
('bunong-vn','ACT',1,19,null,$b$Nau nây lĕ rngôch bunuyh ƀon Yêrusalem tăng lư, tât bu rnha mir lŏ nây, tâm nau khân păng nơm lah Hakêlđama, nâm bu ntĭt, mir lŏ mham).$b$,false),
('bunong-vn','ACT',1,20,null,$b$Pô ri bu nchih jêh tâm ndrom sămƀŭt Nau mprơ ơm: Ăn ngih păng mra jêng rngol, mâu geh bunuyh gŭ ôh; jêh ri nchih: Ăn du huê êng rdơn kan păng!$b$,true),
('bunong-vn','ACT',1,21,null,$b$Pô ri yơh, tâm phung tĭng hăn ndrel ma he, dôl lĕ nar Brah Yêsu gŭ rêh jêh ndrel ma he,$b$,true),
('bunong-vn','ACT',1,22,null,$b$ntơm bơh nar Y-Yôhan ƀư ƀaptem ma Păng tât ta nar Brah Ndu chông Păng leo klơ tă bơh he, ăn geh du huê jêng nơm mbơh ndrel ma he ma nau Brah Yêsu dâk rêh đŏng.”$b$,false),
('bunong-vn','ACT',1,23,null,$b$Khân păng tâm mpơl bar hê, Y-Yôsep rnha Y-Barsabas, ăt tâm amoh Y-Yustus, jêh ri Y-Mathias.$b$,true),
('bunong-vn','ACT',1,24,null,$b$Jêh ri khân păng mbơh sơm pô aơ: “Ơ Kôranh Brah, may gĭt jêh nuih n'hâm lĕ rngôch bunuyh, ntĭm ma hên tâm bar hê aơ, mbu nơm may hŏ săch jêh,$b$,false),
('bunong-vn','ACT',1,25,null,$b$gay ma păng pah kan jêng kôranh oh mon ntrok ntŭk Y-Yuđas Iskariôt cha lơi jêh, ŭch hăn ta ntŭk ơm păng.”$b$,false),
('bunong-vn','ACT',1,26,null,$b$Jêh ri khân păng nchroh, nau nchroh di ma Y-Mathias jêh ri bu ăn păng ntop tâm phung jât ma nguay nuyh kôranh oh mon.$b$,false),
('bunong-vn','ACT',2,1,null,$b$Nar Pantơkôt lĕ rngôch khân păng tâm rƀŭn du ntŭk.$b$,true),
('bunong-vn','ACT',2,2,null,$b$Ƀât lât, geh nteh tă bơh trôk tâm ban ma nteh n'gôr sial ktang, bêng ngih ntŭk khân păng gŭ tâm rƀŭn.$b$,false),
('bunong-vn','ACT',2,3,null,$b$Dôl nây khân păng saơ geh mpiăt ŭnh, gŭ ta klơ ăp nơm khân păng.$b$,true),
('bunong-vn','ACT',2,4,null,$b$Lĕ rngôch khân păng bêng ma Brah Huêng Ueh, jêh ri ngơi nau bu năch êng tĭng nâm Brah Huêng Ueh ăn ma khân păng ngơi.$b$,false),
('bunong-vn','ACT',2,5,null,$b$Rnôk nây geh phung Yuđa, phung sŏng srăng, văch ma lĕ rngôch mpôl băl tâm dâng trôk, gŭ tâm ƀon Yêrusalem.$b$,true),
('bunong-vn','ACT',2,6,null,$b$Tơ lah tăng nteh nây, phung âk nchuăt ran jêh ri khân păng hih rhâl da dê, yor lah ăp nơm khân păng tăng phung nây ngơi nau khân păng nơm.$b$,false),
('bunong-vn','ACT',2,7,null,$b$Khân păng ndrŏt tâm nuih n'hâm, khân păng lah: “Lĕ rngôch phung ngơi nây, di lĕ khân păng jêng phung Galilê?$b$,false),
('bunong-vn','ACT',2,8,null,$b$Mâm ƀư ăp nơm phung he tăng khân păng ngơi, nau ngơi n'gor he nơm lĕ?$b$,false),
('bunong-vn','ACT',2,9,null,$b$Phung Parthê, phung Mêđơ, phung Êlamit, phung gŭ tâm n'gor Mêsôpôtami, n'gor Yuđa, n'gor Kapadôs, n'gor Pôns, n'gor Asi,$b$,true),
('bunong-vn','ACT',2,10,null,$b$n'gor Phriji, n'gor Pamphili, n'gor Êjipt, n'gor Libi dăch n'gor Siren, jêh ri phung văch tă bơh ƀon Rôm, nđâp ma phung Yuđa, nđâp ma phung lăp Yuđa,$b$,false),
('bunong-vn','ACT',2,11,null,$b$phung Kret, phung Arap, mâm ƀư he iăt khân păng ngơi nau khlay bơh Brah Ndu ma nau ngơi n'gor he nơm.”$b$,false),
('bunong-vn','ACT',2,12,null,$b$Lĕ rngôch khân păng hih rhâl ngăn jêh ri mâu hôm blau mĭn ôh. Khân păng tâm lah ndrăng nơm pô aơ: “Moh nau nây?”$b$,false),
('bunong-vn','ACT',2,13,null,$b$Ƀiă lah ƀa ƀă mưch jêh ri lah: “Khân păng nhŭl ndrănh.”$b$,false),
('bunong-vn','ACT',2,14,null,$b$Rnôk nây Y-Pêtrôs dâk hăn ndrel ma phung jât ma nguay nuyh kôranh oh mon. Păng ngơi huy ma phung âk pô aơ: “Hơi phung Yuđa jêh ri lĕ rngôch bunuyh gŭ ta ƀon Yêrusalem, ăn khân may gĭt nau aơ, jêh ri rkêng tôr iăt nau gâp ngơi.$b$,true),
('bunong-vn','ACT',2,15,null,$b$Phung aơ mâu geh nhŭl ndrănh ôh, nâm bu khân may mĭn, yor lah aƀaơ geh knŏng pe mông ôi djay,$b$,false),
('bunong-vn','ACT',2,16,null,$b$ƀiă lah nau aơ tât di ma nau kôranh nơm mbơh lor Y-Yôel mbơh jêh pô aơ:$b$,false),
('bunong-vn','ACT',2,17,null,$b$‘Brah Ndu lah: Tâm rnôk kêng lôch kăndơ̆ , gâp mra nkhŭt Brah Huêng Ueh gâp ma lĕ rngôch bunuyh, phung kon bu ur, bu klâu khân may mra mbơh lor, phung bu klâu ndăm khân may, mra geh nau tâm saơ. Jêh ri phung bu ranh bu klâu mra geh nau mbơi.$b$,false),
('bunong-vn','ACT',2,18,null,$b$N'hêl nanê̆, tâm nar nây, gâp mra nkhŭt Brah Huêng Ueh gâp ta phung oh mon bu ur bu klâu gâp, jêh ri khân păng mra mbơh lor.$b$,true),
('bunong-vn','ACT',2,19,null,$b$Gâp mra tâm mpơl nau khlay tâm trôk klơ jêh ri nau tâm mbên khlay ta neh ntu tâm dâng, n'hâm ŭnh, jêh ri n'hâm nhhŭk ŭnh.$b$,true),
('bunong-vn','ACT',2,20,null,$b$Nar mra rgâl jêng ngo jêh ri khay mra jêng mham lor ma tât nar toyh jêh ri nar chrêk rmah Kôranh Brah.$b$,true),
('bunong-vn','ACT',2,21,null,$b$Pô ri mbu nơm mra kuăl amoh Kôranh Brah mra klaih.’$b$,true),
('bunong-vn','ACT',2,22,null,$b$“Hơi phung Israel, kâp iăt nau ngơi aơ: Brah Yêsu, ƀon Nasaret, Nơm Brah Ndu dơn jêh ta năp khân may ma kan nau brah, ma nau khlay, jêh ri nau tâm mbên khlay, khân may gĭt jêh, Brah Ndu dŏng păng ƀư nau nây ta nklang khân may,$b$,false),
('bunong-vn','ACT',2,23,null,$b$bunuyh nây khân may pâng ta si tâm rkăng, jêh ri tă bơh ti phung tih nkhĭt Păng, Brah Ndu jao jêh tĭng nâm nau săch jêh ri gĭt lor.$b$,false),
('bunong-vn','ACT',2,24,null,$b$Ƀiă lah Brah Ndu ăn Păng dâk rêh đŏng, doh Păng tă bơh rse rvăk nau khĭt, yor lah nau khĭt mâu dơi nkân Păng ôh.$b$,true),
('bunong-vn','ACT',2,25,null,$b$Yor lah Y-Đavit lah jêh ma Păng pô aơ: ‘Gâp saơ Kôranh Brah ta năp gâp mro, yor lah Păng gŭ mpeh pa ma gâp gay ma lơi ăn gâp mpât n'gơ ôh.$b$,false),
('bunong-vn','ACT',2,26,null,$b$Yor ri nuih n'hâm gâp maak, jêh ri mpiăt gâp ngluh nau răm maak; nglay săk gâp tâm ban lĕ, mra rlu tâm nau kâp gân.$b$,true),
('bunong-vn','ACT',2,27,null,$b$Yor lah may mâu mra cha lơi huêng gâp tâm ƀon phung khĭt, jêh ri may mâu ăn ôh ma Nơm kloh ueh may saơ nau ôm rai.$b$,true),
('bunong-vn','ACT',2,28,null,$b$May ăn gâp gĭt jêh trong nau rêh, may mra mbêng gâp ma nau răm maak dôl saơ muh măt may.’$b$,true),
('bunong-vn','ACT',2,29,null,$b$“Hơi phung oh nâu, gâp dơi ngơi nơih ma khân may phung bu bŭnh bu ranh, Y-Đavit. Păng khĭt jêh, bu tâp păng jêh, jêh ri môch păng hôm tât aƀaơ ta nklang phung he.$b$,false),
('bunong-vn','ACT',2,30,null,$b$Yor lah păng jêng kôranh nơm mbơh lor jêh ri gĭt jêh ma Brah Ndu ton jêh ma păng ma nau sân săk, gay ăn du huê tâm phung kon sau păng mra gŭ ta sưng hađăch păng,$b$,false),
('bunong-vn','ACT',2,31,null,$b$păng saơ jêh ri mbơh lor ma nau Brah Krist dâk rêh. Bu mâu lơi Păng tâm ƀon phung khĭt ôh, jêh ri săk jăn Păng mâu blau ôm rai ôh.$b$,false),
('bunong-vn','ACT',2,32,null,$b$Brah Yêsu aơ, Brah Ndu ăn tay Păng dâk rêh jêh, jêh ri lĕ rngôch phung hên jêng nơm mbơh Păng.$b$,false),
('bunong-vn','ACT',2,33,null,$b$Pô ri, jêh geh nau yơk mpeh pa ma Brah Ndu, jêh ri sŏk dơn Brah Huêng Ueh Mbơ̆ ton jêh, Păng nkhŭt ăn Brah Huêng Ueh tâm ban ma khân may saơ jêh ri tăng aƀaơ.$b$,false),
('bunong-vn','ACT',2,34,null,$b$Yor lah Y-Đavit ê mâp hao ta klơ trôk ôh; ƀiă lah Păng nơm lah lĕ: ‘Kôranh Brah lah jêh ma Kôranh Brah gâp: Gŭ hom may pa ma gâp,$b$,false),
('bunong-vn','ACT',2,35,null,$b$Tât gâp ăn phung rlăng đah may jêng rnơl chrong jâng.’$b$,false),
('bunong-vn','ACT',2,36,null,$b$Ăn lĕ rngôch phung Israel gĭt nanê̆ ma Brah Ndu, ăn Brah Yêsu Nơm khân may pâng jêh ta si tâm rkăng, jêng Kôranh Brah jêh ri Brah Krist.”$b$,false),
('bunong-vn','ACT',2,37,null,$b$Jêh tăng nau ngơi nây, khân păng nâm bu ntrŭt ntrôl tâm nuih n'hâm. Pô ri khân păng ôp Y-Pêtrôs jêh ri phung kôranh oh mon êng: “Hơi phung oh nâu, moh nau hên mra ƀư?”$b$,true),
('bunong-vn','ACT',2,38,null,$b$Y-Pêtrôs lah ma khân păng: “Rmal hom nau tih khân may, jêh ri ăn ăp nơm khân may dơn nau ƀaptem tâm amoh Brah Yêsu Krist gay geh nau yô̆ an nau tih khân may, jêh ri khân may mra sŏk dơn ndơ Brah Huêng Ueh ăn.$b$,false),
('bunong-vn','ACT',2,39,null,$b$Yor lah nau ton prăp ma khân may, ma phung kon sau khân may, jêh ri ma lĕ rngôch mbu nơm gŭ ngai, ndah âk bunuyh Kôranh Brah, Brah Ndu he mra kuăl.”$b$,false),
('bunong-vn','ACT',2,40,null,$b$Jêh ri âk nau ngơi êng, Y-Pêtrôs sâm n'hao nuih jêh ri nti lah ma khân păng pô aơ: “Du hom khân may tă bơh phung mpôl băl tih mhĭk aơ.”$b$,false),
('bunong-vn','ACT',2,41,null,$b$Pô ri phung dơn nau nti nây, dơn nau ƀư ƀaptem, jêh ri tâm nar nây phung chroh ntop geh tâm pe rbăn nuyh.$b$,false),
('bunong-vn','ACT',2,42,null,$b$Jêh ri khân păng srôih djôt prăp nau phung kôranh oh mon nti, tâm nau tâm rnglăp ndrăng oh nâu, tâm nau nkêch kapŭng jêh ri tâm nau mbơh sơm.$b$,true),
('bunong-vn','ACT',2,43,null,$b$Lĕ rngôch bunuyh geh nau klach; jêh ri geh âk nau khlay jêh ri nau mbên khlay phung kôranh oh mon ƀư.$b$,false),
('bunong-vn','ACT',2,44,null,$b$Lĕ rngôch mbu nơm chroh gŭ ndrel, jêh ri geh ăp ntil mpa ndrel da dê lĕ.$b$,false),
('bunong-vn','ACT',2,45,null,$b$Khân păng tăch mir, ngih jêh ri drăp ndơ khân păng, tâm pă ndrăng khân păng ăp nơm, tĭng nâm nau pưt ndơ.$b$,false),
('bunong-vn','ACT',2,46,null,$b$Ăp nar, tâm ban lĕ khân păng gơih tâm rƀŭn tâm ngih brah Yuđa, jêh ri tâm ngih vâl khân păng nơm khân păng nkêch kapŭng jêh ri sông sa ndrel ma nau răm jêh ri ma nuih n'hâm lŏng.$b$,false),
('bunong-vn','ACT',2,47,null,$b$Khân păng tâm rnê ma Brah Ndu jêh ri ƀư maak ma lĕ rngôch bunuyh. Jêh ri ăp nar Kôranh Brah ntop ma phung ngih Brah Ndu phung klaih jêh.$b$,false),
('bunong-vn','ACT',3,1,null,$b$Y-Pêtrôs jêh ri Y-Yôhan hăn ta ngih brah Yuđa ta mông mbơh sơm, sĭn mông ôi.$b$,true),
('bunong-vn','ACT',3,2,null,$b$Dôl nây geh du huê bunuyh rvĕn ntơm bơh mê̆ deh. Ăp nar bu chông păng ăn gŭ ta mpông ngih brah Yuđa. Mpông nây bu rnha Mpông ueh. Păng ŭch dăn ma lĕ rngôch bunuyh mbu nơm lăp tâm ngih brah Yuđa, geh ăn ndơ yô̆.$b$,false),
('bunong-vn','ACT',3,3,null,$b$Saơ Y-Pêtrôs, ndrel Y-Yôhan hăn lăp tâm ngih brah Yuđa, păng dăn ma phung ăn ndơ yô̆.$b$,false),
('bunong-vn','ACT',3,4,null,$b$Y-Pêtrôs ndrel ma Y-Yôhan uănh ta păng jêh ri lah: “Uănh ta hên.”$b$,false),
('bunong-vn','ACT',3,5,null,$b$Bunuyh rvĕn nây uănh ro ta khân păng, păng ntôn lah geh ndơ bu ăn.$b$,false),
('bunong-vn','ACT',3,6,null,$b$Ƀiă lah Y-Pêtrôs lah ma păng: “Gâp mâu geh prăk mah ôh, ƀiă lah ndơ gâp geh gâp ăn ma may; ma amoh Brah Yêsu, ƀon Nasaret, dâk hăn hom.”$b$,false),
('bunong-vn','ACT',3,7,null,$b$Jêh nây păng kuăn ta ti nơm rvĕn, păng chông ăn păng dâk, ƀât lât mpang jêh ri rpăk jâng păng jêng nâp.$b$,false),
('bunong-vn','ACT',3,8,null,$b$Păng nsăt du tơ̆ , dâk jêh ri hăn. Khân păng lăp ndrel tâm ngih brah Yuđa dôl hăn, nsăt jêh ri tâm rnê ma Brah Ndu.$b$,false),
('bunong-vn','ACT',3,9,null,$b$Lĕ rngôch bunuyh saơ păng hăn, jêh ri tâm rnê ma Brah Ndu.$b$,true),
('bunong-vn','ACT',3,10,null,$b$Bu gĭt năl ma nơm nây vay gŭ mro ta mpông ueh ngih brah Yuđa dăn ndơ bu ăn yô̆. Pô ri bu bêng ma nau hih rhâl jêh ri mâu hôm blau mĭn ma nau tât jêh ma păng.$b$,false),
('bunong-vn','ACT',3,11,null,$b$Dôl bunuyh nây hôm kuăn ta ti Y-Pêtrôs, Y-Yôhan, lĕ rngôch bunuyh hih rhâl nchuăt ran ta khân păng ta ndring bu rnha ndring Salômôn.$b$,true),
('bunong-vn','ACT',3,12,null,$b$Tơ lah Y-Pêtrôs saơ pô nây, păng lah ma phung ƀon lan pô aơ: “Hơi phung kon Israel, mâm ƀư khân may hih rhâl ma nau tât ma bunuyh aơ? Mâm ƀư khân ay may uănh ta hên, tâm ban ma nau brah hên nơm, mâu lah nau ueh lăng hên nơm, ăn bunuyh aơ blau hăn?$b$,false),
('bunong-vn','ACT',3,13,null,$b$Brah Ndu Y-Abraham, Y-Isăk, jêh ri Y-Yakôp, Brah Ndu phung u che he, ăn nau chrêk rmah ma phung Tông mpăr păng, Brah Yêsu, Nơm khân may ăn, jêh ri dun ta năp Pilat, nơm ŭch mƀơk păng.$b$,false),
('bunong-vn','ACT',3,14,null,$b$Khân may dun jêh nơm kloh sŏng, ƀiă lah khân may dăn mƀơk ma khân may du huê vay nkhĭt bunuyh.$b$,false),
('bunong-vn','ACT',3,15,null,$b$Khân may nkhĭt jêh Kôranh nau rêh, Nơm Brah Ndu hŏ ăn rêh jêh tă bơh phung khĭt. Ma nơm nây yơh hên jêng phung mbơh.$b$,false),
('bunong-vn','ACT',3,16,null,$b$Ma nau chroh tâm amoh Păng, amoh Păng yơh ăn ktang bunuyh aơ, nơm khân may hŏ saơ, jêh ri gĭt năl. Nau chroh tă bơh Păng ăn bunuyh aơ ngăch prăl ta năp lĕ rngôch khân may.$b$,false),
('bunong-vn','ACT',3,17,null,$b$Hơi phung oh nâu gâp, aƀaơ gâp gĭt ma khân may, jêh ri phung kôranh khân may ƀư pô nây ma nau rluk.$b$,false),
('bunong-vn','ACT',3,18,null,$b$Ƀiă lah Brah Ndu ƀư nanê̆ jêh nau Păng mbơh lor ma bâr mbung lĕ rngôch phung kôranh nơm mbơh lor ma Brah Krist dơn nau rêh ni.$b$,false),
('bunong-vn','ACT',3,19,null,$b$Tâm rmal hom nau tih khân may, jêh ri plơ̆ sĭt, gay ma nau tih khân ay may mra lâm lơi, jêh ri rnôk đăp mpăn mra văch tă bơh Kôranh Brah.$b$,false),
('bunong-vn','ACT',3,20,null,$b$Jêh ri Păng mra njuăl Brah Krist, Nơm Păng săch jêh ma khân may, nâm bu ntĭt Brah Yêsu,$b$,false),
('bunong-vn','ACT',3,21,null,$b$Nơm nây mra rom, tât rnôk ăt rdâk lĕ rngôch ndơ, tĭng nâm Nau Brah Ndu Ngơi jêh bơh kăl e ri ma bâr mbung phung kôranh nơm mbơh lor kloh ueh Păng.$b$,false),
('bunong-vn','ACT',3,22,null,$b$Y-Môis lah jêh pô aơ: ‘Kôranh Brah Ndu he mra ngluh bơh phung oh nâu khân may du huê kôranh nơm mbơh lor tâm ban ma gâp. Khân may mra rkêng tôr gŭ iăt lĕ nau păng ngơi ma khân may.$b$,false),
('bunong-vn','ACT',3,23,null,$b$Mbu nơm mâu iăt nau kôranh nơm mbơh lor nây, mra ƀư ngroh lơi tă bơh phung ƀon lan!’$b$,true),
('bunong-vn','ACT',3,24,null,$b$Lĕ rngôch phung kôranh nơm mbơh lor ntơm bơh Y-Samuel jêh ri phung ntrok păng hŏ mbơh jêh lĕ tâm rnôk nây.$b$,false),
('bunong-vn','ACT',3,25,null,$b$Khân may jêng kon sau phung kôranh nơm mbơh lor jêh ri nau tâm rnglăp Brah Ndu ƀư jêh đah phung Mbơ̆ he dôl Păng lah ma Y-Abraham: ‘Lĕ rngôch phung mpôl băl ta neh ntu mra geh nau ueh uĭn tă bơh kon sau may.’$b$,true),
('bunong-vn','ACT',3,26,null,$b$Brah Ndu ngluh lơi Kon Păng, lor lơn njuăl hăn, ăn nau ueh uĭn ma khân may, gay ma ăp nơm tâm phung khân may du der bơh nau tih.”$b$,false),
('bunong-vn','ACT',4,1,null,$b$Dôl Y-Pêtrôs jêh ri Y-Yôhan ngơi đah phung ƀon lan, phung n'gâng kôranh ƀư brah, kôranh ngih brah Yuđa, jêh ri phung Sađusê văch.$b$,true),
('bunong-vn','ACT',4,2,null,$b$Ji nuih ngăn ma nau khân păng nti ma phung ƀon lan jêh ri nkoch mbơh ma amoh Brah Yêsu nau dâk rêh tă bơh khĭt.$b$,false),
('bunong-vn','ACT',4,3,null,$b$Pô ri khân păng nhŭp jêh ri krŭng tâm ndrung tât ôi taơ, yor lah ngo jêh.$b$,false),
('bunong-vn','ACT',4,4,null,$b$Ƀiă lah âk phung iăt nau nti lah nây chroh; jêh ri phung chroh ntop kŏ geh klăp lah prăm rbăn nuyh.$b$,false),
('bunong-vn','ACT',4,5,null,$b$Ơm ôi, ôi taơ phung kôranh, phung bu ranh, jêh ri phung kôranh nchih sămƀŭt tâm rƀŭn ta ƀon Yêrusalem,$b$,true),
('bunong-vn','ACT',4,6,null,$b$ndrel ma Y-Anas, kôranh ƀư brah toyh Y-Kaip, Y-Yôhan, Y-Aleksandrơ jêh ri lĕ rngôch phung mpôl băl phung kôranh ƀư brah toyh.$b$,false),
('bunong-vn','ACT',4,7,null,$b$Khân păng nhŭp Y-Pêtrôs ndrel ma Y-Yôhan ta năp khân păng jêh ri ôp pô aơ: “Ma moh nau dơi mâu lah ma mbu amoh khân may ƀư nau nây?”$b$,false),
('bunong-vn','ACT',4,8,null,$b$Jêh ri Y-Pêtrôs, bêng ma Brah Huêng Ueh, lah ma khân păng pô aơ: “Hơi phung kôranh jêh ri phung bu bŭnh bu ranh,$b$,false),
('bunong-vn','ACT',4,9,null,$b$tơ lah khân may ôp hên nar aơ yor lah hên ƀư ueh ma du huê bunuyh rvĕn, mâm ƀư păng hŏ bah jêh,$b$,false),
('bunong-vn','ACT',4,10,null,$b$ăn khân may jêh ri lĕ rngôch phung Israel gĭt nau aơ, ma amoh Brah Yêsu, ƀon Nasaret yơh Nơm khân may hŏ nkhĭt jêh ta si tâm rkăng, Nơm Brah Ndu hŏ ndâk rêh jêh, Nơm nây yơh bunuyh gŭ dâk ta năp khân may hŏ bah jêh.$b$,false),
('bunong-vn','ACT',4,11,null,$b$Brah Yêsu aơ jêng lŭ khân may, phung ƀư ngih mƀăr lơi, jêh ri Păng jêng lŭ ta njônh ngih.$b$,true),
('bunong-vn','ACT',4,12,null,$b$Mâu hôm geh nau tâm rklaih tâm nơm êng ôh, yor lah tâm dâng trôk mâu geh ôh amoh êng ăn jêh ma bunuyh, jêh ri Păng yơh he dơi geh nau tâm rklaih.”$b$,true),
('bunong-vn','ACT',4,13,null,$b$Tơ lah khân păng saơ nau janh Y-Pêtrôs ndrel ma Y-Yôhan, khân păng hih rhâl, yor lah khân păng gĭt phung nây jêng bunuyh ƀon lan, mâu mâp nti ôh. Khân păng gĭt năl jêh phung nây gŭ ndrel ma Brah Yêsu.$b$,true),
('bunong-vn','ACT',4,14,null,$b$Ƀiă lah saơ bunuyh rvĕn bah jêh gŭ dâk dăch ta nây, khân păng mâu hôm geh nau dơi tâm rlăch.$b$,true),
('bunong-vn','ACT',4,15,null,$b$Pô ri, jêh khân păng đă phung bar hê nây du luh tă bơh ntŭk phat dôih, khân păng tâm nchră ndrăng khân păng nơm jêh ri lah:$b$,false),
('bunong-vn','ACT',4,16,null,$b$“Mâm nau he mra ƀư ma phung nây? Yor lah lĕ rngôch phung ƀon lan, ƀon Yêrusalem gĭt rah vah nanê̆ jêh nau khlay khân păng ƀư. He mâu dơi dun ôh.$b$,false),
('bunong-vn','ACT',4,17,null,$b$Ƀiă lah gay ma lơi ăn nau nây jêng lư n'găr lam ntŭk, ăn he buay khân păng ma nau thăm rmat, lơi hôm ngơi ma bu ma amoh nây.”$b$,false),
('bunong-vn','ACT',4,18,null,$b$Khân păng kuăl khân păng lăp, jêh ri buay ktang ngăn mâu hôm ăn ngơi mâu lah nti lah ma amoh Brah Yêsu ôh.$b$,false),
('bunong-vn','ACT',4,19,null,$b$Ƀiă lah Y-Pêtrôs jêh ri Y-Yôhan lah pô aơ: “Ăn khân may mĭn, moh nau di ta năp Brah Ndu, tông ma khân may hĕ, mâm lah ma Brah Ndu?$b$,false),
('bunong-vn','ACT',4,20,null,$b$Yor lah hên mâu dơi gŭ iăt săk ôh, jêh ri mâu geh ngơi ma nau hên nơm saơ jêh ri tăng.”$b$,false),
('bunong-vn','ACT',4,21,null,$b$Khân păng thăm rmat tay jêh ri mƀơk, mâu geh nau dơi tâm rmal phung nây ôh, yor phung ƀon lan, lĕ rngôch mât ton tâm rnê ma Brah Ndu ma nau tât jêh.$b$,false),
('bunong-vn','ACT',4,22,null,$b$Bunuyh bah jêh ma nau khlay nây, geh jêh rmeh tâm puăn jât năm.$b$,false),
('bunong-vn','ACT',4,23,null,$b$Jêh bu mƀơk khân păng, khân păng hăn ta phung oh nâu jêh ri nkoch bri lĕ nau phung n'gâng kôranh ƀư brah jêh ri phung bu bŭnh bu ranh lah jêh.$b$,true),
('bunong-vn','ACT',4,24,null,$b$Jêh khân păng tăng, khân păng n'hao bâr ndrel n'grŭp ma Brah Ndu pô aơ: “Ơ Kôranh Brah, Nơm rhăk trôk, neh ntu, dak mƀŭt jêh ri lĕ rngôch mpô mpa,$b$,false),
('bunong-vn','ACT',4,25,null,$b$Nơm lah jêh ma Brah Huêng Ueh ma bâr mbung mbơ̆ hên, oh mon may, Y-Đavit: ‘Mâm ƀư mpôl băl bunuyh geh nau uh ah, jêh ri phung ƀon lan mĭn ma nau mâu khlay?$b$,false),
('bunong-vn','ACT',4,26,null,$b$Phung hađăch ta neh ntu dâk gŭ râng, jêh ri phung kôranh tâm rƀŭn ndrel, gay ma tâm rdâng đah Kôranh Brah jêh ri đah Brah Krist.’$b$,true),
('bunong-vn','ACT',4,27,null,$b$Yor lah Hêrôt jêh ri Pôns Pilat nđâp ma âk phung mpôl băl, đah phung ƀon lan Israel, tâm rƀŭn jêh nanê̆ tâm ƀon aơ, gay ma tâm rdâng đah phung oh mon kloh ueh may, Brah Yêsu, Nơm may troch jêh dak ngi,$b$,false),
('bunong-vn','ACT',4,28,null,$b$gay ma nanê̆ lĕ rngôch nau ti may, jêh ri nau mĭn may săch jêh bơh lor.$b$,false),
('bunong-vn','ACT',4,29,null,$b$Aƀaơ aơ, ơ Kôranh Brah ăn may sek uănh nau khân păng thăm rmat, jêh ri ăn ma phung oh mon may mbơh nau may ngơi ma nau janh ktang.$b$,false),
('bunong-vn','ACT',4,30,null,$b$Ăn yơr ti may gay ma amoh Tông mpăr kloh ueh may, Brah Yêsu, dơi ƀư bah, ƀư nau khlay jêh ri nau tâm mbên khlay.”$b$,false),
('bunong-vn','ACT',4,31,null,$b$Jêh mbơh sơm, ntŭk khân păng tâm rƀŭn nây geh nau mpât n'gơ. Lĕ rngôch khân păng bêng ma Brah Huêng Ueh, jêh ri khân păng mbơh Nau Brah Ndu Ngơi ma nau janh.$b$,false),
('bunong-vn','ACT',4,32,null,$b$Pô ri, âk ngăn phung chroh geh nau du ai nuih n'hâm jêh ri du nau mĭn. Mâu geh du huê bunuyh uănh drăp ndơ păng geh, jêng ndơ êng păng nơm ôh, ƀiă lah khân păng uănh ma drăp ndơ khân păng jêng ndrel n'grŭp.$b$,true),
('bunong-vn','ACT',4,33,null,$b$Ma nau brah phung kôranh oh mon mbơh ma nau Brah Yêsu dâk rêh, jêh ri lĕ rngôch khân păng geh nau ueh lăng âk ngăn.$b$,false),
('bunong-vn','ACT',4,34,null,$b$Mâu geh du huê tâm phung khân păng ât ji ngot, yor lah lĕ rngôch phung geh mir lŏ, mâu lah ngih vâl, tăch lơi jêh ri dŭm prăk khân păng geh, khân păng djôt leo.$b$,false),
('bunong-vn','ACT',4,35,null,$b$Dơm ta jâng phung kôranh oh mon, jêh ri bu tâm pă ma ăp nơm tĭng nâm nau pưt mâu tŏng.$b$,false),
('bunong-vn','ACT',4,36,null,$b$Y-Yôsep, phung kôranh oh mon tâm amoh Y-Ƀarnaƀas (nâm bu ntĭt, kon nau bonh) mpôl băl Y-Lêvi tă bơh n'gor Chiprơ,$b$,false),
('bunong-vn','ACT',4,37,null,$b$geh du lôk mir lŏ. Păng tăch jêh ri djôt prăk nây, dơm ta jâng phung kôranh oh mon.$b$,false),
('bunong-vn','ACT',5,1,null,$b$Ƀiă lah geh du huê amoh păng Y-Ananias du ai nau đah ur păng, H'Saphira tăch neh.$b$,true),
('bunong-vn','ACT',5,2,null,$b$Jêh tâm nchră đah ur, păng djôt prăk du kô̆ rnoh neh, jêh ri kô̆ hôm păng njŭn ăn ta jâng phung kôranh oh mon.$b$,false),
('bunong-vn','ACT',5,3,null,$b$Y-Pêtrôs lah ma păng: “Hơi Y-Ananias, mâm ƀư ăn Satan mbêng nuih n'hâm may? May mƀruh ma Brah Huêng Ueh tât djôt prăp du kô̆ rnoh tăch neh.$b$,false),
('bunong-vn','ACT',5,4,null,$b$Tơ lah may ê tăch neh nây, di lĕ păng ăt hôm ma may? Tơ lah jêh may tăch, may mâu dơi djôt prăp hĕ prăk nây? Mâm ƀư nuih n'hâm may mĭn tâm ban pô nây? May mƀruh mâu di ma bunuyh ôh, ƀiă lah may mƀruh ma Brah Ndu yơh.”$b$,false),
('bunong-vn','ACT',5,5,null,$b$Dôl Y-Ananias tăng nau ngơi nây păng cha lôt ta neh jêh ri khĭt. Lĕ rngôch phung tăng nau nây klach hâu ngăn.$b$,false),
('bunong-vn','ACT',5,6,null,$b$Phung bu klâu ndăm, dâk put nklâm săk jăn păng, jêh ri tung hăn tâp lơi.$b$,false),
('bunong-vn','ACT',5,7,null,$b$Klăp lah tâm pe mông jêh ma nây, ur Y-Ananias lăp, păng mâu hŏ gĭt moh nau tât jêh,$b$,true),
('bunong-vn','ACT',5,8,null,$b$Y-Pêtrôs ôp păng: “Nkoch ma gâp, di lĕ khân ay tăch neh nây rnoh dŭm aơ?” Ur păng plơ̆ lah: “Nanê̆ dŭm rnoh nây.”$b$,false),
('bunong-vn','ACT',5,9,null,$b$Y-Pêtrôs lah ma păng: “Mâm ƀư khân ay jêng du ai nau ŭch rlong uănh Brah Huêng Ueh Kôranh Brah? Ri, nteh jâng phung hăn tâp jêh sai ay bu tăng ta bôk mpông. Khân păng mra tung tâp ay đŏng tâm ban lĕ.”$b$,true),
('bunong-vn','ACT',5,10,null,$b$Ƀât lât ta nây păng cha lôt ta jâng Y-Pêtrôs jêh ri khĭt phung bu klâu ndăm sĭt, jêh ri saơ đŏng ur păng khĭt. Bu tung păng hăn tâp dăch ta môch sai păng.$b$,false),
('bunong-vn','ACT',5,11,null,$b$Geh nau klach toyh ngăn ma lĕ rngôch phung ngih Brah Ndu nđâp ma phung tăng lư nau nây.$b$,false),
('bunong-vn','ACT',5,12,null,$b$Phung kôranh oh mon ƀư âk nau khlay jêh ri nau tâm mbên khlay ta năp phung ƀon lan. Lĕ rngôch khân păng tâm rƀŭn ta nkual Salômôn.$b$,true),
('bunong-vn','ACT',5,13,null,$b$Mâu geh bunuyh êng ôh janh lăp ndrel ma khân păng, ƀiă lah phung ƀon lan tâm rnê ma khân păng hâu ngăn.$b$,false),
('bunong-vn','ACT',5,14,null,$b$Phung chroh ma Kôranh Brah jêng lơ hâu nđâp ma bu ur bu klâu.$b$,false),
('bunong-vn','ACT',5,15,null,$b$Pô ri bu tung njŭn leo âk bunuyh ji dơm ta trong sâng, ăn bêch ta klơ sưng toyh mâu lah jê̆, gay ma tơ lah Y-Pêtrôs prot rgăn ta nây gui păng dơi nkŭm lĕ khân păng ƀa ƀă.$b$,false),
('bunong-vn','ACT',5,16,null,$b$Tâm ban lĕ phung ƀon lan gŭ jŭm văr ta nây, hăn ta ƀon Yêrusalem njŭn leo phung ji kuet, jêh ri phung brah mhĭk lơh, jêh ri lĕ rngôch dơi bah da dê.$b$,true),
('bunong-vn','ACT',5,17,null,$b$Rnôk nây kôranh ƀư brah toyh jêh ri lĕ rngôch phung băl păng, nâm bu ntĭt, phung Sađusê dâk tâm rdâng bêng ma nau tâm nach.$b$,true),
('bunong-vn','ACT',5,18,null,$b$Khân păng nhŭp kôranh oh mon jêh ri krŭng tâm ndrung bu nă.$b$,false),
('bunong-vn','ACT',5,19,null,$b$Ƀiă lah dôl măng geh du huê Tông mpăr ueh Brah Ndu, pơk mpông ndrung bu nă, jêh ri ăn luh du, păng lah:$b$,false),
('bunong-vn','ACT',5,20,null,$b$“Hăn hom lăp tâm ngih brah Yuđa, jêh ri mbơh ma phung ƀon lan, lĕ rngôch nau ngơi rêh aơ.”$b$,false),
('bunong-vn','ACT',5,21,null,$b$Jêh tăng nau nây ôi ơm, khân păng lăp tâm ngih brah Yuđa, jêh ri ntơm nti lah. Ƀiă lah kôranh ƀư brah toyh jêh ri phung băl păng tât. Khân păng tâm rƀŭn phung kôranh phat dôih, jêh ri lĕ rngôch phung bu bŭnh bu ranh tâm phung Israel. Jêh ri khân păng njuăl hăn, gay ma njŭn leo du huê nây tă bơh ndrung bu nă.$b$,false),
('bunong-vn','ACT',5,22,null,$b$Phung ta han hăn, ƀiă lah mâu hôm saơ phung nây tâm ndrung bu nă ôh. Phung ta han sĭt, jêh ri mbơh ma phung kôranh pô aơ:$b$,false),
('bunong-vn','ACT',5,23,null,$b$“Hên saơ jêh ndrung bu nă nchăng nâp ngăn, jêh ri phung ta han gak ăt gŭ pa dih ƀiă lah mpông jêh pơk, hên mâu saơ du huê bunuyh tâm nây ôh.”$b$,false),
('bunong-vn','ACT',5,24,null,$b$Jêh tăng nau nây kôranh chiă uănh ngih brah Yuđa, jêh ri phung n'gâng kôranh ƀư brah, geh nau uh ah, yor ma phung oh mon nây, jêh ri yor ma nau mra tât.$b$,false),
('bunong-vn','ACT',5,25,null,$b$Ƀiă lah geh du huê văch tât jêh ri lah: “Ri, phung bunuyh khân may krŭng jêh tâm ndrung, aƀaơ khân păng gŭ nti ma phung ƀon lan tâm ngih brah Yuđa.”$b$,false),
('bunong-vn','ACT',5,26,null,$b$Jêh ma nây kôranh ta han hăn ndrel ma phung ta han chiă jêh ri nhŭp phung oh mon, ƀiă lah mâu ƀư mhĭk ôh, yor lah khân păng klach ma phung ƀon lan klŭp lŭ ma khân păng.$b$,false),
('bunong-vn','ACT',5,27,null,$b$Jêh nhŭp, khân păng njŭn leo ta kôranh phat dôih, jêh ri phung kôranh ƀư brah toyh ôp pô aơ:$b$,true),
('bunong-vn','ACT',5,28,null,$b$“Hên buay khân may ktang ngăn, mâu ăn nti lah ma amoh bunuyh nây ôh, ƀiă lah khân may ƀư bêng jêh, ƀon Yêrusalem nau khân may nti. Khân may ŭch ăn tŭp mham bunuyh nây ta hên.”$b$,false),
('bunong-vn','ACT',5,29,null,$b$Y-Pêtrôs jêh ri kôranh oh mon plơ̆ lah: “Ăn he tông bâr Brah Ndu, mâu di ma bunuyh ôh.$b$,false),
('bunong-vn','ACT',5,30,null,$b$Brah Ndu phung mbơ̆ he ăn jêh Brah Yêsu dâk rêh Nơm khân păng nkhĭt jêh ta si tâm rkăng.$b$,false),
('bunong-vn','ACT',5,31,null,$b$Brah Ndu chông jêh Nơm nây ăn gŭ mpeh pa ma jêng hađăch jêh ri Nơm Tâm Rklaih, gay ăn ma phung Israel nau tâm rmal nau tih, jêh ri nau yô̆ an ma nau tih.$b$,false),
('bunong-vn','ACT',5,32,null,$b$Bi phung hên, hên jêng phung mbơh lĕ nau hên saơ nây, tâm ban ma Brah Huêng Ueh, Nơm Brah Ndu ăn ma phung tông bâr ma Păng.”$b$,false),
('bunong-vn','ACT',5,33,null,$b$Jêh tăng nau nây khân păng ji nuih ngăn, khân păng tâm nchră gay ma nkhĭt lơi phung nây.$b$,true),
('bunong-vn','ACT',5,34,null,$b$Ƀiă lah geh du huê Pharisi tâm amoh Y-Gamaliel, kôranh phat dôih, nơm bu vay yơk, păng dâk ta năp phung phat dôih, đă bu ăn phung oh mon luh ƀât.$b$,false),
('bunong-vn','ACT',5,35,null,$b$Jêh ri păng lah: “Hơi phung Israel, njrăng hom ma nau khân may mra ƀư ma phung aơ.$b$,true),
('bunong-vn','ACT',5,36,null,$b$Rnôk lor geh Y-Thiôdas yơk êng ma păng nơm, tât geh tâm puăn rhiăng nuyh tĭng ndô̆ păng, ƀiă lah bu nkhĭt Păng jêh ri lĕ rngôch bunuyh nkhah du jêh ri kan khân păng mâu jêng ôh.$b$,false),
('bunong-vn','ACT',5,37,null,$b$Jêh nau aơ ăt geh đŏng Y-Yuđas n'gor Galilê, tâm rdâng rnôk bu kơp rnoh bunuyh, jêh ri păng kuăl âk bunuyh tĭng ndô̆ păng. Păng khĭt jêh ri lĕ rngôch bunuyh tĭng ndô̆ păng nkhah du êng êng.$b$,false),
('bunong-vn','ACT',5,38,null,$b$Aƀaơ aơ, gâp lah ma khân may, lơi hôm tĭng phung nây ôh, khân đi păng. Tơ lah nau nti aơ mâu lah kan aơ luh tă bơh bunuyh, păng mra rai êng păng nơm.$b$,false),
('bunong-vn','ACT',5,39,null,$b$Ƀiă lah, tơ lah luh tă bơh Brah Ndu, khân may mâu mra dơi ƀư rai phung nây ôh, klach lah khân may tâm lơh đah Brah Ndu!”$b$,false),
('bunong-vn','ACT',5,40,null,$b$Khân păng dơn nau Y-Gamaliel lah. Khân păng kuăl tay phung kôranh oh mon lăp, jêh ri đă bu dong phung nây ma mâng jêh ri buay mâu ăn ngơi ma amoh Brah Yêsu ôh, jêh ri mƀơk khân păng.$b$,false),
('bunong-vn','ACT',5,41,null,$b$Phung oh mon du luh tă bơh phung phat dôih. Khân păng răm ngăn yor lah bu kơp khân păng khư dơn nau rêh ni yor amoh Brah Yêsu.$b$,true),
('bunong-vn','ACT',5,42,null,$b$Jêh ri ăp nar tâm ngih brah Yuđa mâu lah tâm ăp ngih, khân păng nti lah mbơh nau mhe mhan ueh Brah Yêsu Krist mâu rlu ôh.$b$,false),
('bunong-vn','ACT',6,1,null,$b$Tâm rnôk nây phung oh mon lơ hâu âk phung Hêlênist ngơi ƀŭk dŭk suyh ma phung Hêbrơ, yor lah khân păng mâu pă ăp nar ndơ ma phung bu ur khĭt sai Hêlênist.$b$,true),
('bunong-vn','ACT',6,2,null,$b$Phung jât ma bar nuyh kuăl lĕ rngôch phung chroh tâm rƀŭn jêh ri lah ma khân păng: “Mâu ueh ôh he cha lơi nau Brah Ndu ngơi gay ma tâm pă ndơ sông sa.$b$,false),
('bunong-vn','ACT',6,3,null,$b$Pô ri, hơi phung oh nâu, săch hom tâm phung khân may pơh nuyh geh nau lư n'găr ueh, bêng ma Brah Huêng Ueh jêh ri ma nau blau mĭn. Hên mra jao ma khân păng kan aơ.$b$,false),
('bunong-vn','ACT',6,4,null,$b$Bi hên, hên djôt mro kan mbơh sơm jêh ri nti lah nau Brah Ndu ngơi.”$b$,false),
('bunong-vn','ACT',6,5,null,$b$Lĕ rngôch phung tâm rƀŭn rŏng ma nau nây. Khân păng săch Y-Êtiên, nơm bêng ma nau chroh jêh ri Brah Huêng Ueh, Y-Philip, Y-Prôkor, Y-Nikanor, Y-Timôn, Y-Parmênas jêh ri Y-Nikôlas bunuyh ƀon Antiôs lăp phung Yuđa.$b$,false),
('bunong-vn','ACT',6,6,null,$b$Jêh ri khân păng tâm mpơl mbơh pơh nuyh aơ ma phung oh mon. Jêh phung kôranh oh mon mbơh sơm khân păng pah ti ma phung nây.$b$,false),
('bunong-vn','ACT',6,7,null,$b$Nau chroh Brah Ndu bu mbơh lơ hâu lam ntŭk, jêh ri phung oh mon ntop lơ hâu âk ta ƀon Yêrusalem, nđâp ma âk phung kôranh ƀư brah tông ma nau chroh.$b$,false),
('bunong-vn','ACT',6,8,null,$b$Y-Êtiên, bêng ma nau yô̆, jêh ri nau brah ƀư nau khlay toyh, jêh ri nau tâm mbên khlay ta năp phung ƀon lan$b$,true),
('bunong-vn','ACT',6,9,null,$b$Ƀiă lah ƀa ƀă geh phung tâm ngih rƀŭn phung Yuđa bu rnha phung đăp mpăn kon me, ndrel ma phung Siren, phung Aleksandrơ, jêh ri phung Yuđa tă bơh n'gor Silisi jêh ri n'gor Asi, dâk jêh ri tâm rlăch đah Y-Tiên,$b$,false),
('bunong-vn','ACT',6,10,null,$b$Ƀiă lah khân păng mâu dơi tâm rdâng ma nau blau mĭn, păng jêh ri ma Brah Huêng Ueh, nơm kơl păng ngơi.$b$,false),
('bunong-vn','ACT',6,11,null,$b$Khân păng nkhôm bunuyh ăn lah pô aơ: “Hên tăng jêh păng ngơi sưr ma Y-Môis, jêh ri ma Brah Ndu.”$b$,false),
('bunong-vn','ACT',6,12,null,$b$Khân păng nchâp phung ƀon lan, phung bu bŭnh bu ranh, jêh ri phung kôranh nchih sămƀŭt. Khân păng hăn ta Y-Êtiên nhŭp jêh ri njŭn ô băl ta năp phung kôranh phat dôih phung Yuđa.$b$,true),
('bunong-vn','ACT',6,13,null,$b$Khân păng ăn phung nchơt mƀruh pô aơ: “Bunuyh aơ vay ngơi sưr ma ntŭk kloh ueh aơ jêh ri ma nau vay.$b$,false),
('bunong-vn','ACT',6,14,null,$b$Yor lah hên tăng păng lah ma Brah Yêsu, ƀon Nasaret nây mra ƀư rai ntŭk aơ, jêh ri tâm rgâl nau vay ơm he geh jêh tă bơh Y-Môis.”$b$,false),
('bunong-vn','ACT',6,15,null,$b$Jêh ri lĕ rngôch bunuyh tâm rƀŭn tâm ntŭk phat dôih nây, gŭ uănh ma Y-Êtiên, saơ muh măt păng nâm bu măt Tông mpăr ueh Brah Ndu.$b$,false),
('bunong-vn','ACT',7,1,null,$b$Kôranh ƀư brah toyh ôp păng: “Di tâm ban pô nây lĕ?”$b$,true),
('bunong-vn','ACT',7,2,null,$b$Y-Êtiên plơ̆ lah: “Hơi phung oh nâu jêh ri phung mbơ̆ , gŭ iăt hom. Brah Ndu, nơm chrêk rmah, tâm mpơl jêh ma mbơ̆ he, Y-Abraham, dôl păng gŭ tâm n'gor Mêsôpôtami; lor ma păng hăn gŭ ta ƀon Charan.$b$,false),
('bunong-vn','ACT',7,3,null,$b$Păng lah pô aơ: ‘Luh hom tă bơh n'gor may jêh ri mpôl băl may, jêh ri hăn ta n'gor gâp mra ntĭm an ma may.’$b$,false),
('bunong-vn','ACT',7,4,null,$b$Rnôk nây păng du luh tă bơh n'gor Kalđê hăn gŭ ta ƀon Charan. Tă bơh ntŭk nây, jêh khĭt mbơ̆ păng, Brah Ndu ăn păng gŭ tâm n'gor khân may gŭ aƀaơ aơ.$b$,false),
('bunong-vn','ACT',7,5,null,$b$Brah Ndu mâu ăn neh ƀư mir ma păng ôh tâm n'gor nây, dĭng mpang jâng neh mâu geh lĕ, ƀiă lah păng ton mra ăn n'gor aơ jêng ndơ păng jêh ri ndơ phung kon sau păng kăndơ̆ , dôl Y-Abraham ê hŏ geh kon kđôi lĕ.$b$,false),
('bunong-vn','ACT',7,6,null,$b$Brah Ndu lah ma phung kon sau păng, mra gŭ jăng jai tâm n'gor bu năch. Bu mra njêng khân păng jêng dĭk jêh ri tŭn jot khân păng tâm puăn rhiăng năm.$b$,false),
('bunong-vn','ACT',7,7,null,$b$Brah Ndu lah tay: ‘Gâp mra phat dôih, n'gor mra njêng khân păng jêng dĭk. Jêh lôch nau nây khân păng mra luh, jêh ri pah kan ma gâp tâm ntŭk aơ.’$b$,false),
('bunong-vn','ACT',7,8,null,$b$Brah Ndu ăn ma Y-Abraham nau tâm rnglăp ma nau koh ntâu. Pô ri yơh jêh Y-Abraham geh du huê kon bu klâu, amoh păng Y-Isăk, păng ƀư nau koh ntâu, tơ lah păng geh pham nar; Y-Isăk ƀư ma Y-Yakôp, jêh ri Y-Yakôp ƀư ma phung jât ma bar nuyh che tơm ma phung Israel.$b$,false),
('bunong-vn','ACT',7,9,null,$b$“Phung che kăl e ri nach ma Y-Yôsep, tăch jêh ri njŭn leo ô băl tâm n'gor Êjipt. Ƀiă lah Brah Ndu gŭ ndrel ma păng.$b$,true),
('bunong-vn','ACT',7,10,null,$b$Brah Ndu rklaih păng bơh lĕ rngôch nau mhĭk ăp ntil jêh ri bêng ma nau yô̆, jêh ri nau blau mĭn ta năp Pharaôn, n'gor Êjipt. Hađăch nây ăn păng jêng kôranh n'gor Êjipt jêh ri kôranh ma lĕ ngih păng.$b$,false),
('bunong-vn','ACT',7,11,null,$b$Rnôk nây geh nau sa sât ji ngot tâm n'gor Êjipt jêh ri n'gor Kanaan. Geh nau rêh ni toyh ngăn, jêh ri phung mbơ̆ he mâu dơi blau geh ndơ sông sa ôh.$b$,false),
('bunong-vn','ACT',7,12,null,$b$Y-Yakôp gĭt bu geh ba me tâm n'gor Êjipt. Păng njuăl phung mbơ̆ he hăn du tơ̆ lor lơn.$b$,false),
('bunong-vn','ACT',7,13,null,$b$Tal bar phung oh nâu Y-Yôsep gĭt năl păng jêh ri Pharaôn gĭt ndŭl mpôl Y-Yôsep.$b$,false),
('bunong-vn','ACT',7,14,null,$b$Y-Yôsep njuăl bunuyh chuă Y-Yakôp, mbơ̆ păng, jêh ri ur kon păng, lĕ rngôch geh pơh jât ma prăm nuyh.$b$,false),
('bunong-vn','ACT',7,15,null,$b$Y-Yakôp jŭr hăn ta n'gor Êjipt jêh ri păng khĭt ta nây, nđâp ma phung mbơ̆ he tâm ban lĕ.$b$,true),
('bunong-vn','ACT',7,16,null,$b$Jêh ri bu rdeng săk jăn khân păng tă ƀon Sichem, jêh ri bu tâp khân păng tâm môch Y-Abraham rvăt jêh ma prăk tă bơh phung kon bu klâu Y-Hamôr ƀon Sichem.$b$,false),
('bunong-vn','ACT',7,17,null,$b$“Ƀiă lah, tơ lah dăch tât nar Brah Ndu ton jêh ma Y-Abraham, bunuyh lơ hâu bĭk rơ̆ tâm n'gor Êjipt,$b$,true),
('bunong-vn','ACT',7,18,null,$b$Tât nar geh hađăch êng ma n'gor Êjipt. Hađăch nây mâu gĭt năl Y-Yôsep ôh.$b$,false),
('bunong-vn','ACT',7,19,null,$b$Hađăch nây dŏng nau ndơm, đah phung mpôl băl he. Păng tŭn jot phung mbơ̆ he, gay nchâp khân păng cha lơi kon mhe deh, mâu ăn khân ô băl gŭ rêh.$b$,false),
('bunong-vn','ACT',7,20,null,$b$Rnôk nây bu deh ma Y-Môis, păng ueh ngăn ta năp Brah Ndu. Jêh ri bu rong păng pe khay tâm ngih mbơ̆ păng.$b$,true),
('bunong-vn','ACT',7,21,null,$b$Tơ lah bu cha lat păng, kon bu ur Pharaôn dônh jêh ri rong njêng kon păng nơm.$b$,false),
('bunong-vn','ACT',7,22,null,$b$Y-Môis nti lĕ nau blau mĭn phung Êjipt. Păng ktang tâm nau ngơi jêh ri tâm kan.$b$,false),
('bunong-vn','ACT',7,23,null,$b$“Ƀiă lah tât păng geh puăn jât năm, Păng geh nau klâng tâm nuih n'hâm, ŭch hăn khâl oh nâu păng, phung kon Israel.$b$,true),
('bunong-vn','ACT',7,24,null,$b$Saơ bu tŭn jot du huê tâm phung khân păng, păng king nơm bu tŭn jot, jêh ri păng dong du huê Êjipt, gay ma tâm plơng bôk.$b$,true),
('bunong-vn','ACT',7,25,null,$b$Păng mĭn ma phung oh nâu păng mra gĭt rbăng ma Brah Ndu mra tâm rklaih khân păng, yor ti Păng, ƀiă lah phung nây mâu gĭt rbăng ôh.$b$,true),
('bunong-vn','ACT',7,26,null,$b$Nar ôi taơ dôl khân păng tâm nhăt, păng hăn dăch phung nây gay ma rthi nuih, gay ma gŭ đăp mpăn, păng lah: ‘Hơi khân may jêng oh nâu, mâm ƀư khân may ƀư mhĭk ndrăng oh nâu nơm?’$b$,false),
('bunong-vn','ACT',7,27,null,$b$Nơm ƀư mhĭk ma mpôl băl păng nây, nklơ̆ Y-Môis jêh ri lah: ‘Mbu ăn may jêng kôranh, jêh ri kôranh phat dôih ma hên?$b$,false),
('bunong-vn','ACT',7,28,null,$b$May ŭch nkhĭt gâp, nâm bu nđaơ may hŏ nkhĭt jêh du huê Êjipt?’$b$,true),
('bunong-vn','ACT',7,29,null,$b$Tăng nau nây Y-Môis hăn du gŭ tâm n'gor Madian, ta nây păng geh bar hê kon bu klâu.$b$,false),
('bunong-vn','ACT',7,30,null,$b$“Puăn jât năm ma nây, geh du huê Tông mpăr ueh Brah Ndu tâm mpơl ma păng tâm bri rdah yôk Sinai, nâm bu mpiăt ŭnh sa pôm lok.$b$,true),
('bunong-vn','ACT',7,31,null,$b$Saơ pô nây, Y-Môis hih rhâl ngăn ma nau tâm mpơl nây. Dôl păng hăn dăch lơn ŭch uănh, geh bâr Kôranh Brah ngơi ma păng:$b$,false),
('bunong-vn','ACT',7,32,null,$b$‘Gâp jêng Brah Ndu ma phung mbơ̆ may, Brah Ndu Y-Abraham, Y-Isăk, jêh ri Y-Yakôp,’ Y-Môis sâr săk jăn mâu janh uănh ôh.$b$,false),
('bunong-vn','ACT',7,33,null,$b$Jêh ri Kôranh Brah lah ma păng: ‘Doh lơi ntâu jot may, yor lah ntŭk may gŭ nây jêng neh kloh ueh.$b$,false),
('bunong-vn','ACT',7,34,null,$b$Dôl uănh, gâp saơ jêh nau rêh ni phung gâp tâm n'gor Êjipt. Gâp tăng jêh nau khân păng nter, nđêng jêh ri gâp jŭr văch gay ma tâm rklaih khân păng: Văch hom aƀaơ, Gâp mra njuăl may hăn ta n'gor Êjipt.’$b$,false),
('bunong-vn','ACT',7,35,null,$b$Y-Môis nây nơm bu dun, jêh ri lah: ‘Mbu ăn may jêng kôranh, jêng kôranh phat dôih hên?’ Păng yơh, nơm Brah Ndu njuăl jêng kôranh, jêh ri nơm tâm rklaih ma nau kơl bơh Tông mpăr ueh Brah Ndu, tâm mpơl jêh ma păng tâm pôm lok.$b$,false),
('bunong-vn','ACT',7,36,null,$b$Păng yơh nơm ăn khân păng luh. Păng ƀư nau khlay jêh ri nau tâm mbên khlay tâm n'gor Êjipt, ta dak Rlai Chăng jêh ri tâm bri rdah dôl tâm puăn jât năm.$b$,false),
('bunong-vn','ACT',7,37,null,$b$Y-Môis nây yơh, ngơi jêh ma phung kon Israel pô aơ: ‘Brah Ndu mra ngluh tâm phung oh nâu khân may, du huê kôranh nơm mbơh lor tâm ban ma gâp.’$b$,false),
('bunong-vn','ACT',7,38,null,$b$Păng yơh, nơm tâm nau tâm rƀŭn ta bri rdah, ndrel ma Tông mpăr ueh Brah Ndu, nơm ngơi ma. Păng ta yôk Sinai, jêh ri ma phung mbơ̆ he. Păng sŏk dơn jêh nau ngơi rêh, gay ăn ma he.$b$,false),
('bunong-vn','ACT',7,39,null,$b$Ma păng yơh, phung mbơ̆ he mâu tông bâr. Bu dun păng gay ma nuih n'hâm khân păng plơ̆ ma n'gor Êjipt.$b$,false),
('bunong-vn','ACT',7,40,null,$b$Jêh ri lah ma Y-Arôn: ‘Ƀư ma hên phung rup brah, mra leo trong ma hên, yor lah Y-Môis nây nơm leo hên luh bơh n'gor Êjipt, hên mâu gĭt ôh moh nau tât jêh ma păng.’$b$,true),
('bunong-vn','ACT',7,41,null,$b$Tâm nar nây khân păng ƀư rup du mlâm kon ndrôk. Khân păng nhhơr ndơ ƀư brah ma rup brah nây, jêh ri khân păng maak ma ti khân păng ƀư.$b$,false),
('bunong-vn','ACT',7,42,null,$b$Pô ri Brah Ndu cha lơi khân păng, jêh ri jao khân păng ăn mbah ma âk mpa tâm trôk, tĭng nâm hŏ nchih jêh, tâm ndrom sămƀŭt phung kôranh nơm mbơh lor: ‘Khân may mâp lĕ nhhơr ma gâp mpa jêh ri nau ƀư brah, dôl puăn jât năm tâm bri rdah, hơi phung Israel?$b$,false),
('bunong-vn','ACT',7,43,null,$b$Khân may tung leo ngih bok brah Môlok, jêh ri mănh brah Rômphan, phung rup brah nây khân may ƀư prăp mbah, yor amoh gâp, mra njŭn leo khân may ta ƀon Babilôn.’$b$,true),
('bunong-vn','ACT',7,44,null,$b$“Phung mbơ̆ he geh jêh ngih bok, nau mbơh tâm bri rdah, tĭng nâm Brah Ndu ntăm jêh ma Y-Môis, ƀư tĭng nâm rup ngih păng saơ jêh.$b$,false),
('bunong-vn','ACT',7,45,null,$b$Phung mbơ̆ he sŏk dơn jêh ngih nây. Ndrel ma Y-Yôsuê, khân păng tung leo ma n'gor khân păng, sŏk tă bơh phung mpôl băl Brah Ndu nsot jêh ta năp khân păng. Jêh ri ngih nây ăt hôm tât ta nar hađăch Y-Đavit.$b$,false),
('bunong-vn','ACT',7,46,null,$b$Nơm geh nau yô̆ ta năp Brah Ndu jêh ri păng dăn du ntŭk ma Brah Ndu Y-Yakôp.$b$,false),
('bunong-vn','ACT',7,47,null,$b$Pô ri hađăch Salômôn ƀư du mlâm ngih ma păng.$b$,false),
('bunong-vn','ACT',7,48,null,$b$Ƀiă lah nơm prêh lơn mâu gŭ ôh tâm ngih ƀư ma ti bunuyh, tĭng nâm nau phung kôranh nơm mbơh lor ngơi jêh:$b$,false),
('bunong-vn','ACT',7,49,null,$b$‘Trôk jêng sưng hađăch ma gâp, jêh ri neh ntu jêng rnơl gâp chrong jâng, Kôranh Brah lah. Moh ngih khân may mra ƀư ma gâp, mâu lah ta ntŭk gâp mra rlu?$b$,false),
('bunong-vn','ACT',7,50,null,$b$Mâu di hĕ ti gâp ƀư jêh lĕ rngôch ndơ aơ.’$b$,true),
('bunong-vn','ACT',7,51,null,$b$“Hơi phung bunuyh dăng nko, nuih n'hâm jêh ri tôr mâu geh koh ntâu, khân may tâm rdâng mro đah Brah Huêng Ueh. Khân may jêng tâm ban ma phung mbơ̆ khân may.$b$,false),
('bunong-vn','ACT',7,52,null,$b$Mbu nơm du huê tâm phung kôranh nơm mbơh lor, phung mbơ̆ khân may mâu mâp ƀư mhĭk? Khân păng nkhĭt jêh phung mbơh lor ma nơm sŏng mra văch, nơm khân may ƀư rlăng, jêh ri nkhĭt lơi jêh.$b$,false),
('bunong-vn','ACT',7,53,null,$b$Khân may sŏk dơn jêh nau vay tă bơh Tông mpăr ueh Brah Ndu mbơh an, jêh ri khân may mâu tông ôh.”$b$,true),
('bunong-vn','ACT',7,54,null,$b$Dôl tăng nau nây, khân păng bêng ma nau ji nuih, jêh ri kăp sêk ma Y-Êtiên.$b$,true),
('bunong-vn','ACT',7,55,null,$b$Ƀiă lah Y-Êtiên, bêng ma Brah Huêng Ueh, n'gơr măt ta klơ trôk, saơ nau chrêk rmah Brah Ndu jêh ri Brah Yêsu gŭ dâk mpeh pa ma Brah Ndu.$b$,false),
('bunong-vn','ACT',7,56,null,$b$Jêh ri păng lah: “Ri, gâp saơ trôk pơk mpơl jêh ri Kon Bunuyh gŭ dâk mpeh pa ma Brah Ndu.”$b$,false),
('bunong-vn','ACT',7,57,null,$b$Pô ri khân păng nter hâu ngăn, nsêt trôm tôr khân păng, jêh ri lĕ rngôch nchuăt ran nhŭp Y-Êtiên.$b$,false),
('bunong-vn','ACT',7,58,null,$b$Khân păng têk ô băl leo ta mpâr ƀon jêh ri klŭp lŭ ma ô băl. Phung gŭ uănh, dơm bok ao khân păng ta jâng du huê bu klâu ndăm, amoh păng Y-Sôl.$b$,true),
('bunong-vn','ACT',7,59,null,$b$Dôl khân păng klŭp lŭ, Y-Êtiên mbơh sơm pô aơ: “Ơ Brah Yêsu sŏk dơn huêng gâp.”$b$,false),
('bunong-vn','ACT',7,60,null,$b$Păng chon kômâk jêh ri păng nter huy ngăn: “Ơ Kôranh Brah, lơi kơp nau tih aơ ma khân păng ôh”, jêh păng lah nau nây, păng bêch.$b$,false),
('bunong-vn','ACT',8,1,null,$b$Y-Sôl du ai nau lĕ ma nau nkhĭt Y-Êtiên. Nar nây lĕ geh nau ƀư mhĭk toyh ngăn ma phung Ngih Brah Ndu tâm ƀon Yêrusalem, lĕ rngôch phung chroh du êng êng tâm n'gor Yuđa jêh ri n'gor Samari. Hôm knŏng phung kôranh oh mon.$b$,true),
('bunong-vn','ACT',8,2,null,$b$Phung geh nau chroh ktang tâp Y-Êtiên. Khân păng nhĭm nhhiăng rngot klâng ma ô băl.$b$,false),
('bunong-vn','ACT',8,3,null,$b$Ƀiă lah Y-Sôl ƀư mhĭk ma phung ngih Brah Ndu ktang ngăn, lăp ăp ngih vâl, nhŭp phung bu ur bu klâu têk leo krŭng khân păng.$b$,true),
('bunong-vn','ACT',8,4,null,$b$Đơ phung du gŭ êng êng nsong ăp ntŭk jêh ri mbơh nau mhe mhan ueh.$b$,true),
('bunong-vn','ACT',8,5,null,$b$Jêh ri Y-Philip jŭr ta ƀon Samari nti nau Brah Krist ta nây.$b$,false),
('bunong-vn','ACT',8,6,null,$b$Jêh phung âk tăng nau ngơi, jêh ri saơ nau khlay Y-Philip ƀư, khân păng geh du ai nau ŭch iăt păng nti lah.$b$,false),
('bunong-vn','ACT',8,7,null,$b$Yor lah geh âk brah mhĭk du luh tă bơh bunuyh ma nau nter ktang ngăn jêh ri âk bunuyh rvĕn, jêh ri bunuyh ji jâng ti bah da dê.$b$,false),
('bunong-vn','ACT',8,8,null,$b$Yor nây geh âk nau maak ngăn tâm ƀon nây.$b$,false),
('bunong-vn','ACT',8,9,null,$b$Rnôk nây, tâm ƀon nây geh du huê bunuyh, amoh păng Y-Simôn. Păng ƀư n'hŭm jêh ri nkoch nau păng nơm jêng bunuyh khlay, lĕ rngôch phung ƀon lan Samari hih rhâl ngăn.$b$,true),
('bunong-vn','ACT',8,10,null,$b$Lĕ rngôch nđâp ma kon se, bu ranh gŭ iăt ueh jêh ri lah: “Bunuyh aơ jêng nau brah Brah Ndu, nau brah bu rnha toyh ngăn.”$b$,false),
('bunong-vn','ACT',8,11,null,$b$Bu gŭ iăt nau păng da dê, yor lah bơh jŏ jêh păng ƀư bu, geh nau hih rhâl ma nau păng ƀư n'hŭm.$b$,false),
('bunong-vn','ACT',8,12,null,$b$Ƀiă lah jêh khân păng chroh nau Y-Philip nti nau mhe mhan ueh, ma ƀon bri hađăch Brah Ndu, jêh ri amoh Brah Yêsu Krist, nđâp bu ur bu klâu dơn nau ƀaptem.$b$,false),
('bunong-vn','ACT',8,13,null,$b$Y-Simôn jêng nơm chroh tâm ban lĕ. Jêh păng dơn nau ƀaptem, păng nsong ndrel ma Y-Philip mro. Tơ lah păng saơ nau khlay jêh ri nau tâm mbên khlay, păng hih rhâl ngăn.$b$,false),
('bunong-vn','ACT',8,14,null,$b$Tơ lah phung kôranh oh mon gŭ ta ƀon Yêrusalem, gĭt ma phung Samari dơn jêh Nau Brah Ndu Ngơi, khân păng njuăl Y-Pêtrôs ndrel ma Y-Yôhan hăn ta nây.$b$,true),
('bunong-vn','ACT',8,15,null,$b$Tơ lah phung aơ tât, khân păng mbơh sơm ma phung mhe chroh, gay ma khân păng sŏk dơn Brah Huêng Ueh.$b$,false),
('bunong-vn','ACT',8,16,null,$b$Yor lah ê hŏ Brah Huêng Ueh jŭr ôh, ma du huê tâm phung khân păng, mâu geh lĕ, knŏng khân păng dơn jêh nau ƀaptem ma amoh Brah Yêsu.$b$,false),
('bunong-vn','ACT',8,17,null,$b$Pô ri Y-Pêtrôs ndrel ma Y-Yôhan pah ti ta khân păng, jêh ri khân păng sŏk dơn Brah Huêng Ueh.$b$,true),
('bunong-vn','ACT',8,18,null,$b$Tơ lah Y-Simôn saơ Brah Huêng Ueh jŭr jêh ta khân păng, ma nau phung kôranh oh mon pah ti, păng nhhơr prăk jêh ri lah:$b$,false),
('bunong-vn','ACT',8,19,null,$b$“Ăn ma gâp ƀă nau brah nây, gay ma mbu nơm gâp pah ti, păng mra sŏk dơn Brah Huêng Ueh.”$b$,false),
('bunong-vn','ACT',8,20,null,$b$Ƀiă lah Y-Pêtrôs lah ma păng: “Ăn prăk may rai ndrel ma may, yor lah may mĭn bu dơi rvăt ma prăk nau Brah Ndu ăn!$b$,false),
('bunong-vn','ACT',8,21,null,$b$Du kô̆ mâu lah du ntil, may mâu dơi geh lĕ tâm kan aơ, yor lah nuih n'hâm may mâu sŏng ôh ta năp Brah Ndu.$b$,false),
('bunong-vn','ACT',8,22,null,$b$Rmal hom ma nau ƀai may, jêh ri mbơh sơm ma Kôranh Brah gay Păng yô̆ an nau mĭn nuih n'hâm may tơ lah dơi.$b$,false),
('bunong-vn','ACT',8,23,null,$b$Yor lah gâp saơ may geh nuih n'hâm tăng jêh ri may gŭ tâm rse rvăk nau tih kât.”$b$,false),
('bunong-vn','ACT',8,24,null,$b$Y-Simôn plơ̆ lah: “Mbơh sơm hom khân may nơm ma Kôranh Brah gay ma, lơi ăn tât ma gâp, mâm nau khân may lah jêh.”$b$,true),
('bunong-vn','ACT',8,25,null,$b$Jêh Y-Pêtrôs ndrel ma Y-Yôhan nti lah mbơh Nau Brah Ndu Ngơi, khân păng sĭt ta ƀon Yêrusalem. Dôl sĭt khân păng nti lah nau mhe mhan ueh tâm âk ƀon phung Samari.$b$,true),
('bunong-vn','ACT',8,26,null,$b$Dôl nây geh du huê Tông mpăr ueh Kôranh Brah ngơi ma Y-Philip: “Dâk hom may jêh ri hăn leo bơh rđŭng ta trong tă bơh ƀon Yêrusalem hăn ta ƀon Gaxa, trong nây ta bri rdah”, Y-Philip dâk hăn.$b$,true),
('bunong-vn','ACT',8,27,null,$b$Ri, geh du huê Êthiôpi bunuyh char jêh, chiă uănh kan, jêh ri lĕ drăp ndơ H'Kandas, hađăch bu ur n'gor Êthiôpi, păng hăn jêh ta ƀon Yêrusalem gay ma mbah yơk ma Brah Ndu,$b$,false),
('bunong-vn','ACT',8,28,null,$b$dôl sĭt, jêh ri gŭ ndrel tâm ndeh seh păng, păng uănh ndrom sămƀŭt kôranh nơm mbơh lor Y-Êsai.$b$,false),
('bunong-vn','ACT',8,29,null,$b$Brah Huêng Ueh lah ma Y-Philip: “Hăn dăch hom, ăn ban ndeh seh nây.”$b$,false),
('bunong-vn','ACT',8,30,null,$b$Y-Philip nchuăt tĭng jêh ri păng tăng kôranh Êthiôpi uănh ndrom sămƀŭt kôranh nơm mbơh lor Y-Êsai, păng ôp: “May gĭt rbăng lĕ nau may uănh nây?”$b$,false),
('bunong-vn','ACT',8,31,null,$b$Kôranh nây plơ̆ lah: “Mâm gâp dơi gĭt rbăng tơ lah mâu geh nơm rblang an ma gâp?” Jêh ri păng dăn ma Y-Philip ncho ndrel gŭ dăch păng.$b$,true),
('bunong-vn','ACT',8,32,null,$b$Ntŭk nau nchih păng uănh nây pô aơ: “Bu têk păng tâm ban ma du mlâm biăp ta ntŭk gŭch puăch jêh ri tâm ban ma kon biăp mlo ta năp nơm nkăp rsau păng, păng mâu mâp hă du bâr ôh.$b$,true),
('bunong-vn','ACT',8,33,null,$b$Tâm nau păng dêh rhêt, bu sŏk lơi nau ngơi dôih sŏng tă bơh păng. Jêh ri mbu mra mbơh ma phung mpôl băl păng? Yor lah nau rêh păng bu sŏk lơi tă bơh neh ntu.”$b$,true),
('bunong-vn','ACT',8,34,null,$b$Kôranh nây lah ma Y-Philip: “Gâp ôp may, ma mbu nơm kôranh nơm mbơh lor lah nau nây, ma păng lĕ, mâu lah ma du huê nơm êng?”$b$,true),
('bunong-vn','ACT',8,35,null,$b$Pô ri, Y-Philip ntơm ngơi jêh ri nti nau Brah Yêsu ma păng ma trong nau nchih nây.$b$,false),
('bunong-vn','ACT',8,36,null,$b$Dôl hăn rŏ trong, khân păng saơ dak, jêh ri kôranh nây lah: “Aơ dak aơ! Geh lĕ nau buay gâp dơn nau ƀaptem?”$b$,false),
('bunong-vn','ACT',8,37,null,$b$Y-Philip lah: “Tơ lah may chroh ma lĕ nuih n'hâm mra dơi.” Kôranh nây plơ̆ lah: “Gâp chroh ma Brah Yêsu Krist jêng Kon Brah Ndu.”$b$,false),
('bunong-vn','ACT',8,38,null,$b$Păng đă nkân ndeh, jêh ri lĕ khân păng bar hê jŭr tâm dak, jêh ri Y-Philip ƀư ƀaptem ma kôranh nây.$b$,false),
('bunong-vn','ACT',8,39,null,$b$Jêh khân păng du tă bơh dak, Brah Huêng Ueh Kôranh Brah sŏk Y-Philip, kôranh nây mâu gĭt saơ păng ôh, jêh ri păng hăn bêng ma nau răm.$b$,false),
('bunong-vn','ACT',8,40,null,$b$Bi Y-Philip, bu saơ păng tâm ƀon Asôt tă bơh ƀon nây păng hăn ta ƀon Sêsarê mbơh nau mhe mhan ueh ăp ƀon păng rgăn.$b$,false),
('bunong-vn','ACT',9,1,null,$b$Rnôk nây Y-Sôl rđuh ma nau thăm rmat jêh ri nau tâm nkhĭt phung oh mon Kôranh Brah, păng hăn ta kôranh ƀư brah toyh.$b$,true),
('bunong-vn','ACT',9,2,null,$b$Jêh ri dăn ƀư sămƀŭt ma phung ngih tâm rƀŭn Yuđa ta ƀon Đamas, gay ma tơ lah saơ phung tĭng trong, bu ur mâu lah bu klâu, păng mra kât têk leo khân ô băl ta ƀon Yêrusalem.$b$,false),
('bunong-vn','ACT',9,3,null,$b$Dôl păng hăn rŏ trong, dăch tât ƀon Đamas, ƀât lât geh nau ang tă bơh trôk nchrat jŭm păng.$b$,false),
('bunong-vn','ACT',9,4,null,$b$Păng cha lôt ta neh jêh ri tăng nau ngơi lah ma păng: “Hơi Y-Sôl, hơi Y-Sôl mâm ƀư may ƀư djơh ma gâp?”$b$,true),
('bunong-vn','ACT',9,5,null,$b$Păng plơ̆ lah: “Ơ Kôranh Brah, mbu may?” Kôranh Brah lah: “Gâp, Brah Yêsu Nơm may ƀư djơh!$b$,false),
('bunong-vn','ACT',9,6,null,$b$Dâk hom may, lăp tâm ƀon, jêh ri bu mra lah ma may, mâm nau may mra ƀư.”$b$,false),
('bunong-vn','ACT',9,7,null,$b$Phung hăn ndrel ma păng gŭ jêh ri hih rhâl ngăn. Khân păng tăng nanê̆ ngăn nau ngơi, ƀiă lah mâu saơ bunuyh ôh.$b$,false),
('bunong-vn','ACT',9,8,null,$b$Y-Sôl dâk, măt păng hôm lin ƀiă lah mâu dơi saơ ôh. Bu kuăn ta ti njŭn leo păng sĭt ta ƀon Đamas.$b$,false),
('bunong-vn','ACT',9,9,null,$b$Păng gŭ ta nây pe nar mâu dơi saơ, mâu sông sa, mâu lĕ nhêt dak.$b$,true),
('bunong-vn','ACT',9,10,null,$b$Rnôk nây geh ta ƀon Đamas du huê oh mon, amoh păng Y-Ananias, Kôranh Brah lah ma păng tâm nau tâm mpơl: “Ơ Y-Ananias”, păng mplơ̆ lah: “Gâp ta aơ, Ơ Kôranh Brah.”$b$,true),
('bunong-vn','ACT',9,11,null,$b$Kôranh Brah lah ma păng: “Dâk hom may jêh ri hăn tâm trong bu rnha trong sŏng, jêh ri joi tâm ngih Y-Yuđas du huê, amoh păng Y-Sôl, bơh ƀon Tara.$b$,false),
('bunong-vn','ACT',9,12,null,$b$Yor lah păng gŭ mbơh sơm jêh ri saơ du huê bunuyh, tâm amoh Y-Ananias lăp tâm ngih păng, jêh ri pah ti ta păng gay ăn păng saơ ang tay.”$b$,false),
('bunong-vn','ACT',9,13,null,$b$Y-Ananias plơ̆ lah: “Ơ Kôranh Brah gâp tăng jêh âk bunuyh lah ma nơm nây, ƀư djơh hâu ngăn ma phung kloh ueh tâm ƀon Yêrusalem;$b$,false),
('bunong-vn','ACT',9,14,null,$b$ta aơ păng geh nau dơi bơh phung n'gâng kôranh ƀư brah gay nhŭp chăp lĕ rngôch mbu nơm kuăl mbơh sơm ma amoh may.”$b$,false),
('bunong-vn','ACT',9,15,null,$b$Ƀiă lah Kôranh Brah lah ma păng: “Hăn hom, yor lah gâp săch jêh nơm aơ jêng ndơ gâp dŏng gay mbơh amoh gâp ta năp phung mpôl băl bunuyh, phung hađăch jêh ri phung kon Israel.$b$,false),
('bunong-vn','ACT',9,16,null,$b$Jêh ri gâp mra tâm mpơl ma păng gĭt âk nau rêh ni, păng mra dơn yor amoh gâp.”$b$,false),
('bunong-vn','ACT',9,17,null,$b$Y-Ananias du luh hăn. Tơ lah păng lăp tâm ngih păng pah ti ta Y-Sôl jêh ri lah: “Hơi nâu Y-Sôl, Brah Yêsu, nơm tâm mpơl jêh ma may ta trong dôl may văch; njuăl gâp văch gay ma may dơi saơ ang tay jêh ri bêng ma Brah Huêng Ueh.”$b$,false),
('bunong-vn','ACT',9,18,null,$b$Ƀât lât geh nâm bu nsiap tŭp tă bơh trôm măt Y-Sôl, jêh ri păng saơ ang tay, păng dâk jêh ri dơn nau ƀaptem.$b$,false),
('bunong-vn','ACT',9,19,null,$b$Tơ lah jêh păng sông sa păng lĕ geh n'hâm ktang. Y-Sôl gŭ bar pe nar ndrel ma phung oh mon tâm ƀon Đamas.$b$,false),
('bunong-vn','ACT',9,20,null,$b$Păng ntơm nti ro tâm ngih tâm rƀŭn Yuđa ma Brah Yêsu jêng Kon Brah Ndu.$b$,true),
('bunong-vn','ACT',9,21,null,$b$Lĕ rngôch phung gŭ iăt nau nti hih rhâl ngăn jêh ri lah: “Di lĕ păng nơm ƀư djơh ta ƀon Yêrusalem, ma phung kuăl mbơh sơm ma amoh aơ? Jêh ri mâu di hĕ păng văch ta aơ, ŭch chăp phung chroh, jêh ri têk njŭn leo ma phung n'gâng kan ƀư brah?”$b$,true),
('bunong-vn','ACT',9,22,null,$b$Ƀiă lah Y-Sôl jêng lơ hâu nâp, jêh ri di nau păng đah phung Yuđa ta ƀon Đamas, dôl tâm mpơl rah vah ma Brah Yêsu jêng Brah Krist.$b$,true),
('bunong-vn','ACT',9,23,null,$b$Jŏ nar pa kơi jêh nây, phung Yuđa tâm nchră ndrel gay ma nkhĭt păng.$b$,true),
('bunong-vn','ACT',9,24,null,$b$Ƀiă lah bu mbơh ma Y-Sôl ma nau tâm nchră nây. Măng nar bu gŭ chiă ta mpông pêr, kâp nkhĭt păng.$b$,false),
('bunong-vn','ACT',9,25,null,$b$Ƀiă lah dôl măng phung oh mon nhŭp păng, dơm tâm du mlâm bĭ, jêh ri njŭr păng pa dih mpêr.$b$,false),
('bunong-vn','ACT',9,26,null,$b$Tơ lah Y-Sôl tât jêh ta ƀon Yêrusalem păng ŭch hăn ndrel ma phung oh mon ta nây, ƀiă lah lĕ rngôch khân păng klach, mâu mĭn ôh ma păng jêng jêh du huê nơm chroh.$b$,true),
('bunong-vn','ACT',9,27,null,$b$Ƀiă lah Y-Ƀarnaƀas rom păng, njŭn leo păng ma phung kôranh oh mon, jêh ri nkoch bri ma khân păng nau Kôranh Brah tâm mpơl, jêh ri ngơi ma Y-Sôl ta trong, jêh ri păng janh nti jêh ma amoh Brah Yêsu ta ƀon Đamas.$b$,false),
('bunong-vn','ACT',9,28,null,$b$Ntơm bơh nar nây, păng hăn ƀa ƀơ ndrel ma phung oh mon tâm ƀon Yêrusalem.$b$,false),
('bunong-vn','ACT',9,29,null,$b$Jêh ri păng nti, janh ktang ma amoh Kôranh Brah. Păng ngơi jêh ri tâm rlăch đah phung Hêlênist, ƀiă lah phung nây joi nau nkhĭt păng.$b$,false),
('bunong-vn','ACT',9,30,null,$b$Tơ lah phung oh nâu gĭt nau nây, bu njŭn păng ta ƀon Sêsarê, jêh ri njuăl păng hăn ta ƀon Tars.$b$,false),
('bunong-vn','ACT',9,31,null,$b$Phung ngih Brah Ndu tâm n'gor Yuđa, n'gor Galilê, jêh ri n'gor Samari, geh nau đăp mpăn, văch ma toyh, jêh ri hăn tâm nau klach yơk ma Kôranh Brah; jêh ri khân păng jêng lơ hâu âk lơn đŏng, yor lah Brah Huêng Ueh kơl.$b$,true),
('bunong-vn','ACT',9,32,null,$b$Dôl Y-Pêtrôs nsong lam n'gor, păng hăn lĕ ma phung kloh ueh gŭ ta ƀon Liđa.$b$,true),
('bunong-vn','ACT',9,33,null,$b$Păng saơ ta nây du huê rvĕn, amoh păng Y-Ênê, gŭ bêch pham năm jêh ta sưng păng.$b$,true),
('bunong-vn','ACT',9,34,null,$b$Y-Pêtrôs lah ma păng: “Hơi Y-Ênê, Brah Yêsu Krist ƀư bah may, dâk hom, jêh ri nkra sưng may.” Ƀât lât Y-Ênê dâk ro.$b$,true),
('bunong-vn','ACT',9,35,null,$b$Lĕ rngôch phung ƀon lan ta Liđa, jêh ri ta Sarôn saơ pô nây, khân păng chroh ma Kôranh Brah.$b$,false),
('bunong-vn','ACT',9,36,null,$b$Geh ta ƀon Jôpa tâm phung oh mon du huê bu ur, amoh păng H'Tabitha, nâm bu ntĭt Dôrkas. Păng ƀư âk kan ueh jêh ri păng ăn âk ndơ yô̆ ma phung o ach.$b$,true),
('bunong-vn','ACT',9,37,null,$b$Rnôk nây păng kuet jêh ri khĭt. Bu rao săk jăn păng, jêh ri ăn păng ta jrô klơ.$b$,false),
('bunong-vn','ACT',9,38,null,$b$Phung oh mon gĭt Y-Pêtrôs gŭ ta ƀon Liđa dăch ƀon Jôpa. Khân păng njuăl hăn bar hê dăn, gay ăn păng văch gơnh.$b$,false),
('bunong-vn','ACT',9,39,null,$b$Y-Pêtrôs dâk hăn ndrel ma khân păng. Tơ lah păng tât, bu njŭn leo păng ta jrô klơ nây. Lĕ rngôch phung bu ur khĭt sai gŭ nhĭm jŭm păng, jêh ri ăn Y-Pêtrôs uănh dŭm âk bok ao H'Dôrkas ƀư dôl păng hôm gŭ rêh.$b$,false),
('bunong-vn','ACT',9,40,null,$b$Y-Pêtrôs ăn lĕ rngôch bunuyh du luh. Păng chon kômâk mbơh sơm, jêh ri n'gĭl uănh ta săk jăn bunuyh khĭt. Păng lah: “Hơi H'Tabitha, dâk hom ay.” Păng lin măt, saơ Y-Pêtrôs, jêh ri dâk ro.$b$,false),
('bunong-vn','ACT',9,41,null,$b$Y-Pêtrôs yơr ti, rdâk păng dâk, păng kuăl phung kloh ueh nđâp ma phung bu ur khĭt sai, jêh ri ăn phung nây saơ păng dâk rêh.$b$,false),
('bunong-vn','ACT',9,42,null,$b$Nau nây tăng lư ma lĕ ƀon Jôpa, jêh ri âk bunuyh chroh ma Kôranh Brah.$b$,false),
('bunong-vn','ACT',9,43,null,$b$Y-Pêtrôs ăt gŭ âk nar ta ƀon Jôpa tâm ngih Y-Simôn, nơm nkra ntâu.$b$,true),
('bunong-vn','ACT',10,1,null,$b$Ta ƀon Sêsarê geh du huê bunuyh amoh Y-Kôrnei, kôranh ta han phung Italy.$b$,true),
('bunong-vn','ACT',10,2,null,$b$Păng ueh sŏng jêh ri geh nau klach yơk ma Brah Ndu, nđâp ma phung tâm ngih păng tâm ban lĕ. Păng ăn yô̆ âk ndơ ma phung ƀon lan jêh ri păng mbơh sơm ƀa ƀơ.$b$,false),
('bunong-vn','ACT',10,3,null,$b$Tâm du nar, dôl tâm sĭn mông bơh ôi, păng saơ ang tâm nau tâm mpơl du huê Tông mpăr ueh Brah Ndu, lăp tâm ngih păng jêh ri lah: “Hơi Y-Kôrnei.”$b$,false),
('bunong-vn','ACT',10,4,null,$b$Măt păng uănh ta Tông mpăr ueh Brah Ndu, jêh ri klach ngăn, păng plơ̆ lah: “Moh nau geh ơ Kôranh Brah?” Tông mpăr ueh Brah Ndu lah: “Nau may mbơh sơm jêh ri ndơ may ăn yô̆ hao tât ta Brah Ndu, jêh ri Brah Ndu kah gĭt nau nây.$b$,false),
('bunong-vn','ACT',10,5,null,$b$Aƀaơ njuăl bunuyh hăn ƀon Jôpa jêh ri kuăl Y-Simôn, tâm amoh Y-Pêtrôs, văch,$b$,false),
('bunong-vn','ACT',10,6,null,$b$Păng gŭ ndrel ma Y-Simôn, nơm nkra ntâu, tâm ngih dăch dak mƀŭt.”$b$,false),
('bunong-vn','ACT',10,7,null,$b$Tơ lah Tông mpăr ueh, nơm ngơi đah păng lĕ du jêh, Y-Kôrnei kuăl bar hê oh mon păng jêh ri du huê ta han ueh sŏng tâm phung tĭng ndrel păng.$b$,true),
('bunong-vn','ACT',10,8,null,$b$Jêh păng nkoch bri lĕ nau nây ma phung khân păng, păng njuăl phung nây hăn ta ƀon Jôpa.$b$,false),
('bunong-vn','ACT',10,9,null,$b$Ôi taơ dôl khân păng hăn, dăch tât ta ƀon di tâm nar nklang bôk, Y-Pêtrôs hao ta klơ chor ngih mbơh sơm.$b$,true),
('bunong-vn','ACT',10,10,null,$b$Păng ji ngot ŭch sông sa, jêh ri dôl ƀư nkra ndơ sông sa păng tât ma nau tâm saơ.$b$,false),
('bunong-vn','ACT',10,11,null,$b$Păng saơ trôk pơk mpơl jêh ri geh ndơ tâm ban ma du blah bok toyh jŭr tât ta neh, kât rdjŭm puăn njônh ndrel.$b$,false),
('bunong-vn','ACT',10,12,null,$b$Tâm nây geh phung mpô mpa puăn jâng ăp ntil, phung mpa vơr ta neh, jêh ri phung sĭm tâm trôk.$b$,false),
('bunong-vn','ACT',10,13,null,$b$Geh du bâr ngơi lah ma păng: “Hơi Y-Pêtrôs, dâk hom, sreh sa hom.”$b$,false),
('bunong-vn','ACT',10,14,null,$b$Y-Pêtrôs plơ̆ lah: “Mâu, Ơ Kôranh Brah, yor lah gâp mâu mâp sa ôh mpa ƀơ̆ , mâu lah mâu kloh.”$b$,false),
('bunong-vn','ACT',10,15,null,$b$Bâr ngơi nây lah tay ma păng tal bar pô aơ: “Moh mpa ndơ Brah Ndu ƀư kloh jêh, lơi uănh păng ƀơ̆ ôh.”$b$,false),
('bunong-vn','ACT',10,16,null,$b$Nau ngơi nây lah pe tơ̆ , jêh ri ƀât lât bok nây hoai sĭt ta klơ trôk.$b$,false),
('bunong-vn','ACT',10,17,null,$b$Dôl Y-Pêtrôs mâu hôm blau mĭn ôh ma nau păng saơ nây, phung bunuyh Y-Kôrnei njuăl hăn tât jêh ta ngih Y-Simôn, jêh ri khân păng tât ta mpông.$b$,true),
('bunong-vn','ACT',10,18,null,$b$Khân păng kuăl huy ôp gĭt lah ta nây Y-Simôn, tâm amoh Y-Pêtrôs gŭ.$b$,false),
('bunong-vn','ACT',10,19,null,$b$Dôl Y-Pêtrôs mĭn ma nau tâm mpơl nây, Brah Huêng Ueh lah ma păng: “Aơ, geh pe nuyh joi may.$b$,false),
('bunong-vn','ACT',10,20,null,$b$Dâk hăn trŭnh, hăn ndrel ma khân păng ro. Lơi ƀư vât vâng, yor lah gâp yơh njuăl khân păng văch.”$b$,false),
('bunong-vn','ACT',10,21,null,$b$Jêh ri Y-Pêtrôs trŭnh hăn ta khân păng jêh ri lah: “Gâp yơh, nơm khân may joi. Moh nau khân may văch?”$b$,false),
('bunong-vn','ACT',10,22,null,$b$Khân păng plơ̆ lah, “Y-Kôrnei, kôranh ta han du huê ueh sŏng jêh ri klach yơk ma Brah Ndu, jêh ri lĕ rngôch phung Yuđa mbơh ma păng jêng nơm ueh, geh nau ntăm tă bơh Tông mpăr ueh kloh ueh, đă kuăl may hăn ta ngih păng, ŭch iăt nau may nti lah.”$b$,false),
('bunong-vn','ACT',10,23,null,$b$Pô ri Y-Pêtrôs ăn phung nây lăp tâm ngih, jêh ri rom khân păng bêch măng ta nây. Ôi taơ păng dâk, hăn ndrel ma phung nây, jêh ri geh ƀa ƀă phung oh nâu tâm ƀon Jôpa hăn ndrel.$b$,false),
('bunong-vn','ACT',10,24,null,$b$Nar pa kơi khân păng tât ta ƀon Sêsarê, Y-Kôrnei kâp khân păng. Păng kuăl tâm rƀŭn jêh phung ndŭl mpôl păng nđâp ma phung mĭt jiăng păng.$b$,false),
('bunong-vn','ACT',10,25,null,$b$Tơ lah Y-Pêtrôs lăp, Y-Kôrnei hăn chuă ta năp păng jêh ri chon mon păn mbah ta jâng păng.$b$,false),
('bunong-vn','ACT',10,26,null,$b$Ƀiă lah Y-Pêtrôs rdâk păng jêh ri lah: “Dâk hom may, gâp tâm ban đŏng jêng bunuyh.”$b$,false),
('bunong-vn','ACT',10,27,null,$b$Dôl ngơi păng lăp jêh ri saơ âk bunuyh tâm rƀŭn.$b$,true),
('bunong-vn','ACT',10,28,null,$b$Păng lah ma phung nây: “Khân may gĭt lĕ, mâu vay ôh du huê Yuđa tâm rnglăp đah phung bu năch, mâu lah lăp ngih păng. Ƀiă lah Brah Ndu tâm mpơl ma gâp jêh, lơi ăn uănh du huê bunuyh ƀơ̆ mâu lah mâu kloh.$b$,false),
('bunong-vn','ACT',10,29,null,$b$Pô ri gâp mâu dun văch ôh ta ngih khân may, tơ lah khân may njuăl bunuyh hăn kuăl gâp. Pô ri gâp ôp, moh nau khân may ŭch kuăl gâp văch?”$b$,false),
('bunong-vn','ACT',10,30,null,$b$Y-Kôrnei plơ̆ lah ma păng: “Geh jêh puăn nar ta mông aơ, dôl gâp mbơh sơm ta sĭn mông ôi tâm ngih gâp, ƀât lât geh du huê bunuyh soh ao nglang ngăn, tâm mpơl ta năp gâp,$b$,true),
('bunong-vn','ACT',10,31,null,$b$jêh ri lah: ‘Hơi Kôrnei, Brah Ndu tăng jêh nau may mbơh sơm, jêh ri păng kah gĭt âk ndơ ăn yô̆, may ăn jêh ma bu.$b$,false),
('bunong-vn','ACT',10,32,null,$b$Pô ri njuăl bunuyh hăn ta ƀon Jôpa, gay ma kuăl Y-Simôn, bu amoh Y-Pêtrôs, văch. Păng gŭ ndrel ma Y-Simôn, bunuyh nkra ntâu, ngih dăch kơh dak mƀŭt.’$b$,true),
('bunong-vn','ACT',10,33,null,$b$Pô ri gâp njuăl bunuyh hăn gơnh đă kuăl may văch ta aơ. Di jêh may văch aƀaơ. Aƀaơ aơ lĕ rngôch hên gŭ ta năp Brah Ndu, gay ma iăt lĕ rngôch nau Kôranh Brah đă may ngơi.”$b$,false),
('bunong-vn','ACT',10,34,null,$b$Jêh ri Y-Pêtrôs ngơi pô aơ: “Nanê̆ gâp gĭt ma Brah Ndu mâu kơp bunuyh êng êng ôh,$b$,true),
('bunong-vn','ACT',10,35,null,$b$ƀiă lah tâm lĕ mpôl băl bunuyh, mbu nơm klach yơk ma Păng, jêh ri ƀư nau sŏng srăng mra ƀư maak ma Păng.$b$,false),
('bunong-vn','ACT',10,36,null,$b$Pô ri nau Păng ngơi jêh ma phung kon Israel dôl mbơh ma khân păng nau đăp mpăn bơh Brah Yêsu Krist, Nơm jêng Kôranh Brah ma lĕ rngôch bunuyh.$b$,false),
('bunong-vn','ACT',10,37,null,$b$Khân may gĭt jêh nau hŏ tât ntơm bơh n'gor Galilê n'ho ma lam n'gor Yuđa pa kơi, jêh Y-Yôhan nti nau ƀaptem.$b$,false),
('bunong-vn','ACT',10,38,null,$b$Khân may gĭt jêh mâm Brah Ndu mbêng ma Brah Yêsu, ƀon Nasaret, ma Brah Huêng Ueh jêh ri nau brah. Păng nsong nti, ƀư ueh, jêh ri ƀư bah lĕ rngôch bunuyh brah mhĭk tŭn jot, yor lah Brah Ndu gŭ ndrel ma Păng.$b$,false),
('bunong-vn','ACT',10,39,null,$b$Hên jêng phung saơ lĕ nau Păng ƀư jêh tâm n'gor Yuđa jêh ri ta ƀon Yêrusalem. Phung Yuđa, pâng nkhĭt Păng ta si tâm rkăng.$b$,false),
('bunong-vn','ACT',10,40,null,$b$Ƀiă lah tăch pe nar Brah Ndu ăn Păng dâk rêh, jêh ri tâm mpơl Păng nơm.$b$,false),
('bunong-vn','ACT',10,41,null,$b$Mâu di ma lĕ rngôch bunuyh ôh, ƀiă lah ma phung Brah Ndu săch jêh bơh lor, jêng phung mbơh, nâm bu ntĭt, phung hên nhêt sa jêh ndrel ma Păng, pa kơi ta nar Păng dâk rêh đŏng.$b$,false),
('bunong-vn','ACT',10,42,null,$b$Jêh ri Păng ntăm jêh ma hên đă nti ma lĕ rngôch bunuyh jêh ri mbơh rah vah ma Brah Ndu njêng Păng jêng kôranh phat dôih ma phung rêh jêh ri phung khĭt.$b$,true),
('bunong-vn','ACT',10,43,null,$b$Lĕ rngôch phung kôranh nơm mbơh lor mbơh jêh ma mbu nơm chroh ma Păng geh nau yô̆ an ma nau tih ma amoh Păng.”$b$,false),
('bunong-vn','ACT',10,44,null,$b$Dôl Y-Pêtrôs ngơi, Brah Huêng Ueh jŭr ta lĕ rngôch phung gŭ iăt nau nti nây.$b$,true),
('bunong-vn','ACT',10,45,null,$b$Jêh ri phung chroh koh ntâu jêh, văch ndrel ma Y-Pêtrôs, hih rhâl ngăn saơ nau ăn Brah Huêng Ueh tât, ma phung bu năch tâm ban lĕ.$b$,true),
('bunong-vn','ACT',10,46,null,$b$Yor lah khân păng tăng nau ngơi nau bu năch, mât ton ma Brah Ndu. Dôl nây Y-Pêtrôs lah pô aơ:$b$,false),
('bunong-vn','ACT',10,47,null,$b$“Dơi lĕ bu dun dak ƀaptem ma phung geh jêh Brah Huêng Ueh tâm ban ma he?”$b$,false),
('bunong-vn','ACT',10,48,null,$b$Jêh ri bu đă păng ƀư ƀaptem ma phung nây, ma amoh Brah Yêsu Krist. Phung nây dăn ma păng gŭ ndrel ma khân păng bar pe nar.$b$,false),
('bunong-vn','ACT',11,1,null,$b$Phung kôranh oh mon jêh ri phung oh nâu tâm n'gor Yuđa gĭt ma phung bu năch dơn Nau Brah Ndu Ngơi,$b$,true),
('bunong-vn','ACT',11,2,null,$b$Jêh ri Y-Pêtrôs hao jêh ta ƀon Yêrusalem, geh phung chroh koh ntâu, nduyh ma păng pô aơ:$b$,false),
('bunong-vn','ACT',11,3,null,$b$“May lăp jêh tâm ngih phung mâu koh ntâu, jêh ri sông sa jêh ndrel ma khân păng!”$b$,false),
('bunong-vn','ACT',11,4,null,$b$Ƀiă lah Y-Pêtrôs nkoch bri ma khân păng, lĕ nau tât jêh pô aơ:$b$,false),
('bunong-vn','ACT',11,5,null,$b$“Dôl gâp gŭ mbơh sơm tâm ƀon Jôpa dôl nây, tât gâp geh tât nau srŭt lang bôk, saơ geh nau tâm mpơl. Geh ndơ tâm ban ma du blah bok toyh kât rdjŭm puăn njônh ndrel, tă bơh trôk jŭr tât ta gâp.$b$,false),
('bunong-vn','ACT',11,6,null,$b$Gâp treng uănh n'hêl nanê̆ jêh ri saơ tâm nây geh phung mpô mpa puăn jâng ăp ntil, phung mpa bri, phung mpô mpa hăn vơr ma ntơh jêh ri phung sĭm tâm trôk.$b$,false),
('bunong-vn','ACT',11,7,null,$b$Jêh ri gâp tăng bâr ngơi lah ma gâp pô aơ: ‘Hơi Y-Pêtrôs, dâk hom may, sreh sa hom.’$b$,false),
('bunong-vn','ACT',11,8,null,$b$Gâp plơ̆ lah: ‘Mâu, Ơ Kôranh Brah yor lah mâu mâp geh mpa ƀơ̆ mâu lah ndơ mâu kloh dơi lăp tâm trôm mbung gâp ôh!’$b$,false),
('bunong-vn','ACT',11,9,null,$b$Bâr ngơi tă bơh trôk lah ma gâp tal bar pô aơ: ‘Moh ndơ Brah Ndu ƀư kloh jêh, lơi may uănh păng ƀơ̆ ôh!’$b$,false),
('bunong-vn','ACT',11,10,null,$b$Geh nau ngơi pô nây pe tơ̆ , jêh ri lĕ rngôch ndơ nây rhuăt tay leo klơ trôk.$b$,false),
('bunong-vn','ACT',11,11,null,$b$Dôl nây ro, pe nuyh bu njuăl ma gâp tă bơh ƀon Sêsarê, tât ta năp mpông ngih gâp gŭ nây.$b$,true),
('bunong-vn','ACT',11,12,null,$b$Brah Huêng Ueh đă gâp hăn ndrel ma khân păng, lơi ƀư vât vâng ôh. Phung prao nuyh oh nâu aơ hăn ndrel ma gâp lĕ, jêh ri hên lăp tâm ngih Y-Kôrnei.$b$,false),
('bunong-vn','ACT',11,13,null,$b$Păng nây nkoch bri ma hên nau păng saơ jêh tâm ngih păng, du huê Tông mpăr ueh Brah Ndu tâm mpơl jêh ri ngơi ma păng pô aơ: ‘Njuăl bunuyh hăn ta ƀon Jôpa, đă kuăl Y-Simôn, tâm amoh Y-Pêtrôs, văch.$b$,true),
('bunong-vn','ACT',11,14,null,$b$Păng mra mbơh ma may nau bu mra tâm rklaih may jêh ri lĕ ngih may.’$b$,true),
('bunong-vn','ACT',11,15,null,$b$Tơ lah gâp ntơm ngơi, Brah Huêng Ueh jŭr ta khân păng, nâm bu Păng jŭr ta phung he lor lơn.$b$,false),
('bunong-vn','ACT',11,16,null,$b$Jêh ri gâp kah gĭt tay nau Kôranh Brah lah jêh: ‘Y-Yôhan ƀư ƀaptem jêh ma dak, ƀiă lah khân may mra dơn nau ƀaptem ma Brah Huêng Ueh.’$b$,true),
('bunong-vn','ACT',11,17,null,$b$Pô ri, tơ lah Brah Ndu ăn ma khân păng du nau yô̆ tâm ban ma he, phung chroh jêh ma Brah Yêsu Krist, dơi lĕ, gâp buay Brah Ndu?”$b$,false),
('bunong-vn','ACT',11,18,null,$b$Jêh tăng pô nây khân păng gŭ đăp mpăn jêh ri tâm rnê ma Brah Ndu pô aơ: “Brah Ndu ăn jêh lĕ ma phung bu năch nau rmal ma nau tih gay ma khân păng geh nau rêh.”$b$,false),
('bunong-vn','ACT',11,19,null,$b$Phung bu hŏ tâm nkhah jêh yor nau ƀư mhĭk, tât ntơm bơh nau Y-Êtiên, hăn tât ta n'gor Phênisi, ta kôdak Chiprơ, jêh ri ta ƀon Antiôs, mbơh Nau Brah Ndu Ngơi knŏng ma phung Yuđa.$b$,true),
('bunong-vn','ACT',11,20,null,$b$Ƀiă lah bơh phung nây geh bar pe nuyh bơh Chiprơ jêh ri bơh ƀon Siren tât ta ƀon Antiôs. Khân păng nti ma phung Grek lĕ jêh ri nkoch nau mhe mhan ueh Brah Yêsu.$b$,false),
('bunong-vn','ACT',11,21,null,$b$Ti Kôranh Brah gŭ ndrel ma khân păng, jêh ri geh âk bunuyh chroh ma Kôranh Brah.$b$,false),
('bunong-vn','ACT',11,22,null,$b$Nau bu mbơh ma khân păng, tât ta phung ngih Brah Ndu tâm ƀon Yêrusalem, jêh ri bu njuăl hăn Y-Ƀarnaƀas, tât ta ƀon Antiôs.$b$,false),
('bunong-vn','ACT',11,23,null,$b$Tơ lah păng tât jêh ta nây, păng saơ nau yô̆ Brah Ndu ăn. Păng maak jêh ri tâm n'hao nuih lĕ rngôch ăn gŭ nâp du ai tâm rnglăp đah Kôranh Brah.$b$,false),
('bunong-vn','ACT',11,24,null,$b$Y-Ƀarnaƀas jêng bunuyh ueh ngăn, bêng ma Brah Huêng Ueh jêh ri nau chroh. Rnôk nây geh âk ngăn bunuyh sĭt ma Kôranh Brah.$b$,true),
('bunong-vn','ACT',11,25,null,$b$Y-Ƀarnaƀas hăn ta ƀon Tars ŭch joi Y-Sôl.$b$,false),
('bunong-vn','ACT',11,26,null,$b$Jêh păng saơ Y-Sôl, păng njŭn leo ta ƀon Antiôs. Trâl du năm khân păng tâm rƀŭn ndrel ma phung ngih Brah Ndu, jêh ri sâm nti âk bunuyh. Pô ri ta ƀon Antiôs yơh, ntơm lor lơn bu rnha, jêng phung Brah Krist.$b$,false),
('bunong-vn','ACT',11,27,null,$b$Tâm rnôk nây geh phung kôranh nơm mbơh lor jŭr tă bơh ƀon Yêrusalem, jŭr ta ƀon Antiôs.$b$,true),
('bunong-vn','ACT',11,28,null,$b$Du huê tâm phung khân păng, amoh păng Y-Agabus, dâk jêh ri mbơh lor Brah Huêng Ueh, mra geh nau sa sât ji ngot toyh lam neh ntu nau sa sât ji ngot nây tât ngăn tâm rnôk hađăch Klôt chiă uănh$b$,false),
('bunong-vn','ACT',11,29,null,$b$Phung oh mon mĭn mra njuăl ndơ kơl ma phung oh nâu chroh gŭ tâm n'gor Yuđa tĭng nâm ndơ khân păng geh.$b$,false),
('bunong-vn','ACT',11,30,null,$b$Khân păng njuăl ndơ kơl ma phung bu bŭnh bu ranh ma ti Y-Ƀarnaƀas jêh ri Y-Sôl.$b$,false),
('bunong-vn','ACT',12,1,null,$b$Rnôk nây lĕ, hađăch Hêrôt ntơm ƀư djơh ma bar pe nuyh tâm phung ngih Brah Ndu.$b$,true),
('bunong-vn','ACT',12,2,null,$b$Păng đă bu nkhĭt Y-Yakơ, nâu Y-Yôhan, ma đao gưm.$b$,false),
('bunong-vn','ACT',12,3,null,$b$Saơ nau nây maak ma phung Yuđa, păng đă bu nhŭp Y-Pêtrôs tâm ban lĕ. Nar nây jêng nar sa kapŭng mâu geh ndrui.$b$,false),
('bunong-vn','ACT',12,4,null,$b$Jêh nhŭp, păng krŭng tâm ndrung. Păng jao ma phung ta han puăn kơn gak, du kơn geh puăn nuyh ta han, hađăch Hêrôt mĭn jêh, lôch nar Nau Găn mra sŏk leo păng ta năp phung ƀon lan.$b$,false),
('bunong-vn','ACT',12,5,null,$b$Pô ri Y-Pêtrôs gŭ tâm ndrung, ƀiă lah phung ngih Brah Ndu mbơh sơm ma Brah Ndu mâu blau hŭnh yor păng.$b$,false),
('bunong-vn','ACT',12,6,null,$b$Măng lor ma hađăch Hêrôt ŭch sŏk păng, ăn ta năp phung ƀon lan, Y-Pêtrôs bêch ta vah vang bar hê ta han chiă, ti păng kât ma bar njăr rse rvăk, jêh ri ta năp bôk mpông geh phung ta han chiă uănh ndrung bu nă.$b$,true),
('bunong-vn','ACT',12,7,null,$b$Ƀât lât du huê Tông mpăr ueh Kôranh Brah văch jêh ri geh nau ang nchrat tâm ndrung. Tông mpăr ueh gŏ Y-Pêtrôs ta pŭng, rlay păng jêh ri lah pô aơ: “Dâk hom gơnh.” Jêh ri rse rvăk tŭp tă bơh ti păng:$b$,true),
('bunong-vn','ACT',12,8,null,$b$Tông mpăr ueh lah ma păng: “Vân hom rse bŭt may, soh ntâu jot”, Y-Pêtrôs tông. Tông mpăr ueh lah ma păng: “Soh hom ao mbâl may hăn tĭng gâp.”$b$,false),
('bunong-vn','ACT',12,9,null,$b$Y-Pêtrôs du luh jêh ri tĭng. Păng mâu gĭt nau Tông mpăr ueh nây jêng ngăn, ƀiă lah păng mĭn ma nau păng mbơi saơ.$b$,false),
('bunong-vn','ACT',12,10,null,$b$Tơ lah khân păng rgăn lăn jêh ntŭk ta han chiă tal nguay, n'ho ma tal bar, khân păng tât ta mpông pêr nây pơk êng păng, ta năp khân păng. Khân păng luh hăn ta trong sâng. Ƀât lât, Tông mpăr ueh du bơh Y-Pêtrôs.$b$,false),
('bunong-vn','ACT',12,11,null,$b$Tơ lah Y-Pêtrôs mĭn nanê̆ jêh, păng lah pô aơ: “Aƀaơ aơ mơ gâp gĭt ngăn, Kôranh Brah njuăl jêh Tông mpăr ueh Păng, tâm rklaih gâp bơh ti hađăch Hêrôt, jêh ri bơh lĕ nau phung Yuđa ŭch ƀư ma gâp”,$b$,true),
('bunong-vn','ACT',12,12,null,$b$jêh păng mĭn, păng hăn ta ngih H'Mari, mê̆ Y-Yôhan, trơn amoh Y-Markôs. Ta nây geh âk bunuyh gŭ rƀŭn mbơh sơm.$b$,false),
('bunong-vn','ACT',12,13,null,$b$Păng goh mpông pa dih, geh du huê bu ur, amoh H'Rôt hăn iăt.$b$,false),
('bunong-vn','ACT',12,14,null,$b$Jêh gĭt năl bâr Y-Pêtrôs, păng răm ngăn, tât mâu hôm pơk mpông ôh, ƀiă lah păng sĭt mbơh ma bu, Y-Pêtrôs gŭ pa năp mpông.$b$,false),
('bunong-vn','ACT',12,15,null,$b$Bu lah ma păng: “Ay rluk.” Ƀiă lah păng râng nau nây jêng ngăn. Khân păng lah: “Tông mpăr ueh păng yơh!”$b$,false),
('bunong-vn','ACT',12,16,null,$b$Ƀiă lah Y-Pêtrôs ăt goh ngăn. Tơ lah jêh pơk mpông, khân păng hih rhâl ngăn saơ Y-Pêtrôs.$b$,true),
('bunong-vn','ACT',12,17,null,$b$Ƀiă lah Y-Pêtrôs yơr ti đă khân păng gŭ rklăk, jêh ri nkoch bri mâm nau Kôranh Brah rklaih jêh păng tă bơh ndrung nây: “Mbơh hom nau aơ ma Y-Yakơ jêh ri ăn phung oh nâu gĭt.” Jêh nau nây păng luh du, hăn ta ntŭk êng.$b$,false),
('bunong-vn','ACT',12,18,null,$b$Lah trôk ang jêh, geh nau uh ah toyh tâm phung ta han, yor lah khân păng mâu gĭt ôh moh nau tât jêh ma Y-Pêtrôs.$b$,true),
('bunong-vn','ACT',12,19,null,$b$Hađăch Hêrôt đă bu joi ƀiă lah mâu hôm dơi saơ ôh. Păng sek ôp phung ta han chiă jêh ri đă bu nhŭp nkhĭt lơi. Jêh ma nây hađăch jŭr tă bơh n'gor Yuđa hăn ta ƀon Sêsarê, păng gŭ ta nây.$b$,true),
('bunong-vn','ACT',12,20,null,$b$Hađăch Hêrôt nuih ma phung Tyr jêh ri phung Sidôn, ƀiă lah phung nây, tă sa jiăng đah Y-Blastus, du huê kôranh toyh păng, khân păng du ai ndrel hăn ta hađăch dăn nau đăp mpăn, yor lah n'gor khân păng geh ndơ sông sa bơh n'gor hađăch.$b$,true),
('bunong-vn','ACT',12,21,null,$b$Tât ta nar tâm nal, jêh hađăch Hêrôt nkrơ̆ ndơ hađăch, gŭ ta klơ sưng, jêh ri nti lah ta năp phung âk.$b$,false),
('bunong-vn','ACT',12,22,null,$b$Phung ƀon lan nter lah: “Bâr aơ brah ngơi, mâu di bâr bunuyh ôh!”$b$,false),
('bunong-vn','ACT',12,23,null,$b$Ƀât lât geh du huê Tông mpăr ueh Kôranh Brah dong hađăch Hêrôt yor lah păng mâu yơk ma Brah Ndu ôh, jêh ri păng khĭt rhai sa.$b$,false),
('bunong-vn','ACT',12,24,null,$b$Ƀiă lah Nau chroh Brah Ndu lơ hâu bu tăng lư lam ntŭk.$b$,true),
('bunong-vn','ACT',12,25,null,$b$Y-Ƀarnaƀas jêh ri Y-Sôl, jêh lôch kan khân păng, sĭt tă ƀon Yêrusalem, jă hăn ndrel ma khân păng Y-Yôhan, trơn amoh Y-Markôs.$b$,false),
('bunong-vn','ACT',13,1,null,$b$Tâm phung ngih Brah Ndu ƀon Antiôs geh phung kôranh nơm mbơh lor, jêh ri phung kôranh nơm nti Y-Ƀarnaƀas, Y-Simêôn, ntơ amoh Y-Niger, Y-Lusius, n'gor Siren, Y-Manahen, nơm bu rong ndrel ma hađăch Hêrôt, jêh ri Y-Sôl.$b$,true),
('bunong-vn','ACT',13,2,null,$b$Dôl khân păng ƀư nau yơk ma Kôranh Brah jêh ri ver sông sa, Brah Huêng Ueh lah ma khân păng pô aơ: “Prăp êng, Y-Ƀarnaƀas jêh ri Y-Sôl ma kan gâp kuăl khân păng jêh.”$b$,true),
('bunong-vn','ACT',13,3,null,$b$Jêh khân păng ver sông sa jêh ri mbơh sơm khân păng pah ti ma phung nây jêh ri ăn phung nây hăn.$b$,true),
('bunong-vn','ACT',13,4,null,$b$Pô ri Brah Huêng Ueh njuăl Y-Sôl ndrel ma Y-Ƀarnaƀas jŭr ta ƀon Sêlusi; tă bơh nây khân păng ncho kŭmpăn hăn ta kôdak Chiprơ.$b$,true),
('bunong-vn','ACT',13,5,null,$b$Tât ta ƀon Salamin khân păng mbơh Nau chroh Brah Ndu tâm ngih rƀŭn phung Yuđa, geh nđâp ma Y-Yôhan kơl ndrel.$b$,false),
('bunong-vn','ACT',13,6,null,$b$Jêh khân păng rgăn lĕ kôdak tât ta ƀon Paphôs, khân păng mâp du huê Yuđa n'hŭm, kôranh nơm mbơh lor tih, amoh păng, Y-Bar Yêsu.$b$,false),
('bunong-vn','ACT',13,7,null,$b$Păng gŭ ndrel ma du huê kôranh n'gor, amoh păng Y-Serjus Pôlus. Păng geh âk nau blau mĭn, jêh ri đă bu kuăl Y-Ƀarnaƀas jêh ri Y-Sôl yor lah păng ŭch iăt Nau Brah Ndu Ngơi.$b$,false),
('bunong-vn','ACT',13,8,null,$b$Ƀiă lah Y-Êlimas, bunuyh n'hŭm rƀên (pô ri nâm bu ntĭt amoh păng), buay lơi phung nây gay ma nsak lơi nau chroh kôranh n'gor nây.$b$,false),
('bunong-vn','ACT',13,9,null,$b$Rnôk nây Y-Sôl tâm amoh păng Y-Pôl bêng ma Brah Huêng Ueh uănh ta păng jêh ri lah pô aơ:$b$,false),
('bunong-vn','ACT',13,10,null,$b$“Hơi bunuyh bêng ma nau mƀruh, jêh ri nau ƀai, kon brah mhĭk, rlăng ma lĕ nau sŏng, may mâu mra lơi hĕ nau ƀư tih trong sŏng Kôranh Brah?$b$,false),
('bunong-vn','ACT',13,11,null,$b$Aƀaơ aơ, ti Kôranh Brah ƀư ma may, may mra chieh măt, jŏ ma nây may mâu mra saơ nar ôh.” Ƀât lât nau ngo tŭp ta Y-Êlimas jêh ri păng joi rvơ uănh, gay geh bunuyh njŭn păng.$b$,false),
('bunong-vn','ACT',13,12,null,$b$Kôranh n'gor saơ nau tât nây chroh ro, hih rhâl ngăn ma nau nti tă bơh Kôranh Brah.$b$,false),
('bunong-vn','ACT',13,13,null,$b$Y-Pôl jêh ri phung băl păng ncho kŭmpăn ta ƀon Paphôs hăn tât ta ƀon Pergi tâm n'gor Pamphili. Y-Yôhan tâm nkhah đah khân păng jêh ri sĭt tay ta ƀon Yêrusalem.$b$,true),
('bunong-vn','ACT',13,14,null,$b$Tă bơh ƀon Pergi khân păng n'ho hăn tât ta ƀon Antiôs, n'gor Pisidi. Nar Saƀat khân păng lăp gŭ tâm ngih tâm rƀŭn Yuđa.$b$,false),
('bunong-vn','ACT',13,15,null,$b$Jêh ri bu uănh ndrom sămƀŭt nau vay, nau kôranh nơm mbơh lor, kôranh ngih tâm rƀŭn Yuđa lah ma khân păng: “Hơi phung oh nâu, tơ lah khân may geh nau nti ma ƀon lan, ngơi hom.”$b$,false),
('bunong-vn','ACT',13,16,null,$b$Y-Pôl gŭ dâk, yơr ti lah: “Hơi phung kon Israel jêh ri phung klach yơk ma Brah Ndu, gŭ iăt hom:$b$,false),
('bunong-vn','ACT',13,17,null,$b$Brah Ndu phung Israel săch jêh phung mbơ̆ he. Păng ăn phung nây geh lư n'găr dôl gŭ tâm n'gor Êjipt, jêh ri ăn khân păng luh tă bơh ti jâng ktang păng.$b$,false),
('bunong-vn','ACT',13,18,null,$b$Păng siăm phung nây tâm bri rdah dôl tâm puăn jât năm.$b$,true),
('bunong-vn','ACT',13,19,null,$b$Jêh păng ƀư rai pơh phung mpôl băl tâm n'gor Kanaan, păng jao n'gor phung nây ma phung Israel dôl tâm puăn rhiăng prăm jât năm.$b$,false),
('bunong-vn','ACT',13,20,null,$b$Jêh ri păng ăn ma khân păng phung kôranh phat dôih, ma phung nây tâm rnôk kôranh nơm mbơh lor Y-Samuel.$b$,false),
('bunong-vn','ACT',13,21,null,$b$Rnôk nây phung Israel dăn, du huê hađăch. Brah Ndu ăn ma khân păng Y-Sôl, kon bu klâu Y-Kis bơh ndŭl mpôl Benjamin jêng hađăch puăn jât năm.$b$,false),
('bunong-vn','ACT',13,22,null,$b$Jêh Brah Ndu cha lơi Y-Sôl, păng njêng Y-Đavit hađăch jêh ri mbơh ma păng pô aơ: ‘Gâp saơ jêh Y-Đavit, kon bu klâu Y-Yêsê, nơm ƀư maak gâp, jêh ri ƀư lĕ nau gâp ŭch.’$b$,false),
('bunong-vn','ACT',13,23,null,$b$Tĭng nâm nau păng ton jêh, Brah Ndu ăn du huê Nơm tâm rklaih, păng yơh Brah Yêsu, luh tă bơh kon sau Y-Đavit.$b$,false),
('bunong-vn','ACT',13,24,null,$b$Lor ma păng văch, Y-Yôhan nti jêh ma lĕ rngôch phung Israel nau ƀaptem rmal ma nau tih.$b$,false),
('bunong-vn','ACT',13,25,null,$b$Dôl Y-Yôhan ƀư jêh kan Păng, Păng lah pô aơ: ‘Gâp mâu di bunuyh khân may mĭn ôh. Ƀiă lah geh du huê văch pa kơi gâp taơ, gâp mâu khư doh rse ntâu jot Păng ôh.’$b$,true),
('bunong-vn','ACT',13,26,null,$b$“Hơi phung oh nâu gâp, phung kon sau Y-Abraham jêh ri phung klach yơk ma Brah Ndu, ma khân may yơh bu mbơh ma nau tâm rklaih aơ.$b$,false),
('bunong-vn','ACT',13,27,null,$b$Yor lah phung ƀon lan, ƀon Yêrusalem nđâp phung kôranh khân păng, mâu gĭt năl ôh Brah Yêsu aơ, dôl phat dôih ô băl, khân păng nanê̆ jêh nau phung kôranh nơm mbơh lor nchih jêh. Nau nây khân păng uănh ăp nar Saƀat ƀiă lah mâu gĭt rbăng.$b$,false),
('bunong-vn','ACT',13,28,null,$b$Jêh khân păng mâu saơ tâm ô băl, nau khư tâm nkhĭt, khân păng ăt dăn ma Pilat gay ma nkhĭt.$b$,false),
('bunong-vn','ACT',13,29,null,$b$Tơ lah jêh khân păng nanê̆ nau bu nchih mbơh ô băl, khân păng njŭr ô băl bơh si tâm rkăng jêh ri tâp tâm môch.$b$,false),
('bunong-vn','ACT',13,30,null,$b$Ƀiă lah Brah Ndu ăn Păng dâk rêh đŏng.$b$,false),
('bunong-vn','ACT',13,31,null,$b$Dôl âk nar Păng mpơl ma phung hăn ndrel ma Păng ntơm bơh n'gor Galilê, tât ta ƀon Yêrusalem. Phung nây aƀaơ jêng phung mbơh ta năp phung ƀon lan.$b$,false),
('bunong-vn','ACT',13,32,null,$b$Jêh ri hên mbơh ma khân may nau mhe mhan ueh Brah Ndu ton jêh ma phung u che he.$b$,false),
('bunong-vn','ACT',13,33,null,$b$Brah Ndu ăn nanê̆ jêh nau ton nây ma he, phung kon sau khân păng, yor păng ăn Brah Yêsu dâk rêh đŏng, nâm bu hŏ nchih jêh tâm nau Mprơ ơm mrô bar: ‘May jêng kon gâp, gâp deh ma may nar aơ!’$b$,false),
('bunong-vn','ACT',13,34,null,$b$Ma nau Brah Ndu ăn păng dâk rêh đŏng, aƀaơ Păng mâu hôm sĭt ma nau ôm rai ôh, Păng lah pô aơ: ‘Gâp mra ăn ma khân may nau yô̆ ueh uĭn nanê̆ ngăn, ton jêh ma Y-Đavit.’$b$,false),
('bunong-vn','ACT',13,35,null,$b$Yor amoh Păng ăt lah tâm Nau Mprơ Ơm êng: ‘May mâu ăn Nơm Kloh Ueh may blau ôm ôh!’$b$,false),
('bunong-vn','ACT',13,36,null,$b$Ƀiă lah jêh pah kan tâm rnôk Păng, tĭng nâm Brah Ndu ŭch Y-Đavit khĭt, jêh ri bu tâp păng ndrel ma phung mbơ̆ păng, jêh ri păng ôm jêh.$b$,false),
('bunong-vn','ACT',13,37,null,$b$Ƀiă lah nơm Brah Ndu ăn dâk rêh nây mâu blau ôm ôh.$b$,false),
('bunong-vn','ACT',13,38,null,$b$Hơi phung oh nâu, ăn khân may gĭt ma Păng yơh, bu mbơh jêh ma khân may nau yô̆ an ma nau tih.$b$,false),
('bunong-vn','ACT',13,39,null,$b$Jêh ri ma Păng yơh mbu nơm chroh, Păng mra kơp sŏng ma lĕ rngôch nau bu mâu dơi kơp sŏng ôh ma nau vay Y-Môis.$b$,false),
('bunong-vn','ACT',13,40,null,$b$Pô ri njrăng hom, lơi ăn tât ma khân may tĭng nâm nau phung kôranh nơm mbơh lor mbơh jêh pô aơ:$b$,false),
('bunong-vn','ACT',13,41,null,$b$‘Uănh hom, Hơi phung dăng mưch! Hih rhâl hom jêh ri rai lôch hom; Yor lah gâp mra ƀư du ntil kan tâm rnôk may, du ntil kan khân may mâu mra chroh ôh, tơ lah bu nkoch bri ma khân may!’ ”$b$,false),
('bunong-vn','ACT',13,42,null,$b$Dôl khân păng du luh, bu dăn ma khân păng ngơi tay nau nây lĕ nar Saƀat pa kơi.$b$,true),
('bunong-vn','ACT',13,43,null,$b$Tơ lah lôch nau tâm rƀŭn geh âk phung Yuđa jêh ri phung lăp jêng Yuđa sŏng srăng tĭng ndô̆ Y-Pôl, jêh ri Y-Ƀarnaƀas. Phung nây nkoch bri ma khân păng jêh ri nti lah đă gŭ nâp tâm nau Brah Ndu yô̆.$b$,true),
('bunong-vn','ACT',13,44,null,$b$Nar Saƀat pa kơi bơi ma lĕ ƀon nây tâm rƀŭn ŭch iăt Nau Brah Ndu Ngơi.$b$,true),
('bunong-vn','ACT',13,45,null,$b$Ƀiă lah phung Yuđa saơ phung âk nây, khân păng bêng ma nau nach, tâm rdâng đah nau Y-Pôl ngơi hâu ngăn, rtăp, suai rak ma ô băl,$b$,false),
('bunong-vn','ACT',13,46,null,$b$Y-Pôl jêh ri Y-Ƀarnaƀas lah ma khân păng ma nau janh ktang: “Hên ŭch mbơh Nau Brah Ndu Ngơi ma khân may lor lơn, ƀiă lah yor lah khân may mĭn, khân may nơm nâu khư dơn nau rêh n'ho ro, jêh ri hên rle ma phung bu năch.$b$,false),
('bunong-vn','ACT',13,47,null,$b$Yor lah Kôranh Brah lah jêh ma hên pô aơ: ‘Gâp njêng jêh khân may nau ang ma phung bu năch, gay ma khân may njŭn leo nau tâm rklaih tât ta ntŭk dŭt neh.’ ”$b$,false),
('bunong-vn','ACT',13,48,null,$b$Phung bu năch tăng nau nây răm ngăn, jêh ri khân păng tâm rnê ma Nau Brah Ndu Ngơi; jêh ri lĕ rngôch mbu nơm Brah Ndu săch jêh, ma nau rêh n'ho ro chroh.$b$,true),
('bunong-vn','ACT',13,49,null,$b$Nau Kôranh Brah Ngơi bu tăng lư lam n'gor nây.$b$,true),
('bunong-vn','ACT',13,50,null,$b$Ƀiă lah ntrŭt phung bu ur sŏng srăng, bu yơk, jêh ri phung kôranh tâm ƀon. Khân păng joi nau ƀư djơh ma Y-Pôl jêh ri Y-Ƀarnaƀas, mprơh lơi khân ô băl bơh n'gor khân păng.$b$,false),
('bunong-vn','ACT',13,51,null,$b$Y-Pôl jêh ri Y-Ƀarnaƀas rtuh ndruyh jâng khân păng ma phung nây jêh ri hăn ta ƀon Ikôni.$b$,false),
('bunong-vn','ACT',13,52,null,$b$Bi phung oh mon bêng ma nau răm maak jêh ri Brah Huêng Ueh.$b$,false),
('bunong-vn','ACT',14,1,null,$b$Ta ƀon Ikôni Y-Pôl jêh ri Y-Ƀarnaƀas, lăp ndrel tâm ngih tâm rƀŭn Yuđa, jêh ri khân păng nti tât geh âk phung Yuđa jêh ri phung Grek chroh.$b$,true),
('bunong-vn','ACT',14,2,null,$b$Đơ phung Yuđa mâu chroh nsônh, jêh ri ăn phung bu năch ji nuih ma phung oh nâu.$b$,false),
('bunong-vn','ACT',14,3,null,$b$Ƀiă lah Y-Pôl ndrel ma Y-Ƀarnaƀas gŭ ta nây jŏ nar. Khân păng bêng ma nau janh ktang tâm Kôranh Brah, jêh ri Kôranh Brah dŏng ti khân păng ƀư nau khlay, jêh ri nau tâm mbên khlay, mbơh nau ngơi ma nau yô̆.$b$,false),
('bunong-vn','ACT',14,4,null,$b$Ƀiă lah phung ƀon lan tâm pă, ƀa ƀă gŭ mpeh phung Yuđa, ƀa ƀă mpeh ma phung oh mon.$b$,false),
('bunong-vn','ACT',14,5,null,$b$Pô ri phung bu năch jêh ri phung Yuđa, nđâp ma kôranh khân păng ntơm, ƀư djơh jêh ri klŭp lŭ ma phung oh mon.$b$,false),
('bunong-vn','ACT',14,6,null,$b$Ƀiă lah Y-Pôl jêh ri Y-Ƀarnaƀas gĭt nau nây bơh lor jêh ri nchuăt du ntŭng hăn ta n'gor Likaoni, ƀon Listrơ, ƀon Đerbơ jêh ri tâm ƀon dăch dăch.$b$,false),
('bunong-vn','ACT',14,7,null,$b$Ta nây khân păng mbơh nau mhe mhan ueh. Y-Pôl jêh ri Y-Ƀarnaƀas ta ƀon Listrơ.$b$,true),
('bunong-vn','ACT',14,8,null,$b$Ta ƀon Listrơ geh du huê bunuyh dăng jâng, păng hăn tĭl dĭt ntơm bơh mê̆ păng deh, jêh ri păng mâu mâp hăn.$b$,true),
('bunong-vn','ACT',14,9,null,$b$Păng gŭ iăt Y-Pôl nti, Y-Pôl uănh ta păng jêh ri saơ păng geh nau chroh dơi ƀư bah.$b$,false);
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','ACT',14,10,null,$b$Lah ma bâr huy: “Dâk hom may, gŭ râng sŏng.” Păng nsăt du tơ̆ jêh ri ntơm hăn.$b$,false),
('bunong-vn','ACT',14,11,null,$b$Phung ƀon lan saơ nau Y-Pôl ƀư, nter ma nau phung Likaoni ngơi, pô aơ: “Phung brah sŏk rup bunuyh văch jêh ta he!”$b$,false),
('bunong-vn','ACT',14,12,null,$b$Khân păng tâm amoh Yupitê ma Y-Ƀarnaƀas jêh ri Merkurơ ma Y-Pôl, yor lah păng yơh nơm ngơi.$b$,false),
('bunong-vn','ACT',14,13,null,$b$Kôranh ƀư brah ma brah Yupitê, geh ngih brah ta mpông pêr ƀon, têk leo ndrôk nkuăng ta năp bôk mpông ndrel ma rvang kao jêh ri geh du ai nau đah phung ƀon lan, gay ma nhhơr ndơ ƀư brah ma khân păng.$b$,false),
('bunong-vn','ACT',14,14,null,$b$Tơ lah Y-Ƀarnaƀas ndrel ma Y-Pôl gĭt nau nây, khân păng nkhêk bok ao khân păng, jêh ri hăn nchuăt nter tâm nklang phung âk nây pô aơ:$b$,false),
('bunong-vn','ACT',14,15,null,$b$“Hơi phung bunuyh, moh nau khân may ƀư pô nây? Hên jêng bunuyh tâm ban ma khân may lĕ, jêh ri hên mbơh ma khân may nau mhe mhan ueh, gay ma khân may lơi phung brah dơm dam jêh ri sĭt ma Brah Ndu rêh, nơm rhăk njêng jêh trôk, neh ntu, dak mƀŭt jêh ri lĕ rngôch mpa tâm păng.$b$,false),
('bunong-vn','ACT',14,16,null,$b$Tâm rnôk kăl e păng cha lơi ăn phung bunuyh tĭng trong khân păng nơm;$b$,false),
('bunong-vn','ACT',14,17,null,$b$ƀiă lah păng ăt mbơh ma păng nơm dôl păng ƀư ueh. Păng ăn trôk mih jêh ri ăn yan geh play âk, ăn ndơ sông sa âk rmeh, jêh ri nuih n'hâm khân may bêng ma nau răm maak.”$b$,false),
('bunong-vn','ACT',14,18,null,$b$Jêh khân păng ngơi nau nây kđôi, ăt ma nau jêr khân păng dơi buay phung âk nây ƀư brah ma khân păng.$b$,false),
('bunong-vn','ACT',14,19,null,$b$Rnôk nây geh phung Yuđa văch tă bơh ƀon Antiôs jêh ri ƀon Ikôni. Khân păng ntrŭt phung ƀon lan, jêh ri khân păng klŭp lŭ ma Y-Pôl. Khân păng têk ô băl luh pa dih ƀon, yor lah khân păng ntôn lah Y-Pôl khĭt jêh.$b$,true),
('bunong-vn','ACT',14,20,null,$b$Ƀiă lah dôl phung oh mon gŭ rƀŭn jŭm păng, păng dâk jêh ri hăn lăp tâm ƀon. Ơm ôi taơ, Y-Pôl hăn ta ƀon Đerbơ ndrel ma Y-Ƀarnaƀas.$b$,false),
('bunong-vn','ACT',14,21,null,$b$Jêh khân păng mbơh nau mhe mhan ueh tâm ƀon nây jêh ri geh âk bunuyh chroh, khân păng plơ̆ sĭt ta ƀon Listrơ, ƀon Ikôni, jêh ri ƀon Antiôs,$b$,true),
('bunong-vn','ACT',14,22,null,$b$tâm n'hao nuih phung oh mon, nti ma khân păng, ăn srôih tâm nau chroh, jêh ri mbơh ma khân păng, ma âk nau jêr yơh he dơi lăp tâm ƀon bri hađăch Brah Ndu.$b$,false),
('bunong-vn','ACT',14,23,null,$b$Jêh khân păng săch phung bu bŭnh bu ranh ăp ngih Brah Ndu. Jêh khân păng mbơh sơm jêh ri ver sông sa, khân păng jao phung nây ma Kôranh Brah, nơm khân păng chroh.$b$,false),
('bunong-vn','ACT',14,24,null,$b$Jêh khân păng rgăn n'gor Pisidi khân păng tât ta n'gor Pamphili.$b$,false),
('bunong-vn','ACT',14,25,null,$b$Jêh ri jêh khân păng nti ta ƀon Pergi, khân păng jŭr hăn ta ƀon Atali.$b$,false),
('bunong-vn','ACT',14,26,null,$b$Ntơm bơh nây khân păng ncho kŭmpăn hăn leo ta Antiôs, bơh ƀon nây bu jao khân păng ma nau Brah Ndu yô̆, gay pah kan khân păng mhe ƀư jêh.$b$,false),
('bunong-vn','ACT',14,27,null,$b$Jêh khân păng tât ta nây, khân păng tâm rƀŭn phung ngih Brah Ndu, jêh ri nkoch bri lĕ nau Brah Ndu đă khân păng ƀư, jêh ri mâm ƀư păng pơk jêh mpông nau chroh ma phung bu năch.$b$,true),
('bunong-vn','ACT',14,28,null,$b$Jêh ri khân păng gŭ ta nây jŏ ndrel ma phung oh mon.$b$,false),
('bunong-vn','ACT',15,1,null,$b$Rnôk nây, geh ƀa ƀă văch tă bơh n'gor Yuđa nti ma phung oh nâu pô aơ: “Tơ lah khân may mâu koh ntâu tĭng nâm nau vay Y-Môis, khân may mâu dơi geh nau tâm rklaih ôh.”$b$,true),
('bunong-vn','ACT',15,2,null,$b$Y-Pôl jêh ri Y-Ƀarnaƀas, geh nau tâm dun ktang đah phung nây. Pô ri bu ŭch ma Y-Pôl jêh ri Y-Ƀarnaƀas ndrel ma bar pe nuyh tâm phung nây, hăn ta ƀon Yêrusalem, tât ta phung kôranh oh mon jêh ri phung bu ranh gay ôp ma nau nây.$b$,false),
('bunong-vn','ACT',15,3,null,$b$Jêh phung ngih Brah Ndu leo trong, khân păng n'ho rgăn Phênisi, jêh ri n'gor Phênisi Samari, nkoch bri nau phung bu năch chroh. Nau nây ăn nau maak ngăn ma lĕ rngôch phung oh nâu.$b$,false),
('bunong-vn','ACT',15,4,null,$b$Tât ta ƀon Yêrusalem, phung ngih Brah Ndu, phung kôranh oh mon, jêh ri phung bu bŭnh bu ranh rom khân păng, jêh ri khân păng nkoch bri ma phung nây lĕ nau Brah Ndu đă khân păng ƀư.$b$,false),
('bunong-vn','ACT',15,5,null,$b$Ƀiă lah geh ƀa ƀă tâm phung Pharisi chroh jêh, dâk jêh ri lah: “Ăn koh ntâu, nđâp ma phung bu năch tâm ban lĕ, jêh ri ntăm ma khân păng tông nau vay Y-Môis.”$b$,false),
('bunong-vn','ACT',15,6,null,$b$Phung kôranh oh mon, jêh ri phung bu bŭnh bu ranh tâm rƀŭn, ŭch sek uănh nau nây.$b$,true),
('bunong-vn','ACT',15,7,null,$b$Jêh geh nau tâm nchră âk ngăn, Y-Pêtrôs dâk jêh ri lah ma khân păng pô aơ: “Hơi phung oh nâu, khân may gĭt bơh jŏ jêh, Brah Ndu săch gâp tâm phung khân may, ăn nti nau mhe mhan ueh ma phung bu năch jêh ri khân păng chroh.$b$,false),
('bunong-vn','ACT',15,8,null,$b$Jêh ri Brah Ndu, Nơm dơi gĭt nuih n'hâm bunuyh, mbơh nanê̆ jêh ma phung bu năch dôl ăn Brah Huêng Ueh ma khân păng tâm ban ma phung he.$b$,false),
('bunong-vn','ACT',15,9,null,$b$Păng mâu uănh phung he đah phung bu năch jêng êng êng ôh, yor lah păng ƀư kloh nuih n'hâm khân păng ma nau chroh.$b$,false),
('bunong-vn','ACT',15,10,null,$b$Pô ri aƀaơ, mâm ƀư khân may rlong uănh Brah Ndu, jêh ri dơm ta trô ko phung oh mon du mlâm mâng mbăk? Mâng mbăk nây phung mbơ̆ he jêh ri phung he nơm mâu dơi mbăk lĕ.$b$,false),
('bunong-vn','ACT',15,11,null,$b$Ƀiă lah he chroh yor nau yô̆ Brah Yêsu yơh, he tâm rklaih tâm ban ma khân păng lĕ!”$b$,false),
('bunong-vn','ACT',15,12,null,$b$Lĕ rngôch phung rƀŭn gŭ rklăk, jêh ri iăt nau Y-Ƀarnaƀas jêh ri Y-Pôl nkoch bri lĕ rngôch nau khlay jêh ri nau tâm mbên khlay, Brah Ndu đă khân păng ƀư jêh ta nklang phung bu năch.$b$,true),
('bunong-vn','ACT',15,13,null,$b$Jêh khân păng rlu ngơi, Y-Yakơ lah pô aơ: “Hơi phung oh nâu, iăt nau gâp!$b$,false),
('bunong-vn','ACT',15,14,null,$b$Y-Simêôn nkoch bri jêh, mâm ƀư tal lor Brah Ndu uănh jêh ma mpôl băl phung bu năch, gay ma săch, tă bơh khân păng du phung prăp ma amoh Păng.$b$,false),
('bunong-vn','ACT',15,15,null,$b$Nau nây tâm di jêh đah nau kôranh nơm mbơh lor, yor lah bu nchih jêh pô aơ:$b$,false),
('bunong-vn','ACT',15,16,null,$b$‘Jêh nau nây, gâp mra plơ̆ sĭt, jêh ri rdâk tay ngih bok Y-Đavit, ngih nây cha lôt rai jêh; gâp mra nkra tay ndơ ơm lĕ djơh nây, jêh ri ndâk tay păng,$b$,false),
('bunong-vn','ACT',15,17,null,$b$Gay ma phung bunuyh hôm e, jêh ri lĕ rngôch phung bu năch kuăl amoh gâp, joi Kôranh Brah.$b$,false),
('bunong-vn','ACT',15,18,null,$b$Kôranh Brah jêng Nơm dơi ƀư lĕ nau aơ jêh ri Nơm gĭt jêh, lĕ bơh lor lah pô nây!’$b$,true),
('bunong-vn','ACT',15,19,null,$b$Yor nây tĭng nâm nau gâp mĭn lơi ta he joi nau ƀư jêr, ma phung bu năch chroh ma Brah Ndu ôh.$b$,false),
('bunong-vn','ACT',15,20,null,$b$Ƀiă lah ăn he nchih sămƀŭt ntăm ma khân păng, ăn ver lĕ rngôch nau ƀơ̆ ƀơch, mbah rup brah, nau văng tĭr, sa mpô mpa khĭt măp, jêh ri mham.$b$,false),
('bunong-vn','ACT',15,21,null,$b$Yor lah ntơm bơh âk rnôk jêh, geh tâm ăp mƀon phung nti nau vay Y-Môis, jêh ri bu uănh nau vay nây ăp nar Saƀat tâm ngih rƀŭn Yuđa.”$b$,false),
('bunong-vn','ACT',15,22,null,$b$Rnôk nây phung kôranh oh mon, phung bu bŭnh bu ranh, jêh ri lĕ rngôch phung ngih Brah Ndu mĭn ueh, mra săch tâm phung khân păng, jêh ri njuăl hăn ndrel ma Y-Pôl, jêh ri Y-Ƀarnaƀas ta ƀon Antiôs. Khân păng săch Y-Yuđas, trơn amoh Y-Ƀarnaƀas, jêh ri Y-Silas bar hê geh nau bu yơk tâm phung oh nâu.$b$,true),
('bunong-vn','ACT',15,23,null,$b$Jêh ri khân păng jao ma phung nây du pŏk sămƀŭt pô aơ: “Phung kôranh oh mon, phung bu bŭnh bu ranh, jêh ri phung oh nâu nchih sămƀŭt khâl, ma phung oh nâu tâm phung bu năch chroh, ta ƀon Antiôs, tâm n'gor Siri, jêh ri n'gor Silisi,$b$,false),
('bunong-vn','ACT',15,24,null,$b$hên tăng jêh geh bunuyh ƀa ƀă hăn tă bơh phung hên, mâu mâp geh nau ntăm tă bơh phung hên ôh, rsuak jêh khân may ma nau khân păng ngơi, ƀư phit nuih n'hâm khân may.$b$,false),
('bunong-vn','ACT',15,25,null,$b$Pô ri, lĕ rngôch hên dơn du nau mĭn ueh gay ma săch phung tâm tang ma hên, jêh ri njuăl khân păng hăn ndrel ma Y-Ƀarnaƀas, jêh ri Y-Pôl, phung hên rŏng ngăn.$b$,false),
('bunong-vn','ACT',15,26,null,$b$Phung bunuyh nây sân săk jăn khân păng ma amoh Kôranh Brah he, Yêsu Krist.$b$,false),
('bunong-vn','ACT',15,27,null,$b$Hên njuăl jêh Y-Yuđas jêh ri Y-Silas, phung nây mra ngơi đah khân may ma nau nây tâm ban lĕ.$b$,false),
('bunong-vn','ACT',15,28,null,$b$Yor lah Brah Huêng Ueh, jêh ri hên mĭn ueh, mâu dơm nau jâk êng ma khân may ôh, ƀiă lah knŏng nau khlay aơ,$b$,false),
('bunong-vn','ACT',15,29,null,$b$ăn khân may ver sa ndơ ƀư brah, mham, mpô mpa khĭt măp, jêh ri nau văng tĭr. Pô ri, ver hom lĕ rngôch nau aơ, jêh ri khân may mra gŭ ueh. Gŭ hom khân may!”$b$,false),
('bunong-vn','ACT',15,30,null,$b$Phung nây, jêh phung chroh đă hăn, khân păng jŭr hăn ta ƀon Antiôs. Jêh tâm rƀŭn phung âk, khân păng jao sămƀŭt njuăl nây ma khân Păng.$b$,true),
('bunong-vn','ACT',15,31,null,$b$Jêh uănh sămƀŭt nây phung oh nâu răm maak jêh ri n'hao nuih.$b$,false),
('bunong-vn','ACT',15,32,null,$b$Y-Yuđas jêh ri Y-Silas jêng kôranh nơm mbơh lor lĕ, nti lah jêh ri tâm n'hao nuih khân păng ma âk nau ngơi.$b$,true),
('bunong-vn','ACT',15,33,null,$b$Jŏ djê̆ ma nây phung oh nâu ăn khân păng plơ̆ sĭt đăp mpăn ma phung njuăl khân păng.$b$,false),
('bunong-vn','ACT',15,34,null,$b$Ƀiă lah Y-Silas mĭn ueh ăt gŭ ta ƀon Antiôs.$b$,false),
('bunong-vn','ACT',15,35,null,$b$Y-Pôl jêh ri Y-Ƀarnaƀas gŭ ta ƀon Antiôs nti lah nau mhe mhan ueh jêh ri sâm nti bu ndrel ma âk phung êng.$b$,true),
('bunong-vn','ACT',15,36,null,$b$Jŏ djê̆ ma nây Y-Pôl lah ma Y-Ƀarnaƀas: “Kay lŏng he plơ̆ sĭt khâl phung oh nâu tâm lĕ mƀon he hŏ tă nti jêh nau Kôranh Brah, ŭch uănh, mâm păng jêng.”$b$,false),
('bunong-vn','ACT',15,37,null,$b$Y-Ƀarnaƀas ŭch jă ndrel ma Y-Yôhan, trơn amoh Y-Markôs.$b$,false),
('bunong-vn','ACT',15,38,null,$b$Ƀiă lah Y-Pôl mĭn mâu ueh jă ndrel ma Y-Markôs yor lah cha lơi khân păng tâm n'gor Pamphili, mâu pah kan ndrel ma khân păng ôh.$b$,true),
('bunong-vn','ACT',15,39,null,$b$Nau tâm dun nây ktang ngăn, tât khân păng tâm nkhah. Y-Ƀarnaƀas jă ndrel ma păng Y-Markôs jêh ri ncho kŭmpăn hăn ta kôdak Chiprơ.$b$,false),
('bunong-vn','ACT',15,40,null,$b$Y-Pôl săch Y-Silas. Jêh phung oh nâu jao păng ma nau yô̆ Kôranh Brah, păng hăn.$b$,false),
('bunong-vn','ACT',15,41,null,$b$Păng nsong tâm n'gor Siri jêh ri n'gor Silisi ƀư ăn nâp phung ngih Brah Ndu. Y-Pôl jă Y-Timôthê ndrel$b$,false),
('bunong-vn','ACT',16,1,null,$b$Y-Pôl hăn ta ƀon Đerbơ, jêh ri ta ƀon Listrơ. Ta nây geh du huê oh mon, amoh păng Y-Timôthê, geh kon bu klâu, du huê bu ur Yuđa chroh, jêh ri mbơ̆ păng jêng du huê Grek.$b$,true),
('bunong-vn','ACT',16,2,null,$b$Phung oh nâu ta ƀon Listrơ, jêh ri ta ƀon Ikôni mbơh nau păng jêng ueh.$b$,false),
('bunong-vn','ACT',16,3,null,$b$Y-Pôl jă păng hăn ndrel; pô ri, yor lah lĕ rngôch phung Yuđa gŭ tâm n'gor nây gĭt mbơ̆ păng jêng du huê Grek, jêh păng sŏk, păng koh ntâu nơm nây.$b$,false),
('bunong-vn','ACT',16,4,null,$b$Ta ƀon khân păng rgăn, khân păng ntăm ăn tông nau vay phung kôranh oh mon jêh ri bu bŭnh bu ranh tâm ƀon Yêrusalem.$b$,false),
('bunong-vn','ACT',16,5,null,$b$Phung ngih Brah Ndu jêng nâp tâm nau chroh, jêh ri ăp nar phung chroh ntop lơ hâu âk đŏng.$b$,true),
('bunong-vn','ACT',16,6,null,$b$Khân păng rgăn n'gor Phriji jêh ri n'gor Galati, yor lah Brah Huêng Ueh buay jêh khân păng, mbơh Nau Brah Ndu Ngơi tâm n'gor Asi.$b$,true),
('bunong-vn','ACT',16,7,null,$b$Dăch tât ta n'gor Misi, khân păng mĭn ntơm lăp tâm n'gor Bithini, ƀiă lah Brah Huêng Ueh mâu ăn ôh.$b$,false),
('bunong-vn','ACT',16,8,null,$b$Khân păng rgăn gao n'gor Misi jêh ri jŭr ta ƀon Trôas.$b$,false),
('bunong-vn','ACT',16,9,null,$b$Dôl măng Y-Pôl geh nau saơ pô aơ; du huê Masêđôn dâk ta năp păng jêh ri vơh vơl: “Văch hom ta n'gor Masêđôn jêh ri kơl hên!”$b$,true),
('bunong-vn','ACT',16,10,null,$b$Ƀât lât jêh Y Pôl saơ pô nây, hên ndrăp nau hăn ta n'gor Masêđôn, yor lah hên gĭt Kôranh Brah kuăl jêh hên mbơh nau mhe mhan ueh ta nây.$b$,false),
('bunong-vn','ACT',16,11,null,$b$Luh tă bơh ƀon Trôas, hên ncho kŭmpăn hăn tham ƀon Samôtras, jêh ri nar ôi taơ ta ƀon Nêapôlis.$b$,true),
('bunong-vn','ACT',16,12,null,$b$Tă bơh nây hên hăn ta ƀon Philip, du ƀon toyh tâm n'gor Masêđôn jêng n'gor phung Rôm chiă uănh. Hên gŭ ta nây bar pe nar.$b$,false),
('bunong-vn','ACT',16,13,null,$b$Nar Saƀat hên luh pa dih mpông pêr ƀon ta kơh dak krong. Hên mĭn ta nây geh ntŭk bu tâm rƀŭn mbơh sơm, jêh hên gŭ hên ngơi ma phung bu ur tâm rƀŭn ta nây.$b$,false),
('bunong-vn','ACT',16,14,null,$b$Du huê tâm phung khân păng amoh păng H'Lidi, bơh ƀon Thiatir, bu ur tăch bok sut êr. Păng ăt klach yơk ma Brah Ndu, jêh ri Kôranh Brah pơk nuih n'hâm păng gay ma păng iăt nanê̆ nau Y-Pôl ngơi.$b$,false),
('bunong-vn','ACT',16,15,null,$b$Tơ lah păng dơn nau ƀaptem jêh ndrel ma phung tâm ngih păng, păng dăn ma hên pô aơ: “Tơ lah khân may mĭn ma gâp răp jăp đah Kôranh Brah, lăp gŭ hom tâm ngih gâp.” Jêh ri păng nchâp hên lăp.$b$,false),
('bunong-vn','ACT',16,16,null,$b$Dôl hên hăn mbơh sơm, hên tâm mâp đah du huê oh mon bu ur brah mhĭk Pithôn lơh. Ma nau păng ngơi, păng n'hao ndrŏng kôranh păng.$b$,true),
('bunong-vn','ACT',16,17,null,$b$Jêh ri păng tĭng groi pa kơi Y-Pôl, jêh ri hên, lah pô aơ: “Phung aơ jêng phung oh mon Brah Ndu ta klơ lơn, khân păng mbơh ma khân may trong nau tâm rklaih.”$b$,false),
('bunong-vn','ACT',16,18,null,$b$Păng ƀư pô nây mro âk nar tât Y-Pôl rgănh, n'gĭl uănh, jêh ri lah ma brah mhĭk: “Gâp tâm amoh Brah Yêsu Krist, du luh hom may tă bơh bu ur aơ.” Jêh ri brah mhĭk du luh ro.$b$,false),
('bunong-vn','ACT',16,19,null,$b$Phung kôranh bu ur nây saơ roh jêh nau kâp gân rnơm sa prăk âk, nhŭp Y-Pôl ndrel ma Y-Silas, têk khân păng ta ntŭk phat dôih, ta năp phung kôranh.$b$,false),
('bunong-vn','ACT',16,20,null,$b$Jêh njŭn leo phung nây, phung kôranh toyh khân păng lah: “Phung aơ ƀư nau uh ah ma phung ƀon lan he. Khân păng jêng phung Yuđa yơh.$b$,false),
('bunong-vn','ACT',16,21,null,$b$Khân păng nti nau vay he mâu dơi dơn, mâu dơi tông lĕ, yor lah he jêng phung Rôm.”$b$,false),
('bunong-vn','ACT',16,22,null,$b$Phung âk ƀư ma khân păng tâm ban lĕ, jêh ri phung kôranh đă bu doh bok ao phung nây, jêh ri đă bu dong ma mâng.$b$,false),
('bunong-vn','ACT',16,23,null,$b$Jêh bu dong âk tơ̆ , phung kôranh đă bu krŭng khân păng tâm ndrung jêh ri ntăm ma kôranh bu nă chiă ăn ueh.$b$,false),
('bunong-vn','ACT',16,24,null,$b$Jêh tăng nau nây, kôranh bu nă ăn khân păng tâm ndrung ngo tâm trôm, jêh ri nkông jâng.$b$,false),
('bunong-vn','ACT',16,25,null,$b$Tâm klong măng Y-Pôl jêh ri Y-Silas mbơh sơm, mprơ tâm rnê ma Brah Ndu, jêh ri phung bu nă gŭ iăt.$b$,true),
('bunong-vn','ACT',16,26,null,$b$Ƀât lât geh nau n'găr neh ntu tât ntur vâl tât n'gơ lĕ, jêh ri lĕ rngôch mpông pơk da dê, rse rvăk phung bu nă klaih lĕ.$b$,false),
('bunong-vn','ACT',16,27,null,$b$Kôranh bu nă kah rngăl. Tơ lah păng saơ mpông ndrung pơk da dê, păng mĭn phung bu nă du lĕ, yor ri păng sŏk đao, ŭch nkhĭt êng săk nơm.$b$,false),
('bunong-vn','ACT',16,28,null,$b$Ƀiă lah Y-Pôl nter huy hâu ngăn: “Lơi ƀư djơh ma may nơm ôh. Hên ăt hôm tâm aơ da dê!”$b$,false),
('bunong-vn','ACT',16,29,null,$b$Pô nây, kôranh bu nă dăn ŭnh kđen jêh ri nchuăt hăn ma nau sâr săk jăn, chon mon ta jâng Y-Pôl jêh ri Y-Silas.$b$,true),
('bunong-vn','ACT',16,30,null,$b$Păng ăn phung nây du luh jêh ri ôp: “Hơi phung kôranh, mâm gâp mra ƀư gay dơi tâm rklaih?”$b$,false),
('bunong-vn','ACT',16,31,null,$b$Y-Pôl, Y-Silas lah ma păng: “Chroh hom ma Brah Yêsu, may jêh ri phung tâm ngih may mra klaih.”$b$,true),
('bunong-vn','ACT',16,32,null,$b$Khân păng mbơh nau Brah Ndu ma nơm nây jêh ri ma phung gŭ tâm ngih păng.$b$,false),
('bunong-vn','ACT',16,33,null,$b$Tâm mông măng nây lĕ kôranh bu nă đă Y-Pôl jêh ri Y-Silas rao ntŭk sôt khân păng, jêh ri păng ndrel ma phung gŭ tâm ngih păng, dơn nau ƀaptem ro.$b$,false),
('bunong-vn','ACT',16,34,null,$b$Jêh ăn phung nây lăp tâm ngih păng, păng thai sông sa, jêh ri păng ndrel ma mpôl băl păng răm maak, yor lah păng chroh jêh ma Brah Ndu.$b$,false),
('bunong-vn','ACT',16,35,null,$b$Tât ang trôk, phung kôranh njuăl oh mon păng hăn ta kôranh bu nă jêh ri lah: “Pơk hom phung nây.”$b$,true),
('bunong-vn','ACT',16,36,null,$b$Kôranh bu nă mbơh ma Y-Pôl pô aơ: “Phung kôranh njuăl bunuyh văch, đă pơk khân may. Pô ri, du luh hom aƀaơ ro, jêh ri hăn đăp mpăn.”$b$,false),
('bunong-vn','ACT',16,37,null,$b$Ƀiă lah Y-Pôl lah ma phung oh mon nây: “Hên jêng phung Rôm. Ê hŏ bu ngơi dôih, bu dong jêh hên ma mâng ta năp phung âk, jêh ri krŭng tâm ndrung. Aƀaơ khân păng pơk ntŭng hên? Mâu, hên mâu dơn ôh! Ăn phung kôranh nơm văch ta aơ pơk hên.”$b$,true),
('bunong-vn','ACT',16,38,null,$b$Phung oh mon mbơh nau nây ma phung kôranh, jêh ri khân păng klach tơ lah gĭt phung nây jêng phung Rôm.$b$,false),
('bunong-vn','ACT',16,39,null,$b$Phung kôranh hăn rthi nuih khân păng, pơk khân păng, jêh ri dăn ma khân păng du luh tă ƀon nây.$b$,false),
('bunong-vn','ACT',16,40,null,$b$Jêh du luh tă bơh ndrung, khân păng lăp tâm ngih H'Lidi, jêh tâm khâl, nti lah ma phung oh nâu, jêh ri khân păng hăn.$b$,false),
('bunong-vn','ACT',17,1,null,$b$Y-Pôl jêh ri Y-Silas rgăn ƀon Amphipôlis, jêh ri ƀon Apôlôni, tât ta ƀon Têsalônik. Ta nây phung Yuđa geh du mlâm ngih tâm rƀŭn.$b$,true),
('bunong-vn','ACT',17,2,null,$b$Tĭng nâm nau vay păng, Y-Pôl lăp tâm ngih tâm rƀŭn, jêh ri păng tâm dun tâm ndăng đah phung Yuđa tâm pe nar Saƀat tĭng nâm nau nchih jêh.$b$,false),
('bunong-vn','ACT',17,3,null,$b$Păng rblang jêh ri mbơh nanê̆ ma Brah Krist dơn jêh nau rêh ni jêh ri dâk rêh đŏng. Păng lah: “Brah Yêsu, Nơm gâp mbơh ma khân may aơ, Păng yơh Brah Krist.”$b$,false),
('bunong-vn','ACT',17,4,null,$b$Ƀa ƀă tâm phung khân păng chroh, jêh ri tĭng ndô̆ Y-Pôl ndrel ma Y-Silas; jêh ri geh âk phung Grek sŏng srăng, nđâp ma âk phung bu ur bu yơk.$b$,false),
('bunong-vn','ACT',17,5,null,$b$Ƀiă lah phung Yuđa, bêng ma nau nach, jă âk bunuyh mhĭk tâm ƀon lan ndrel ma khân păng. Khân păng nsônh phung âk ƀư nau uh ah tâm ƀon. Khân păng nchueng ngih Y-Yason, joi Y-Pôl ndrel ma Y-Silas gay ma nhŭp, njŭn leo ta năp phung ƀon lan.$b$,false),
('bunong-vn','ACT',17,6,null,$b$Ƀiă lah mâu dơi saơ ôh, khân păng nhŭp têk Y-Yason, jêh ri phung oh nâu ƀa ƀă ta năp phung kôranh phat dôih ƀon nây, jêh ri nter pô aơ: “Ta aơ, phung ƀư rŭng lĕ neh ntu.$b$,false),
('bunong-vn','ACT',17,7,null,$b$Y-Yason rom khân păng, lĕ rngôch khân păng tâm rdâng đah nau vay Sêsar, yor lah khân păng lah, geh du huê hađăch êng, Brah Yêsu.”$b$,false),
('bunong-vn','ACT',17,8,null,$b$Nau ngơi nây ƀư rŭng phung âk jêh ri phung kôranh phat dôih.$b$,false),
('bunong-vn','ACT',17,9,null,$b$Ƀiă lah jêh geh nau rnơm bơh Y-Yason jêh ri phung chroh nây, khân păng mƀơk lơi phung nây.$b$,false),
('bunong-vn','ACT',17,10,null,$b$Ƀât lât, dôl măng phung oh nâu ăn Y-Pôl ndrel ma Y-Silas hăn ta ƀon Bêrê, tât ta nây, khân păng lăp tâm ngih tâm rƀŭn Yuđa.$b$,true),
('bunong-vn','ACT',17,11,null,$b$Phung Yuđa aơ geh nau mĭn ueh lơn ma phung Yuđa tâm ƀon Têsalônik. Khân păng dơn nau Brah Ndu ngơi ma âk nau rŏng, ăp nar sek uănh nau nchih gay gĭt tơ lah nau bu nti ma khân păng jêng nanê̆.$b$,false),
('bunong-vn','ACT',17,12,null,$b$Âk tâm phung khân păng chroh, nđâp ma phung bu ur Grek bu yơk, jêh ri nđâp ma âk bu klâu.$b$,false),
('bunong-vn','ACT',17,13,null,$b$Ƀiă lah, tơ lah phung Yuđa ta ƀon Têsalônik gĭt ma Y-Pôl nti lĕ nau Brah Ndu ngơi ta ƀon Bêrê, khân păng hăn ta nây gay ma ƀư nau uh ah.$b$,false),
('bunong-vn','ACT',17,14,null,$b$Dôl nây phung oh nâu ăn Y-Pôl du hăn măng leo ta dak mƀŭt, bi Y-Silas jêh ri Y-Timôthê ăt hôm gŭ ta ƀon Bêrê.$b$,false),
('bunong-vn','ACT',17,15,null,$b$Phung njŭn Y-Pôl, hăn ndrel ma păng tât ta ƀon Athen; jêh ri sĭt tă bơh ƀon nây mbơh ma Y-Silas jêh ri Y-Timôthê nau Y-Pôl ntăm đă hăn tĭng păng ăn gơnh.$b$,false),
('bunong-vn','ACT',17,16,null,$b$Dôl Y-Pôl gŭ kâp khân păng ta ƀon Athen, păng geh nau ji nuih, yor lah saơ ƀon nây bêng ma rup brah.$b$,true),
('bunong-vn','ACT',17,17,null,$b$Tâm ngih tâm rƀŭn Yuđa tâm rlăch đah phung Yuđa jêh ri phung sŏng, phung păng vay mâp ăp nar ta ntŭk tâm rƀŭn.$b$,false),
('bunong-vn','ACT',17,18,null,$b$Ƀa ƀă phung kôranh, gĭt âk Êpikur jêh ri Stôik tâm rlăch đah păng đŏng. Ƀa ƀă lah: “Moh nơm âk ngơi aơ ŭch lah?” Phung êng lah: “Tâm ban ma păng mbơh nau brah phung bu năch.” Yor lah Y-Pôl mbơh Brah Yêsu jêh ri nau dâk rêh.$b$,false),
('bunong-vn','ACT',17,19,null,$b$Pô ri khân păng nhŭp Y-Pôl, njŭn leo ta ntŭk tâm rƀŭn Arêôpa jêh ri lah: “Dơi lĕ may ăn hên gĭt moh nau nti mhe may nti nây?$b$,true),
('bunong-vn','ACT',17,20,null,$b$Yor lah may ăn hên iăt nau hih rhâl. Hên ŭch gĭt nâm bu ntĭt nau nây.”$b$,false),
('bunong-vn','ACT',17,21,null,$b$Yor lah lĕ rngôch bunuyh ƀon Athen, nđâp ma phung bu năch gŭ ta nây ŭch knŏng mbơh mâu lah iăt nau mhe mhan.$b$,false),
('bunong-vn','ACT',17,22,null,$b$Y-Pôl dâk ta nklang ntŭk bu rnha Arêôpa, lah pô aơ: “Hơi phung ƀon Athen, gâp saơ kan khân may yơk ma brah âk ngăn.$b$,true),
('bunong-vn','ACT',17,23,null,$b$Yor lah dôl gâp nsong tâm ƀon khân may, jêh ri treng uănh mpa ndơ khân may prăp mbah, gâp saơ du mlâm nơng ƀư brah, geh sămƀŭt nchih pô aơ: MA BRAH BU MÂU MÂP GĬT NĂL! Pô ri Nơm khân may mbah, ƀiă lah mâu gĭt năl nây, Păng yơh gâp mbơh ma khân may.$b$,false),
('bunong-vn','ACT',17,24,null,$b$Brah Ndu, Nơm rhăk njêng neh ntu jêh ri lĕ rngôch mpô mpa gŭ rêh tâm nây, Păng jêng Kôranh ma trôk jêh ri lĕ rngôch neh ntu. Păng mâu gŭ ôh tâm ti bunuyh ƀư.$b$,false),
('bunong-vn','ACT',17,25,null,$b$Păng mâu chrê ma ti bunuyh pah kan ôh, tâm ban ma Păng ŭch ti bunuyh kơl, yor lah Păng yơh ăn nau rêh ma lĕ rngôch, nau suh n'hâm, jêh ri ăp ntil ndơ.$b$,false),
('bunong-vn','ACT',17,26,null,$b$Păng ăn lĕ rngôch bunuyh luh bơh du huê, jêh ri gŭ lam bri neh. Păng tâm nal jêh rnôk khân păng, jêh ri ntŭk khân păng gŭ.$b$,false),
('bunong-vn','ACT',17,27,null,$b$Păng ŭch ma lĕ rngôch bunuyh joi Brah Ndu, ăn khân păng srôih joi tât saơ, dôl Păng mâu gŭ ngai đah ăp nơm he,$b$,false),
('bunong-vn','ACT',17,28,null,$b$Yor lah tâm Păng yơh he geh nau rêh, nau sak nsong, jêh ri nau jêng, tâm ban ma phung nchih sămƀŭt nau mprĭng, khân may lah pô aơ: ‘He luh tă bơh ndŭl mpôl Păng yơh!’$b$,false),
('bunong-vn','ACT',17,29,null,$b$Pô nây, yor lah he jêng, ndŭl mpôl Brah Ndu, lơi ta he mĭn Brah Ndu jêng tâm ban ma mah, prăk, mâu lah lŭ bunuyh mon, tĭng nâm nau njêh khân păng.$b$,false),
('bunong-vn','ACT',17,30,null,$b$Brah Ndu mâu kơp ôh tâm rnôk rluk mâl, ngo nây, ƀiă lah aƀaơ aơ păng mbơh ma lĕ rngôch bunuyh lam bri neh gay tâm rmal nau tih khân păng.$b$,false),
('bunong-vn','ACT',17,31,null,$b$Yor lah Păng tâm nal jêh nar Păng phat dôih sŏng ma neh ntu. Păng săch jêh du huê bunuyh jêng kôranh phat dôih, jêh ri mbơh ngăn jêh ma nau nây, yor lah Păng ăn jêh ô băl dâk rêh jêh.”$b$,false),
('bunong-vn','ACT',17,32,null,$b$Tơ lah khân păng tăng Y-Pôl ngơi ma nau dâk rêh, ƀa ƀă mưch, ƀiă lah ƀa ƀă lah: “Hên mra iăt tay nau may tâm nar êng.”$b$,false),
('bunong-vn','ACT',17,33,null,$b$Pô ri Y-Pôl du luh tă bơh khân păng,$b$,false),
('bunong-vn','ACT',17,34,null,$b$ƀiă lah geh ƀa ƀă tĭng ndô̆ păng jêh ri chroh. Tâm phung nây geh Y-Dênis, du huê kôranh phat dôih Arêôpa, jêh ri du huê bu ur, amoh păng H'Damaris, ndrel ma phung êng.$b$,false),
('bunong-vn','ACT',18,1,null,$b$Jêh nau nây Y-Pôl luh tă bơh ƀon Athen, hăn ta ƀon Kôrintô.$b$,true),
('bunong-vn','ACT',18,2,null,$b$Ta nây păng tâm mâp đah du huê Yuđa amoh păng Y-Akilas tă bơh n'gor Pônt, mhe văch tă bơh n'gor Italy ndrel ma H'Phrisil, ur păng, yor lah hađăch Klôt ntăm, ăn lĕ rngôch phung Yuđa luh du lĕ tă bơh ƀon Rôm. Y-Pôl hăn ta khân păng.$b$,false),
('bunong-vn','ACT',18,3,null,$b$Yor lah păng geh kan tâm ban, păng gŭ ndrel ma phung nây jêh ri pah kan ndrel. Kan khân păng tanh bok ƀư ngih.$b$,false),
('bunong-vn','ACT',18,4,null,$b$Ăp nar Saƀat Y-Pôl ngơi tâm ngih tâm rƀŭn Yuđa jêh ri nsônh đă phung Yuđa jêh ri phung Grek.$b$,false),
('bunong-vn','ACT',18,5,null,$b$Tơ lah Y-Silas jêh ri Y-Timôthê văch tă bơh n'gor Masêđôn, Y-Pôl rđuh nti lah, păng mbơh ma phung Yuđa ma nau Brah Yêsu jêng Brah Krist.$b$,false),
('bunong-vn','ACT',18,6,null,$b$Yor lah phung Yuđa tâm rdâng jêh ri suai rak ma păng, păng rtuh bok ao păng jêh ri lah pô aơ: “Ăn mham khân may tŭp ta bôk khân may nơm. Bi gâp be, gâp jêng kloh, ntơm bơh aƀaơ aơ gâp mra hăn ta phung bu năch.”$b$,true),
('bunong-vn','ACT',18,7,null,$b$Luh tă bơh nây păng lăp tâm ngih Y-Yustus, du huê mbah yơk ma Brah Ndu, jêh ri ngih păng dăch ta ngih tâm rƀŭn Yuđa.$b$,false),
('bunong-vn','ACT',18,8,null,$b$Jêh ri Y-Krispus kôranh ngih tâm rƀŭn Yuđa, ndrel ma lĕ rngôch ngih păng, chroh ma Kôranh Brah Yêsu. Jêh ri âk phung Kôrintô, jêh iăt nau Y-Pôl nti, chroh jêh ri dơn nau ƀaptem.$b$,false),
('bunong-vn','ACT',18,9,null,$b$Kôranh Brah lah ma Y-Pôl dôl măng tâm nau tâm mpơl pô aơ: “Lơi klach ôh, ƀiă lah ngơi jêh ri lơi gŭ rklăk ôh.$b$,false),
('bunong-vn','ACT',18,10,null,$b$Yor lah gâp gŭ ndrel ma may, jêh ri mâu geh du huê dơi ƀư djơh ma may ôh; yor lah gâp geh âk bunuyh tâm ban aơ.”$b$,false),
('bunong-vn','ACT',18,11,null,$b$Y-Pôl gŭ ta nây du năm n'gul, nti lah Nau Brah Ndu Ngơi ma bu.$b$,false),
('bunong-vn','ACT',18,12,null,$b$Rnôk Y-Galiôn jêng kôranh n'gor Akai, phung Yuđa du ai nau tâm rdâng đah Y-Pôl, njŭn leo păng ta ntŭk phat dôih.$b$,true),
('bunong-vn','ACT',18,13,null,$b$Khân păng lah: “Bunuyh aơ nchâp phung ƀon lan mbơh Brah Ndu ma nau tih đah nau vay.”$b$,false),
('bunong-vn','ACT',18,14,null,$b$Dôl Y-Pôl hă ngơi gay ma plơ̆ lah, Y-Galiôn lah ma phung Yuđa pô aơ: “Hơi phung Yuđa, tơ lah geh nau kue mâu lah nau tih mhĭk, nanê̆ gâp mra iăt nau khân may.$b$,false),
('bunong-vn','ACT',18,15,null,$b$Ƀiă lah, tơ lah geh nau tâm nkăl ma nau nti, ma amoh bunuyh, jêh ri ma nau vay khân may nơm, gâp mâu ŭch phat nau nây ôh.”$b$,false),
('bunong-vn','ACT',18,16,null,$b$Jêh ri Y-Galiôn mprơh lơi khân păng bơh ntŭk phat dôih.$b$,false),
('bunong-vn','ACT',18,17,null,$b$Jêh ri lĕ rngôch bunuyh nhŭp Y-Sôsthen, kôranh ngih tâm rƀŭn phung Yuđa jêh ri khân păng dong ô băl ta năp ntŭk phat dôih, ƀiă lah Y-Galiôn mâu chrê ma nau nây ôh.$b$,false),
('bunong-vn','ACT',18,18,null,$b$Y-Pôl gŭ jŏ nar ta ƀon Kôrintô. Jêh ri păng lơi phung oh nâu, ncho kŭmpăn, hăn ta n'gor Siri ndrel ma H'Phrisil jêh ri Y-Akilas. Păng poih lĕ sŏk păng ta ƀon Sankrê, yor lah păng geh nau ton jêh.$b$,true),
('bunong-vn','ACT',18,19,null,$b$Khân păng tât ta ƀon Êphêsô. Y-Pôl lơi băl păng ta nây. Bi păng lăp tâm ngih rƀŭn Yuđa jêh ri nkoch bri đah phung Yuđa.$b$,true),
('bunong-vn','ACT',18,20,null,$b$Phung nây dăn ma păng gŭ jŏ lơn, ƀiă lah păng mâu ŭch ôh.$b$,true),
('bunong-vn','ACT',18,21,null,$b$Păng lơi phung nây jêh ri lah: “Khlay ngăn gâp hăn ma nau tâm rƀŭn toyh ta ƀon Yêrusalem. Gâp mra plơ̆ văch tơ lah Brah Ndu ŭch.” Păng luh tă bơh ƀon Êphêsô.$b$,false),
('bunong-vn','ACT',18,22,null,$b$Jêh jŭr tă bơh kŭmpăn ta ƀon Sêsarê, păng hăn leo hao ta ƀon Yêrusalem. Jêh khâl đah phung ngih Brah Ndu ta nây, păng hăn jŭr ta ƀon Antiôs.$b$,true),
('bunong-vn','ACT',18,23,null,$b$Tơ lah păng gŭ jŏ jêh ta nây, păng hăn nsong lam lĕ n'gor Galati jêh ri n'gor Phriji ƀư ăn nâp lĕ rngôch phung oh mon.$b$,false),
('bunong-vn','ACT',18,24,null,$b$Geh du huê Yuđa, amoh păng Y-Apôlôs tă bơh ƀon Aleksandrơ, blau nau ngơi ngăn, gĭt rbăng Nau Brah Ndu Ngơi văch tât ta ƀon Êphêsô.$b$,true),
('bunong-vn','ACT',18,25,null,$b$Păng nti jru jêh trong Kôranh Brah. Păng mbơh ma lĕ nuih n'hâm jêh ri nti ăn rah vah ma nau Brah Yêsu, nđâp tơ lah păng gĭt knŏng nau ƀaptem Y-Yôhan.$b$,false),
('bunong-vn','ACT',18,26,null,$b$Păng ntơm ngơi ma nau janh ktang tâm ngih rƀŭn Yuđa. Jêh iăt nau păng nti H'Phrisil jêh ri Y-Akilas kuăl păng gŭ ndrel, jêh ri sâm nti păng nanê̆ lơn tâm trong Brah Ndu.$b$,false),
('bunong-vn','ACT',18,27,null,$b$Tơ lah Y-Apôlôs ŭch hăn ta n'gor Akai phung oh nâu n'hao nuih păng, jêh ri nchih sămƀŭt ma phung oh mon n'gor nây, ăn rom păng ma nau ueh. Tơ lah păng tât jêh, ma nau yô̆ păng kơl âk ngăn phung chroh ta nây.$b$,false),
('bunong-vn','ACT',18,28,null,$b$Yor lah păng tâm rlăch ktang ngăn đah phung Yuđa ta năp phung âk, jêh ri sŏk Nau Brah Ndu Ngơi nchih, păng tâm mpơl Brah Yêsu jêng Brah Krist.$b$,false),
('bunong-vn','ACT',19,1,null,$b$Dôl Y-Apôlôs gŭ ta ƀon Kôrintô, Y-Pôl, lĕ hăn nsong tâm lĕ n'gor bri mpeh pa lơ, jêh nây jŭr tât ta ƀon Êphêsô. Păng tâm mâp đah bar hê pe nuyh, phung oh mon gŭ ta nây,$b$,true),
('bunong-vn','ACT',19,2,null,$b$jêh ri ôp phung nây: “Ntơm bơh khân may chroh, geh sŏk dơn Brah Huêng Ueh lĕ?” Khân păng plơ̆ lah: “Mâu, hên mâu mâp tăng ôh bu lah geh Brah Huêng Ueh.” Păng lah: “Moh nau ƀaptem khân may dơn?”$b$,false),
('bunong-vn','ACT',19,3,null,$b$Phung nây plơ̆ lah: “Nau ƀaptem Y-Yôhan.”$b$,false),
('bunong-vn','ACT',19,4,null,$b$Y-Pôl lah: “Y-Yôhan ƀư ƀaptem rmal nau tih, jêh ri mbơh ma phung ƀon lan ăn chroh ma Nơm mra văch pa kơi păng, nâm bu ntĭt, chroh ma Brah Yêsu.”$b$,false),
('bunong-vn','ACT',19,5,null,$b$Jêh tăng nau nây, khân păng dơn ƀaptem ma amoh Brah Yêsu.$b$,true),
('bunong-vn','ACT',19,6,null,$b$Jêh Y-Pôl pah ti ta khân păng, Brah Huêng Ueh jŭr ta khân păng, jêh ri khân păng ngơi nau bu năch jêh ri mbơh lor.$b$,false),
('bunong-vn','ACT',19,7,null,$b$Lĕ rngôch khân păng geh klăp lah tâm jât ma bar nuyh.$b$,false),
('bunong-vn','ACT',19,8,null,$b$Jêh ma nây Y-Pôl lăp tâm ngih rƀŭn phung Yuđa, jêh ri nti ta nây ma nau janh. Dôl tâm pe khay păng rblang lĕ rngôch nau ma ƀon bri hađăch Brah Ndu, jêh ri nsônh phung gŭ iăt nau păng nti ma nau chroh.$b$,true),
('bunong-vn','ACT',19,9,null,$b$Ƀiă lah, yor lah ƀa ƀă geh nuih n'hâm dăng, mâu ŭch chroh, ngơi djơh ma Trong Nau chroh ta năp phung âk, Y-Pôl rnglah khân păng, tâm rƀŭn êng phung oh mon ta ntŭk êng, jêh ri nti ma khân păng ăp nar tâm ngih sămƀŭt Y-Tiranus.$b$,true),
('bunong-vn','ACT',19,10,null,$b$Păng nti ta nây tâm bar năm, tât lĕ rngôch bunuyh gŭ tâm n'gor Asi, nđâp ma phung Yuđa, phung Grek, iăt Nau Brah Ndu Ngơi da dê.$b$,false),
('bunong-vn','ACT',19,11,null,$b$Jêh ri Brah Ndu dŏng ti Y-Pôl ƀư nau khlay toyh ngăn,$b$,false),
('bunong-vn','ACT',19,12,null,$b$tât bu sŏk bok, ao păng nsoh tâm săk jăn păng ăn ta klơ phung ji kuet dơi bah ji, nđâp ma brah mhĭk luh du.$b$,false),
('bunong-vn','ACT',19,13,null,$b$Rnôk nây phung Yuđa nsong ăp ntŭk, jan lah dŏng amoh Brah Yêsu ma phung bunuyh brah mhĭk lơh, khân păng lah pô aơ: “Gâp ntăm ma khân may ma amoh Brah Yêsu, Y-Pôl nti nây!”$b$,true),
('bunong-vn','ACT',19,14,null,$b$Phung pơh nuyh kon bu klâu Y-Sêvas ƀư nau nây. Y-Sêvas jêng du huê n'gâng kôranh ƀư brah ma phung Yuđa.$b$,false),
('bunong-vn','ACT',19,15,null,$b$Ƀiă lah brah mhĭk plơ̆ lah ma khân păng: “Gâp năl jêh Brah Yêsu, jêh ri gĭt nanê̆ mbu Y-Pôl jêng. Bi khân may, mbu khân may jêng?”$b$,false),
('bunong-vn','ACT',19,16,null,$b$Pô ri, bunuyh brah mhĭk lơh nchuăt ran ta khân păng, dơi ƀư ma bar hê tâm phung khân păng mhĭk ngăn, tât khân păng nchuăt du tă bơh ngih nây rhôk rhak jêh ri sôt găt da dê.$b$,false),
('bunong-vn','ACT',19,17,null,$b$Lĕ rngôch phung Yuđa jêh ri phung Grek gŭ ta ƀon Êphêsô tăng lư nau nây. Khân păng bêng ma nau klach, jêh ri mât ton tâm rnê ma amoh Brah Yêsu.$b$,false),
('bunong-vn','ACT',19,18,null,$b$Âk bunuyh hŏ chroh jêh, văch mbơh nau tih, nđâp ma kan khân păng ƀư jêh sa ơm ri.$b$,false),
('bunong-vn','ACT',19,19,null,$b$Âk phung ƀư rƀên kăl e, djôt su lơi ndrom sămƀŭt khân păng ta năp lĕ rngôch bunuyh. Rnoh khlay klăp ndrom sămƀŭt nây prăm jât rbăn prăk.$b$,false),
('bunong-vn','ACT',19,20,null,$b$Pô ri bu mbơh Nau Brah Ndu Ngơi lam ntŭk ma nau brah jêh ri nau ktang.$b$,false),
('bunong-vn','ACT',19,21,null,$b$Jêh lôch nau nây, Y-Pôl mĭn ŭch hăn ta ƀon Yêrusalem, rgăn n'gor Masêđôn jêh ri n'gor Akai. Păng lah: “Tơ lah gâp tât ta nây, gâp mra khâl lĕ ƀon Rôm.”$b$,true),
('bunong-vn','ACT',19,22,null,$b$Păng njuăl bar hê nơm kâp kơl păng, Y-Timôthê jêh ri Y-Êrast, hăn ta n'gor Masêđôn. Bi păng nơm, gŭ mâu ir jŏ ta n'gor Asi.$b$,false),
('bunong-vn','ACT',19,23,null,$b$Dôl nây geh nau uh ah toyh ngăn yor ma nau chroh.$b$,true),
('bunong-vn','ACT',19,24,null,$b$Du huê bunuyh nkra nau ndrăp, amoh păng Y-Dêmêtrus, ƀư rup ngih brah H'Dian ma prăk. Nau nây ăn phung pah kan sa prăk âk.$b$,false),
('bunong-vn','ACT',19,25,null,$b$Păng tâm rƀŭn phung pah kan ma păng, nđâp ma phung kan ndrel, jêh ri lah ma phung nây: “Hơi phung oh nâu, khân may gĭt ma kan aơ he dơi sa âk prăk.$b$,false),
('bunong-vn','ACT',19,26,null,$b$Khân may saơ jêh ri tăng, mâu di knŏng ta ƀon Êphêsô ôh, ƀiă lah bơi ma lĕ n'gor Asi, Y-Pôl aơ nti jêh ri nsônh âk bunuyh lah ma rup brah ti bunuyh ƀư mâu geh brah ngăn ôh.$b$,false),
('bunong-vn','ACT',19,27,null,$b$He klach mâu di knŏng ma nau tâm rmot ma kan he ôh, ƀiă lah klach ma ngih brah toyh H'Dian roh dơm dam. Jêh ri klach ma nau lư n'găr brah bu ur he, bu yơk tâm lam n'gor Asi jêh ri lam neh ntu mra rai yot tâm ban lĕ.”$b$,false),
('bunong-vn','ACT',19,28,null,$b$Tăng nau nây, khân păng ji nuih ngăn jêh ri nter pô aơ: “H'Dian phung Êphêsô, brah toyh ngăn!”$b$,false),
('bunong-vn','ACT',19,29,null,$b$Lĕ ƀon nây geh nau uh ah, jêh ri khân păng hăn lĕ rngôch nđâp ma ngih bu pâl, têk ndrel ma khân păng Y-Gaius jêh ri Y-Aristar, bunuyh n'gor Masêđôn, phung hăn nsong ndrel ma Y-Pôl.$b$,false),
('bunong-vn','ACT',19,30,null,$b$Y-Pôl ŭch mpơl păng nơm ta năp ƀon lan, ƀiă lah phung oh mon mâu ăn ôh.$b$,false),
('bunong-vn','ACT',19,31,null,$b$Geh phung kôranh n'gor Asi, mĭt jiăng đah păng, njuăl bunuyh hăn lah ma păng, lơi hăn ta ntŭk bu pâl ôh.$b$,true),
('bunong-vn','ACT',19,32,null,$b$Ƀa ƀă nter pô aơ, ƀa ƀă nter pô ri, yor lah mbah tă geh nau uh ah tâm phung gŭ rƀŭn, âk bunuyh mâu gĭt mâm ƀư khân păng gŭ tâm rƀŭn.$b$,false),
('bunong-vn','ACT',19,33,null,$b$Bu đă Y-Aleksandrơ luh tă bơh phung âk. Phung Yuđa nchâp păng đă gŭ pa năp, Y-Aleksandrơ yơr ti, păng ŭch ngơi ma phung ƀon lan, gay ma king ma phung păng.$b$,true),
('bunong-vn','ACT',19,34,null,$b$Ƀiă lah, tơ lah phung âk gĭt năl păng jêng phung Yuđa, lĕ rngôch nter du bâr ndrel n'grŭp tâm bar mông: “H'Dian, phung Êphêsô, brah toyh ngăn!”$b$,false),
('bunong-vn','ACT',19,35,null,$b$Rnôk nây geh du huê kôranh nchih sămƀŭt ƀon nây, buay phung âk nây, păng lah pô aơ: “Hơi phung Êphêsô, mbu nơm mâu gĭt ma ƀon Êphêsô jêng phung chiă ngih brah toyh H'Dian, jêh ri rup păng jŭr tŭp tă bơh trôk?$b$,false),
('bunong-vn','ACT',19,36,null,$b$Bu mâu dơi dun ôh nau nây. Pô ri ăn khân may gŭ rklăk hom. Lơi ƀât ƀư nau uh ah.$b$,true),
('bunong-vn','ACT',19,37,null,$b$Yor lah phung bunuyh khân may njŭn leo jêh ta aơ mâu geh tih ƀư ƀơ̆ ndơ brah mâu lah ngơi sưr ma brah bu ur he ôh.$b$,false),
('bunong-vn','ACT',19,38,null,$b$Bi tơ lah Y-Dêmêtrus jêh ri phung pah kan ndrel ma păng, geh nau phong ma bu, geh nar phat dôih jêh ri kôranh n'gor, ăn khân păng tâm ngơi dôih ndrăng khân păng nơm.$b$,false),
('bunong-vn','ACT',19,39,null,$b$Tơ lah khân may geh nau êng ŭch dăn, ăn tâm nchră nau nây tâm nau tâm rƀŭn tĭng nâm nau vay.$b$,false),
('bunong-vn','ACT',19,40,null,$b$Klach lah bu phong he, yor nau uh ah nar aơ, jêh ri he mâu dơi geh nau king ma nau tâm rƀŭn aơ ôh.”$b$,false),
('bunong-vn','ACT',19,41,null,$b$Jêh păng ngơi pô nây, păng ăn phung tâm rƀŭn sĭt.$b$,false),
('bunong-vn','ACT',20,1,null,$b$Tơ lah nau uh ah nây lĕ jêh, Y-Pôl tâm rƀŭn phung oh mon. Jêh nti lah, păng nkoch bri nau khâl đah phung nây jêh ri hăn ta n'gor Masêđôn.$b$,true),
('bunong-vn','ACT',20,2,null,$b$Păng hăn nsong lam n'gor nây, tâm n'hao nuih phung chroh jêh ri hăn ta n'gor Grek.$b$,false),
('bunong-vn','ACT',20,3,null,$b$Jêh păng gŭ ta nây pe khay, ta nar păng ndrăp ŭch ncho kŭmpăn hăn ta n'gor Siri, phung Yuđa joi nau ƀư mhĭk ma păng. Pô ri, păng mĭn sĭt ta n'gor Masêđôn.$b$,false),
('bunong-vn','ACT',20,4,null,$b$Y-Sôpatê, kon Y-Piru, ƀon Bêrê, hăn ndrel ma păng; geh nđâp ma Y-Aristar, Y-Sêkôndu, ƀon Têsalônik, ri Y-Trôphim, n'gor Asi.$b$,false),
('bunong-vn','ACT',20,5,null,$b$Phung aơ hăn lor jêh ri gŭ kâp hên ta ƀon Trôas.$b$,false),
('bunong-vn','ACT',20,6,null,$b$Bi hên, jêh lôch nar sa kapŭng mâu geh ndrui, hên ncho kŭmpăn hăn ta ƀon Philip, jêh ri prăm nar rlau hên tâm mâp đah khân păng ta ƀon Trôas. Ta nây hên gŭ pơh nar.$b$,false),
('bunong-vn','ACT',20,7,null,$b$Nar nguay tâm nar ver, dôl hên tâm rƀŭn gay sa kapŭng. Y-Pôl nkoch bri đah phung chroh yor lah păng mĭn ŭch hăn nar ôi taơ, pô ri păng nti tât klong măng.$b$,true),
('bunong-vn','ACT',20,8,null,$b$Geh âk ŭnh kđen tâm jrô klơ ngih, ta ntŭk hên tâm rƀŭn nây.$b$,false),
('bunong-vn','ACT',20,9,null,$b$Du huê bu klâu ndăm amoh păng Y-Ơtik, gŭ ta mpông bloh jê̆. Păng bêch dôl mông Y-Pôl nti jŏ ngăn. Jêh ri dôl bêch gui, păng tŭp tă bơh ngih pe tăp. Tơ lah bu chông păng, păng khĭt jêh.$b$,false),
('bunong-vn','ACT',20,10,null,$b$Ƀiă lah Y-Pôl trŭnh, kŭnh ut păng tâm ti jêh ri lah pô aơ: “Lơi ta khân may klach ôh, yor lah huêng păng hôm tâm păng.”$b$,false),
('bunong-vn','ACT',20,11,null,$b$Jêh Y-Pôl hao tay ta klơ, păng nkêch kapŭng jêh ri sa. Păng ngơi jŏ ngăn tât ôi jêh ri păng hăn.$b$,false),
('bunong-vn','ACT',20,12,null,$b$Bi kon se ndăm nây ăt hôm rêh bu njŭn păng sĭt. Nau nây bonh leng ma âk bunuyh.$b$,true),
('bunong-vn','ACT',20,13,null,$b$Bi hên, hên ncho kŭmpăn hăn lor ta ƀon Asôs, ta nây hên ŭch tâm mâp đah Y-Pôl, yor lah păng ŭch hăn trong jâng.$b$,true),
('bunong-vn','ACT',20,14,null,$b$Jêh tâm mâp đah păng ta ƀon Asôs păng ncho kŭmpăn ndrel jêh ri hên hăn ta ƀon Mitilen.$b$,true),
('bunong-vn','ACT',20,15,null,$b$Tă bơh nây ăt hên ncho kŭmpăn, jêh ri ôi taơ hên tât ta năp ƀon Chiôs. Nar pa kơi hên mra tât ta ƀon Samôs, jêh ri nar pa kơi đŏng hên tât ta ƀon Milê.$b$,false),
('bunong-vn','ACT',20,16,null,$b$Y-Pôl mĭn nanê̆ ŭch găn ƀon Êphêsô, mâu geh njưh ta nây ôh, klach ƀư roh nar tâm n'gor Asi. Păng ndal ŭch gơnh tât ta ƀon Yêrusalem di nar Pantơkôt tơ lah dơi.$b$,false),
('bunong-vn','ACT',20,17,null,$b$Rnôk nây, bơh ƀon Milê, Y-Pôl njuăl bunuyh ta ƀon Êphêsô kuăl phung bu bŭnh bu ranh tâm phung ngih Brah Ndu ta nây.$b$,true),
('bunong-vn','ACT',20,18,null,$b$Tơ lah phung nây tât jêh ta năp păng, păng lah ma phung nây pô aơ: “Khân may gĭt jêh ntơm bơh nar gâp ntơm tât tâm n'gor Asi, mâm ƀư gâp gŭ ndrel ma khân may.$b$,true),
('bunong-vn','ACT',20,19,null,$b$Gâp pah kan ma Kôranh Brah ma lĕ nau yơk, tông ma nau nhĭm, jêh ri ta nklang nau rlong uănh luh tă bơh nau ƀai phung Yuđa joi ƀư ma gâp.$b$,false),
('bunong-vn','ACT',20,20,null,$b$Khân may gĭt gâp mâu mâp mo nau khlay ma khân may, jêh ri gâp mâu klach nti ma khân may, ta năp phung âk jêh ri tâm ăp ngih.$b$,false),
('bunong-vn','ACT',20,21,null,$b$Gâp nti ma phung Yuđa jêh ri phung Grek, nau rmal nau tih ta năp Brah Ndu, jêh ri nau chroh tâm Yêsu Krist, Kôranh Brah he.$b$,true),
('bunong-vn','ACT',20,22,null,$b$Aƀaơ aơ đŏng, Brah Huêng Ueh ntrôl gâp hăn ta ƀon Yêrusalem, mâu gĭt ôh moh nau mra tât ma gâp ta nây.$b$,true),
('bunong-vn','ACT',20,23,null,$b$Knŏng Brah Huêng Ueh mbơh ma gâp gĭt, tâm ăp ƀon geh rse rvăk jêh ri nau rêh ni gŭ kâp gâp.$b$,false),
('bunong-vn','ACT',20,24,null,$b$Ƀiă lah gâp mâu kơp nau rêh gâp khlay ôh, knŏng gâp nchuăt ăn lĕ ma nau răm jêh ri ƀư ăn jêh kan gâp dơn tă bơh Brah Yêsu, ăn gâp mbơh nau mhe mhan ueh, nau Brah Ndu yô̆.$b$,true),
('bunong-vn','ACT',20,25,null,$b$“Aƀaơ, gâp gĭt tâm lĕ rngôch khân may phung gâp nti jêh nau ƀon bri hađăch Brah Ndu, nanê̆ mâu hôm saơ muh măt gâp đŏng ôh.$b$,true),
('bunong-vn','ACT',20,26,null,$b$Yor nây nar aơ gâp mbơh ma khân may, gâp kloh jêh ma mham lĕ rngôch khân may.$b$,false),
('bunong-vn','ACT',20,27,null,$b$Yor lah gâp mbơh jêh, mâu mo ôh ma khân may, lĕ nau Brah Ndu ŭch.$b$,false),
('bunong-vn','ACT',20,28,null,$b$Njrăng hom ma khân may nơm jêh ri ma lĕ rngôch phung biăp Brah Huêng Ueh ăn khân may jêng nơm chiăp, ŭch siăm phung ngih Brah Ndu Kôranh Brah, rvăt jêh ma mham Păng nơm.$b$,true),
('bunong-vn','ACT',20,29,null,$b$Gâp gĭt, jêh gâp hăn mra geh phung so bri janh lăp tâm phung khân may. Khân păng mâu chrê ma phung biăp ôh.$b$,false),
('bunong-vn','ACT',20,30,null,$b$Jêh ri mra geh tâm phung khân may bunuyh nti nau tih mhĭk, gay ma ndơm phung chroh tĭng ndô̆ khân păng.$b$,false),
('bunong-vn','ACT',20,31,null,$b$Pô ri njrăng hom, ăn khân may kah gĭt dôl tâm pe năm jêh, gâp mâu rlu ôh măng nâm nar mbơh ma ăp nơm khân may ma nau nhĭm.$b$,false),
('bunong-vn','ACT',20,32,null,$b$Aƀaơ aơ gâp jao khân may ma Brah Ndu jêh ri ma nau Păng ngơi yô̆, ma nơm dơi ndâk khân may jêh ri ăn ndơn drăp ndrel ma lĕ rngôch phung kloh ueh.$b$,false),
('bunong-vn','ACT',20,33,null,$b$Gâp mâu kơnh prăk, mah mâu lah bok ao bu ôh$b$,false),
('bunong-vn','ACT',20,34,null,$b$Khân may nơm gĭt jêh, ti aơ yơh ăn gâp jêh ri phung băl ndrel ma gâp, geh ndơ hên ŭch.$b$,false),
('bunong-vn','ACT',20,35,null,$b$Gâp ntĭm jêh ri nti jêh ma khân may, dôl pah kan, pô ri dơi kơl phung rdja jêh ri kah gĭt nau Brah Yêsu, Nơm ngơi pô aơ: ‘Ăn ma bu jêng ueh maak lơn ma sŏk dơn.’ ”$b$,false),
('bunong-vn','ACT',20,36,null,$b$Jêh păng lah pô nây, păng chon kômâk, mbơh sơm ndrel ma lĕ rngôch phung nây.$b$,true),
('bunong-vn','ACT',20,37,null,$b$Lĕ rngôch khân păng nhĭm, ut ta trô ko Y-Pôl, jêh ri chŭm păng.$b$,true),
('bunong-vn','ACT',20,38,null,$b$Khân păng rngot lơn yor nau Y-Pôl lah khân păng mâu mra saơ muh măt păng ôh. Jêh ri khân păng njŭn Y-Pôl tât ta kŭmpăn.$b$,false),
('bunong-vn','ACT',21,1,null,$b$Jêh hên tâm nkhah đah khân păng, hên ncho kŭmpăn jêh ri n'ho hăn ta ƀon Kôs, nar ôi taơ ta ƀon Rôt, jêh ri tă bơh nây ta ƀon Patara.$b$,true),
('bunong-vn','ACT',21,2,null,$b$Saơ ta nây du mlâm kŭmpăn hăn ta n'gor Phênisi, hên ncho jêh ri hăn.$b$,false),
('bunong-vn','ACT',21,3,null,$b$Tơ lah hên saơ kôdak Chiprơ, hên teng trong pa chiau, n'ho hăn ta n'gor Siri jêh ri hên tât ta mpâr ƀon Tir; yor lah ta nây bu huai sŏk ndơ kŭmpăn rdeng.$b$,false),
('bunong-vn','ACT',21,4,null,$b$Jêh saơ phung oh mon, hên gŭ pơh nar ndrel ma khân păng. Brah Huêng Ueh ntrôl khân păng lah ma Y-Pôl, lơi hăn ta ƀon Yêrusalem ôh.$b$,false),
('bunong-vn','ACT',21,5,null,$b$Tơ lah nar hên jưh ta nây lĕ jêh, hên hăn tay; jêh ri phung chroh ndrel ma ur kon khân păng njŭn hên tât ta mpâr ƀon; lĕ rngôch hên chon kômâk ta kơh, jêh ri mbơh sơm.$b$,false),
('bunong-vn','ACT',21,6,null,$b$Jêh hên tâm khâl, hên ncho kŭmpăn jêh ri khân păng sĭt ta ngih khân păng nơm.$b$,false),
('bunong-vn','ACT',21,7,null,$b$Jêh lôch trong dak, bơh ƀon Tir hên tât ta ƀon Pôtôlêmê, hên tâm khâl đah phung oh nâu ta nây, jêh ri gŭ ndrel ma khân păng du nar.$b$,true),
('bunong-vn','ACT',21,8,null,$b$Nar ôi taơ hên hăn ta ƀon Sêsarê. Jêh lăp hên gŭ tâm ngih Y-Philip, nơm nsong mbơh nau mhe mhan ueh. Păng jêng du huê tâm phung pơh nuyh.$b$,false),
('bunong-vn','ACT',21,9,null,$b$Păng geh puăn nuyh kon bu ur druh, vay mbơh lor.$b$,false),
('bunong-vn','ACT',21,10,null,$b$Dôl gŭ ta nây bar pe nar, geh du huê kôranh nơm mbơh lor amoh, păng Y-Agabus, tă bơh n'gor Yuđa, hăn tât ta hên.$b$,false),
('bunong-vn','ACT',21,11,null,$b$Păng sŏk rse bŭt Y-Pôl, kât jâng ti păng nơm jêh ri lah: “Aơ Brah Huêng Ueh mbơh, ta ƀon Yêrusalem phung Yuđa mra chăp tâm ban pô aơ lĕ, nơm rse bŭt aơ, jêh ri jao păng ma phung bu năch!”$b$,false),
('bunong-vn','ACT',21,12,null,$b$Jêh hên tăng nau nây phung gŭ ta nây, jêh ri hên dăn ma Y-Pôl lơi hăn ta ƀon Yêrusalem ôh.$b$,false),
('bunong-vn','ACT',21,13,null,$b$Ƀiă lah păng plơ̆ lah: “Mâm ƀư khân may nhĭm jêh ri ƀư chah rai lơi nuih n'hâm gâp? Gâp kâp dơn mâu di knŏng nau bu chăp ôh, ƀiă lah nđâp ma nau khĭt ta ƀon Yêrusalem, yor amoh Brah Yêsu lĕ.”$b$,false),
('bunong-vn','ACT',21,14,null,$b$Yor lah păng mâu tông ma hên, hên mâu hôm nchâp păng ôh, jêh ri hên lah: “Ăn nau Kôranh Brah ŭch mra tât.”$b$,false),
('bunong-vn','ACT',21,15,null,$b$Lôch nar nây hên nkra ndô ndơ jêh ri hăn ta ƀon Yêrusalem.$b$,true),
('bunong-vn','ACT',21,16,null,$b$Ƀa ƀă phung oh mon tă bơh ƀon Sêsarê hăn ndrel ma hên. Khân păng njŭn hên ta ngih Y-Manasôn bơh kôdak Chiprơ, păng jêng du huê oh mon jŏ jêh, jêh ri păng rom hên tâm ngih păng.$b$,false),
('bunong-vn','ACT',21,17,null,$b$Tât hên ta ƀon Yêrusalem, phung oh nâu rom hên ma nau răm maak.$b$,false),
('bunong-vn','ACT',21,18,null,$b$Nar ôi taơ Y-Pôl hăn ndrel ma hên ta ngih Y-Yakơ, jêh ri lĕ rngôch phung bu bŭnh bu ranh tâm rƀŭn ta nây.$b$,true),
('bunong-vn','ACT',21,19,null,$b$Jêh tâm khâl đah khân păng, Y-Pôl nkoch bri ăp ntil nau Brah Ndu dŏng kan păng ƀư jêh tâm phung bu năch.$b$,false),
('bunong-vn','ACT',21,20,null,$b$Jêh tăng nau nây, khân păng tâm rnê ma Brah Ndu jêh ri khân păng lah ma Y-Pôl: “Hơi nâu, may saơ geh âk rbăn phung Yuđa hŏ chroh, jêh ri lĕ rngôch khân păng duh nđơr tông nau vay.$b$,false),
('bunong-vn','ACT',21,21,null,$b$Khân păng tăng jêh nau may nti ma lĕ rngôch phung Yuđa gŭ tâm n'gor bu năch đă dun Y-Môis, mâu ăn bu koh ntâu phung kon khân păng ôh, mâu lĕ dơi tĭng nau vay ơm khân păng.$b$,true),
('bunong-vn','ACT',21,22,null,$b$Moh mra ƀư? Nanê̆ phung âk mra tâm rƀŭn, yor lah bu mra gĭt may tât jêh.$b$,false),
('bunong-vn','ACT',21,23,null,$b$Pô ri ƀư hom tĭng nâm hên mra lah ma may. Hên geh ta aơ puăn nuyh geh nau ton jêh.$b$,false),
('bunong-vn','ACT',21,24,null,$b$Njŭn khân păng ndrel ma may, ƀư kloh may ndrel ma khân păng, jêh ri may nơm nkhôm bu poih sŏk khân may. Pô ri lĕ rngôch mra gĭt nau bu nkoch bri ma may mâu nanê̆ ôh, ƀiă lah may tâm ban lĕ gŭ ngao krao sach di ma nau vay.$b$,false),
('bunong-vn','ACT',21,25,null,$b$Bi phung bu năch chroh jêh, hên nchih sămƀŭt ntăm jêh ma khân păng, ver sa puăch ƀư brah, ver sa mham mâu lah mpô mpa khĭt măp, jêh ri ver lơi văng tĭr.”$b$,false),
('bunong-vn','ACT',21,26,null,$b$Pô ri Y-Pôl njŭn leo phung nây ndrel ma păng. Nar ôi taơ păng ƀư nau kloh ndrel ma khân păng, jêh ri lăp tâm ngih brah Yuđa gay mbơh nar ƀư kloh mra lôch, jêh ri tâm nal nar nhhơr ndơ, yor ăp nơm khân păng.$b$,true),
('bunong-vn','ACT',21,27,null,$b$Dăch lôch pơh nar, phung Yuđa tă bơh n'gor Asi, saơ Y-Pôl tâm ngih brah Yuđa. Khân păng nsônh phung âk ƀư nau uh ah jêh ri nhŭp Y-Pôl,$b$,true),
('bunong-vn','ACT',21,28,null,$b$dôl khân păng nter pô aơ: “Hơi phung Israel, văch kơl! Aơ, bunuyh nsong nti lam ntŭk, ma lĕ rngôch bunuyh tâm rdâng đah phung ƀon lan, đah nau vay, jêh ri ta ntŭk aơ, tât păng ăn nđâp phung Grek lăp tâm ngih brah Yuđa, jêh ri ƀư ƀơ̆ ntŭk kloh ueh aơ.”$b$,false),
('bunong-vn','ACT',21,29,null,$b$Yor lah, lor ri khân păng saơ Y-Trôphim ƀon Êphêsô, gŭ ndrel ma păng tâm ƀon, jêh ri khân păng ntôn Y-Pôl, nơm njŭn leo păng tâm ngih brah Yuđa.$b$,false),
('bunong-vn','ACT',21,30,null,$b$Lĕ ƀon lan jêng uh ah, jêh ri âk bunuyh nchuăt văch. Khân păng nhŭp Y-Pôl jêh ri têk ô băl luh tă bơh ngih brah Yuđa. Jêh ri bu nchăng lơi mpông ro.$b$,false),
('bunong-vn','ACT',21,31,null,$b$Dôl khân păng joi nau dơi nkhĭt ô băl, kôranh ta han toyh tăng lư bơh lĕ ƀon Yêrusalem geh nau uh ah.$b$,false),
('bunong-vn','ACT',21,32,null,$b$Ƀât lât păng sŏk ta han, nđâp ma phung kôranh ta han, nchuăt ran ta phung âk. Tơ lah saơ kôranh ta han toyh jêh ri phung ta han, khân păng mâu hôm dong Y-Pôl.$b$,false),
('bunong-vn','ACT',21,33,null,$b$Kôranh ta han toyh hăn dăch, nhŭp Y-Pôl, đă bu kât ma bar njăr rse rvăk jêh ri păng ôp, mbu păng jêng jêh ri moh nau păng ƀư.$b$,false),
('bunong-vn','ACT',21,34,null,$b$Ƀiă lah tâm phung âk nây ƀa ƀă nter lah pô aơ, ƀa ƀă nter lah pô ri, jêh ri yor nau uh ah, păng mâu dơi gĭt nau ngăn. Pô ri, păng đă bu njŭn leo tâm pôih.$b$,false),
('bunong-vn','ACT',21,35,null,$b$Tơ lah Y-Pôl tât ta gung, phung ta han chông păng yor lah phung âk bu ƀư djơh ngăn.$b$,true),
('bunong-vn','ACT',21,36,null,$b$Yor lah phung âk tĭng ndô̆ jêh ri nter lah: “Nkhĭt lơi hom păng!”$b$,false),
('bunong-vn','ACT',21,37,null,$b$Dôl ntơm lăp tâm pôih, Y-Pôl lah ma kôranh ta han toyh: “Dơi ăn lĕ gâp ngơi bar pe tong đah may?” Kôranh ta han toyh plơ̆ lah: “May blau lĕ ngơi nau Grek?$b$,true),
('bunong-vn','ACT',21,38,null,$b$Pô ri, may mâu gĭt hĕ du huê Êjipt, nơm ƀư rlăng nôk ri, jêh ri njŭn leo tâm bri rdah puăn rbăn nuyh nơm ntŭng?”$b$,false),
('bunong-vn','ACT',21,39,null,$b$Y-Pôl lah ma păng: “Gâp jêng du huê Yuđa, ƀon Tars, n'gor Silisi, ƀon nây mâu di ôh ƀon mâu geh nau lư n'găr. Gâp dăn ma may, ăn gâp ngơi đah phung âk aơ.”$b$,false),
('bunong-vn','ACT',21,40,null,$b$Jêh kôranh toyh nây ăn Y-Pôl dâk ta jâng gung. Yơr ti ma phung âk; jêh ri lĕ rngôch gŭ iăt răk klăk. Y-Pôl ngơi nau Hêbrơ lah pô aơ:$b$,false),
('bunong-vn','ACT',22,1,null,$b$“Hơi phung nâu, phung mbơ̆ gâp, gŭ iăt hom nau gâp ngơi ma khân may, gay ma king gâp nơm.”$b$,true),
('bunong-vn','ACT',22,2,null,$b$Tơ lah khân păng iăt Y-Pôl ngơi nau Hêbrơ, khân păng gŭ krep ngăn, kâp iăt Y-Pôl lah:$b$,false),
('bunong-vn','ACT',22,3,null,$b$“Gâp jêng du huê Yuđa, bu deh ma gâp ta ƀon Tars, n'gor Silisi, ƀiă lah bu rong gâp ta aơ, tâm ƀon aơ gâp nti bơh Y-Gamaliel, di tĭng nâm nau vay phung che he, bêng ma nau duh nđơr ma Brah Ndu, tâm ban ma lĕ rngôch phung khân may nar aơ.$b$,false),
('bunong-vn','ACT',22,4,null,$b$Gâp ƀư mhĭk tât tâm nkhĭt phung tĭng trong aơ, chăp jêh ri krŭng nđâp ma bu ur bu klâu.$b$,false),
('bunong-vn','ACT',22,5,null,$b$Ma nau nây kôranh ƀư brah toyh jêh ri phung bu bŭnh bu ranh lĕ rngôch dơi mbơh gâp, yor lah gâp pah kan tă bơh phung nây, njuăl ma phung oh nâu ta ƀon Đamas. Ta nây gâp hăn ŭch nhŭp chăp phung chroh jêh ri njŭn khân păng ta ƀon Yêrusalem gay ma tâm rmal.$b$,false),
('bunong-vn','ACT',22,6,null,$b$“Dôl gâp hăn rŏ trong, dăch tât ta ƀon Đamas, nklang bôk nar, ƀât lât geh nau ang hâu ngăn tă bơh trôk nchrat ang jŭm gâp.$b$,true),
('bunong-vn','ACT',22,7,null,$b$Gâp cha lôt ta neh jêh ri tăng bâr lah ma gâp pô aơ: ‘Hơi Y-Sôl, hơi Y-Sôl, mâm ƀư may ƀư djơh ma gâp?’$b$,true),
('bunong-vn','ACT',22,8,null,$b$Gâp plơ̆ lah: ‘Mbu moh may, Ơ Kôranh Brah?’ Păng lah ma gâp: ‘Gâp jêng Brah Yêsu, ƀon Nasaret, may ƀư djơh mhĭk ma gâp.’$b$,false),
('bunong-vn','ACT',22,9,null,$b$Phung hăn ndrel ma gâp, saơ rah vah nau ang nây, ƀiă lah khân păng mâu tăng bâr ngơi đah gâp ôh.$b$,false),
('bunong-vn','ACT',22,10,null,$b$Pô ri gâp lah: ‘Moh gâp mra ƀư, Ơ Kôranh Brah?’ Kôranh Brah plơ̆ lah ma gâp: ‘Dâk hom may, hăn ta ƀon Đamas. Ta nây bu mra lah lĕ nau gâp đă may ƀư.’$b$,true),
('bunong-vn','ACT',22,11,null,$b$Yor lah gâp mâu hôm dơi saơ yor nau ang nây, phung hăn ndrel ma gâp têk ta ti jêh ri njŭn gâp ta ƀon Đamas.$b$,false),
('bunong-vn','ACT',22,12,null,$b$“Geh du huê, amoh păng Y-Ananias, bunuyh ueh sŏng tĭng nâm nau vay, jêh ri lĕ rngôch phung Yuđa ta ƀon Đamas nkoch bri lư n'găr ma păng jêng ueh.$b$,true),
('bunong-vn','ACT',22,13,null,$b$Nơm nây văch joi gâp jêh ri lah: ‘Hơi Y-Sôl, nâu gâp, ăn may dơi saơ!’ Ƀât lât gâp dơi saơ jêh ri uănh ta păng.$b$,false),
('bunong-vn','ACT',22,14,null,$b$Jêh ri păng lah ma gâp pô aơ: ‘Brah Ndu phung che he săch jêh, may ăn gĭt nau păng ŭch, ăn saơ nơm sŏng, jêh ri ăn iăt nau tă bơh bâr mbung Păng ngơi.$b$,false),
('bunong-vn','ACT',22,15,null,$b$Yor lah may mra jêng nơm mbơh ma Păng ta năp lĕ rngôch bunuyh nau may hŏ saơ jêh ri tăng.$b$,true),
('bunong-vn','ACT',22,16,null,$b$Aƀaơ ri, moh ndơ may gŭ kâp? Dâk hom, dơn nau ƀaptem jêh ri ƀư kloh nau tih may, ma nau kuăl mbơh sơm ma amoh Kôranh Brah!’$b$,false),
('bunong-vn','ACT',22,17,null,$b$“Dôl gâp plơ̆ sĭt ta ƀon Yêrusalem, dôl gâp gŭ mbơh sơm tâm ngih brah Yuđa, gâp geh tât nau tâm saơ,$b$,false),
('bunong-vn','ACT',22,18,null,$b$jêh ri gâp saơ Kôranh Brah ngơi đah gâp pô aơ: ‘Răng dăng hom may, luh gơnh tă bơh ƀon Yêrusalem, yor lah bu mâu mra dơn ôh, nau may mbơh nkoch bri nau gâp!’$b$,false),
('bunong-vn','ACT',22,19,null,$b$Gâp plơ̆ lah: ‘Ơ Kôranh Brah, khân păng nơm gĭt jêh gâp mâp krŭng, jêh ri dong phung chroh ma may tâm ăp ngih rƀŭn Yuđa.$b$,false),
('bunong-vn','ACT',22,20,null,$b$Rnôk bu nkhĭt Y-Êtiên, nơm mbơh nau may, gâp gŭ ta nây dơn nau khân păng ƀư, jêh ri chiă bok ao phung nkhĭt ô băl.’$b$,false),
('bunong-vn','ACT',22,21,null,$b$Păng lah ma gâp: ‘Hăn hom, yor lah gâp mra njuăl may hăn ngai ma n'gor bu năch.’ ”$b$,false),
('bunong-vn','ACT',22,22,null,$b$Bu gŭ iăt nau Y-Pôl tât ta nau nây, ƀiă lah jêh nây khân păng ntơm nter pô aơ: “Ngroh lơi bunuyh nâm nđĕ bơh neh ntu! Păng mâu khư gŭ rêh ôh.”$b$,true),
('bunong-vn','ACT',22,23,null,$b$Dôl khân păng nter huy ktang, khân păng doh bok ao mƀăr jêh ri nhom ma ndruyh neh.$b$,false),
('bunong-vn','ACT',22,24,null,$b$Kôranh ta han toyh đă bu njŭn leo Y-Pôl tâm pôih dong ma mâng, jêh ri ôp gay gĭt mâm ƀư phung âk nter ŭch ƀư ma păng.$b$,false),
('bunong-vn','ACT',22,25,null,$b$Dôl bu chăp ŭch dong păng, Y-Pôl lah ma kôranh ta han gŭ ta nây: “Vay lĕ may dong du huê phung Rôm, ê phat dôih?”$b$,false),
('bunong-vn','ACT',22,26,null,$b$Tăng nau Y-Pôl lah pô nây, kôranh ta han nây hăn mbơh ma kôranh ta han toyh lah pô aơ: “Moh may mra ƀư? Bunuyh nây jêng du huê phung Rôm.”$b$,false),
('bunong-vn','ACT',22,27,null,$b$Kôranh ta han toyh hăn ta nây jêh ri ôp Y-Pôl: “Lah ma gâp. May jêng Rôm ngăn ƀơh?” Y-Pôl plơ̆ lah: “Nanê̆ ngăn.”$b$,false),
('bunong-vn','ACT',22,28,null,$b$Kôranh ta han toyh lah: “Gâp rvăt nau dơi jêng phung Rôm khlay ngăn.” Y-Pôl plơ̆ lah: “Ƀiă lah gâp geh nau nây bơh ndŭl mê̆.”$b$,false),
('bunong-vn','ACT',22,29,null,$b$Ƀât lât phung ŭch ôp păng du êng êng, jêh ri kôranh ta han toyh nây klach, tơ lah păng gĭt bunuyh păng đă chăp nây jêng du huê Rôm.$b$,false),
('bunong-vn','ACT',22,30,null,$b$Nar ôi taơ, yor lah kôranh ta han toyh ŭch gĭt nanê̆ moh nau phung Yuđa phong Y-Pôl, păng đă bu doh lơi. Jêh păng đă phung n'gâng kôranh ƀư brah, jêh ri phung kôranh phat dôih tâm rƀŭn, păng njŭn leo Y-Pôl jêh ri ăn păng gŭ ta năp phung nây.$b$,true),
('bunong-vn','ACT',23,1,null,$b$Y-Pôl nđar măt ma phung kôranh phat dôih lah pô aơ: “Hơi phung oh nâu, ta năp Brah Ndu gâp gŭ ngao krao sach ma nuih n'hâm sŏng tât ta nar aơ.”$b$,true),
('bunong-vn','ACT',23,2,null,$b$Kôranh ƀư brah toyh, Y-Nanias đă nơm gŭ dăch, tap ta mbung Y-Pôl.$b$,true),
('bunong-vn','ACT',23,3,null,$b$Ƀiă lah Y-Pôl lah ma păng: “Hơi mpêr mhĭng dak nglang, Brah Ndu mra dong may! May phat dôih gâp tĭng nâm nau vay, ƀiă lah may rlau nau vay đă bu dong gâp.”$b$,false),
('bunong-vn','ACT',23,4,null,$b$Phung gŭ ta nây lah: “May suai rak kôranh ƀư brah toyh Brah Ndu hĕ?”$b$,false),
('bunong-vn','ACT',23,5,null,$b$Y-Pôl plơ̆ lah: “Hơi phung oh nâu, gâp mâu gĭt ôh păng jêng kôranh ƀư brah toyh, yor lah geh nau nchih jêh pô aơ: ‘Lơi ngơi ndjơh ma kôranh phung ƀon lan ôh.’ ”$b$,false),
('bunong-vn','ACT',23,6,null,$b$Tơ lah Y-Pôl gĭt tâm phung khân păng du ntil phung Sađusê, jêh ri du ntil êng jêng phung Pharisi, păng nter ta năp phung phat dôih pô aơ: “Hơi oh nâu, gâp jêng du huê Pharisi, kon phung Pharisi, yor nau kâp gân ma nau phung khĭt dâk rêh bu phat dôih gâp.”$b$,true),
('bunong-vn','ACT',23,7,null,$b$Jêh păng ngơi pô nây, phung Pharisi tâm rlăch đah phung Sađusê, jêh ri phung tâm rƀŭn ta nây tâm pă.$b$,false),
('bunong-vn','ACT',23,8,null,$b$Yor lah phung Sađusê, lah mâu geh nau dâk rêh ôh, mâu lĕ geh Tông mpăr ueh mâu lah brah; ƀiă lah phung Pharisi chroh lĕ ma bar ntil nau nây.$b$,false),
('bunong-vn','ACT',23,9,null,$b$Pô ri geh nau tâm ngơi ktang, jêh ri geh phung kôranh nchih sămƀŭt mpeh ma Pharisi dâk jêh ri tâm rlăch đah phung êng lah pô aơ: “Hên mâu saơ ôh du ntil nau tih tâm bunuyh aơ. Gĭt lah brah mâu lah Tông mpăr ueh ngơi đah păng?”$b$,false),
('bunong-vn','ACT',23,10,null,$b$Yor nau uh ah nây lơ hâu toyh, kôranh ta han toyh klach bu mra ƀư rai săk jăn Y-Pôl, ăn ta han păng jŭr, pit sŏk leo Y-Pôl sĭt ta pôih.$b$,false),
('bunong-vn','ACT',23,11,null,$b$Măng pa kơi Kôranh Brah tâm mpơl ma Y-Pôl jêh ri lah: “Gŭ nâp hom, tâm ban ma may mbơh nau gâp ta ƀon Yêrusalem, may mra mbơh ta ƀon Rôm tâm ban lĕ.”$b$,false),
('bunong-vn','ACT',23,12,null,$b$Nar ôi taơ, phung Yuđa rƀŭn tâm nchră jêh ri sân săk lah ma khân păng, ver sông sa nhêt tât khân păng dơi nkhĭt Y-Pôl.$b$,true),
('bunong-vn','ACT',23,13,null,$b$Phung khân păng rmeh tâm puăn jât nuyh mĭn ma nau nây.$b$,false),
('bunong-vn','ACT',23,14,null,$b$Păng hăn joi phung n'gâng kôranh ƀư brah jêh ri phung bu bŭnh bu ranh, jêh ri lah ma phung nây pô aơ: “Hên sân jêh săk hên nơm, mâu mra sông sa ôh, tât hên dơi nkhĭt Y-Pôl.$b$,false),
('bunong-vn','ACT',23,15,null,$b$Pô ri aƀaơ ri khân may đah phung kôranh phat dôih dăn hom ma kôranh ta han toyh, ăn njŭn leo Y-Pôl ta năp khân may, tâm ban khân may ŭch sek uănh nanê̆ moh nau păng ƀư. Bi hên, gŭ kâp nkhĭt păng lor păng tât ta aơ.”$b$,false),
('bunong-vn','ACT',23,16,null,$b$Ƀiă lah kon ruh Y-Pôl gĭt nau bu ŭch ƀư ma Y-Pôl. Păng lăp tâm pôih mbơh nau nây ma Y-Pôl.$b$,false),
('bunong-vn','ACT',23,17,null,$b$Y-Pôl kuăl du huê kôranh ta han jêh ri lah: “Njŭn leo kon se aơ ma kôranh ta han toyh, păng geh nau mhe hăn ŭch mbơh.”$b$,false),
('bunong-vn','ACT',23,18,null,$b$Kôranh ta han njŭn kon se nây ma kôranh ta han toyh jêh ri lah: “Du huê bu nă, amoh păng Y-Pôl, kuăl gâp jêh ri đă gâp njŭn kon se aơ ma may, yor lah păng geh nau ŭch nkoch ma may.”$b$,false),
('bunong-vn','ACT',23,19,null,$b$Kôranh ta han toyh kuăn ta ti kon se leo păng ta ntŭk êng, jêh ri ôp: “Moh nau may ŭch mbơh ma gâp?”$b$,false),
('bunong-vn','ACT',23,20,null,$b$Kon se nây lah: “Phung Yuđa ŭch dăn ma may, ôi taơ njŭn Y-Pôl ta năp phung kôranh phat dôih, tâm ban ma khân păng ŭch sek uănh nanê̆ moh nau Y-Pôl ƀư.$b$,false),
('bunong-vn','ACT',23,21,null,$b$Ƀiă lah lơi may iăt nau phung nây, yor lah geh rmeh puăn jât nuyh tâm phung khân păng, hŏ tâm nchră jêh gay ƀư ƀai ma Y-Pôl. Khân păng sân săk jăn ât sông sa nhêt tât khân păng dơi nkhĭt Y-Pôl. Aƀaơ khân păng gŭ kâp, knŏng kâp nau may dơm.”$b$,false),
('bunong-vn','ACT',23,22,null,$b$Kôranh ta han toyh nây ăn kon se sĭt, buay lơi ăn nkoch ma bu lĕ nau păng hŏ mbơh jêh.$b$,false),
('bunong-vn','ACT',23,23,null,$b$Jêh ri kôranh ta han toyh kuăl bar hê kôranh ta han jêh ri ntăm pô aơ: “Ta pe mông măng ta oi, ăn khân may kuăl bar rhiăng ta han, pơh jât nuyh ta han ncho seh, jêh ri bar rhiăng nuyh ta han djôt tak, mra hăn ta ƀon Sêsarê.$b$,true),
('bunong-vn','ACT',23,24,null,$b$Nkra đŏng seh gay njŭn Y-Pôl, hăn ta kôranh n'gor Phêlik ma nau đăp mpăn.”$b$,false),
('bunong-vn','ACT',23,25,null,$b$Jêh ri păng nchih sămƀŭt ma kôranh n'gor nây pô aơ:$b$,false),
('bunong-vn','ACT',23,26,null,$b$“Klôt Lysias nchih khâl ma kôranh n'gor toyh, Phêlik.$b$,false),
('bunong-vn','ACT',23,27,null,$b$Phung Yuđa nhŭp jêh bunuyh aơ gay ma nkhĭt. Tơ lah gâp tât ndrel ma phung ta han, gâp pit sŏk păng, yor lah gâp gĭt păng jêng du huê phung Rôm.$b$,false),
('bunong-vn','ACT',23,28,null,$b$Gay ŭch gĭt moh nau bu ŭch phong păng, gâp đă bu njŭn păng ta năp phung kôranh phat dôih phung Yuđa.$b$,false),
('bunong-vn','ACT',23,29,null,$b$Gâp saơ nau bu phong păng, rlau nau vay khân păng nơm, ƀiă lah păng mâu mâp ƀư tih khư ma nau khĭt mâu lah krŭng ôh.$b$,false),
('bunong-vn','ACT',23,30,null,$b$Gâp gĭt phung Yuđa kâp ƀư djơh ma păng, pô ri gâp njuăl păng ma may ro, jêh ri ntênh phung phong păng hăn ngơi ta năp may.”$b$,false),
('bunong-vn','ACT',23,31,null,$b$Tĭng nâm nau ntăm, phung ta han sŏk Y-Pôl dôl măng, jêh ri njŭn păng tât ta ƀon Antipatris.$b$,true),
('bunong-vn','ACT',23,32,null,$b$Nar ôi taơ khân păng ăn ta han ncho seh hăn ndrel ma Y-Pôl, jêh ri khân păng plơ̆ sĭt ta pôih.$b$,false),
('bunong-vn','ACT',23,33,null,$b$Tât ta ƀon Sêsarê, phung ta han ncho seh, ăn sămƀŭt jêh ri jao Y-Pôl ma kôranh n'gor.$b$,false),
('bunong-vn','ACT',23,34,null,$b$Jêh uănh sămƀŭt, kôranh n'gor ôp ntŭk Y-Pôl gŭ. Jêh gĭt Y-Pôl jêng bunuyh tă bơh n'gor Silisi.$b$,false),
('bunong-vn','ACT',23,35,null,$b$Kôranh n'gor lah ma păng pô aơ: “Tơ lah phung phong may tât gâp mra iăt nau may.” Jêh ri păng đă bu mât Y-Pôl tâm ngih hađăch Hêrôt.$b$,true),
('bunong-vn','ACT',24,1,null,$b$Prăm nar ma nây kôranh ƀư brah toyh, Y-Ananias, tât ndrel ma phung bu bŭnh bu ranh jêh ri du huê nơm ngơi, amoh păng Y-Tertulus. Khân păng phong Y-Pôl ta năp kôranh n'gor.$b$,true),
('bunong-vn','ACT',24,2,null,$b$Bu kuăl Y-Pôl, jêh ri Y-Tertulus ntơm phong păng pô aơ: “Hơi kôranh n'gor Phêlik, nơm ueh ngăn, may ăn ma hên nau đăp mpăn, jêh ri yor nau may blau mĭn n'gor aơ geh nau rgâl jêng ueh.$b$,false),
('bunong-vn','ACT',24,3,null,$b$Pô ri, tâm lĕ rngôch nau, jêh ri tâm lĕ rngôch ntŭk hên kah gĭt tôr ma may âk ngăn.$b$,false),
('bunong-vn','ACT',24,4,null,$b$Ƀiă lah mâu ŭch kân may jŏ ta aơ ôh, gâp dăn ma may gŭ iăt ma nuih n'hâm ueh may nau hên mra ngơi bar pe tong.$b$,false),
('bunong-vn','ACT',24,5,null,$b$Hên saơ bunuyh aơ tâm ban ma nau ji tưp, ƀư uh ah lĕ rngôch phung Yuđa, lam bri neh. Păng jêng du huê kôranh ma phung Nasaret.$b$,false),
('bunong-vn','ACT',24,6,null,$b$Jêh ri păng ŭch ƀư ƀơ̆ lơi ngih brah Yuđa. Pô ri hên nhŭp chăp păng. Hên ŭch phat dôih păng tĭng nâm nau vay hên.$b$,false),
('bunong-vn','ACT',24,7,null,$b$Ƀiă lah kôranh ta han toyh Y-Lysias văch ƀư janh, pit păng ta ti hên, jêh ri ntăm ma phung phong păng hăn ta năp may.$b$,false),
('bunong-vn','ACT',24,8,null,$b$May nơm mra dơi ôp păng, jêh ri may mra gĭt moh nau hên phong păng.”$b$,false),
('bunong-vn','ACT',24,9,null,$b$Phung Yuđa dơn nau phong nây, khân păng lah nanê̆ pô aơ.$b$,true),
('bunong-vn','ACT',24,10,null,$b$Jêh kôranh n'gor nchŏng ti đă Y-Pôl ngơi, păng plơ̆ lah pô aơ: “Yor gâp gĭt jêh may jêng kôranh phat dôih tâm n'gor aơ jŏ năm jêh, pô ri gâp janh ngơi king săk gâp nơm.$b$,true),
('bunong-vn','ACT',24,11,null,$b$May dơi gĭt ngăn, ê gao ôh jât ma bar nar ntơm bơh gâp tât ta ƀon Yêrusalem, gay ma mbah yơk ma Brah Ndu.$b$,false),
('bunong-vn','ACT',24,12,null,$b$Bu mâu mâp saơ gâp tâm rlăch đah bu, mâu lah ƀư uh ah ma ƀon lan tâm ngih brah Yuđa, tâm ngih tâm rƀŭn Yuđa, mâu lah tâm ƀon toyh.$b$,false),
('bunong-vn','ACT',24,13,null,$b$Aƀaơ aơ mâu lĕ saơ khân păng tâm mpơl nanê̆, nau khân păng phong gâp.$b$,false),
('bunong-vn','ACT',24,14,null,$b$Gâp mbơh ta năp may, gâp yơk ma Brah Ndu che hên, tĭng nâm trong khân păng lah jêng du phung tih, ƀiă lah gâp chroh lĕ nau nchih jêh tâm ndrom sămƀŭt nau vay, jêh ri nau phung kôranh nơm mbơh lor.$b$,true),
('bunong-vn','ACT',24,15,null,$b$Jêh ri gâp geh nau kâp gân aơ tâm Brah Ndu, tâm ban ma khân păng lĕ, nâm bu ntĭt, phung sŏng jêh ri phung kue mra geh nau dâk rêh.$b$,false),
('bunong-vn','ACT',24,16,null,$b$Yor nây gâp tĭng joi ƀa ƀơ gay geh nuih n'hâm sŏng, mâu geh nau nduyh ôh ta năp Brah Ndu jêh ri ta năp bunuyh.$b$,false),
('bunong-vn','ACT',24,17,null,$b$Jŏ năm jêh ndŭt kơi gâp sĭt ăn ndơ yô̆ ma ndŭl mpôl gâp, jêh ri nhhơr mpa.$b$,false),
('bunong-vn','ACT',24,18,null,$b$Rnôk nây yơh geh phung Yuđa tă bơh n'gor Asi saơ gâp ƀư nau kloh tâm ngih brah Yuđa, mâu geh phung âk mâu lah nau uh ah ôh.$b$,false),
('bunong-vn','ACT',24,19,null,$b$Ăn khân păng văch phong ta năp may, tơ lah khân păng geh nau đah gâp.$b$,false),
('bunong-vn','ACT',24,20,null,$b$Mâu lah ăn phung gŭ ta aơ mbơh, moh nau tih khân păng saơ gâp ƀư, dôl gâp gŭ ta năp phung kôranh phat dôih.$b$,false),
('bunong-vn','ACT',24,21,null,$b$Tơ lah geh, knŏng dơi nduyh yor nau gâp nter ngơi tâm nklang khân păng pô aơ, yor nau phung khĭt dâk rêh yơh bu phat dôih gâp ta năp khân may nar aơ.”$b$,true),
('bunong-vn','ACT',24,22,null,$b$Kôranh n'gor Phêlik gĭt nanê̆ jêh ma Trong, pô ri păng njong nar phat dôih jêh ri lah: “Tơ lah kôranh ta han toyh, Y-Lysias, văch, gâp mra sek uănh an nau aơ.”$b$,true),
('bunong-vn','ACT',24,23,null,$b$Jêh ri păng đă kôranh ta han mât Y-Pôl, ƀiă lah ăn nau nơih ma păng, jêh ri mâu buay ôh mbu nơm văch ŭch kơl păng.$b$,false),
('bunong-vn','ACT',24,24,null,$b$Bar pe nar pa kơi, Kôranh n'gor Phêlik hăn ndrel ma ur păng, H'Drusil, bu ur Yuđa, jêh ri đă bu kuăl Y-Pôl, ŭch iăt nau păng nti ma nau chroh ma Yêsu Krist.$b$,true),
('bunong-vn','ACT',24,25,null,$b$Ƀiă lah dôl Y-Pôl ngơi ma nau sŏng srăng, ma nau di rnâng jêh ri ma nau phat dôih tâm du nar kăndơ̆ , kôranh n'gor Phêlik klach jêh ri lah: “Sĭt hom may aƀaơ ro. Tơ lah gâp ru, gâp mra kuăl may.”$b$,false),
('bunong-vn','ACT',24,26,null,$b$Păng kâp Y-Pôl mra blŏl drăp ma păng, pô ri păng kuăl Y-Pôl văch ƀa ƀơ, ŭch ngơi đah ô băl.$b$,false),
('bunong-vn','ACT',24,27,null,$b$Bar năm pa kơi, Pôrtus Phêtus ntrok kôranh n'gor Phêlik, yor lah kôranh n'gor Phêlik ŭch ƀư maak ma phung Yuđa, ăt păng ăn bu krŭng Y-Pôl.$b$,false),
('bunong-vn','ACT',25,1,null,$b$Jêh păng tât ta n'gor nây, pe nar ma nây, Phêtus, tă bơh ƀon Sêsarê, leo hăn ta ƀon Yêrusalem.$b$,true),
('bunong-vn','ACT',25,2,null,$b$Phung n'gâng kôranh ƀư brah jêh ri phung bu bŭnh bu ranh tâm phung Yuđa phong Y-Pôl ta năp păng.$b$,false),
('bunong-vn','ACT',25,3,null,$b$Khân păng dăn vơh vơl ma Phêtus ƀư ueh ma khân păng, ăn kuăl Y-Pôl plơ̆ sĭt ta ƀon Yêrusalem. Khân păng kâp nkhĭt Y-Pôl rŏ trong.$b$,false),
('bunong-vn','ACT',25,4,null,$b$Phêtus lah: “Y-Pôl bu krŭng ta ƀon Sêsarê, jêh ri păng nơm hăn gơnh lĕ ta nây.”$b$,false),
('bunong-vn','ACT',25,5,null,$b$Phêtus lah: “Ăn phung kôranh tâm phung khân may hăn ndrel ma gâp, jêh ri tơ lah bunuyh nây geh nau tih, ăn khân may phong păng.”$b$,false),
('bunong-vn','ACT',25,6,null,$b$Jêh Phêtus gŭ ta nây klăp lah tâm pham mâu lah jât nar, păng trŭnh ta Sêsarê, ôi taơ păng gŭ ta sưng phat dôih, jêh ri đă bu njŭn Y-Pôl ma păng.$b$,true),
('bunong-vn','ACT',25,7,null,$b$Tơ lah Y-Pôl tât, phung Yuđa tă bơh ƀon Yêrusalem gŭ jŭm păng jêh ri phong âk nau tih toyh, ƀiă lah khân păng mâu dơi ƀư rah vah ôh.$b$,false),
('bunong-vn','ACT',25,8,null,$b$Y-Pôl ngơi king ma păng nơm pô aơ: “Gâp mâu mâp ƀư tih ma nau vay phung Yuđa ôh mâu lĕ mâp ƀư tih ma ngih brah Yuđa, mâu lah đah Sêsar tâm ban lĕ.”$b$,false),
('bunong-vn','ACT',25,9,null,$b$Ƀiă lah Phêtus, ŭch ƀư maak ma phung Yuđa, lah ma Y-Pôl pô aơ: “May ŭch hăn đŏng ta ƀon Yêrusalem, jêh ri bu phat dôih may ta nây ta năp gâp?”$b$,false),
('bunong-vn','ACT',25,10,null,$b$Ƀiă lah Y-Pôl lah: “Gâp ŭch nau Sêsar phat dôih. Ta nây yơh bu dơi phat dôih gâp. Gâp mâu mâp tih đah phung Yuđa ôh, nâm bu may hŏ gĭt rah vah jêh nau nây.$b$,true),
('bunong-vn','ACT',25,11,null,$b$Tơ lah gâp geh nau kue mâu lah ƀư tih khư khĭt, gâp mâu dun nau khĭt ôh, ƀiă lah, tơ lah nau khân păng phong gâp mâu di, mâu geh du huê dơi jao gâp ma khân păng ôh. Gâp ŭch dăn nau aơ tât ta Sêsar.”$b$,false),
('bunong-vn','ACT',25,12,null,$b$Pô ri, jêh tâm nchră đah phung kôranh ta nây, Phêtus lah ma Y-Pôl: “May ŭch dăn ma Sêsar. May mra hăn ta Sêsar.”$b$,false),
('bunong-vn','ACT',25,13,null,$b$Bar pe nar ma nây, hađăch Agripa jêh ri H'Bêrênis tât ta ƀon Sêsarê, ŭch tâm khâl đah Phêtus.$b$,true),
('bunong-vn','ACT',25,14,null,$b$Yor lah khân păng gŭ jŏ nar ta nây, Phêtus nkoch ma hađăch nây nau Y-Pôl pô aơ: “Kôranh n'gor Phêlik ăn ta aơ du huê bu nă.$b$,false),
('bunong-vn','ACT',25,15,null,$b$Dôl gâp gŭ ta ƀon Yêrusalem phung n'gâng kôranh ƀư brah, jêh ri phung bu bŭnh bu ranh tâm phung Yuđa phong păng, jêh ri dăn ma gâp rmal păng.$b$,false),
('bunong-vn','ACT',25,16,null,$b$Gâp plơ̆ lah ma khân păng: Phung Rôm mâu vay ôh jao du huê bunuyh, tơ lah ê mâp geh nau tâm ngơi ta năp phung phong păng, jêh ri nơm nây ê geh nau dơi tâm nkăl đah phung phong păng.$b$,false),
('bunong-vn','ACT',25,17,null,$b$Pô ri khân păng văch ta aơ, jêh ri ôi taơ, gâp gŭ ta ngih phat dôih đă bu njŭn păng ro, mâu kâp ôh.$b$,false),
('bunong-vn','ACT',25,18,null,$b$Phung phong păng gŭ ta nây da dê, ƀiă lah mâu phong ma păng du ntil nau tih tâm ban ma gâp mĭn ôh;$b$,false),
('bunong-vn','ACT',25,19,null,$b$ƀiă lah khân păng phong ma nau brah phung khân păng, jêh ri ma du huê, amoh Brah Yêsu, khĭt jêh, ƀiă lah Y-Pôl mbơh ngăn ma nau păng hôm gŭ rêh.$b$,false),
('bunong-vn','ACT',25,20,null,$b$Tâm nau tâm rlăch nây gâp mâu gĭt ôh mbah ma gâp gŭ. Pô ri gâp ôp Y-Pôl, tơ lah păng ŭch hăn phat dôih nau nây ta ƀon Yêrusalem.$b$,false),
('bunong-vn','ACT',25,21,null,$b$Ƀiă lah Y-Pôl dăn ŭch kâp Sêsar Ôgust gĭt nau păng. Pô ri gâp đă bu mât păng tât nar gâp dơi njuăl păng ma Sêsar.”$b$,false),
('bunong-vn','ACT',25,22,null,$b$Agripa lah ma Phêtus: “Gâp ŭch iăt nau păng lĕ.” Phêtus plơ̆ lah: “Ôi taơ may mra tăng nau păng.”$b$,false),
('bunong-vn','ACT',25,23,null,$b$Pô ri, nar ôi taơ hađăch Agripa, jêh ri H'Bêrênis văch ma nau nkhưm rnam, jêh ri lăp tâm jrô phat dôih ndrel ma phung kôranh ta han toyh, jêh ri phung kôranh tâm ƀon nây. Phêtus đă bu njŭn leo Y-Pôl ta nây.$b$,true),
('bunong-vn','ACT',25,24,null,$b$Jêh ri Phêtus lah: “Hơi hađăch Agripa, jêh ri lĕ rngôch phung gŭ tâm aơ khân may saơ bunuyh aơ. Yor păng yơh lĕ rngôch phung Yuđa, nđâp ma tâm ƀon Yêrusalem, nđâp ta aơ, văch ta gâp, nter dăn lơi hôm ăn păng gŭ rêh ôh.$b$,false),
('bunong-vn','ACT',25,25,null,$b$Ƀiă lah gâp mâu saơ nau tih păng khư nau khĭt ôh; jêh ri păng nơm lĕ, ŭch dăn ma nau aơ ŭch tât ta Sêsar Ôgust. Pô ri gâp mĭn mra njuăl păng ma hađăch nây.$b$,false),
('bunong-vn','ACT',25,26,null,$b$Gâp mâu gĭt, moh di tâm nau aơ dơi nchih ma Sêsar. Pô ri gâp đă bu njŭn leo păng ta năp khân may, lor lơn ma may yơh, hađăch Agripa. Pô nây mơ, jêh may sek ôp păng, gâp mra geh nau dơi nchih ma hađăch Sêsar.$b$,false),
('bunong-vn','ACT',25,27,null,$b$Yor lah mâu vay ôh njuăl du huê bu nă tơ lah mâu mbơh moh ntil nau bu phong păng.”$b$,false),
('bunong-vn','ACT',26,1,null,$b$Hađăch Agripa lah ma Y-Pôl: “Ăn may ngơi king ma may nơm.” Y-Pôl yơr ti jêh ri ngơi king ma păng nơm pô aơ:$b$,true),
('bunong-vn','ACT',26,2,null,$b$“Hơi hađăch Agripa, gâp geh nau ƀun ngăn, yor lah gâp dơi king gâp nơm nar aơ ma lĕ nau phung Yuđa phong gâp.$b$,false),
('bunong-vn','ACT',26,3,null,$b$Rplay khlay ngăn ngên, yor lah hađăch gĭt jêh lĕ nau vay phung Yuđa, jêh ri nau khân păng tâm rlăch. Pô ri gâp dăn ma hađăch srôih gŭ iăt nau gâp.$b$,true),
('bunong-vn','ACT',26,4,null,$b$Nau gâp gŭ ngao krao sach ntơm bơh hôm jêng kon se, tâm nklang phung ndŭl mpôl gâp, jêh ri ta ƀon Yêrusalem, lĕ rngôch phung Yuđa gĭt da dê jêh.$b$,false),
('bunong-vn','ACT',26,5,null,$b$Tơ lah khân păng ŭch mbơh, khân păng hŏ gĭt bơh jŏ jêh gâp jêng du huê Pharisi, tĭng nâm nau vay ktang ngăn tâm nau phung hên chroh.$b$,false),
('bunong-vn','ACT',26,6,null,$b$Aƀaơ bu phat dôih gâp, yor lah kâp gân nau Brah Ndu ton jêh ma phung che hên.$b$,false),
('bunong-vn','ACT',26,7,null,$b$Phung jât ma bar ndŭl mpôl hên hŭch rhŭl yơk ma Brah Ndu măng, nar gay ma nau ton nây mra tât ngăn. Yor nau kâp gân nây yơh, hơi hađăch, phung Yuđa phong gâp.$b$,false),
('bunong-vn','ACT',26,8,null,$b$Hơi! Khân may mĭn, mâu hĕ dơi chroh ma Brah Ndu dơi ăn rêh phung bunuyh khĭt?$b$,false),
('bunong-vn','ACT',26,9,null,$b$“Nanê̆ gâp mĭn jêh lĕ nau ŭch ƀư ktang. Tâm rdâng đah amoh Brah Yêsu ƀon Nasaret.$b$,true),
('bunong-vn','ACT',26,10,null,$b$Gâp ƀư jêh pô nây ta ƀon Yêrusalem. Jêh gâp geh nau dơi tă bơh phung n'gâng kan kôranh ƀư brah, gâp krŭng âk phung kloh ueh, jêh ri tơ lah bu nkhĭt khân păng gâp dơn lĕ.$b$,false),
('bunong-vn','ACT',26,11,null,$b$Ƀa ƀơ gâp dong khân păng tâm lĕ rngôch ngih tâm rƀŭn Yuđa jêh ri nchâp khân păng ngơi sưr rlau. Dôl gâp ji nuih ma khân păng, gâp ƀư djơh ma khân păng kŏ tât ta ƀon phung bu năch.$b$,false),
('bunong-vn','ACT',26,12,null,$b$“Hơi hađăch, yor nây du nar gâp hăn ta ƀon Đamas ma nau dơi tă bơh phung n'gâng kôranh ƀư brah.$b$,true),
('bunong-vn','ACT',26,13,null,$b$Tâm nar nklang bôk dôl hăn, gâp saơ nau ang tă bơh trôk, ang lơn ma nar, sol nchrat jŭm gâp jêh ri phung hăn ndrel ma gâp.$b$,false),
('bunong-vn','ACT',26,14,null,$b$Lĕ rngôch hên cha lôt ta neh da dê, jêh ri gâp tăng bâr ngơi lah ma gâp tâm nau Hêbrơ: ‘Hơi Y-Sôl, hơi Y-Sôl, mâm ƀư may ƀư mhĭk ma gâp? Jêr ngăn may chưng loih mplanh.’$b$,false),
('bunong-vn','ACT',26,15,null,$b$Gâp plơ̆ lah: ‘Mbu may jêng Ơ Kôranh Brah?’ Kôranh Brah plơ̆ lah: ‘Gâp jêng Brah Yêsu, Nơm may hŏ ƀư mhĭk.$b$,false),
('bunong-vn','ACT',26,16,null,$b$Dâk hom may, yor lah gâp ŭch tâm mpơl ma may, ŭch ăn may jêng oh mon ktang gâp jêh ri nơm mbơh ma lĕ rngôch nau may hŏ saơ jêh, jêh ri nđâp ma nau gâp mra tâm mpơl ma may.$b$,false),
('bunong-vn','ACT',26,17,null,$b$Gâp săch jêh may tă bơh tâm phung mpôl băl aơ, jêh ri phung bu năch, mpeh ma khân păng gâp mra njuăl may hăn,$b$,true),
('bunong-vn','ACT',26,18,null,$b$gay ma may pơk an măt khân păng, ăn khân păng du bơh nau ngo hăn tâm nau ang, jêh ri bơh nau Satan, rŏng ma Brah Ndu, gay ma nau chroh ma gâp, khân păng geh nau yô̆ an nau tih, jêh ri ndơn drăp ndrel ma phung kloh ueh.’$b$,false),
('bunong-vn','ACT',26,19,null,$b$“Hơi hađăch Agripa, ntơm bơh nây gâp mâu janh tâm rdâng đah nau tâm saơ tă bơh trôk ôh.$b$,false),
('bunong-vn','ACT',26,20,null,$b$Ƀiă lah gâp mbơh lor lơn ma phung ƀon Đamas, ma phung ƀon Yêrusalem, ma lĕ n'gor Yuđa, jêh ri ma phung bu năch, ăn khân păng rmal nau tih jêh ri sĭt ma Brah Ndu, pah kan khư ma nau tâm rmal ma nau tih.$b$,false),
('bunong-vn','ACT',26,21,null,$b$Yor nây phung Yuđa nhŭp gâp tâm ngih brah Yuđa, jêh ri ŭch nkhĭt gâp.$b$,false),
('bunong-vn','ACT',26,22,null,$b$Ƀiă lah Brah Ndu king gâp, pô ri gâp ăt hôm gŭ rêh tât ta nar aơ, jêh ri mbơh ma phung jê̆ jêh ri phung toyh knŏng nau kôranh nơm mbơh lor, jêh ri Y-Môis mbơh jêh mra tât,$b$,false),
('bunong-vn','ACT',26,23,null,$b$nâm bu ntĭt, ma Brah Krist mra dơn nau rêh ni, mra jêng nơm dâk rêh lor lơn bơh phung khĭt, jêh ri mra mbơh nau ang ma phung ƀon lan jêh ri ma phung bu năch.”$b$,false),
('bunong-vn','ACT',26,24,null,$b$Dôl Y-Pôl ngơi king ma păng nơm pô nây, Phêtus ngơi huy pô aơ: “Hơi Y-Pôl, may roh nau mĭn jêh. May nti âk ngăn tât may jêng rluk.”$b$,true),
('bunong-vn','ACT',26,25,null,$b$Y-Pôl plơ̆ lah: “Gâp mâu jêng rluk ôh, hơi Phêtus, nơm ueh ngăn, ƀiă lah nau gâp ngơi ngăn jêh ri di.$b$,false),
('bunong-vn','ACT',26,26,null,$b$Hađăch gĭt nanê̆ jêh nau aơ, jêh ri gâp janh ngơi ma păng ma nau nơih, yor lah gâp mĭn păng gĭt jêh lĕ rngôch nau, yor lah lĕ nau aơ mâu ƀư ma nau ndâp ôh.$b$,true),
('bunong-vn','ACT',26,27,null,$b$Hơi hađăch Agripa, may chroh lĕ ma nau phung kôranh nơm mbơh lor? Gâp gĭt ngăn ma may chroh.”$b$,false),
('bunong-vn','ACT',26,28,null,$b$Hađăch Agripa plơ̆ lah ma Y-Pôl: “Bơi ma may nchâp gâp jêng du huê phung oh mon Brah Krist!”$b$,false),
('bunong-vn','ACT',26,29,null,$b$Y-Pôl ngơi: “Gâp dăn ma Brah Ndu, nđâp tơ lah gŭ jŏ mâu lah gơnh, mâu di knŏng êng hađăch ôh, ƀiă lah nđâp ma lĕ rngôch bunuyh phung gŭ iăt gâp nar aơ mra jêng nâm bu gâp, yŏng mâu geh rse rvăk aơ.”$b$,false),
('bunong-vn','ACT',26,30,null,$b$Pô ri, hađăch, kôranh n'gor, H'Bêrênis, jêh ri lĕ rngôch phung gŭ ndrel ma khân păng dâk da dê.$b$,true),
('bunong-vn','ACT',26,31,null,$b$Dôl khân păng du, khân păng tâm lah ndrăng nơm pô aơ, mâu geh nau tih khư khĭt mâu lah krŭng ôh tâm bunuyh aơ.$b$,false),
('bunong-vn','ACT',26,32,null,$b$Agripa lah ma Phêtus: “May dơi mƀơk păng tơ lah păng ê dăn nau phat dôih ta năp Sêsar.”$b$,false),
('bunong-vn','ACT',27,1,null,$b$Jêh tâm nchră ma nau ăn hên ncho kŭmpăn hăn ta n'gor Italy, bu jao Y-Pôl ndrel ma du huê bu nă êng, ma du huê kôranh ta han, amoh păng Y-Julius tâm phung ta han Ôgust.$b$,true),
('bunong-vn','ACT',27,2,null,$b$Hên ncho kŭmpăn tă bơh Adramit mra tĭng njŏ kơh rlai n'gor Asi. Hên hăn jêh ri geh Y-Aristar, du huê Mêsêdôn tă bơh ƀon Têsalônik ndrel ma hên.$b$,false),
('bunong-vn','ACT',27,3,null,$b$Nar pa kơi hên tât ta ƀon Sidôn, jêh ri Y-Julius ƀư ueh ma Y-Pôl, ăn păng khâl phung mĭt jiăng păng, jêh ri dơi dơn ndơ bu ăn kơl.$b$,false),
('bunong-vn','ACT',27,4,null,$b$Tă bơh nây hên hăn njŏ kơh kôdak Chiprơ, yor lah sialn njach ta năp hên.$b$,false),
('bunong-vn','ACT',27,5,null,$b$Tơ lah jêh hăn rgăn dak mƀŭt n'gor Silisi jêh ri n'gor Pamphili, hên tât ta ƀon Mira tâm n'gor Lisi.$b$,false),
('bunong-vn','ACT',27,6,null,$b$Ta nây kôranh ta han saơ du mlâm kŭmpăn, tă bơh ƀon Aleksandrơ hăn ta n'gor Italy, jêh ri păng ăn hên ncho kŭmpăn nây.$b$,false),
('bunong-vn','ACT',27,7,null,$b$Hên ncho kŭmpăn hăn mbrơi jŏ nar, ma nau jêr ngăn hên tât ta năp ƀon Knit, ƀiă lah sial mpuh mâu ăn hên veh ta nây ôh. Pô ri hên hăn njŏ kơh kôdak Kret dăch ƀon Salmôn.$b$,false),
('bunong-vn','ACT',27,8,null,$b$Hên rgăn ta nây ma nau jêr, jêh ri tât ta ntŭk bu rnha ntŭk jưh ueh, dăch đah ƀon toyh Lasê.$b$,false),
('bunong-vn','ACT',27,9,null,$b$Jŏ nar rlau jêh, jêh ri ncho kŭmpăn nsong ma nau jêr, yor lah yan ver sông sa rlau lôch jêh, yor nây Y-Pôl mbơh lor ma phung êng tâm kŭmpăn pô aơ:$b$,true),
('bunong-vn','ACT',27,10,null,$b$“Hơi lĕ rngôch phung khân may, gâp saơ nau he nsong aơ jêng jêr ngăn, jêh ri geh nau roh, mâu di knŏng ma ndô ndơ jêh ri kŭmpăn, ƀiă lah nđâp ma săk jăn he nơm lĕ.”$b$,false),
('bunong-vn','ACT',27,11,null,$b$Ƀiă lah kôranh ta han tông ngăn nau nơm gai, jêh ri kôranh kŭmpăn ma nau Y-Pôl mbơh.$b$,false),
('bunong-vn','ACT',27,12,null,$b$Ntŭk jưh nây mâu ueh ăn kŭmpăn veh, dôl tâm yan sĭt puh. Pô ri âk bunuyh mĭn, ăn kŭmpăn srôih hăn tât ta ƀon Phênik, ntŭk jưh pa dâng, gay ăn kŭmpăn veh gŭ ta nây dôl yan sĭt puh.$b$,true),
('bunong-vn','ACT',27,13,null,$b$Khêp geh sial rngân khôm bơh rđŭng, khân păng mĭn dơi hăn tât ta ntŭk khân păng ŭch, pô ri khân păng yơk loih nkân kŭmpăn, jêh ri njŏ hăn dăch kơh kôdak Kret.$b$,false),
('bunong-vn','ACT',27,14,null,$b$Ƀiă lah ƀât lât ta nây geh sial ktang ngăn bu rnha Ơrakilôn khôm leo bơh kôdak nây.$b$,true),
('bunong-vn','ACT',27,15,null,$b$Sial njach kŭmpăn, mâu hôm dơi tâm jach đah sial ôh, pô ri hên ăn kŭmpăn hăn tĭng nâm sial rdu yơh.$b$,false),
('bunong-vn','ACT',27,16,null,$b$Hên rgăn pa dâng kôdak jê̆ amoh Klôda, jêh ri jêr ngăn hên dơi kuăn rdâng kŭmpăn.$b$,false),
('bunong-vn','ACT',27,17,null,$b$Jêh têk kŭmpăn klơ, bu sŏk rse kât ăn nâp, klach khan ta choih Sirtơ, bu njŭr bok kŭmpăn jêh ri ăn sial khôm dah ŭch.$b$,false),
('bunong-vn','ACT',27,18,null,$b$Nar ôi taơ sial ăt hôm ktang tâm ban lĕ, jêh ri bu klŭp lơi tâm dak mƀŭt ndô ndơ kŭmpăn rdeng.$b$,false),
('bunong-vn','ACT',27,19,null,$b$Nar pe, ti hên nơm klŭp lơi ndơ bu dŏng tâm kŭmpăn.$b$,true),
('bunong-vn','ACT',27,20,null,$b$Dôl tâm lĕ nar mâu geh nchrat nar, mănh mâu geh lĕ, sial ktang ngăn tât hên mâu hôm kâp gân ma nau dơi klaih ôh.$b$,false),
('bunong-vn','ACT',27,21,null,$b$Jŏ nar jêh phung gŭ tâm kŭmpăn mâu geh sông sa. Pô ri Y-Pôl dâk ta nklang khân păng jêh ri lah: “Hơi lĕ rngôch phung khân may, tơ lah khân may tông jêh ma gâp, jêh ri mâu luh tă bơh kôdak Kret, he klaih bơh nau jêr, jêh ri nau roh aơ.$b$,true),
('bunong-vn','ACT',27,22,null,$b$Aƀaơ gâp ntăm ma khân may, lơi ăn khân may rdja nuih n'hâm yor lah mâu geh du huê tâm phung he mra roh ôh, ƀiă lah knŏng kŭmpăn mra roh dơm.$b$,false),
('bunong-vn','ACT',27,23,null,$b$Măng aơ geh du huê Tông mpăr ueh Brah Ndu gâp, jêh ri ma Brah Ndu nây gâp pah kan, tâm mpơl ma gâp jêh ri lah:$b$,false),
('bunong-vn','ACT',27,24,null,$b$‘Hơi Y-Pôl lơi klach ôh, may mra hăn tât ta năp Sêsar, jêh ri aơ, Brah Ndu hŏ ăn ma may lĕ rngôch phung ncho kŭmpăn ndrel ma may.’$b$,false),
('bunong-vn','ACT',27,25,null,$b$Hơi lĕ rngôch phung khân may, lơi klach ôh, yor lah gâp chroh ma Brah Ndu gay ma nanê̆ nau păng lah jêh ma gâp.$b$,false),
('bunong-vn','ACT',27,26,null,$b$Ƀiă lah nanê̆ kŭmpăn mra nkhŭt he ta du ntŭk kôdak.”$b$,true),
('bunong-vn','ACT',27,27,null,$b$Geh jât ma puăn năng jêh kŭmpăn hên ăt hôm nthông ta dak mƀŭt Adritik. Klong măng phung rmăk kŭmpăn ntôn lah dăch tât ta kơh.$b$,true),
('bunong-vn','ACT',27,28,null,$b$Pô ri jêh khân păng njŭr ndơ veh jêh ri gĭt nau jru bar jât laih, trơn ƀah đah nây khân păng veh tay jêh ri gĭt nau jru jât ma prăm laih.$b$,false),
('bunong-vn','ACT',27,29,null,$b$Klach nchênh đah lŭ, tă ta bôk ntŭk gai kŭmpăn khân păng klŭp puăn glo loih nkân tâm dak mƀŭt jêh ri khân păng vơh vơl gay trôk gơnh ang.$b$,false),
('bunong-vn','ACT',27,30,null,$b$Ƀiă lah phung rmăk ŭch joi nau du ntŭng bơh kŭmpăn. Khân păng njŭr duk tâm dak mƀŭt, jan lah đuh glo loih nkân kŭmpăn.$b$,true),
('bunong-vn','ACT',27,31,null,$b$Y-Pôl lah ma kôranh ta han pô aơ: “Tơ lah phung bunuyh aơ mâu gŭ tâm kŭmpăn, khân may mâu dơi klaih ôh.”$b$,true),
('bunong-vn','ACT',27,32,null,$b$Pô ri phung ta han siăt lơi rse kât duk jêh ri ăn păng tŭp.$b$,false),
('bunong-vn','ACT',27,33,null,$b$Dôl gŭ kâp trôk ang, Y-Pôl đă lĕ rngôch khân păng sông sa. Păng lah pô aơ: “Aƀaơ aơ geh jêh jât ma puăn nar khân may gŭ kâp jêh ri ât mâu geh sông sa.$b$,true),
('bunong-vn','ACT',27,34,null,$b$Gâp jă khân may sông sa, yor lah nau nây jêng khlay ma nau rêh khân may, jêh ri mâu geh du huê tâm phung khân may mra roh du mbrai sŏk ta klơ bôk păng?”$b$,false),
('bunong-vn','ACT',27,35,null,$b$Jêh ngơi pô nây Y-Pôl sŏk kapŭng, lah ueh ma Brah Ndu ta năp lĕ rngôch jêh ri sa.$b$,false),
('bunong-vn','ACT',27,36,null,$b$Pô ri lĕ rngôch n'hao nuih jêh ri sông sa yơh.$b$,false),
('bunong-vn','ACT',27,37,null,$b$Lĕ rngôch phung hên tâm kŭmpăn nây geh bar rhiăng pơh jât ma prao nuyh.$b$,false),
('bunong-vn','ACT',27,38,null,$b$Jêh hơm sa khân păng nkhŭt lơi ba kapŭng tâm dak mƀŭt gay ma n'gơch oi kŭmpăn.$b$,false),
('bunong-vn','ACT',27,39,null,$b$Lah trôk ang jêh khân păng mâu gĭt nal neh ôh, ƀiă lah jêh khân păng saơ ntŭk dak rnhuĭl geh kơh choih, khân păng mĭn ŭch nkân kŭmpăn ta nây tơ lah dơi.$b$,true),
('bunong-vn','ACT',27,40,null,$b$Khân păng doh lơi rse kât loih nkân, cha lơi tâm dak mƀŭt, jêh ri khân păng mƀơk lĕ rse kât ndơ gai kŭmpăn. Jêh ri khân păng n'hao bok pa kơi ndre sial, gay hăn ta kơh.$b$,false),
('bunong-vn','ACT',27,41,null,$b$Ƀiă lah khân păng mâp ntŭk dak tâm chruh jêh ri khan kŭmpăn ta nây. Bôk kŭmpăn khan drŭp tâm choih, mâu blau mpât ôh, ƀiă lah bŭt kŭmpăn dak rpuh njach ktang ƀư rai lơi.$b$,false),
('bunong-vn','ACT',27,42,null,$b$Phung ta han mĭn ŭch nkhĭt lơi phung bu nă klach lah ƀa ƀă nchuăt du ta kơh.$b$,false),
('bunong-vn','ACT',27,43,null,$b$Ƀiă lah kôranh ta han ŭch rklaih Y-Pôl buay nau nây. Păng ntăm ma phung blau re nsăt lor tâm dak leo hăn ta kơh.$b$,false),
('bunong-vn','ACT',27,44,null,$b$Bi ma phung êng păng ăn ƀa ƀă hao ta klơ kđar, jêh ri ƀa ƀă hao ta mpir kŭmpăn pô ri lĕ rngôch khân păng tât ta kơh, mâu geh tât nau mhĭk ôh.$b$,true),
('bunong-vn','ACT',28,1,null,$b$Jêh hên klaih, hên gĭt bu amoh kôdak nây Maltơ.$b$,true),
('bunong-vn','ACT',28,2,null,$b$Phung bunuyh bri nây rom hên ma nau ueh, mâu vay mâp saơ tâm ban pô nây, khân păng ăn hên njâr ŭnh toyh khân păng sân ơm jêh, yor lah trôk mih jêh ri kăt.$b$,false),
('bunong-vn','ACT',28,3,null,$b$Tơ lah Y-Pôl sŏk du rđu long kro jêh ri chê̆ tâm ŭnh, yor lah ŭnh duh, luh du mlâm bêh rmâng tă bơh long jêh ri krêp ta ti păng.$b$,false),
('bunong-vn','ACT',28,4,null,$b$Tơ lah phung bunuyh bri nây rom hên saơ bêh krêp ta ti Y-Pôl, khân păng tâm lah drăng nơm pô aơ: “Nanê̆ nơm nây jêng du huê nkhĭt bunuyh. Pô ri jêh klaih tă bơh dak mƀŭt kđôi lĕ nau sŏng mâu ăn păng gŭ rêh ôh.”$b$,false),
('bunong-vn','ACT',28,5,null,$b$Ƀiă lah rteh lơi bêh nây tâm ŭnh, jêh ri păng mâu geh nau ji ôh.$b$,true),
('bunong-vn','ACT',28,6,null,$b$Phung bunuyh bri nây kâp uănh mĭn lah Y-Pôl dô môr săk jăn mâu lah cha lôt khĭt ro, ƀiă lah jŏ jêh khân păng gŭ uănh, mâu saơ geh nau ji ôh. Jêh ri khân păng tâm rgâl tay nau mĭn, lah bunuyh nây jêng du huê brah.$b$,false),
('bunong-vn','ACT',28,7,null,$b$Tâm ntŭk nây geh neh du huê kôranh kôdak, amoh păng Y-Publius, păng rom hên ueh jêh ri ăn hên bêch ta nây pe năng.$b$,true),
('bunong-vn','ACT',28,8,null,$b$Mbơ̆ Y-Publius ji kăt jêh ri ji ndŭl gŭ bêch ta sưng. Y-Pôl hăn uănh, mbơh sơm, pah ti ta nơm ji nây jêh ri ƀư bah păng.$b$,true),
('bunong-vn','ACT',28,9,null,$b$Yor ri phung ji êng ƀa ƀă tâm kôdak nây văch lĕ, jêh ri khân păng dơi bah da dê.$b$,false),
('bunong-vn','ACT',28,10,null,$b$Pô ri khân păng yơk ma hên hâu ngăn, jêh ri dôl hên ncho kŭmpăn, khân păng ăn ma hên, ndơ hên mra dŏng.$b$,false),
('bunong-vn','ACT',28,11,null,$b$Jêh pe khay hên hăn ncho kŭmpăn ƀon Aleksandrơ, păng geh rup Điôskur, nâm bu ntĭt kon bar, jêh ri gŭ ta kôdak nây dôl yan sĭt puh.$b$,true),
('bunong-vn','ACT',28,12,null,$b$Tât ta ƀon Sirakus hên gŭ ta nây pe nar.$b$,false),
('bunong-vn','ACT',28,13,null,$b$Tă bơh ƀon nây hên njŏ kơh dak mƀŭt hăn tât ta ƀon Rêjơ. Nar ôi taơ yor lah geh sial bơh rđŭng, hên hăn tâm bar nar tât ta ƀon Pusôl.$b$,false),
('bunong-vn','ACT',28,14,null,$b$Ta nây hên tâm mâp đah phung oh nâu ŭch ma hên gŭ khâl khân păng pơh nar. Tâm ban pô nây yơh hên tât ta ƀon Rôm.$b$,false),
('bunong-vn','ACT',28,15,null,$b$Phung oh nâu tă bơh ƀon Rôm tăng lư hên jêh ri, hăn tât ta ngih tăch drăp Apius jêh ri ntŭk bu rnha Pe Ngih Jưh, ŭch chuă hên. Saơ khân păng, Y-Pôl lah ueh ma Brah Ndu jêh ri tâm n'hao nuih.$b$,false),
('bunong-vn','ACT',28,16,null,$b$Tơ lah hên tât jêh ta ƀon Rôm, bu ăn Y-Pôl gŭ êng ndrel ma du huê ta han mât păng.$b$,true),
('bunong-vn','ACT',28,17,null,$b$Lôch pe nar Y-Pôl kuăl tâm rƀŭn phung kôranh phung Yuđa. Jêh ri Y-Pôl ngơi ma khân păng pô aơ: “Hơi phung oh nâu, gâp mâu mâp ƀư tih đah phung ƀon lan ôh, mâu lĕ mâp ƀư tih đah nau vay phung che he. Bu krŭng gâp ta ƀon Yêrusalem jêh ri jao gâp ma phung Rôm.$b$,false),
('bunong-vn','ACT',28,18,null,$b$Jêh sek ôp gâp, khân păng ŭch mƀơk, yor lah gâp mâu geh nau tih khư nkhĭt ôh.$b$,true),
('bunong-vn','ACT',28,19,null,$b$Ƀiă lah phung Yuđa tâm rdâng đah nau nây. Pô ri gâp geh nau nchâp ŭch ngơi ta năp Sêsar, mâu di gâp ŭch phong ndŭl mpôl gâp ôh.$b$,false),
('bunong-vn','ACT',28,20,null,$b$Yor nây yơh, gâp dăn gay tâm mâp jêh ri ngơi đah khân may, yor lah ma nau phung Israel kâp gân gâp, geh rse rvăk aơ bu kât.”$b$,false),
('bunong-vn','ACT',28,21,null,$b$Phung nây plơ̆ lah ma Y-Pôl: “Hên mâu mâp geh ôh sămƀŭt njuăl tă bơh n'gor Yuđa nkoch bri ma nau may, jêh ri mâu geh du huê tâm phung oh nâu văch mbơh mâu lah ngơi mhĭk ma may.$b$,false),
('bunong-vn','ACT',28,22,null,$b$Ƀiă lah hên ŭch gĭt mâm nau may mĭn, yor lah hên gĭt bu tâm rdâng đah phung chroh, nau aơ lam ntŭk.”$b$,true),
('bunong-vn','ACT',28,23,null,$b$Tât nar khân păng tâm nal, âk bunuyh văch ta păng tâm ngih păng gŭ. Y-Pôl nti ƀon bri hađăch Brah Ndu ntơm bơh ôi tât măng. Păng mbơh jêh ri rblang tă bơh nau vay Y-Môis, jêh ri tă bơh phung kôranh nơm mbơh lor, mbơh jêh nau Brah Yêsu.$b$,true),
('bunong-vn','ACT',28,24,null,$b$Ƀa ƀă chroh nau Y-Pôl ngơi; ƀa ƀă mâu ŭch chroh ôh.$b$,true);
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','ACT',28,25,null,$b$Saơ khân păng luh du mâu geh du ai, Y-Pôl ngơi tay pô aơ: “Di jêh Brah Huêng Ueh ngơi ma che khân may, ma kôranh nơm mbơh lor Y-Êsai pô aơ:$b$,false),
('bunong-vn','ACT',28,26,null,$b$Hăn hom ma phung ƀon lan aơ jêh ri lah: Tôr khân may mra iăt ƀiă lah mâu gĭt rbăng ôh, măt khân may mra uănh ƀiă lah mâu saơ.$b$,false),
('bunong-vn','ACT',28,27,null,$b$Yor lah nuih n'hâm phung ƀon lan aơ jêng brơl jêh, tôr khân păng rngêl, măt khân păng nhêp; lah mâu, măt khân păng saơ, tôr khân păng tăng, jêh ri nuih n'hâm khân păng gĭt rbăng, jêh ri khân păng plơ̆ tay, gay ma Gâp mra ƀư bah an khân păng.$b$,true),
('bunong-vn','ACT',28,28,null,$b$Pô ri ăn khân may gĭt nau Brah Ndu tâm rklaih aơ, njuăl jêh ma phung bu năch, jêh ri khân păng mra gŭ iăt.”$b$,true),
('bunong-vn','ACT',28,29,null,$b$Jêh Y-Pôl lah pô nây, phung Yuđa du tâm rlăch ndrăng khân păng nơm hâu ngăn.$b$,false),
('bunong-vn','ACT',28,30,null,$b$Y-Pôl gŭ trĭp bar năm tâm du mlâm ngih păng nkhôm. Păng rom lĕ rngôch bunuyh hăn uănh păng.$b$,false),
('bunong-vn','ACT',28,31,null,$b$Păng nti nau ƀon bri hađăch Brah Ndu, jêh ri ma nau Brah Yêsu Krist ma nau kon me, jêh ri bu mâu buay păng ôh.$b$,true);
