insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','ROM',1,1,null,$b$Y-Pôl, oh mon Yêsu Krist, Brah Ndu kuăl jêh ăn jêng kôranh oh mon jêh ri prăp ma kan nsong mbơh nau mhe mhan ueh Brah Ndu.$b$,true),
('bunong-vn','ROM',1,2,null,$b$Nau aơ Brah Ndu ton jêh bơh lor ma nau phung kôranh nơm mbơh lor nchih jêh tâm nau nchih kloh ueh,$b$,false),
('bunong-vn','ROM',1,3,null,$b$ma Kon Păng, tĭng nâm nglay săk bu deh ma păng tâm ndŭl mpôl Y-Đavit,$b$,false),
('bunong-vn','ROM',1,4,null,$b$jêh ri tĭng nâm huêng kloh ueh mbơh jêh păng jêng Kon Brah Ndu ma nau brah, Yor lah păng dâk rêh jêh tă bơh phung khĭt, Yêsu Krist Kôranh Brah he.$b$,false),
('bunong-vn','ROM',1,5,null,$b$Tâm păng he dơn jêh nau yô̆ jêh ri jêng kôranh oh mon gay ma njŭn leo lĕ rngôch phung mpôl băl tông ma nau chroh yor amoh Păng,$b$,false),
('bunong-vn','ROM',1,6,null,$b$bơh phung nây Yêsu Krist kuăl jêh phung khân may.$b$,false),
('bunong-vn','ROM',1,7,null,$b$Njuăl ma lĕ rngôch phung Brah Ndu rŏng tâm ƀon Rôm, phung Brah Ndu kuăl jêh ăn jêng phung kloh ueh: Ăn khân may geh nau yô̆ jêh ri nau đăp mpăn tă Brah Ndu, Mbơ̆ he, jêh ri Yêsu Krist Kôranh Brah he.$b$,false),
('bunong-vn','ROM',1,8,null,$b$Lor lơn, tâm Brah Yêsu Krist gâp lah ueh ma Brah Ndu yor lĕ rngôch khân ay may, ma nau chroh khân may jêng lư n'găr tâm neh ntu.$b$,true),
('bunong-vn','ROM',1,9,null,$b$Yor lah Brah Ndu, ma păng nây gâp pah kan ma huêng gâp tâm nau mhe mhan ueh Kon Păng, jêng nơm mbơh ma gâp kah gĭt ma khân may ƀa ƀơ ăp tơ̆ gâp mbơh sơm.$b$,false),
('bunong-vn','ROM',1,10,null,$b$Gâp ăt mbơh sơm ƀa ƀơ ma Brah Ndu dơi ăn nar găl ma gâp hăn khâl ma khân may tĭng nâm păng ŭch.$b$,false),
('bunong-vn','ROM',1,11,null,$b$Nanê̆ gâp ŭch ngăn hăn khâl khân may, gay ma tâm pă nau Brah Huêng Ueh ăn, pô ri mơ khân may dơi gŭ nâp;$b$,true),
('bunong-vn','ROM',1,12,null,$b$nâm bu ntĭt gâp gŭ ndrel ma khân may, gay ma he tâm n'hao nuih ndrăng he ăn du nau chroh tâm ban, nau chroh khân may jêh ri nau chroh gâp.$b$,false),
('bunong-vn','ROM',1,13,null,$b$Hơi phung oh nâu, gâp mâu ŭch ôh ma khân may mâu gĭt ƀa ƀơ jêh gâp geh nau mĭn ŭch hăn ta khân may, ŭch pĕ play tâm phung khân may tâm ban ma phung mpôl băl êng, ƀiă lah gâp geh nau buay tât nar aơ.$b$,true),
('bunong-vn','ROM',1,14,null,$b$Gâp iang rnon phung Grek jêh ri phung bri, ma phung blau mĭn jêh ri ma phung rluk mâl tâm ban lĕ;$b$,false),
('bunong-vn','ROM',1,15,null,$b$pô nây yơh ma lĕ nuih n'hâm gâp ŭch mbơh nau mhe mhan ueh ma khân may tâm ban lĕ, phung gŭ ta ƀon Rôm.$b$,false),
('bunong-vn','ROM',1,16,null,$b$Nanê̆ gâp mâu prêng ôh ma nau mhe mhan ueh, yor lah păng jêng nau brah Brah Ndu, tâm rklaih lĕ rngôch mbu nơm chroh, phung Yuđa lor lơn jêh ri nđâp ma phung Grek tâm ban lĕ.$b$,true),
('bunong-vn','ROM',1,17,null,$b$Yor lah tâm nau mhe mhan ueh aơ tâm mpơl jêh nau sŏng Brah Ndu, geh bơh nau chroh jêh ri njŭn leo nau chroh tâm ban ma nchih jêh pô aơ: “Bunuyh sŏng mra rêh yor nau chroh.”$b$,false),
('bunong-vn','ROM',1,18,null,$b$Nau Brah Ndu nuih mpơl jêh tă bơh trôk ma nau mâu yơk mbah ma Brah Ndu, jêh ri ma nau kue bu dŏng tŭn nau ngăn.$b$,true),
('bunong-vn','ROM',1,19,null,$b$Yor lah moh nau bu dơi gĭt năl Brah Ndu tâm mpơl jêh ma khân păng. Brah Ndu tâm mpơl jêh nau nây ma khân păng.$b$,true),
('bunong-vn','ROM',1,20,null,$b$Yor lah nau rah vah păng jêng ndâp, nâm bu ntĭt, nau brah păng n'ho ro jêh ri nau păng jêng Brah Ndu, ntơm bơh rhăk njêng neh ntu, bu dơi saơ ang tơ lah treng uănh ndơ păng ƀư jêh. Yor nây khân păng mâu dơi n'gang khân păng nơm ôh.$b$,false),
('bunong-vn','ROM',1,21,null,$b$Yor lah gĭt năl jêh Brah Ndu, khân păng mâu ŭch mât ton ma Brah Ndu ôh, mâu lĕ khân păng mâp lah ueh, ƀiă lah khân păng chuêl hêng tâm nau mĭn dơm dam khân păng nơm, jêh ri nuih n'hâm rluk bêng ma nau ngo.$b$,false),
('bunong-vn','ROM',1,22,null,$b$Khân păng mbơh khân păng nơm jêng bunuyh gĭt âk, ƀiă lah khân păng jêng rluk.$b$,false),
('bunong-vn','ROM',1,23,null,$b$Khân păng tâm rgâl nau chrêk rmah Brah Ndu jêng rup mâu blau ôm rai jêng rup ƀư tĭng nâm rup bunuyh blau ôm rai, mâu lah rup sĭm mpăr, mpa puăn, jâng jêh ri mpa vơr.$b$,false),
('bunong-vn','ROM',1,24,null,$b$Yor ri Brah Ndu jao ma khân păng ma nau ƀơ̆ ƀơch tĭng nâm nuih n'hâm khân păng kơnh, tât khân păng ƀư bêk prêng ma săk jăn khân păng nơm,$b$,true),
('bunong-vn','ROM',1,25,null,$b$Yor lah khân păng tâm rgâl nau ngăn Brah Ndu jêng nau mƀruh, jêh ri khân păng yơk, pah kan ma ndơ hŏ tă rhăk njêng jêh mâu di ma nơm rhăk njêng ôh, ma Nơm nây khư mât ton tâm rnê n'ho ro! Amen.$b$,false),
('bunong-vn','ROM',1,26,null,$b$Yor nau nây Brah Ndu jao jêh ma khân păng ma nau ƀơ̆ ƀơch khân păng nơm ŭch, yor lah tâm phung khân păng phung bu ur tâm rgâl jêh nau vay kănđai jêng nau vay êng tih.$b$,false),
('bunong-vn','ROM',1,27,null,$b$Phung bu klâu tâm ban lĕ cha lơi nau vay kănđai đah bu ur, khân păng tâm kơnh muh măt ndrăng khân păng nơm, bu klâu đah bu klâu ƀư nau tih ƀơ̆ ngăn, jêh ri khân păng dơn nau tâm rmal, ma khân păng nơm yor nau chuêl hêng nây.$b$,false),
('bunong-vn','ROM',1,28,null,$b$Yor lah khân păng mâu chrê gĭt năl Brah Ndu ôh, pô nây Brah Ndu n'ho jao khân păng ma nau mĭn mhĭk tât khân păng ƀư âk nau mâu khư ôh.$b$,false),
('bunong-vn','ROM',1,29,null,$b$Khân păng bêng ma ăp ntil nau kue, nau tih mhĭk, nau kơnh, nau ƀai. Khân păng bêng ma nau ji nuih biănh, nau nkhĭt bunuyh, nau tâm lah tâm djrel, nau ndơm, nau hăt janh, nau nchơt,$b$,true),
('bunong-vn','ROM',1,30,null,$b$ngơi kek, tâm rmot ma Brah Ndu, nau ƀai, ngơi sưr, hao kach, vay ƀư nau tih, dăng bôk đah mê̆ mbơ̆ ,$b$,false),
('bunong-vn','ROM',1,31,null,$b$rluk mâl, rlăng nau tâm rnglăp, mâu geh nuih n'hâm rŏng, mâu geh nau tâm yô̆ ôh.$b$,false),
('bunong-vn','ROM',1,32,null,$b$Jêh khân păng gĭt nau vay Brah Ndu mbơh ma mbu nơm ƀư tih pô nây khư khĭt, mâu di knŏng khân păng nơm ƀư, ƀiă lah khân păng ŭch nđâp ma phung êng ƀư tâm ban lĕ.$b$,false),
('bunong-vn','ROM',2,1,null,$b$Pô nây, hơi jiăng, kđôi mbu may jêng, tơ lah may phat dôih bu, may mâu dơi n'gang may nơm, yor lah dôl may phat dôih bu, may tâm rmal may nơm yơh, yor lah may phat dôih bu ƀiă lah may ƀư tâm ban ma bu lĕ.$b$,true),
('bunong-vn','ROM',2,2,null,$b$He gĭt nau Brah Ndu phat dôih ma phung ƀư tih tâm ban pô nây di ngăn.$b$,false),
('bunong-vn','ROM',2,3,null,$b$Moh may mĭn, hơi nơm phat dôih bu ƀư tih pô nây ƀiă lah may ăt ƀư tâm ban, may mĭn may mra klaih bơh nau Brah Ndu phat dôih hĕ?$b$,false),
('bunong-vn','ROM',2,4,null,$b$Mâu lah may tâm rmot lĕ ma nau ueh Brah Ndu toyh ngăn ngên, ma nau păng srôih, nau mpăn păng? Jêh ri may mâu gĭt hĕ nau ueh Brah Ndu njŭn leo may tâm rmal nau tih may nơm?$b$,false),
('bunong-vn','ROM',2,5,null,$b$Yor nuih n'hâm dăng may mâu rmal nau tih, may bun tâm may nơm nau nuih tâm nar Brah Ndu ji nuih jêh ri tâm mpơl nau păng phat dôih sŏng.$b$,false),
('bunong-vn','ROM',2,6,null,$b$Păng mra mplơ̆ ma ăp nơm tĭng nâm kan păng ƀư.$b$,false),
('bunong-vn','ROM',2,7,null,$b$Păng mra ăn nau rêh n'ho ro ma nơm srôih ƀư nau ueh ƀa ƀơ joi nau chrêk rmah, nau yơk, jêh ri nau mâu blau khĭt;$b$,false),
('bunong-vn','ROM',2,8,null,$b$ƀiă lah păng mra nuih jêh ri nau ji nuih ma mbu nơm tâm rdâng, mâu tông ôh ma nau nanê̆ ngăn nkhơng ma tông nau kue.$b$,false),
('bunong-vn','ROM',2,9,null,$b$Păng mra ăn nau rêh ni toyh jêh ri nau rngot klâng ma lĕ rngôch bunuyh ƀư tih ma phung Yuđa lor lơn jêh ri nđâp ma phung Grek lĕ,$b$,false),
('bunong-vn','ROM',2,10,null,$b$ƀiă lah nau chrêk rmah, nau yơk jêh ri nau đăp mpăn mra tât ma lĕ rngôch bunuyh ƀư ueh, ma phung Yuđa lor jêh ri nđâp ma phung Grek lĕ.$b$,false),
('bunong-vn','ROM',2,11,null,$b$Yor lah Brah Ndu mâu kơp bunuyh êng êng ôh.$b$,false),
('bunong-vn','ROM',2,12,null,$b$Lĕ rngôch mbu nơm mâu geh nau vay ƀiă lah ƀư tih mra rai lôch ăt tâm păng mâu geh nau vay ôh, jêh ri lĕ rngôch mbu nơm geh nau vay ƀiă lah ƀư tih nau vay nây mra phat dôih păng.$b$,true),
('bunong-vn','ROM',2,13,null,$b$Yor lah mâu di phung iăt nau vay jêng bunuyh sŏng ta năp Brah Ndu, ƀiă lah phung tông nau vay mra geh nau kơp sŏng.$b$,false),
('bunong-vn','ROM',2,14,null,$b$Bi phung bu năch mâu geh nau vay, tơ lah khân păng mơng ƀư tâm ban ma nau vay ntăm, dôl khân păng mâu geh nau vay dơn, nau nây jêng nau vay ma khân păng nơm.$b$,false),
('bunong-vn','ROM',2,15,null,$b$Khân păng tâm mpơl moh kan nau vay ntăm nchih jêh tâm nuih n'hâm khân păng, nuih n'hâm sŏng khân păng mbơh nau nây, jêh ri nau mĭn khân păng geh tơ̆ phong mâu lah n'gang ma khân păng.$b$,false),
('bunong-vn','ROM',2,16,null,$b$Nau nây mra tâm mpơl ta nar Brah Ndu ăn Yêsu Krist phat dôih kan ndâp bunuyh ƀư, tĭng nâm nau mhe mhan ueh gâp nti.$b$,false),
('bunong-vn','ROM',2,17,null,$b$Ƀiă lah may geh amoh phung Yuđa; may nsing ma nau vay; may tâm rnê ma may nơm yor Brah Ndu;$b$,true),
('bunong-vn','ROM',2,18,null,$b$may gĭt nau păng ŭch, jêh ri may gĭt mbên ndơ ueh yor lah nau vay sâm nti may;$b$,false),
('bunong-vn','ROM',2,19,null,$b$may tâm rnê ma may jêng nơm njŭn leo phung chieh măt, jêng nau ang ma phung gŭ tâm nau ngo;$b$,false),
('bunong-vn','ROM',2,20,null,$b$kôranh nơm nti ma phung rluk mâl, nơm nti ma phung kon se, yor lah may geh tâm nau vay trong ma nau gĭt rbăng jêh ri nau ngăn,$b$,false),
('bunong-vn','ROM',2,21,null,$b$may nti ma bu, mâm dĭng may mâu nti ma may nơm? May nti lơi ntŭng, bi may, may ntŭng mâu?$b$,false),
('bunong-vn','ROM',2,22,null,$b$May nti lơi văng tĭr, bi may, may văng tĭr mâu? May tâm rmot ma rup brah, bi may, may pit sŏk ndô ndơ ngih brah mâu?$b$,false),
('bunong-vn','ROM',2,23,null,$b$May tâm rnê ma may nơm yor nau vay, bi may, may mưch Brah Ndu ma nau may rlau nau vay mâu?$b$,false),
('bunong-vn','ROM',2,24,null,$b$Tĭng nâm nau nchih jêh: “Yor khân may yơh phung bu năch ngơi sưr ma amoh Brah Ndu.”$b$,false),
('bunong-vn','ROM',2,25,null,$b$Nau koh ntâu jêng khlay tơ lah may tông nau vay, ƀiă lah tơ lah may rlau nau vay, nau koh ntâu may jêng dơm dam.$b$,true),
('bunong-vn','ROM',2,26,null,$b$Tơ lah du huê mâu dơn nau koh ntâu tông moh nau vay nti, mâu di hĕ Brah Ndu mra kơp nau păng mâu koh ntâu tâm ban ma nau koh ntâu jêh?$b$,false),
('bunong-vn','ROM',2,27,null,$b$Nơm ê koh ntâu ƀiă lah tông nau vay, păng mra phat dôih may, nơm geh Sămƀŭt nau vay jêh ri koh ntâu, ƀiă lah rlau nau vay.$b$,false),
('bunong-vn','ROM',2,28,null,$b$Yor lah mbu nơm knŏng pa dih jêng phung Yuđa, păng mâu jêng Yuđa ngăn ôh, jêh ri nau koh ntâu ngăn mâu di bu ƀư ta săk jăn ôh.$b$,false),
('bunong-vn','ROM',2,29,null,$b$Ƀiă lah phung Yuđa ngăn jêng tâm trôm, jêh ri nau koh ntâu ngăn ƀư tâm nuih n'hâm, ƀư tĭng nâm huêng, mâu geh kơt nâm bu Sămƀŭt ôh. Du huê phung Yuđa pô nây geh nau tâm rnê mâu geh tă bơh bunuyh ôh, ƀiă lah bơh Brah Ndu.$b$,false),
('bunong-vn','ROM',3,1,null,$b$Pô ri moh nau ueh lơn phung Yuđa geh? Mâu lah moh khlay nau koh ntâu?$b$,true),
('bunong-vn','ROM',3,2,null,$b$Ueh khlay da dê. Lor lơn pô aơ: “Nau Brah Ndu Ngơi ntăm jao jêh ma phung Yuđa.”$b$,true),
('bunong-vn','ROM',3,3,null,$b$Mâm ƀư tơ lah bar pe nuyh tâm phung khân păng mâu jêng răp jăp? Nau khân păng mâu răp jăp nây dơi ƀư rai đŏng nau răp jăp Brah Ndu?$b$,false),
('bunong-vn','ROM',3,4,null,$b$Mâu, mâu dơi ôh! Ăn bu gĭt ma Brah Ndu jêng nanê̆ jêh ri lĕ rngôch jêng mƀruh, nâm bu nchih jêh: “Pô nây mơ bu kơp may sŏng tâm nau may ngơi, jêh ri di nau may tơ lah bu ŭch phat dôih may.”$b$,false),
('bunong-vn','ROM',3,5,null,$b$Ƀiă lah tơ lah nau kue he tâm mpơl nau sŏng Brah Ndu, moh he mra lah? Brah Ndu kue lĕ tơ lah păng tâm rmal? (Gâp ngơi tĭng nâm bunuyh ngơi).$b$,true),
('bunong-vn','ROM',3,6,null,$b$Mâu, mâu di ôh! Tơ lah pô nây, mâm Brah Ndu dơi phat dôih neh ntu?$b$,false),
('bunong-vn','ROM',3,7,null,$b$Ƀiă lah tơ lah nau gâp mƀruh ƀư lư n'găr âk lơn nau ngăn Brah Ndu, mâm ƀư bu phat dôih gâp tâm ban ma bunuyh tih?$b$,false),
('bunong-vn','ROM',3,8,null,$b$Jêh ri mâm ƀư he mâu ƀư tih gay geh nau ueh? Tâm ban ma âk bunuyh nchơt lah ma hên nti jêh nau nây, nau tâm rmal ma phung nây jêng sŏng.$b$,false),
('bunong-vn','ROM',3,9,null,$b$Mâm ƀư? He jêng ueh lơn ma phung êng lĕ? Mâu, yor lah he gĭt nanê̆ jêh ma lĕ rngôch phung Yuđa jêh ri phung Grek jêng dĭk ma nau tih da dê.$b$,true),
('bunong-vn','ROM',3,10,null,$b$Nâm bu nchih jêh pô aơ: Mâu geh bunuyh sŏng ôh, du huê mâu geh lĕ;$b$,false),
('bunong-vn','ROM',3,11,null,$b$Mâu geh du huê gĭt rbăng ôh, mâu geh du huê joi Brah Ndu ôh.$b$,false),
('bunong-vn','ROM',3,12,null,$b$Lĕ rngôch nkhah du, jêh ri jêng dơm dam da dê; mâu geh bunuyh ƀư nau ueh ôh, du huê mâu geh lĕ.$b$,true),
('bunong-vn','ROM',3,13,null,$b$“Rmlông dơ̆ khân păng nâm bu trôm môch bu kuai;” “Mpiăt khân păng ndơm bu tâm dâng trô yoi khân păng geh tâm ban ma dak kăch bêh rmâng.$b$,true),
('bunong-vn','ROM',3,14,null,$b$“Trôm mbung khân păng bêng ma nau rtăp rak jêh ri nau tăng.”$b$,true),
('bunong-vn','ROM',3,15,null,$b$“Khân păng geh jâng ngăch gay ma ƀư rung mham bu,$b$,true),
('bunong-vn','ROM',3,16,null,$b$Ta trong khân păng geh nau ƀư rai jêh ri nau rêh ni,$b$,false),
('bunong-vn','ROM',3,17,null,$b$Jêh ri khân păng mâu mâp gĭt trong nau đăp mpăn ôh.”$b$,false),
('bunong-vn','ROM',3,18,null,$b$“Nau klach yơk ma Brah Ndu mâu gŭ ta năp khân păng ôh.”$b$,true),
('bunong-vn','ROM',3,19,null,$b$Pô ri he gĭt lĕ nau vay lah, păng lah ma phung geh nau vay gay ma lĕ rngôch trôm mbung gŭ rklăk, jêh ri lĕ rngôch bunuyh ta neh ntu dơn khân păng jêng tih ta năp Brah Ndu.$b$,true),
('bunong-vn','ROM',3,20,null,$b$Yor lah ta năp Brah Ndu mâu geh du huê mra kơp sŏng yor kan nau vay, yor lah nau vay ăn bu gĭt nau tih.$b$,false),
('bunong-vn','ROM',3,21,null,$b$Ƀiă lah nau vay jêh ri phung kôranh nơm mbơh lor mbơh jêh ma nau sŏng Brah Ndu tâm mpơl jêh aƀaơ bơh deh nau vay.$b$,true),
('bunong-vn','ROM',3,22,null,$b$Mâm bu ntĭt, nau sŏng Brah Ndu ma nau chroh ma Yêsu Krist ăn ma lĕ rngôch mbu nơm chroh. Yor lah mâu geh nau êng êng ôh;$b$,true),
('bunong-vn','ROM',3,23,null,$b$Yor lah lĕ rngôch bunuyh tih jêh da dê jêh ri mâu dơi tât ta keh chrêk rmah Brah Ndu nal ôh,$b$,false),
('bunong-vn','ROM',3,24,null,$b$jêh ri ma nau yô̆ Brah Ndu ăn jêh ma khân păng dơm dam nau kơp sŏng yor nau tâm chuai ƀư jêh tâm Yêsu Krist.$b$,false),
('bunong-vn','ROM',3,25,null,$b$Brah Ndu săch jêh Brah Yêsu ăn păng jêng mpa tâm chuai nau tih ma mham păng ma mbu nơm chroh, gay tâm mpơl nau sŏng păng pô nây, yor lah păng lơi mâu tâm rmal ôh nau tih bu ƀư lor ma nây.$b$,false),
('bunong-vn','ROM',3,26,null,$b$Tâm rnôk nây păng srôih ăt gay ma tâm mpơl nau sŏng păng tâm rnôk aơ, ăn bu gĭt păng sŏng dôl păng kơp sŏng mbu nơm chroh ma Brah Yêsu.$b$,false),
('bunong-vn','ROM',3,27,null,$b$Pô nây, moh ndơ dơi tâm rnê ma păng nơm? Mâu geh ôh. Ma moh nau vay? Ma nau vay kan bu ƀư ƀơh? Mâu di ôh, ƀiă lah ma nau vay nau chroh.$b$,true),
('bunong-vn','ROM',3,28,null,$b$Yor he mĭn bunuyh geh nau kơp sŏng ma nau chroh mâu di ma kan nau vay ôh.$b$,false),
('bunong-vn','ROM',3,29,null,$b$Mâu lah Brah Ndu jêng Brah Ndu knŏng ma phung Yuđa dơm? Mâu di hĕ păng jêng Brah Ndu nđâp ma phung bu năch tâm ban lĕ? Ngăn, păng jêng Brah Ndu phung bu năch lĕ.$b$,false),
('bunong-vn','ROM',3,30,null,$b$Yor lah geh knŏng du huê Brah Ndu. Păng nơm kơp sŏng ma nau chroh phung koh ntâu, jêh ri ăt ma nau chroh lĕ kơp sŏng phung mâu geh koh ntâu ôh.$b$,false),
('bunong-vn','ROM',3,31,null,$b$Pô ri ma nau chroh he mƀăr lơi nau vay lĕ? Mâu! He ƀư ăn nanê̆ ngăn nau vay.$b$,false),
('bunong-vn','ROM',4,1,null,$b$Pô ri mâm he mra lah ma nau che he, Y-Abraham, geh jêh tĭng nâm nglay săk?$b$,true),
('bunong-vn','ROM',4,2,null,$b$Tơ lah ma kan păng pah Brah Ndu kơp sŏng jêh Y-Abraham, păng geh nau dơi tâm rnê ma păng nơm, ƀiă lah mâu geh ta năp Brah Ndu ôh.$b$,false),
('bunong-vn','ROM',4,3,null,$b$Moh nau nchih lah jêh? “Y-Abraham chroh ma Brah Ndu, jêh ri nau nây kơp păng sŏng jêh.”$b$,false),
('bunong-vn','ROM',4,4,null,$b$Pô ri ma mbu nơm pah kan geh nau nkhôm, mâu di nau yô̆ ôh, ƀiă lah kơp tâm ban ma rnon.$b$,false),
('bunong-vn','ROM',4,5,null,$b$Bi ma phung mâu geh pah kan ôh, ƀiă lah chroh ma nơm kơp sŏng bunuyh tih, nau păng chroh kơp păng sŏng.$b$,false),
('bunong-vn','ROM',4,6,null,$b$Yor nây Y-Đavit lah jêh nau ueh maak phung bunuyh Brah Ndu kơp sŏng mâu di ma kan khân păng ƀư, păng lah:$b$,false),
('bunong-vn','ROM',4,7,null,$b$“Ueh maak yơh ma phung geh nau yô̆jêh ma nau kue khân păng jêh ri nau tih khân păng nkŭm jêh,$b$,false),
('bunong-vn','ROM',4,8,null,$b$Ueh maak yơh ma bunuyh Kôranh Brah mâu kơp nau tih păng ôh.”$b$,false),
('bunong-vn','ROM',4,9,null,$b$Di lĕ nau mât ton nau ueh uĭn nây knŏng ma phung koh ntâu, mâu lah nđâp ma phung mâu koh ntâu? Yor lah he lah Brah Ndu kơp nau chroh Y-Abraham jêng nau sŏng ma păng.$b$,true),
('bunong-vn','ROM',4,10,null,$b$Pô ri, mâm ƀư kơp sŏng? Jêh păng koh ntâu lĕ, mâu lah ê păng dơi geh nau păng koh ntâu? Mâu di păng koh ntâu ôh, ƀiă lah lor ma nây.$b$,false),
('bunong-vn','ROM',4,11,null,$b$Pô ri păng dơn jêh nau tâm mbên ma nau koh ntâu tâm ban tâp pŏng nau sŏng păng geh jêh ma nau chroh dôl ê păng koh ntâu, ăn păng jêng mbơ̆ ma lĕ rngôch phung mâu geh koh ntâu ƀiă lah chroh, gay ma khân păng dơi geh nau kơp sŏng tâm ban lĕ.$b$,false),
('bunong-vn','ROM',4,12,null,$b$Jêh ri păng jêng mbơ̆ ma phung koh ntâu. Phung nây mâu di knŏng koh ntâu ôh, ƀiă lah hăn tĭng nau chroh Y-Abraham, mbơ̆ he, geh lor ma păng koh ntâu.$b$,false),
('bunong-vn','ROM',4,13,null,$b$Yor lah mâu di ma nau vay ôh Y-Abraham jêh ri phung kon sau păng geh nau ton ăn neh ntu jêng drăp ndơ, ƀiă lah ma nau sŏng bơh nau chroh.$b$,true),
('bunong-vn','ROM',4,14,null,$b$Yor lah, tơ lah tông nau vay dơi jêng phung ndơn drăp, nau chroh jêng dơm dam, jêh ri nau ton lĕ cha lơi jêh.$b$,false),
('bunong-vn','ROM',4,15,null,$b$Yor lah nau vay dơi ngluh nau ji nuih, jêh ri ntŭk mâu geh nau vay mâu geh nau rlau nau vay ôh.$b$,false),
('bunong-vn','ROM',4,16,null,$b$Pô ri, yor nau chroh yơh bu dơi jêng nơm ndơn drăp, gay ma nau nây luh bơh nau yô̆ jêh ri ăn nanê̆ nau Brah Ndu ton jêh ma lĕ rngôch phung kon sau Y-Abraham mâu di ôh knŏng ma phung geh jêh nau vay, ƀiă lah nđâp ma phung geh nau chroh Y-Abraham, mbơ̆ lĕ rngôch he,$b$,true),
('bunong-vn','ROM',4,17,null,$b$nâm bu, bu nchih jêh: “Gâp ăn jêh may jêng mbơ̆ ma âk phung ndŭl mpôl.” Păng jêng mbơ̆ he ta năp Brah Ndu, Nơm păng chroh, Nơm ăn nau rêh ma phung khĭt, jêh ri nơm kuăl ndơ mâu geh tâm ban ma ndơ hŏ geh jêh.$b$,false),
('bunong-vn','ROM',4,18,null,$b$Păng kâp gân dôl mâu hôm dơi kâp gân, păng ăt chroh tât bu jêng mbơ̆ ma âk phung ndŭl mpôl, tĭng nâm nau ngơi jêh ma păng pô aơ: “Phung kon sau may mra jêng tâm ban pô nây yơh.”$b$,true),
('bunong-vn','ROM',4,19,null,$b$Nau chroh păng mâu jêng rdja ôh dôl păng saơ săk jăn păng dăch khĭt, yor lah păng dăch tât du rhiăng năm, jêh ri H'Sara ranh jêh, mâu hôm dơi geh kon ôh.$b$,false),
('bunong-vn','ROM',4,20,null,$b$Păng mâu geh nau vât vâng mâu lah mâu chroh ma nau Brah Ndu ton, ƀiă lah păng jêng ktang lơn tâm nau chroh, jêh ri păng tâm rnê ma Brah Ndu,$b$,false),
('bunong-vn','ROM',4,21,null,$b$Yor lah păng chroh moh nau Brah Ndu ton jêh, nau nây păng dơi ăn nanê̆ tâm ban lĕ.$b$,false),
('bunong-vn','ROM',4,22,null,$b$Yor nây păng dơi geh nau kơp sŏng.$b$,false),
('bunong-vn','ROM',4,23,null,$b$Jêh ri mâu di knŏng du huê păng ôh geh nau nchih jêh ma nau chroh kơp păng sŏng jêh.$b$,false),
('bunong-vn','ROM',4,24,null,$b$Ƀiă lah nđâp ma phung he lĕ nau chroh mra kơp he sŏng yor lah he chroh ma Nơm hŏ dâk rêh jêh Brah Yêsu, Kôranh Brah he, bơh phung khĭt.$b$,false),
('bunong-vn','ROM',4,25,null,$b$Bu jao Păng ma nau mhĭk yor nau tih he jêh ri Păng hŏ ăn dâk rêh jêh gay kơp he sŏng.$b$,false),
('bunong-vn','ROM',5,1,null,$b$Pô ri, jêh kơp sŏng ma nau chroh he geh nau đăp mpăn đah Brah Ndu tâm Yêsu Krist Kôranh Brah he.$b$,true),
('bunong-vn','ROM',5,2,null,$b$Đah păng yơh yor nau chroh he dơi lăp tâm nau yô̆ aơ. Tâm nây he gŭ rjăp, jêh ri yor nau chroh he tâm rnê tâm nau kâp gân ma nau chrêk rmah Brah Ndu.$b$,false),
('bunong-vn','ROM',5,3,null,$b$Mâu di knŏng dŭm nĕ ôh, ƀiă lah he tâm rnê nđâp tâm nau rêh ni lĕ, yor lah he gĭt jêh tă bơh nau rêh ni luh nau srôih,$b$,false),
('bunong-vn','ROM',5,4,null,$b$tă bơh nau srôih nây luh nau dơi dôl geh nau rlong uănh jêh ri tă bơh nau dơi nây luh nau kâp gân,$b$,false),
('bunong-vn','ROM',5,5,null,$b$jêh ri nau kâp gân mâu ƀư prêng ôh, yor lah nau Brah Ndu rŏng ăn mbêng nŭm jêh tâm nuih n'hâm he ma Brah Huêng Ueh Brah Ndu ăn jêh ma he.$b$,false),
('bunong-vn','ROM',5,6,null,$b$Yor lah dôl he hôm jêng rdja Brah Krist khĭt jêh ma phung tih tĭng nâm rnôk tâm nal jêh.$b$,true),
('bunong-vn','ROM',5,7,null,$b$Jêr geh bunuyh khĭt yor du huê bunuyh sŏng klăp lah geh lĕ bunuyh ŭch khĭt yor du huê bunuyh ueh.$b$,false),
('bunong-vn','ROM',5,8,null,$b$Ƀiă lah Brah Ndu tâm mpơl nau păng rŏng ma he pô aơ, dôl he hôm jêng bunuyh tih, Brah Krist khĭt yor he.$b$,false),
('bunong-vn','ROM',5,9,null,$b$Rlau lơn ma nau nây aƀaơ, yor mham păng he geh nau kơp sŏng jêh, mra tâm rklaih lĕ bơh nau Brah Ndu nuih.$b$,false),
('bunong-vn','ROM',5,10,null,$b$Yor lah dôl he hôm ƀư rlăng đah Brah Ndu, nau khĭt Kon Păng tâm njĭr jêh he đah Păng rlau lơn ma nau nây, jêh tâm njĭr, he mra tâm rklaih yor nau rêh Păng.$b$,true),
('bunong-vn','ROM',5,11,null,$b$Mâu di dŭm nây ôh, ƀiă lah he tâm rnê tâm Brah Ndu ma amoh Kôranh Brah he, Yêsu Krist, yor Păng yơh aƀaơ aơ he geh nau tâm njĭr đah Brah Ndu.$b$,false),
('bunong-vn','ROM',5,12,null,$b$Pô ri, yor du huê bunuyh nau tih lăp jêh tâm neh ntu, jêh ri yor nau tih geh nau khĭt, pô nây yơh nau khĭt tât ma lĕ rngôch bunuyh, yor lah lĕ rngôch bunuyh tih jêh.$b$,true),
('bunong-vn','ROM',5,13,null,$b$Yor lah lor ê geh nau vay, geh jêh nau tih tâm neh ntu, ƀiă lah bu mâu kơp tih ôh tơ lah mâu geh nau vay.$b$,true),
('bunong-vn','ROM',5,14,null,$b$Ƀiă lah ntơm bơh Y-Ađam tât ta Y-Môis nau khĭt chiă uănh, nđâp ma phung mâu geh nau tih tâm ban ma Y-Ađam. Nơm nây jêng nau tâm ntĭt ma nơm mra văch.$b$,false),
('bunong-vn','ROM',5,15,null,$b$Ƀiă lah nau ăn dơm dam mâu di tâm ban ma nau tih ôh. Yor nau tih du huê, âk bunuyh veh khĭt jêh. Rlau lơn ma nau nây lĕ nau Brah Ndu yô̆ jêh ri nau ăn tâm nau yô̆ luh tă bơh du huê, Yêsu Krist mra ăn ma âk bunuyh êng tâm ban lĕ!$b$,false),
('bunong-vn','ROM',5,16,null,$b$Jêh ri nau ăn aơ mâu di tâm ban ma nau tât yor du huê tih ôh. Yor du ntil nau tih nau phat dôih jêng nau tâm rmal, ƀiă lah nau ăn dơm dam jêng nau kơp sŏng jêh bu geh âk nau tih.$b$,false),
('bunong-vn','ROM',5,17,null,$b$Tơ lah yor nau tih du huê nau khĭt chiă uănh jêh yor du huê nây, rlau lơn ma nau nây lĕ phung sŏk dơn âk rmeh nau yô̆ jêh ri ăn tâm nau sŏng mra chiă uănh tâm nau rêh yor du huê, Yêsu Krist, tâm ban lĕ.$b$,false),
('bunong-vn','ROM',5,18,null,$b$Pô nây, yor knŏng du ntil nau tih nau tâm rmal tât jêh ma lĕ rngôch bunuyh, tâm ban lĕ yor du ntil kan sŏng nau kơp sŏng ăn nau rêh tât jêh ma lĕ rngôch bunuyh.$b$,true),
('bunong-vn','ROM',5,19,null,$b$Yor lah, du huê mâu tông bâr âk bunuyh êng jêng tih tâm ban lĕ, yor du huê tông bâr, âk bunuyh êng mra jêng sŏng.$b$,true),
('bunong-vn','ROM',5,20,null,$b$Jêh ri nau vay lăp jêh, gay ma nau tih jêng âk lơn; ƀiă lah tă ntŭk nau tih geh âk jêh, nau yô̆ geh âk rmeh lơn,$b$,true),
('bunong-vn','ROM',5,21,null,$b$gay ma nâm bu nau tih chiă uănh jêh ma nau khĭt, tâm ban pô nây lĕ, nau yô̆ chiă uănh ma nau sŏng gay ăn nau rêh n'ho ro tâm Yêsu Krist, Kôranh Brah he.$b$,false),
('bunong-vn','ROM',6,1,null,$b$Pô ri, moh he mra lah? He mra ăt hôm gŭ tâm nau tih gay geh nau yô̆ âk rmeh lĕ?$b$,true),
('bunong-vn','ROM',6,2,null,$b$Mâu, mâu di ôh! He khĭt jêh yor nau tih. Mâm he dơi gŭ tâm nau tih đŏng?$b$,false),
('bunong-vn','ROM',6,3,null,$b$Khân may mâu gĭt hĕ ma lĕ rngôch phung he dơn jêh nau ƀaptem tâm Yêsu Krist tâm ban ma dơn jêh nau ƀaptem tâm nau păng khĭt?$b$,true),
('bunong-vn','ROM',6,4,null,$b$Ma nau ƀaptem bu tâp jêh he ndrel ma Păng tâm nau păng khĭt, gay ma nâm bu Brah Krist hŏ rêh jêh bơh phung khĭt ma nau chrêk rmah mbơ̆ he mra hăn tâm nau rêh mhe tâm ban lĕ.$b$,false),
('bunong-vn','ROM',6,5,null,$b$Yor lah tơ lah he jêng nguay ndrel ma Păng tâm nau Păng khĭt, he mra jêng nguay tâm nau Păng rêh tâm ban lĕ.$b$,false),
('bunong-vn','ROM',6,6,null,$b$He gĭt jêh ma bunuyh ơm he pâng jêh ta si tâm rkăng ndrel ma Păng, gay ma săk jăn nau tih rai lơi pô nây he mâu hôm jêng dĭk ma nau tih ôh.$b$,false),
('bunong-vn','ROM',6,7,null,$b$Yor lah mbu nơm khĭt jêh, klaih jêh bơh nau tih.$b$,false),
('bunong-vn','ROM',6,8,null,$b$Pô ri tơ lah he khĭt jêh ndrel ma Brah Krist, he chroh ma he hŏ dâk rêh ndrel ma păng lĕ.$b$,false),
('bunong-vn','ROM',6,9,null,$b$Yor lah he gĭt Brah Krist hŏ dâk rêh jêh bơh phung khĭt mâu hôm khĭt đŏng ôh; nau khĭt mâu hôm dơi đah Păng ôh.$b$,true),
('bunong-vn','ROM',6,10,null,$b$Yor lah Păng khĭt, păng khĭt yor nau tih du tơ̆ dŭm nây dơm, ƀiă lah aƀaơ Păng rêh, Păng gŭ rêh ma Brah Ndu.$b$,false),
('bunong-vn','ROM',6,11,null,$b$Pô ri kơp hom khân may nơm tâm ban ma khĭt jêh ma nau tih, ƀiă lah gŭ rêh ma Brah Ndu tâm Yêsu Krist.$b$,false),
('bunong-vn','ROM',6,12,null,$b$Pô ri lơi ăn nau tih chiă uănh tâm săk jăn blau khĭt khân may ôh, jêh ri lơi tông ma nau păng kơnh ôh.$b$,true),
('bunong-vn','ROM',6,13,null,$b$Lơi jao jâng ti khân may ma nau tih tâm ban ma ndơ nau kue dŏng ôh, ƀiă lah ăn khân may nhhơr khân may nơm ma Brah Ndu tâm ban ma phung hŏ dâk rêh jêh bơh phung khĭt jêh ri jâng ti khân may ma Brah Ndu jêng ndơ ma nau sŏng dŏng.$b$,false),
('bunong-vn','ROM',6,14,null,$b$Yor lah nau tih mâu hôm chiă uănh khân may ôh, yor lah khân may mâu gŭ tâm dâng nau vay ôh, ƀiă lah tâm dâng nau yô̆.$b$,false),
('bunong-vn','ROM',6,15,null,$b$Mâm ƀư? Yor lah he mâu gŭ tâm dâng nau vay, ƀiă lah gŭ tâm dâng nau yô̆. Dơi lĕ he hôm ƀư tih?$b$,true),
('bunong-vn','ROM',6,16,null,$b$Mâu! Khân may mâu gĭt hĕ tơ lah khân may jao khân may nơm jêng dĭk gay tông ma du huê bunuyh khân may hŏ jêng jêh dĭk ma nơm nây, geh tơ̆ nau tih njŭn leo ma nau khĭt, mâu lah ma nau tông bâr leo ma nau sŏng?$b$,false),
('bunong-vn','ROM',6,17,null,$b$Ƀiă lah, lah ueh ma Brah Ndu yor lah jêh khân may jêng dĭk ma nau tih kđôi lĕ, khân may tông jêh ma nuih n'hâm ma nau nti lah ăn jêh nâm bu trong khân may tĭng ndô̆ .$b$,false),
('bunong-vn','ROM',6,18,null,$b$Pô ri klaih jêh bơh nau tih, khân may jêng dĭk ma nau sŏng.$b$,false),
('bunong-vn','ROM',6,19,null,$b$Gâp ngơi tâm ban ma bunuyh yor lah nglay săk khân may rdja pô nây, nâm bu khân may jao jêh jâng ti khân may jêng dĭk nau ƀơ̆ jêh ri nau tih, ŭch ƀư tih, aƀaơ aơ jao hom jâng ti khân may jêng dĭk nau sŏng, ŭch geh nau kloh ueh tâm ban lĕ.$b$,false),
('bunong-vn','ROM',6,20,null,$b$Yor lah dôl khân may jêng dĭk ma nau tih, khân may mâu chrê ma nau sŏng.$b$,false),
('bunong-vn','ROM',6,21,null,$b$Pô ri, moh play khân may geh? Play ƀư prêng khân ay may aƀaơ! Yor lah ta dŭt lôch nau nây jêng nau khĭt.$b$,false),
('bunong-vn','ROM',6,22,null,$b$Ƀiă lah aƀaơ tâm rklaih jêh bơh nau tih, khân may jêng dĭk ma Brah Ndu. Khân may geh nau kloh ueh jêng play, jêh ri dăch ma lôch nau rêh n'ho ro.$b$,false),
('bunong-vn','ROM',6,23,null,$b$Yor lah rnoh nkhôm bơh nau tih jêng nau khĭt ƀiă lah nau Brah Ndu ăn dơm dam jêng nau rêh n'ho ro tâm Yêsu Krist, Kôranh Brah he.$b$,false),
('bunong-vn','ROM',7,1,null,$b$Hơi phung oh nâu, yor gâp ngơi đah phung gĭt nau vay, khân may mâu gĭt hĕ nau vay chiă uănh bunuyh knŏng dôl păng hôm gŭ rêh?$b$,true),
('bunong-vn','ROM',7,2,null,$b$Pô ri tĭng nâm nau vay lah, bu ur geh sai tâm krêp đah sai păng dôl păng hôm gŭ rêh; ƀiă lah tơ lah sai păng khĭt jêh, păng klaih đah nau vay tâm krêp đah păng.$b$,false),
('bunong-vn','ROM',7,3,null,$b$Pô ri, dôl sai păng hôm rêh, tơ lah bu ur gŭ bu klâu êng, bu mra rnha păng, bu ur văng tĭr. Ƀiă lah, tơ lah sai păng khĭt, păng klaih jêh ma nau vay, pô ri tơ lah păng gŭ sai êng, păng mâu jêng bu ur văng tĭr ôh.$b$,false),
('bunong-vn','ROM',7,4,null,$b$Tâm ban lĕ, hơi phung oh nâu tâm săk jăn Brah Krist khân may khĭt jêh ma nau vay, gay ma khân may jêng ndơ bu êng, nơm nây hŏ dâk rêh jêh tă bơh phung khĭt, pô nây mơ he geh play ma Brah Ndu.$b$,false),
('bunong-vn','ROM',7,5,null,$b$Yor nây dôl he gŭ rêh tĭng nâm nglay săk, nau kơnh mhĭk luh tă bơh nau vay ƀư tâm săk jăn he, jêh ri geh play ma nau khĭt.$b$,false),
('bunong-vn','ROM',7,6,null,$b$Ƀiă lah aƀaơ he khĭt jêh ma nau vay tŭn jot he sa ơm ri. He klaih jêh bơh nau vay nây jêh ri ŭch pah kan ma nau mĭn mhe bơh Brah Huêng Ueh, mâu di đah sămƀŭt ơm ôh.$b$,false),
('bunong-vn','ROM',7,7,null,$b$Moh he mra lah? Nau vay jêng tih lĕ? Mâu! Ƀiă lah knŏng ma nau vay gâp gĭt năl nau tih. Ƀiă lah tơ lah nau vay mâu lah: “Lơi may kơnh ôh.”$b$,true),
('bunong-vn','ROM',7,8,null,$b$Pô ri, ma nau vay nây nau tih njêng tâm gâp ăp ntil nau kơnh. Yor lah tơ lah mâu geh nau vay, nau tih khĭt jêh.$b$,false),
('bunong-vn','ROM',7,9,null,$b$Rnôk kăl e ri gâp mâu geh nau vay ôh, jêh ri gâp gŭ rêh, ƀiă lah ntơm bơh nau vay tât, nau tih rêh jêh ri gâp khĭt.$b$,false),
('bunong-vn','ROM',7,10,null,$b$Pô ri nau vay dơi ăn, nau rêh, ƀiă lah păng njŭn leo jêh gâp ma nau khĭt.$b$,false),
('bunong-vn','ROM',7,11,null,$b$Yor lah ma nau vay, nau tih ndơm gâp lĕ, jêh ri yor nây păng nkhĭt jêh gâp.$b$,false),
('bunong-vn','ROM',7,12,null,$b$Pô ri nau vay jêng kloh, nau ntăm jêng kloh, sŏng, ueh lĕ.$b$,false),
('bunong-vn','ROM',7,13,null,$b$Pô ri, di lĕ nau ueh nây njêng ma gâp nau khĭt? Mâu! Ƀiă lah nây jêng nau tih hŏ dŏng nau ueh nkhĭt gâp, gay nau tih dơi tâm mpơl jêng tih ngăn, jêh ri yor tă nau vay nau tih jêng lơ hâu lơn.$b$,true),
('bunong-vn','ROM',7,14,null,$b$Pô ri he gĭt nau vay jêng nau brah ƀiă lah gâp jêng nglay săk hŏ tăch jêh ma nau tih.$b$,true),
('bunong-vn','ROM',7,15,null,$b$Yor lah gâp mâu gĭt rbăng nau gâp ƀư. Gâp mâu ƀư nau gâp ŭch, ƀiă lah gâp ƀư nau gâp rmot.$b$,false),
('bunong-vn','ROM',7,16,null,$b$Tơ lah gâp ƀư nau gâp mâu ŭch, pô ri gâp gĭt nau vay jêng ueh.$b$,false),
('bunong-vn','ROM',7,17,null,$b$Pô ri aƀaơ aơ, mâu di gâp ôh ƀư nau nây, ƀiă lah nau tih gŭ tâm gâp.$b$,true),
('bunong-vn','ROM',7,18,null,$b$Gâp gĭt nau ueh mâu gŭ tâm gâp ôh, nâm bu ntĭt, tâm nglay săk gâp. Gâp geh nau ŭch, ƀiă lah mâu dơi ƀư nau ueh ôh.$b$,false),
('bunong-vn','ROM',7,19,null,$b$Yor lah gâp mâu ƀư nau ueh gâp ŭch ôh, ƀiă lah ƀư nau mhĭk gâp mâu ŭch.$b$,false),
('bunong-vn','ROM',7,20,null,$b$Pô ri, tơ lah gâp ƀư nau gâp mâu ŭch, mâu di gâp ôh ƀư nau nây, ƀiă lah nau tih gŭ tâm gâp.$b$,false),
('bunong-vn','ROM',7,21,null,$b$Gâp saơ tâm gâp nau vay pô aơ, tơ lah gâp ŭch ƀư nau ueh, nau mhĭk iang ta gâp.$b$,true),
('bunong-vn','ROM',7,22,null,$b$Yor lah tĭng nâm bunuyh tâm trôm nuih gâp răm ma nau vay Brah Ndu,$b$,true),
('bunong-vn','ROM',7,23,null,$b$Ƀiă lah gâp saơ tâm săk jăn gâp du nau vay êng tâm lơh đah nau vay gâp mĭn jêh ri nau vay nây ăn gâp jêng dĭk ma nau vay nau tih gŭ tâm săk jăn gâp.$b$,false),
('bunong-vn','ROM',7,24,null,$b$Rêh ni ngăn gâp! Mbu nơm mra rklaih gâp bơh săk jăn blau khĭt aơ?$b$,false),
('bunong-vn','ROM',7,25,null,$b$Lah ueh ma Brah Ndu tâm Yêsu Krist, Kôranh Brah he! Pô ri yơh, ma nau mĭn gâp jêng dĭk ma nau vay Brah Ndu, ƀiă lah ma nglay săk gâp jêng dĭk ma nau vay nau tih.$b$,false),
('bunong-vn','ROM',8,1,null,$b$Pô ri aƀaơ aơ mâu hôm geh nau tâm rmal ôh ma phung gŭ tâm Yêsu Krist.$b$,true),
('bunong-vn','ROM',8,2,null,$b$Yor lah nau vay Brah Huêng Ueh rêh tâm Yêsu Krist tâm rklaih jêh gâp bơh nau vay nau tih jêh ri nau khĭt.$b$,true),
('bunong-vn','ROM',8,3,null,$b$Yor lah moh nau vay mâu dơi ƀư, yor nglay săk ƀư păng rdja, Brah Ndu ƀư jêh. Yor nau tih, păng njuăl kon păng nơm jêng nglay săk tâm ban ma nglay săk tih he, jêh ri păng tâm rmal jêh nau tih tâm nglay săk,$b$,false),
('bunong-vn','ROM',8,4,null,$b$gay ma nau sŏng bơh nau vay ngăn jêh tâm he, phung mâu hăn tĭng nâm nglay săk, ƀiă lah tĭng nâm Brah Huêng Ueh.$b$,false),
('bunong-vn','ROM',8,5,null,$b$Yor lah mbu nơm rêh tĭng nâm nglay săk rŏng ma mpa nglay săk ŭch ƀiă lah mbu nơm rêh tĭng nâm Brah Huêng Ueh rŏng ma ndơ Brah Huêng Ueh.$b$,false),
('bunong-vn','ROM',8,6,null,$b$Yor lah nau tĭng nglay săk jêng nau khĭt, ƀiă lah nau tĭng Brah Huêng Ueh jêng nau rêh, jêh ri nau đăp mpăn.$b$,true),
('bunong-vn','ROM',8,7,null,$b$Yor lah nau tĭng nau nglay săk jêng rlăng đah Brah Ndu. Yor lah păng mâu tông nau vay Brah Ndu ôh, jêh ri mâu lĕ păng dơi tông.$b$,false),
('bunong-vn','ROM',8,8,null,$b$Pô ri phung rêh tĭng nâm nglay săk mâu dơi ƀư maak ma Brah Ndu ôh.$b$,false),
('bunong-vn','ROM',8,9,null,$b$Bi khân may, tơ lah Brah Huêng Ueh Brah Ndu gŭ ngăn tâm khân may, khân may mâu rêh tĭng nâm nglay săk ôh, ƀiă lah tĭng nâm Brah Huêng Ueh. Ƀiă lah mbu nơm mâu geh brah huêng Brah Krist, păng mâu jêng phung Brah Krist ôh.$b$,true),
('bunong-vn','ROM',8,10,null,$b$Pô ri, tơ lah Brah Krist gŭ tâm khân may săk jăn khĭt jêh yor nau tih, ƀiă lah huêng rêh yor nau sŏng.$b$,false),
('bunong-vn','ROM',8,11,null,$b$Jêh ri tơ lah Brah Huêng Ueh, Nơm hŏ ƀư rêh jêh Brah Yêsu bơh phung khĭt gŭ tâm khân may, Nơm hŏ ndâk rêh jêh Yêsu Krist bơh phung khĭt mra dâk rêh săk jăn blau khĭt khân may lĕ ma Brah Huêng Ueh gŭ tâm khân may.$b$,false),
('bunong-vn','ROM',8,12,null,$b$Pô ri, hơi oh nâu, he mâu hôm iang rnon nglay săk, ŭch tông tĭng nâm nglay săk ŭch ôh.$b$,true),
('bunong-vn','ROM',8,13,null,$b$Yor lah tơ lah khân may tông tĭng nâm nglay săk ŭch, khân may mra khĭt, ƀiă lah tơ lah ma Brah Huêng Ueh khân may nkhĭt kan tĭng nâm săk jăn, khân may mra rêh.$b$,false),
('bunong-vn','ROM',8,14,null,$b$Yor lah lĕ rngôch phung geh Brah Huêng Ueh Brah Ndu njŭn, jêng kon Brah Ndu.$b$,false),
('bunong-vn','ROM',8,15,null,$b$Yor lah khân may mâu geh sŏk dơn huêng jêng dĭk ăn khân may ăt gŭ tâm nau klach ôh, ƀiă lah khân may sŏk dơn jêh huêng jêng kon mât rong an, yor nây he kuăl, “Abba!” Nâm bu ntĭt, “Mbơ̆ !”$b$,false),
('bunong-vn','ROM',8,16,null,$b$Brah Huêng Ueh nơm mbơh ma huêng he, ma he jêng kon Brah Ndu,$b$,false),
('bunong-vn','ROM',8,17,null,$b$Jêh ri tơ lah he jêng kon, he jêng lĕ phung ndơn drăp Brah Ndu, phung ndơn ndrel ma Brah Krist, tơ lah he dơn nau rêh ni ndrel ma păng, he mra geh nau chrêk rmah ndrel ma Păng.$b$,false),
('bunong-vn','ROM',8,18,null,$b$Gâp kơp nau rêh ni rnôk aơ mâu dơi tâm ban ôh ma nau chrêk rmah mra tâm mpơl ma he nar kăndơ̆ .$b$,true),
('bunong-vn','ROM',8,19,null,$b$Yor lah lĕ rngôch mpô mpa dôl gŭ kâp ma nau tâm mpơl phung Kon Brah Ndu.$b$,false),
('bunong-vn','ROM',8,20,null,$b$Yor lah lĕ rngôch mpa dơn jêh nau sưr mâu di tĭng nâm khân păng nơm ŭch ƀiă lah yor nơm nglăp khân păng ma nau nây,$b$,false),
('bunong-vn','ROM',8,21,null,$b$jêh ri kâp gân mra tâm rklaih bơh dĭk nau rai yot, gay geh ndrel ma phung kon Brah Ndu nau kon me chrêk rmah.$b$,false),
('bunong-vn','ROM',8,22,null,$b$Yor lah he gĭt lĕ rngôch ndơ nter nhhiăng jêh ri dơn nau rêh ni tât ta nar aơ.$b$,false),
('bunong-vn','ROM',8,23,null,$b$Jêh ri mâu di knŏng êng khân păng, ƀiă lah nđâp ma he lĕ, phung jêng play lor lơn bơh Brah Huêng Ueh, he nter nhhiăng lĕ tâm he nơm, dôl gŭ kâp nau jêng kon mât rong an, nâm bu ntĭt, nau tâm chuai ma săk jăn he.$b$,true),
('bunong-vn','ROM',8,24,null,$b$Yor lah he tâm rklaih jêh ma nau kâp gân yơh, ƀiă lah tơ lah bu saơ jêh nau kâp gân, nau nây mâu hôm jêng nau kâp gân ôh! Ndơ păng hŏ saơ jêh mpa nau păng kâp gân đŏng?$b$,false),
('bunong-vn','ROM',8,25,null,$b$Ƀiă lah tơ lah he kâp gân ma ndơ he mâu dơi saơ he gŭ kâp gân ndơ nây ma nau nsrôih yơh.$b$,false),
('bunong-vn','ROM',8,26,null,$b$Tâm ban lĕ Brah Huêng Ueh kơl nau rdja he, yor lah he mâu gĭt moh nau di he dăn dôl mbơh sơm, ƀiă lah Brah Huêng Ueh nơm kơl mbơh sơm ăn ma he ma nau nter mâu dơi rblang.$b$,false),
('bunong-vn','ROM',8,27,null,$b$Jêh ri nơm gĭt năl nuih n'hâm bunuyh gĭt nau mĭn Brah Huêng Ueh tâm ban lĕ, yor lah Brah Huêng Ueh kơl mbơh sơm ma phung kloh ueh tĭng nâm Brah Ndu ŭch.$b$,false),
('bunong-vn','ROM',8,28,null,$b$Pô ri, he gĭt lĕ rngôch nau tâm rnglăp jêng ueh ma phung rŏng ma Brah Ndu, nâm bu ntĭt phung Brah Ndu kuăl tĭng nâm nau Păng săch jêh bơh lor.$b$,true),
('bunong-vn','ROM',8,29,null,$b$Yor lah phung Păng gĭt năl jêh bơh lor, Păng săch jêh, ăn phung nây jêng tâm ban ma Kon Păng, gay ma Kon păng jêng nâu ranh ma âk oh.$b$,false),
('bunong-vn','ROM',8,30,null,$b$Jêh ri phung Păng săch jêh, Păng lĕ kuăl jêh; phung Păng kuăl jêh Păng kơp hŏ kơp sŏng jêh, jêh ri phung Păng kơp sŏng jêh Păng ăn nau chrêk rmah ma khân păng đŏng.$b$,false),
('bunong-vn','ROM',8,31,null,$b$Mâm nau he mra lah ma nau nây? Tơ lah Brah Ndu gŭ mpeh ma he, mbu mra tâm rdâng đah he?$b$,true),
('bunong-vn','ROM',8,32,null,$b$Brah Ndu mâu nhhuach kon Păng nơm, ƀiă lah Păng jao jêh ma lĕ rngôch he, mâm ƀư Păng mâu mra ăn lĕ ma he lĕ rngôch mpa ndrel ma Păng?$b$,false),
('bunong-vn','ROM',8,33,null,$b$Mbu nơm mra phong ma phung Brah Ndu săch? Brah Ndu nơm kơp khân păng jêng sŏng.$b$,false),
('bunong-vn','ROM',8,34,null,$b$Mbu nơm mra tâm rmal khân păng? Yêsu Krist, Nơm khĭt jêh, ƀiă lah Păng hŏ rêh jêh, jêh ri gŭ mpeh pa ma Brah Ndu kơl mbơh sơm ma phung he.$b$,true),
('bunong-vn','ROM',8,35,null,$b$Mbu mra nkhah he đah nau Yêsu Krist rŏng? Nau rêh ni toyh, nau rngot klâng, nau ƀư mhĭk, nau sa sât ji ngot, bêch kuh rhôk, nau djơh mhĭk mâu lah đao ƀơh?$b$,false),
('bunong-vn','ROM',8,36,null,$b$Tĭng nâm nchih jêh: “Ăp nar hên gŭ dăch nau khĭt yor may. Bu uănh hên tâm ban ma biăp bu mra gŭch sa.”$b$,false),
('bunong-vn','ROM',8,37,null,$b$Ƀiă lah ma Nơm rŏng ma he, he dơi mro mrăng tâm lĕ nau nây.$b$,true),
('bunong-vn','ROM',8,38,null,$b$Yor lah gâp gĭt nanê̆ ngăn, gĭt lah nau khĭt, nau rêh, phung kôranh toyh, ndơ rnôk aƀaơ, ndơ rnôk kăndơ̆ , nau brah,$b$,false),
('bunong-vn','ROM',8,39,null,$b$ndah jong, ndah jru, mâu lah moh mpa êng tâm neh trôk mâu dơi ôh tâm nkhah he bơh nau Brah Ndu rŏng tâm mpơl jêh tâm Yêsu Krist, Kôranh Brah he.$b$,false),
('bunong-vn','ROM',9,1,null,$b$Gâp lah nau nanê̆ tâm Brah Krist, gâp mâu mƀruh ôh; ma Brah Huêng Ueh, nuih n'hâm sŏng gâp mbơh nau nây ma gâp.$b$,true),
('bunong-vn','ROM',9,2,null,$b$Gâp rngot ngăn jêh ri nuih n'hâm gâp ji mro.$b$,false),
('bunong-vn','ROM',9,3,null,$b$Yor lah gâp ŭch jêng bunuyh bu suai rak, nkhah đah Brah Krist kđôi, yor phung oh nâu gâp, phung ndŭl mpôl gâp tĭng nâm nglay săk$b$,false),
('bunong-vn','ROM',9,4,null,$b$nâm bu ntĭt phung Israel ma khân păng geh nau dơi jêng kon rŏng an, nau chrêk rmah, nau tâm rnglăp, nau vay, nau yơk ma Brah Ndu, jêh ri nau ton.$b$,false),
('bunong-vn','ROM',9,5,null,$b$Khân păng luh tă bơh phung che jêh ri tĭng nâm nglay săk, tă bơh phung khân păng yơh luh văch Brah Krist nơm klơ lơn ma lĕ rngôch, jêng Brah Ndu, nơm bu mât ton n'ho ro. Amen$b$,false),
('bunong-vn','ROM',9,6,null,$b$Mâu di Nau Brah Ndu Ngơi jêng dơm dam ôh. Yor lah lĕ rngôch luh bơh Israel mâu geh jêng phung Israel ngăn ôh,$b$,false),
('bunong-vn','ROM',9,7,null,$b$Yor lah khân păng jêng mpôl băl Y-Abraham mâu lĕ di lĕ rngôch khân păng jêng kon păng, ƀiă lah bu lah jêh: “Tă bơh Y-Isăk yơh may mra geh mpôl băl djôt amoh may.”$b$,false),
('bunong-vn','ROM',9,8,null,$b$Nâm bu ntĭt, mâu di ôh phung kon nglay săk jêng kon Brah Ndu ƀiă lah kon tă bơh nau Brah Ndu ton, bu kơp khân păng dơi jêng kon Y-Abraham.$b$,true),
('bunong-vn','ROM',9,9,null,$b$Pô aơ geh nau ngơi ton jêh: “Gâp mra văch yan aơ lĕ jêh ri H'Sara mra geh du huê kon bu klâu.”$b$,false),
('bunong-vn','ROM',9,10,null,$b$Mâu di dŭm nĕ ôh, ƀiă lah H'Rêbeka, tơ lah păng ntreo du tơ̆ đah Y-Isăk che he,$b$,false),
('bunong-vn','ROM',9,11,null,$b$dôl phung kon nây ê deh jêh ri khân păng ê mâp ƀư ueh mâu lah mhĭk, gay ma Brah Ndu săch ăt hôm mro, mâu di ma kan ôh, ƀiă lah ma nau nơm kuăl ŭch,$b$,false),
('bunong-vn','ROM',9,12,null,$b$geh nau ngơi ma H'Rêbeka pô aơ: “Nâu mra jêng nơm răk sa ma oh păng.”$b$,false),
('bunong-vn','ROM',9,13,null,$b$Di ma nau nchih jêh: “Gâp rŏng jêh ma Y-Yakôp, jêh ri tâm rmot jêh ma Y-Êsau.”$b$,false),
('bunong-vn','ROM',9,14,null,$b$Pô ri, moh nau he mra lah? Geh lĕ nau kue tâm Brah Ndu? Mâu! Mâu mâp geh ôh.$b$,true),
('bunong-vn','ROM',9,15,null,$b$Yor lah Păng lah ma Y-Môis: “Gâp mra yô̆ ma mbu nơm gâp mra yô̆jêh ri gâp mra rŏng ma mbu nơm gâp ma rŏng.”$b$,true),
('bunong-vn','ROM',9,16,null,$b$Pô ri nau nây mâu tât yor bu ŭch, mâu lĕ di yor bu nchuăt tĭng lĕ, ƀiă lah yor Brah Ndu yô̆.$b$,true),
('bunong-vn','ROM',9,17,null,$b$Yor lah nau nchih lah ma Pharaôn: “Gâp hŏ n'hao may yor gâp ŭch tâm mpơl nau brah gâp tâm may jêh ri ŭch ma amoh gâp bu mbơh lam bri neh.”$b$,false),
('bunong-vn','ROM',9,18,null,$b$Pô nây lĕ, Păng yô̆ ma mbu nơm păng ŭch, jêh ri ƀư dăng nuih n'hâm ma mbu nơm păng ŭch.$b$,true),
('bunong-vn','ROM',9,19,null,$b$Pô ri, khân may mra ôp gâp pô aơ: “Mâm ƀư Brah Ndu hôm nduyh? Yor lah mbu nơm dơi tâm rdâng đah nau Păng ŭch?”$b$,true),
('bunong-vn','ROM',9,20,null,$b$Ƀiă lah hơi jiăng, mbu may jêng janh tâm rlăch đah Brah Ndu? Dơi lĕ yăng ôp nơm mon Păng: “Mâm ƀư may mon gâp pô aơ?”$b$,false),
('bunong-vn','ROM',9,21,null,$b$Mâu di hĕ nơm mon jêng kôranh ma uk, ŭch mon ƀă yăng mâu khlay ƀă yăng khlay?$b$,false),
('bunong-vn','ROM',9,22,null,$b$Mâm ƀư? Tơ lah Brah Ndu ŭch tâm mpơl nau păng nuih jêh ri mbơh nau brah păng, dơn ma nau srôih toyh phung yăng khư nuih prăp ma nau roh,$b$,false),
('bunong-vn','ROM',9,23,null,$b$jêh ri ŭch tâm mpơl nau ndrŏng nau chrêk rmah păng ma phung yăng păng yô̆ săch jêh bơh lor ma nau chrêk rmah,$b$,false),
('bunong-vn','ROM',9,24,null,$b$nâm bu ntĭt he, phung păng kuăl jêh, mâu di knŏng bơh phung Yuđa ôh, ƀiă lah nđâp ma phung bu năch lĕ.$b$,false),
('bunong-vn','ROM',9,25,null,$b$Tĭng nâm hŏ lah jêh tâm ndrom sămƀŭt Y-Ôsê: “Gâp mra kuăl phung gâp ma phung mâu di băl gâp ôh, jêh ri nơm gâp rŏng ma phung mâu khư rŏng ôh.”$b$,false),
('bunong-vn','ROM',9,26,null,$b$“Jêh ri tâm ntŭk păng lah ma khân păng: ‘Khân may mâu di phung gâp ôh,’ ta nây lĕ bu mra kuăl khân păng jêng ‘kon Brah Ndu rêh n'ho ro.’ ”$b$,true),
('bunong-vn','ROM',9,27,null,$b$Bi Y-Êsai, dôl păng ngơi ma phung Israel, nter lah pô aơ: “Tơ lah phung kon Israel mra jêng tâm ban ma choih tâm dak mƀŭt, knŏng du kô̆ hôm mra dơi tâm rklaih.$b$,true),
('bunong-vn','ROM',9,28,null,$b$Yor lah Kôranh Brah mra ndal ƀư nanê̆ lĕ nau păng ton jêh ta neh ntu aơ.”$b$,false),
('bunong-vn','ROM',9,29,null,$b$Jêh ri tĭng nâm Y-Êsai mbơh jêh pô aơ: “Tơ lah Kôranh Brah ma phung ta han mâu prăp mpôl he, he mra jêng nâm bu ƀon Sôdôm jêh ri Gômôrơ.”$b$,true),
('bunong-vn','ROM',9,30,null,$b$Pô ri moh nau he mra lah? Phung bu năch mâu mâp joi ôh nau sŏng, ƀiă lah khân păng geh jêh nau sŏng nây, văch bơh ma nau chroh.$b$,true),
('bunong-vn','ROM',9,31,null,$b$Bi phung Israel tĭng joi nau vay nau sŏng, khân păng mâu tât ôh ma nau vay nây.$b$,false),
('bunong-vn','ROM',9,32,null,$b$Mâm ƀư? Yor lah khân păng mâu joi ma nau chroh ôh, ƀiă lah ma kan khân păng pah, khân păng king lŭ bâp ta trong,$b$,false),
('bunong-vn','ROM',9,33,null,$b$Tĭng nâm nchih jêh pô aơ: “Aơ, gâp dơm tâm Siôn du mlâm lŭ gay ma prah bu. Jêh ri mbu nơm chroh ma păng mâu mra prêng ôh.”$b$,false),
('bunong-vn','ROM',10,1,null,$b$Hơi phung oh nâu, nau gâp ŭch ma lĕ nuih n'hâm jêh ri nau gâp mbơh sơm ma Brah Ndu yor phung Israel ŭch ma khân păng klaih.$b$,true),
('bunong-vn','ROM',10,2,null,$b$Yor lah gâp mbơh sơm ma khân păng geh nau duh nđơr ma Brah Ndu, ƀiă lah mâu di ma nau gĭt rbăng ôh.$b$,false),
('bunong-vn','ROM',10,3,null,$b$Dôl khân păng mâu gĭt năl nau sŏng Brah Ndu, khân păng joi ŭch njêng nau sŏng khân păng nơm, pô ri khân păng mâu tông ma nau sŏng Brah Ndu ôh.$b$,true),
('bunong-vn','ROM',10,4,null,$b$Yor lah Brah Krist jêng play lôch ma nau vay, gay kơp sŏng lĕ rngôch mbu nơm chroh.$b$,false),
('bunong-vn','ROM',10,5,null,$b$Yor lah Y-Môis nchih jêh pô aơ: “Mbu nơm tông nau sŏng bơh nau vay mra gŭ rêh yor păng.”$b$,true),
('bunong-vn','ROM',10,6,null,$b$Ƀiă lah nau sŏng luh tă bơh nau chroh lah pô aơ: “Lơi lah ôh tâm nuih n'hâm: ‘Mbu mra hao klơ trôk?’ ” (Gay ăn Brah Krist jŭr),$b$,false),
('bunong-vn','ROM',10,7,null,$b$mâu lah “Mbu mra jŭr tâm ntu jru?” (Gay ăn Brah Krist dâk bơh phung khĭt).$b$,false),
('bunong-vn','ROM',10,8,null,$b$Ƀiă lah moh nau păng lah? “Nau ngơi gŭ dăch may tâm trôm mbung jêh ri tâm nuih n'hâm may” (nâm bu ntĭt, nau ngơi bơh nau chroh yơh hên nti lah).$b$,false),
('bunong-vn','ROM',10,9,null,$b$Pô ri, tơ lah may mbơh Brah Yêsu ma bâr mbung may, jêh ri chroh tâm nuih n'hâm may ma Brah Ndu ăn Păng rêh jêh bơh phung khĭt, may mra klaih yơh.$b$,true),
('bunong-vn','ROM',10,10,null,$b$Yor lah ma nuih n'hâm chroh yơh bu geh nuih n'hâm sŏng, jêh ri ma bâr mbung bu mbơh nau Păng klaih jêh.$b$,false),
('bunong-vn','ROM',10,11,null,$b$Tĭng nâm nau nchih lah pô aơ: “Mbu nơm chroh ma Păng mâu mra prêng ôh.”$b$,false),
('bunong-vn','ROM',10,12,null,$b$Phung Yuđa mâu geh êng êng ôh đah phung Grek? Yor lah lĕ rngôch khân păng geh nguay Kôranh Brah, ndrŏng ma lĕ rngôch phung kuăl amoh Păng.$b$,false),
('bunong-vn','ROM',10,13,null,$b$Yor lah: “Mbu nơm mra kuăl amoh Kôranh Brah mra klaih.”$b$,false),
('bunong-vn','ROM',10,14,null,$b$Mâm khân păng dơi mbơh sơm ma nơm khân păng ê chroh? Jêh ri mâm khân păng dơi chroh ma nơm khân păng ê mâp iăt? Jêh ri mâm khân păng dơi iăt tơ lah ê geh nơm nti ma khân păng?$b$,true),
('bunong-vn','ROM',10,15,null,$b$Jêh ri mâm bu dơi hăn nti, tơ lah mâu geh bunuyh bu njuăl nsong? Tĭng nâm nau nchih jêh pô aơ: “Ueh lăng yơh jâng phung hăn mbơh nau mhe mhan ueh!”$b$,false),
('bunong-vn','ROM',10,16,null,$b$Ƀiă lah mâu di lĕ rngôch ôh rkêng tôr iăt nau mhe mhan ueh. Yor lah Y-Êsai lah pô aơ: “Ơ Kôranh Brah, mbu nơm chroh ma nau hên nti jêh?”$b$,false),
('bunong-vn','ROM',10,17,null,$b$Pô ri nau chroh luh bơh nau iăt, jêh ri nau iăt luh bơh nau Brah Krist ngơi.$b$,false),
('bunong-vn','ROM',10,18,null,$b$Ƀiă lah gâp ôp: Bu mâu hŏ mâp tăng hĕ? Mâu, mâu di ôh? Yor lah: “Bâr khân păng bu tăng lư jêh lam bri neh, jêh ri nau khân păng mbơh jêh tât ta dŭt bri dŭt neh.”$b$,true),
('bunong-vn','ROM',10,19,null,$b$Gâp ôp tay: Di lĕ phung Israel ê mâp gĭt nau aơ? Y-Môis lah jêh lor pô aơ: “Gâp mra đă phung bu mâu kơp du ndŭl mpôl gay nsônh nau mâu nach khân may. Gâp mra đă du phung mpôl băl mâu geh nau gĭt rbăng ƀư ji nuih ma khân may.”$b$,true),
('bunong-vn','ROM',10,20,null,$b$Y-Êsai lah ma nau brât janh pô aơ: “Phung mâu joi gâp, mâp jêh đah gâp. Gâp mpơl jêh gâp nơm ma phung mâu dăn ma gâp ôh.”$b$,true),
('bunong-vn','ROM',10,21,null,$b$Ƀiă lah ma phung Israel păng lah: “Lĕ nar gâp yơr ti mpeh du phung mâu tông jêh ri ngơi tâm rdâng.”$b$,true),
('bunong-vn','ROM',11,1,null,$b$Pô nây gâp lah, Brah Ndu mâp lơi lĕ phung ƀon lan păng? Mâu, mâu mâp ôh! Yor lah gâp nơm lĕ jêng kon Israel, bơh mpôl băl Y-Abraham, bơh mpôl Benjamin.$b$,true),
('bunong-vn','ROM',11,2,null,$b$Brah Ndu mâu mâp lơi ôh phung păng gĭt năl jêh bơh lor. Khân may mâu gĭt hĕ ma nau nchih mâm nau Y-Êli phong ma phung Israel ta năp Brah Ndu?$b$,true),
('bunong-vn','ROM',11,3,null,$b$“Ơ Kôranh Brah, khân păng nkhĭt jêh phung kôranh nơm mbơh lor may, jêh ri khân păng rơih lĕ jêh nơng ƀư brah ma may. Hôm knŏng êng du huê gâp, jêh ri khân păng joi ŭch nkhĭt gâp.”$b$,false),
('bunong-vn','ROM',11,4,null,$b$Ƀiă lah moh nau Brah Ndu plơ̆ lah ma păng? “Gâp njrăng prăp jêh ma gâp nơm pơh rbăn nuyh ê mâp chon kômâk ta năp brah Baal.”$b$,false),
('bunong-vn','ROM',11,5,null,$b$Tâm ban lĕ tâm rnôk aơ tĭng nâm nau săch ma nau yô̆, geh du kô̆ hôm.$b$,false),
('bunong-vn','ROM',11,6,null,$b$Ƀiă lah tơ lah ma nau yô̆ mâu di ma kan ôh. Tơ lah mâu di pô nây, nau yô̆ mâu hôm jêng di nau yô̆ ôh. Jêh ri tơ lah ma kan, mâu geh nau yô̆ ôh. Tơ lah mâu di pô nây, kan mâu hôm jêng di kan ôh.$b$,false),
('bunong-vn','ROM',11,7,null,$b$Mâm ƀư pô nây? Nau phung Israel joi, khân păng mâu geh ôh, ƀiă lah phung Brah Ndu săch geh jêh nau nây bi phung êng jêng phung dăng.$b$,true),
('bunong-vn','ROM',11,8,null,$b$Di nâm bu nau bu nchih jêh pô aơ: “Brah Ndu ăn jêh ma khân păng nau mĭn ngo, măt khân păng mâu dơi saơ, jêh ri tôr khân păng mâu dơi tăng ôh, tât ma aƀaơ.”$b$,false),
('bunong-vn','ROM',11,9,null,$b$Jêh ri Y-Đavit lah: “Ăn sưng khân păng sông jêng dăk jêng nhuăl. Jêng ndơ cha lôt jêh ri jêng ndơ khư ma khân păng;$b$,true),
('bunong-vn','ROM',11,10,null,$b$Ăn măt khân păng jêng ngo, mâu dơi saơ ôh. Jêh ri ăn ndŭr kơi khân păng kuăt mro.”$b$,false),
('bunong-vn','ROM',11,11,null,$b$Pô ri, gâp ôp, di lĕ nau ƀư tŭp pô nây gay ăn phung Israel prah? Mâu! Mâu di pô nây ôh! Ƀiă lah yor nau tih khân păng, nau tâm rklaih văch tât jêh ma phung bu năch gay ma nsônh nau tâm mâu nach phung Israel.$b$,true),
('bunong-vn','ROM',11,12,null,$b$Tơ lah nau prah khân păng jêng nau ndrŏng ma neh ntu, jêh ri nau hŭch khân păng jêng nau ndrŏng ma phung bu năch; jêh ri dŭm âk rplay khlay rlau lơn ma nau nây mra dơi chăt jêng tơ lah khân păng plơ̆ sĭt chroh?$b$,false),
('bunong-vn','ROM',11,13,null,$b$Gâp lah ma khân may, hơi phung bu năch, yor lah gâp jêng du huê kôranh oh mon ma phung bu năch, gâp yơk ma kan gâp,$b$,true),
('bunong-vn','ROM',11,14,null,$b$gay ma tơ lah dơi tâm nsônh nau mâu nach ma phung ndŭl mpôl gâp, jêh ri gay ma tâm rklaih ƀa ƀă tâm phung khân păng.$b$,false),
('bunong-vn','ROM',11,15,null,$b$Yor lah, tơ lah nau dun ma khân păng jêng nau tâm rnglăp ma neh ntu, pô ri moh mra jêng nau rom tay khân păng? Mâu di hĕ, nau dâk rêh bơh phung khĭt?$b$,false),
('bunong-vn','ROM',11,16,null,$b$Tơ lah play lor lơn jêng kloh ueh, lĕ rngôch phung play ƀa ƀă jêng kloh ueh tâm ban lĕ, jêh ri tơ lah reh jêng kloh ueh, phung n'gĭng păng kloh ueh tâm ban lĕ.$b$,true),
('bunong-vn','ROM',11,17,null,$b$Ƀiă lah tơ lah n'gĭng ƀa ƀă bu koh lơi, jêh ri tơ lah may jêng du n'gâng tơm si Ôlivơ ƀoi tâm ndop lĭr ta ntŭk bu koh jêh, gay may jêng nguay đah n'gĭng nây, jêh ri geh dak rêh bơh tơm si Ôlivơ nây,$b$,true),
('bunong-vn','ROM',11,18,null,$b$lơi ta rnê may nơm ma n'gĭng êng. Bi tơ lah may rnê may nơm, ăn may gĭt, mâu di may ôh djôt reh, reh djôt may.$b$,false),
('bunong-vn','ROM',11,19,null,$b$May mra lah: “Phung n'gĭng bu koh lơi jêh gay ma bu dơi ndop gâp!”$b$,false),
('bunong-vn','ROM',11,20,null,$b$Pô ri, di jêh bu koh lơi jêh khân păng, yor lah khân păng mâu chroh, jêh ri may ăt hôm yor nau may chroh. Lơi may sưr ôh, ƀiă lah ăn klach hom.$b$,false),
('bunong-vn','ROM',11,21,null,$b$Yor lah tơ lah Brah Ndu mâu nhhuach ma phung n'gĭng păng nơm, păng mâu mra nhhuach ma may tâm ban lĕ.$b$,false),
('bunong-vn','ROM',11,22,null,$b$Ăn may uănh nau ueh jêh ri nau dăng Brah Ndu, nau dăng ma mbu nơm tŭp jêh, jêh ri nau ueh ma may, tơ lah may gŭ nâp mro tâm nau ueh păng; tơ lah mâu di pô nây, păng mra koh may tâm ban lĕ.$b$,false),
('bunong-vn','ROM',11,23,null,$b$Khân păng tâm ban lĕ, tơ lah khân păng lơi nau mâu chroh, Brah Ndu mra ndop khân păng, Yor lah Brah Ndu jêng brah dơi ndop tay khân păng.$b$,false),
('bunong-vn','ROM',11,24,null,$b$Tơ lah bu koh jêh may bơh tơm Ôlivơ bri jêh ri tâm ndop may tâm tơm Ôlivơ ngăn, êng đah nau mơng, nơih lơn bu mra tâm ndop phung n'gĭng ngăn tâm tơm Ôlivơ ngăn.$b$,false),
('bunong-vn','ROM',11,25,null,$b$Hơi oh nâu, gâp mâu ŭch ôh ma khân may mâu gĭt rbăng ma nau khlay ndâp aơ, klach lah khân may uănh ma khân may nơm jêng tâm ban ma bunuyh blau mĭn; geh knŏng du kô̆ tâm phung Israel tŭp jêh tâm nau nuih n'hâm dăng, tât nŭm jêh phung bu năch lăp.$b$,true),
('bunong-vn','ROM',11,26,null,$b$Pô ri, lĕ rngôch phung Israel mra klaih, nâm bu, bu nchih jêh: “Nơm tâm rklaih mra văch tă bơh, Siôn jêh ri păng mra nsot ngai nau mâu chroh bơh Y-Yakôp.”$b$,false),
('bunong-vn','ROM',11,27,null,$b$“Jêh ri pô aơ nau tâm rnglăp gâp mra ƀư đah khân păng. Tơ lah gâp mra lâm nau tih khân păng.”$b$,true),
('bunong-vn','ROM',11,28,null,$b$Ma nau mhe mhan ueh khân păng jêng rlăng yor khân may; ƀiă lah ma nau săch, khân păng jêng bunuyh Brah Ndu rŏng jêh yor phung mbơ̆ khân păng.$b$,true),
('bunong-vn','ROM',11,29,null,$b$Yor lah Brah Ndu mâu rgâl ôh nau păng yô̆ jêh ri nau păng kuăl.$b$,false),
('bunong-vn','ROM',11,30,null,$b$Nâm bu kăl e khân may mâu tông ma Brah Ndu, ƀiă lah aƀaơ khân may geh nau yô̆ yor lah nau khân păng mâu tông,$b$,false),
('bunong-vn','ROM',11,31,null,$b$tâm ban lĕ khân păng jêng phung mâu tông bâr aƀaơ aơ, gay ma yor nau yô̆ tâm mpơl jêh ma khân may, khân păng dơi geh nau yô̆ tâm ban lĕ.$b$,false),
('bunong-vn','ROM',11,32,null,$b$Yor lah Brah Ndu krŭng jêh lĕ rngôch bunuyh tâm nau mâu tông bâr gay yô̆ an ma lĕ rngôch.$b$,false),
('bunong-vn','ROM',11,33,null,$b$Ơ! Jru ngăn nau Brah Ndu ndrŏng, nau Păng blau mĭn, jêh ri nau Păng gĭt rbăng! Lĕ rngôch nau Păng phat dôih, mbu dơi sek uănh tât lôch, jêh ri trong Păng mbu dơi tĭng!$b$,true),
('bunong-vn','ROM',11,34,null,$b$“Yor lah mbu gĭt nau mĭn Kôranh Brah, mâu lah mbu nơm nti Păng?”$b$,true),
('bunong-vn','ROM',11,35,null,$b$Mâu lah, “Mbu ăn jêh ma Păng lor gay sŏk ndơ Păng mplơ̆ nsĭt lơi?”$b$,true),
('bunong-vn','ROM',11,36,null,$b$Yor lah tă bơh Păng, đah Păng jêh ri ma Păng yơh lĕ rngôch mpô mpa dơi jêng. Ăn ma Păng yơh nau chrêk rmah n'ho ro. Amen.$b$,true),
('bunong-vn','ROM',12,1,null,$b$Hơi oh nâu, ma nau Brah Ndu yô̆, gâp vơh vơl ma khân may, jao hom săk jăn khân may nơm jêng mpa nhhơr rêh, kloh ueh, maak ma Brah Ndu. Nau nây jêng nau ƀư brah di.$b$,true),
('bunong-vn','ROM',12,2,null,$b$Lơi ƀư tâm ban ma phung rnôk aơ, ƀiă lah ma nau mĭn mhe khân may tâm rgâl hom khân may nơm gay ma khân may mra gĭt rbăng ma nau Brah Ndu jêng ueh, maak, jêh ri rah vah.$b$,false),
('bunong-vn','ROM',12,3,null,$b$Pô ri, ma nau yô̆ Păng ăn jêh ma gâp lah ma ăp nơm khân may, lơi geh nau mĭn gao rnâng ir ôh, ƀiă lah ăn khân may geh nau mĭn di rnâng, khư ma nau chroh Brah Ndu ăn ma ăp nơm.$b$,false),
('bunong-vn','ROM',12,4,null,$b$Yor lah nâm bu geh âk ntil mpa tâm du săk jăn he, ƀiă lah lĕ rngôch mpa nây mâu ƀư kan tâm ban ôh,$b$,false),
('bunong-vn','ROM',12,5,null,$b$tâm ban lĕ geh âk phung he, ƀiă lah jêng du săk jăn tâm Yêsu Krist, jêh ri lĕ rngôch he jêng jâng ti ndrăng phung he.$b$,false),
('bunong-vn','ROM',12,6,null,$b$Yor lah tĭng nâm nau yô̆ Kôranh Brah ăn jêh ma he, he geh nau ăn êng êng. Ma mbu nơm mbơh lor, ăn păng mbơh lor khư ma nau chroh.$b$,false),
('bunong-vn','ROM',12,7,null,$b$Ma mbu nơm bu dơi kuăl djôt kan, ăn păng gơih tâm kan păng; ma mbu nơm sâm tâm ntĭm nti, ăn gơih sâm nti,$b$,false),
('bunong-vn','ROM',12,8,null,$b$ma mbu nơm, nơm nti, gŭ nti mro; ma mbu nơm ăn yô̆, ăn ma nuih n'hâm lŏng; ma mbu nơm chiă uănh, chiă uănh ăn ueh; ma mbu nơm ƀư nau yô̆, ăn păng ƀư ma nau maak.$b$,false),
('bunong-vn','ROM',12,9,null,$b$Ăn nau rŏng khân may jêng ngăn, tâm rmot ma nau mhĭk, rŏng ktang ma nau ueh.$b$,true),
('bunong-vn','ROM',12,10,null,$b$Ăn khân may tâm rŏng tâm êp ndrăng khân may tâm ban ma oh nâu; ăn khân may geh nau yơk ndrăng khân may.$b$,true),
('bunong-vn','ROM',12,11,null,$b$Ăn khân may gơih, lơi ƀlao ôh, ăn geh n'hâm suan mĭn gơih nđơr; pah kan hom ma Kôranh Brah.$b$,false),
('bunong-vn','ROM',12,12,null,$b$Gŭ maak hom tâm nau kâp gân, ăn khân may srôih tâm nau rêh ni, ăn mbơh sơm ƀa ƀơ.$b$,false),
('bunong-vn','ROM',12,13,null,$b$Ăn ma phung kloh ueh ndơ khân păng pưt, ăn may blau rom bu.$b$,false),
('bunong-vn','ROM',12,14,null,$b$Mât ton nau yô̆ ma mbu nơm ƀư mhĭk ma khân may, mât ton nau ueh jêh ri lơi rtăp rak bu.$b$,false),
('bunong-vn','ROM',12,15,null,$b$Maak hom khân may đah phung geh nau maak, nhĭm ndrel ma phung nhĭm,$b$,true),
('bunong-vn','ROM',12,16,null,$b$Ăn geh du nuih n'hâm mĭn ndrăng khân may, lơi mĭn nau n'hao prêh ôh, ƀiă lah ăn mĭn ma nau dêh rhêt. Lơi ta kơp khân may nơm jêng bunuyh blau mĭn.$b$,false),
('bunong-vn','ROM',12,17,null,$b$Lơi mplơ̆ nau tih mhĭk ma nau tih mhĭk bu ôh. Joi hom nau ueh ta năp lĕ rngôch bunuyh.$b$,false),
('bunong-vn','ROM',12,18,null,$b$Tơ lah dơi, tĭng nâm khân may dơi, ăn gŭ đăp mpăn đah lĕ rngôch bunuyh.$b$,false),
('bunong-vn','ROM',12,19,null,$b$Hơi phung gâp rŏng ơi, lơi tâm plơng ndrăng khân may nơm ƀiă lah ăn ma nau Brah Ndu ji nuih. Yor lah geh nau nchih jêh: “Ma gâp yơh nau plơng bôk. Gâp yơh mra ăn nau khư, Kôranh Brah lah”,$b$,false),
('bunong-vn','ROM',12,20,null,$b$Ƀiă lah “tơ lah nơm rlăng đah khân may ji ngot, ăn khân păng sông sa; tơ lah khân păng ji hir, ăn khân păng nhêt; yor lah dôl ƀư pô nây, khân may mra ndô rnga ŭnh ta klơ bôk khân păng.”$b$,false),
('bunong-vn','ROM',12,21,null,$b$Lơi ăn nau mhĭk dơi đah may, ƀiă lah ăn nau ueh dơi đah nau mhĭk.$b$,true),
('bunong-vn','ROM',13,1,null,$b$Ăn lĕ rngôch bunuyh tông ma kôranh chiă uănh, yor lah mâu geh ôh nau dơi chiă uănh mâu luh tă bơh Brah Ndu ăn jêh ri nau dơi chiă uănh Brah Ndu da dê njêng.$b$,true),
('bunong-vn','ROM',13,2,null,$b$Yor nây mbu nơm tâm rdâng ma nau chiă uănh, nơm nây yơh tâm rdâng đah nau Brah Ndu njêng, jêh ri mbu nơm rdâng mra dơn nau tâm rmal ma păng nơm,$b$,false),
('bunong-vn','ROM',13,3,null,$b$mâu di phung ƀư ueh ôh klach ma phung chiă uănh, ƀiă lah phung ƀư mhĭk. May ŭch lĕ mâu klach ma nau chiă uănh? Ƀư hom nau ueh jêh ri may mra geh nau tâm rnê.$b$,false),
('bunong-vn','ROM',13,4,null,$b$Yor lah kôranh chiă uănh jêng oh mon ma Brah Ndu ŭch ƀư ueh ma khân may. Ƀiă lah tơ lah may ƀư nau mhĭk, klach hom, yor lah mâu di ôh klach dơm păng djôt đao gưm (đao dao ); yor lah păng jêng oh mon ma Brah Ndu gay ma rmal mbu nơm ƀư mhĭk.$b$,true),
('bunong-vn','ROM',13,5,null,$b$Pô ri, khlay ngăn ma nau tông bâr mâu di knŏng yor klach ma nau tâm rmal ôh, ƀiă lah yor nuih n'hâm sŏng khân may.$b$,false),
('bunong-vn','ROM',13,6,null,$b$Yor nây lĕ khân may chê̆ pi, yor lah phung kôranh chiă uănh jêng phung oh mon Brah Ndu, djôt kan nây mro.$b$,true),
('bunong-vn','ROM',13,7,null,$b$Trok lơi lĕ rnon may iang, chê̆ hom pi ma mbu nơm hăn riu, chŭng hom ma mbu nơm ŭch tâm chŭng, klach ma nơm khư khân may klach, yơk ma nơm khư khân may yơk.$b$,false),
('bunong-vn','ROM',13,8,null,$b$Lơi ƀư iang rnon đah bu ôh, knŏng tâm iang nau rŏng ndrăng phung khân may yor lah mbu nơm rŏng ma phung êng jêng di jêh đah nau vay.$b$,true),
('bunong-vn','ROM',13,9,null,$b$Nau vay nây pô aơ: “Ver, lơi ta khân may văng tĭr ôh, lơi ta nkhĭt bunuyh ôh, lơi ta sŏk ntŭng ndô ndơ bu ôh, lơi ta kơnh ôh.” Jêh ri lĕ rngôch nau vay êng ngơi trăch jêh tâm nau aơ: “Ăn may rŏng ma bu, tâm ban ma may rŏng ma may nơm.”$b$,false),
('bunong-vn','ROM',13,10,null,$b$Nau rŏng mâu mâp ƀư mhĭk ma bu ôh; pô ri nau rŏng jêng di jêh đah nau vay.$b$,false),
('bunong-vn','ROM',13,11,null,$b$Pô ri, khân may gĭt ma rnôk he gŭ, tât jêh mông khân may kah rngăl bêch, yor lah aƀaơ nau tâm rklaih dăch lơn đah nar he mhe chroh.$b$,true),
('bunong-vn','ROM',13,12,null,$b$Măng dăch lĕ, nar dăch ang, he doh mƀăr lơi hom kan nau ngo, jêh ri nsoh ao nau tâm lơh bơh nau ang,$b$,false),
('bunong-vn','ROM',13,13,null,$b$Hăn hom he ma nau sŏng srăng nâm bu hôm e nar; lơi rlau rnâng mâu lah nhŭl ndrănh ôh, lơi văng tĭr mâu lah ƀư blă blơ ôh, lơi tâm jin mâu lah mâu nach ôh.$b$,false),
('bunong-vn','ROM',13,14,null,$b$Ƀiă lah ăn khân may soh hom Kôranh Brah Yêsu Krist, jêh ri lơi chrê ôh ma nglay săk, gay maak ma nau păng kơnh.$b$,false),
('bunong-vn','ROM',14,1,null,$b$Khân may rom hom mbu nơm rdja tâm nau chroh. Lơi tâm rlăch yor nau mĭn êng êng.$b$,true),
('bunong-vn','ROM',14,2,null,$b$Du huê mĭn dơi sa lĕ rngôch ndơ, du huê nơm êng rdja sa knŏng trao dơm.$b$,false),
('bunong-vn','ROM',14,3,null,$b$Mbu nơm sa lơi tâm rmot ôh ma nơm mâu geh sa, jêh ri mbu nơm mâu geh sa, lơi phat dôih ôh ma nơm sa. Yor lah Brah Ndu rom păng jêh.$b$,false),
('bunong-vn','ROM',14,4,null,$b$Mâm ƀư may janh phat dôih oh mon bu? Tơ lah păng gŭ rjăp mâu lah prah lŭp nau nây bơh kôranh păng nơm. Ƀiă lah păng mra gŭ rjăp yor lah Kôranh Brah geh nau brah dơi ăn păng gŭ rjăp.$b$,false),
('bunong-vn','ROM',14,5,null,$b$Du huê mĭn, geh nar ueh lơn ma nar êng, du huê êng mĭn lĕ rngôch nar tâm ban da dê. Ăn ăp nơm gĭt rah vah tâm nau păng mĭn.$b$,false),
('bunong-vn','ROM',14,6,null,$b$Mbu nơm prăp yơk nar ƀư pô nây yor Kôranh Brah. Jêh ri mbu nơm sa, păng sa yor Kôranh Brah, yor lah păng lah ueh ma Brah Ndu; tâm ban lĕ mbu nơm mâu sa păng mâu sa yor Kôranh Brah lĕ, ăt păng lah ueh ma Brah Ndu.$b$,false),
('bunong-vn','ROM',14,7,null,$b$Yor lah mâu geh du huê tâm phung he gŭ rêh yor păng nơm.$b$,true),
('bunong-vn','ROM',14,8,null,$b$Pô ri, tơ lah he gŭ rêh, he rêh yor Kôranh Brah pô ri, tơ lah hĕ khĭt, he khĭt yor Kôranh Brah lĕ, pô ri tơ lah he gŭ rêh mâu lah khĭt ăt yor Kôranh Brah lĕ.$b$,false),
('bunong-vn','ROM',14,9,null,$b$Yor ma nau nây yơh Brah Krist khĭt jêh ri dâk rêh, gay ma păng dơi jêng Kôranh Brah ma phung khĭt nđâp ma phung rêh.$b$,false),
('bunong-vn','ROM',14,10,null,$b$Ƀiă lah may, mâm ƀư may phat dôih oh nâu may? Mâu lah mâm ƀư may rmot ma oh nâu may? Yor lah lĕ rngôch he mra gŭ ta năp nau Brah Ndu phat dôih.$b$,false),
('bunong-vn','ROM',14,11,null,$b$Yor lah bu nchih jêh pô aơ: “Kôranh Brah lah: Gâp jêng nơm rêh lĕ rngôch mra chon kômâk ta năp gâp. Jêh ri lĕ rngôch mpiăt mra yơk tâm rnê ma Brah Ndu.”$b$,false),
('bunong-vn','ROM',14,12,null,$b$Pô ri ăp nơm phung he mra mbơh kan păng nơm ƀư ta năp Brah Ndu.$b$,true),
('bunong-vn','ROM',14,13,null,$b$Pô ri, lơi hôm tâm phat dôih ndrăng he nơm ôh, ƀiă lah ueh lơn mĭn pô aơ, lơi ăn oh nâu khân may geh chêh jâng ma lŭ mâu lah lơi ƀư nau tŭp khân păng.$b$,true),
('bunong-vn','ROM',14,14,null,$b$Gâp gĭt, Kôranh Brah Yêsu ăn gâp gĭt rah vah, mâu geh ndơ jêng ƀơ̆ êng Păng nơm ôh; ƀiă lah mbu nơm mĭn ma ndơ nây jêng ƀơ̆ , păng jêng ƀơ̆ ma nơm nây.$b$,false),
('bunong-vn','ROM',14,15,null,$b$Ƀiă lah tơ lah ndơ may sa ƀư rngot ma phung oh nâu may, may mâu hôm hăn di tĭng nâm nau rŏng ôh. Yor ndơ may sông sa lơi ƀư roh du huê ôh. Brah Krist khĭt jêh yor păng.$b$,false),
('bunong-vn','ROM',14,16,null,$b$Lơi ăn nau may dơi ƀư nây jêng nau bu dơi nduyh may.$b$,false),
('bunong-vn','ROM',14,17,null,$b$Yor lah ƀon bri hađăch Brah Ndu mâu di ndơ sông sa nhêt ôh, ƀiă lah nau sŏng, nau đăp mpăn jêh ri nau răm maak tâm Brah Huêng Ueh.$b$,true),
('bunong-vn','ROM',14,18,null,$b$Mbu nơm pah kan ma Brah Krist tâm ban pô nây ƀư maak ma Brah Ndu, jêh ri bunuyh dơn nau păng ƀư.$b$,false),
('bunong-vn','ROM',14,19,null,$b$Pô nây yơh, ăn he tĭng joi nau dơi đăp mpăn jêh ri nau dơi n'hao nuih ndrăng phung he.$b$,false),
('bunong-vn','ROM',14,20,null,$b$Lơi ƀư rai ôh kan Brah Ndu yor ndơ sông sa. Nanê̆ lĕ ntil ndơ kloh da dê, ƀiă lah geh nau tih ma bunuyh tơ lah păng sa njêng nau chêh jâng bu.$b$,false),
('bunong-vn','ROM',14,21,null,$b$Ƀiă lah ueh lơn lơi sa puăch, lơi nhêt dak play kriăk ƀâu, mâu lah ƀư nau ƀa ƀă tơ lah nau nây ƀư tŭp oh nâu he.$b$,true),
('bunong-vn','ROM',14,22,null,$b$Nau chroh may hŏ geh jêh ăn may djôt prăp ma may nơm ta năp Brah Ndu, ueh maak yơh ma mbu nơm mâu phat dôih păng nơm tâm nau păng dơn.$b$,false),
('bunong-vn','ROM',14,23,null,$b$Ƀiă lah mbu nơm đing ma ndơ păng sa, geh nau tâm rmal, yor lah păng mâu sa ma nau chroh. Lĕ rngôch nau ƀư mâu luh bơh nau chroh jêng nau tih.$b$,false),
('bunong-vn','ROM',15,1,null,$b$Pô ri, he jêng phung nâp, vay anh nau rêh ni phung rdja jêh ri lơi ƀư maak ma he nơm ôh.$b$,true),
('bunong-vn','ROM',15,2,null,$b$Ăn ăp nơm tâm phung he ƀư maak, ma phung chiau meng he ma nau ueh, gay ma n'hao nuih khân păng.$b$,false),
('bunong-vn','ROM',15,3,null,$b$Yor lah Brah Krist mâu mâp ƀư maak ma păng nơm ƀiă lah tĭng nâm bu hŏ nchih jêh nau: “Nau suai rak bu ƀư ma may, tŭp jêh ta gâp.”$b$,false),
('bunong-vn','ROM',15,4,null,$b$Pô ri, lĕ nau bu nchih jêh lor jêng nau prăp sâm nti he, gay ma he geh nau kâp gân ma nau srôih, jêh ri nau leng he bơh nau nchih.$b$,false),
('bunong-vn','ROM',15,5,null,$b$Pô ri, dăn ma Brah Ndu, nơm srôih jêh ri nơm leng ăn ma khân may geh du nuih n'hâm tĭng nâm Yêsu Krist,$b$,false),
('bunong-vn','ROM',15,6,null,$b$gay ma lĕ rngôch ndrel n'grŭp du bâr, khân may tâm rnê ma Brah Ndu, Mbơ̆ Kôranh Brah he Yêsu Krist.$b$,false),
('bunong-vn','ROM',15,7,null,$b$Pô ri, tâm rom hom ndrăng khân may nơm, tâm ban ma Brah Krist rom jêh khân may, gay geh nau tâm rnê ma Brah Ndu.$b$,true),
('bunong-vn','ROM',15,8,null,$b$Gâp lah ma Brah Krist jêng jêh oh mon ma phung koh ntâu gay tâm mpơl nau Brah Ndu tâm êp ngăn jêh ri gay ma nanê̆ nau Păng ton jêh ma phung che he,$b$,true),
('bunong-vn','ROM',15,9,null,$b$jêh ri gay ma phung bu năch tâm rnê ma Brah Ndu yor nau Păng yô̆. Tĭng nâm nau nchih jêh: “Yor nây gâp mra tâm rnê ma may ta nklang phung bu năch jêh ri gâp mra mprơ mât ton ma amoh may.”$b$,false),
('bunong-vn','ROM',15,10,null,$b$Jêh ri geh nau nchih: “Hơi phung bu năch, maak hom khân may ndrel ma phung mpôl băl Păng.”$b$,true),
('bunong-vn','ROM',15,11,null,$b$Jêh ri lah: “Hơi lĕ rngôch phung bu năch, mât ton hom ma Kôranh Brah, tâm rnê hom ma Păng, hơi lĕ rngôch phung ƀon lan.$b$,true),
('bunong-vn','ROM',15,12,null,$b$Y-Êsai lah đŏng: “Mra geh bơh Y-Yêsê du nkeh, jêng Nơm chiă uănh phung bu năch, bu năch mra kâp gân Păng.”$b$,true),
('bunong-vn','ROM',15,13,null,$b$Pô ri, dăn ma Brah Ndu, nơm ăn nau kâp gân mbêng khân may ma lĕ nau maak jêh ri lĕ nau đăp mpăn tâm nau chroh gay ma nau brah Brah Huêng Ueh khân may geh nau rmeh ler tâm nau kâp gân.$b$,true),
('bunong-vn','ROM',15,14,null,$b$Hơi phung oh nâu, gâp mĭn khân may geh bêng jêh nau ueh, nau gĭt rbăng jêh ri dơi n'hao nuih ndrăng khân may nơm.$b$,true),
('bunong-vn','ROM',15,15,null,$b$Ƀiă lah gâp janh nchih ma khân may nau aơ ŭch kah gĭt ma khân may, yor nau yô̆ Brah Ndu ăn jêh ma gâp,$b$,true),
('bunong-vn','ROM',15,16,null,$b$njêng gâp jêng oh mon Yêsu Krist ma phung bu năch, prăp gâp ma kan mbơh nau mhe mhan ueh Brah Ndu, gay ma phung bu năch, jêh ƀư kloh ueh ma Brah Huêng Ueh, jêng ndơ nhhơr maak ma Brah Ndu.$b$,false),
('bunong-vn','ROM',15,17,null,$b$Pô nây yơh gâp geh nau rnê ma gâp nơm tâm Yêsu Krist yor nau Brah Ndu.$b$,true),
('bunong-vn','ROM',15,18,null,$b$Yor lah gâp mâu janh ngơi du ntil nau êng ma khân may tơ lah Brah Krist mâu đă gâp ƀư, gay njŭn leo phung bu năch ma nau tông ma nau ngơi jêh ri ma kan.$b$,true),
('bunong-vn','ROM',15,19,null,$b$Ma nau brah khlay ngăn jêh ri nau tâm mbên khlay ma nau brah Brah Huêng Ueh Brah Ndu, tă bơh ƀon Yêrusalem jêh ri n'gor chiau meng dăch tât ta ƀon Iliri, gâp nti âk jêh lam ri lam aơ nau mhe mhan ueh Yêsu Krist.$b$,false),
('bunong-vn','ROM',15,20,null,$b$Ƀiă lah gâp răm maak lơn mbơh nau mhe mhan ueh ta ntŭk bu ê mbơh ôh amoh Brah Krist gay ma mâu rdâk ôh ta ntur bu êng,$b$,false),
('bunong-vn','ROM',15,21,null,$b$tĭng nâm bu nchih jêh pô aơ: “Ma mbu nơm bu ê mâp mbơh, khân păng mra saơ, jêh ri ma mbu nơm tăng, khân păng mra gĭt rbăng.”$b$,false),
('bunong-vn','ROM',15,22,null,$b$Pô ri geh âk tơ̆ jêh geh nau buay gâp hăn khâl khân may.$b$,true),
('bunong-vn','ROM',15,23,null,$b$Ƀiă lah aƀaơ mâu hôm geh ôh nau kân gâp tâm ntŭk aơ, jêh ri bơh jŏ năm jêh gâp ŭch ngăn hăn khâl khân may.$b$,false),
('bunong-vn','ROM',15,24,null,$b$Tơ lah gâp hăn ta n'gor Êspanh gâp mra veh uănh khân may. Jêh gâp geh nau maak bar pe nar gŭ ndrel khân may, gay ma khân may njŭn leo gâp tă n'gor nây.$b$,false),
('bunong-vn','ROM',15,25,null,$b$Aƀaơ ri gâp hăn ta ƀon Yêrusalem, ŭch kơl phung kloh ueh.$b$,false),
('bunong-vn','ROM',15,26,null,$b$Yor lah phung kloh ueh tâm n'gor Masêđôn jêh ri n'gor Akai gay ma gâp hăn pă ndơ nhhơr kơl ma phung kloh ueh gŭ tâm nau rêh ni ta ƀon Yêrusalem.$b$,false),
('bunong-vn','ROM',15,27,null,$b$Khân păng rŏng ƀư pô nây jêh ri khân păng iang rnon phung nây lĕ, yor lah tơ lah phung bu năch geh ndrel ma khân păng ndơ khlay ma huêng vay khân păng kơl nhhơr ma phung Yuđa ndơ khlay ma săk jăn.$b$,false),
('bunong-vn','ROM',15,28,null,$b$Pô ri, jêh lôch kan aơ, jao ndơ nhhơr ma khân păng, gâp mra veh ta ƀon khân may, tơ lah gâp hăn ta n'gor Êspanh.$b$,false),
('bunong-vn','ROM',15,29,null,$b$Gâp gĭt, tơ lah gâp hăn ta khân may, gâp mra hăn bêng ma nau ueh uĭn bơh Brah Krist.$b$,false),
('bunong-vn','ROM',15,30,null,$b$Hơi phung oh nâu, ma Kôranh Brah he Yêsu Krist, jêh ri ma nau rŏng bơh Brah Huêng Ueh, gâp vơh vơl ma khân may, ăn khân may kơl tâm lơh ndrel ma gâp tâm nau khân may mbơh sơm ma Brah Ndu yor gâp,$b$,true),
('bunong-vn','ROM',15,31,null,$b$gay ma gâp dơi klaih bơh phung mâu chroh tâm n'gor Yuđa, jêh ri ndơ nhhơr gâp djôt ma ƀon Yêrusalem mra ƀư maak ma phung kloh ueh.$b$,false),
('bunong-vn','ROM',15,32,null,$b$Pô ri, yơh, gâp mra tât ta khân may ma nau răm maak tơ lah Brah Ndu ŭch, jêh ri gâp mra rlu tâm nklang phung khân may.$b$,false),
('bunong-vn','ROM',15,33,null,$b$Dăn ma Brah Ndu, nơm đăp mpăn gŭ ndrel lĕ rngôch khân may Amen.$b$,false),
('bunong-vn','ROM',16,1,null,$b$Gâp mbơh ăn khân may gĭt năl yuh he, H'Phêbê. Păng jêng kôranh ngih brah ta phung ngih Brah Ndu ƀon Sankrê.$b$,true),
('bunong-vn','ROM',16,2,null,$b$Ăn khân may rom păng tâm amoh Kôranh Brah he ma nau khư ma phung kloh ueh, jêh ri ăn khân may kơl păng tĭng nâm nau păng mra ŭch. Yor lah âk jêh bunuyh păng kơl, nđâp ma gâp tâm ban lĕ.$b$,true),
('bunong-vn','ROM',16,3,null,$b$Khâl đah H'Prisil jêh ri Y-Akilas phung pah kan ndrel ma gâp tâm Yêsu Krist.$b$,true),
('bunong-vn','ROM',16,4,null,$b$Khân păng sân săk jăn gay tâm rklaih nau rêh gâp. Mâu di knŏng êng gâp lah ueh ma khân păng, ƀiă lah lĕ rngôch phung ngih Brah Ndu tâm bri bu năch tâm ban lĕ.$b$,true),
('bunong-vn','ROM',16,5,null,$b$Khâl ma phung ngih Brah Ndu tâm rƀŭn tâm ngih khân păng tâm ban lĕ. Khâl đah Y-Êpaniet, nơm gâp rŏng. Păng jêng play lor lơn ma Brah Krist tâm n'gor Asi.$b$,true),
('bunong-vn','ROM',16,6,null,$b$Tâm khâl đah H'Mari nơm pah âk ngăn kan ma khân may.$b$,false),
('bunong-vn','ROM',16,7,null,$b$Khâl đah Y-Andrônikus jêh ri Y-Junias, phung băl gâp bu krŭng ndrel, khân păng geh lư n'găr âk tâm phung kôranh oh mon jêh ri khân păng chroh ma Brah Krist lor ma gâp lĕ.$b$,false),
('bunong-vn','ROM',16,8,null,$b$Khâl đah Y-Amplias, nơm gâp rŏng tâm Kôranh Brah.$b$,false),
('bunong-vn','ROM',16,9,null,$b$Khâl đah Y-Urban nơm pah kan ndrel ma gâp tâm Brah Krist, jêh ri Y-Stakis nơm gâp rŏng.$b$,true),
('bunong-vn','ROM',16,10,null,$b$Khâl đah Y-Apêlê nơm dơn jêh nau rlong uănh tâm Brah Krist khâl đah phung gŭ tâm ngih Y-Aristôbul.$b$,false),
('bunong-vn','ROM',16,11,null,$b$Khâl đah Y-Hêrôdion, du huê băl mpôl gâp khâl đah phung gŭ tâm ngih Y-Narsis, phung gŭ tâm Kôranh Brah.$b$,false),
('bunong-vn','ROM',16,12,null,$b$Khâl đah H'Triphen jêh ri H'Triphôs, phung pah kan ma Kôranh Brah. Khâl đah H'Pêrsit, nơm bu rŏng, nơm pah kan âk ma Kôranh Brah.$b$,false),
('bunong-vn','ROM',16,13,null,$b$Khâl đah Y-Ruphus nơm Kôranh Brah săch jêh ndrel ma mê̆ păng. Păng jêng mê̆ gâp lĕ.$b$,false),
('bunong-vn','ROM',16,14,null,$b$Khâl đah Y-Asun, Y-Phalêgôn, Y-Hêrmê, Y-Patrôbas, Y-Hêrmas, jêh ri phung oh nâu gŭ ndrel ma khân păng.$b$,true),
('bunong-vn','ROM',16,15,null,$b$Khâl đah Y-Philôlôgô jêh ri H'Juli, Y-Nêrê jêh ri ruh păng, Y-Ôlimpơ, jêh ri lĕ rngôch phung kloh ueh gŭ ndrel ma khân păng.$b$,false),
('bunong-vn','ROM',16,16,null,$b$Tâm khâl hom ndrăng khân may ma nau chŭm kloh. Lĕ rngôch phung ngih Brah Ndu Brah Krist khâl đah khân may.$b$,false),
('bunong-vn','ROM',16,17,null,$b$Hơi oh nâu, gâp vơh vơl ma khân may, njrăng hom ma mbu nơm ƀư nau tâm nkhah mpôl, jêh ri nau tŭp, mâu di ma nau nti lah khân may nti jêh. Trơn hom khân may ngai đah khân păng.$b$,true),
('bunong-vn','ROM',16,18,null,$b$Yor lah phung pô nây mâu pah kan ma Brah Krist, Kôranh Brah he ôh, ƀiă lah ma ndŭl khân păng nơm jêh ri ma bâr ra ai, ma nau hao kach khân păng ndơm nuih n'hâm bunuyh sŏng.$b$,false),
('bunong-vn','ROM',16,19,null,$b$Lĕ rngôch bunuyh gĭt jêh ma nau khân may tông bâr. Gâp maak yor nau khân may, ƀiă lah gâp ŭch ma khân may gĭt rbăng ma nau ueh jêh ri ăn kloh ma nau mhĭk.$b$,false),
('bunong-vn','ROM',16,20,null,$b$Brah Ndu, nơm đăp mpăn mra ƀư rai gơnh Satan tâm dâng jâng khân may, ăn nau yô̆ bơh Kôranh Brah he, Brah Yêsu, gŭ ndrel ma khân may.$b$,false),
('bunong-vn','ROM',16,21,null,$b$Y-Timôthê nơm pah kan ndrel ma gâp khâl đah khân may, Y-Lusius, Y-Yason jêh ri Y-Sôsipater phung băl gâp tâm ban lĕ.$b$,true),
('bunong-vn','ROM',16,22,null,$b$Gâp, Y-Tertius, nơm nchih Sămƀŭt aơ, khâl đah khân may tâm Kôranh Brah.$b$,false),
('bunong-vn','ROM',16,23,null,$b$Y-Gaius nơm rom gâp jêh ri rom lĕ rngôch phung ngih Brah Ndu khâl đah khân may, Y-Êrast, kôranh prăp prăk ƀon toyh, khâl đah khân may. Y-Kartus, nâu he, tâm khâl đah khân may tâm ban lĕ.$b$,true),
('bunong-vn','ROM',16,24,null,$b$Ăn nau yô̆ bơh Kôranh Brah he, Yêsu Krist gŭ ndrel ma khân may lĕ rngôch. Amen.$b$,false),
('bunong-vn','ROM',16,25,null,$b$Ma nơm dơi ăn khân may gŭ nâp tĭng nâm nau mhe mhan ueh gâp, jêh ri ma nau nti lah ma Yêsu Krist, tĭng nâm nau tâm mpơl nau khlay ndâp, pôn jêh tâm lĕ rngôch rnôk lor,$b$,true),
('bunong-vn','ROM',16,26,null,$b$ƀiă lah aƀaơ mpơl jêh yor nau phung kôranh nơm mbơh lor nchih jêh tĭng nâm nau Brah Ndu, nơm rêh n'ho ro ntăm, jêh ri ăn lĕ rngôch mpôl băl bunuyh gĭt jêh ri tông ma nau chroh.$b$,false),
('bunong-vn','ROM',16,27,null,$b$Ma Brah Ndu, knŏng êng păng blau mĭn geh nau chrêk rmah tâm lĕ rngôch rnôk tâm amoh Yêsu Krist! Amen.$b$,false);
