insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', '1CO', $b$I Kôrintô$b$, $b$["Sămƀŭt Rơh Nguay Y-Pôl Njuăl Ma Phung", "KÔRINTÔ"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','1CO',1,1,null,$b$Y-Pôl, bunuyh Brah Ndu kuăl, tĭng nâm Păng ŭch ăn jêng kôranh oh mon Yêsu Krist jêh ri nâu he, Y-Sôsthen.$b$,true),
('bunong-vn','1CO',1,2,null,$b$Nchih njuăl ma phung ngih Brah Ndu ta ƀon Kôrintô, ma phung jêng kloh ueh jêh tâm Yêsu Krist, phung Brah Ndu kuăl jêh ăn jêng kloh ueh nđâp ma lĕ rngôch phung gŭ lam ntŭk mbơh sơm ma amoh Kôranh Brah he, Yêsu Krist, Kôranh Brah khân păng, jêh ri Kôranh Brah he:$b$,false),
('bunong-vn','1CO',1,3,null,$b$Ăn khân may geh nau yô̆ jêh ri nau đăp mpăn, bơh Brah Ndu, Mbơ̆ he, jêh ri bơh Kôranh Brah he, Yêsu Krist.$b$,false),
('bunong-vn','1CO',1,4,null,$b$Gâp tâm rnê ma Brah Ndu mro yor khân may, yor lah Păng ăn ma khân may nau yô̆ tâm Yêsu Krist.$b$,true),
('bunong-vn','1CO',1,5,null,$b$Yor lah tâm Păng khân may bêng jêh ma lĕ nau ndrŏng tâm nau ngơi jêh ri tâm nau gĭt rbăng,$b$,false),
('bunong-vn','1CO',1,6,null,$b$tât nau bu mbơh ma Yêsu Krist gŭ rjăp jêh tâm phung khân may.$b$,false),
('bunong-vn','1CO',1,7,null,$b$Pô ri khân may mâu pưt ôh du ntil ndơ Brah Huêng Ueh ăn, dôl khân may gŭ kâp nau Kôranh Brah he, Yêsu Krist, mra tâm mpơl.$b$,false),
('bunong-vn','1CO',1,8,null,$b$Păng mra ăn nâp khân may tât dăch lôch, gay ma khân may mâu geh nau dơi nduyh ta nar Kôranh Brah he, Yêsu Krist.$b$,false),
('bunong-vn','1CO',1,9,null,$b$Brah Ndu jêng răp jăp ngăn Nơm kuăl jêh khân may ma nau tâm rnglăp đah Kon Păng, Yêsu Krist, Kôranh Brah he.$b$,false),
('bunong-vn','1CO',1,10,null,$b$Gâp vơh vơl ma khân may, hơi phung oh nâu, ma amoh Kôranh Brah he Yêsu Krist, ăn lĕ rngôch khân may ngơi nau tâm ban, jêh ri lơi ăn geh nau tâm pă ôh ndrăng khân may, ƀiă lah ăn geh nau tâm rnglăp nanê̆ tâm du nau mĭn jêh ri du ai nau.$b$,true),
('bunong-vn','1CO',1,11,null,$b$Hơi phung oh nâu, yor lah phung bơh ngih Y-Klôê mbơh jêh ma gâp ma phung khân may geh nau tâm jin.$b$,false),
('bunong-vn','1CO',1,12,null,$b$Gâp ŭch rblang ma ăp nơm khân may lah pô aơ: “Gâp tĭng Y-Pôl”, jêh ri: “Gâp tĭng Y-Apôlôs,” jêh ri: “Gâp tĭng Y-Sêphas,” jêh ri: “Gâp tĭng Brah Krist”.$b$,false),
('bunong-vn','1CO',1,13,null,$b$Di lĕ bu hŏ tâm nkhah jêh Brah Krist? Di đŏng Y-Pôl bu pâng ta si tâm rkăng yor khân may? Mâu lah ma amoh Y-Pôl lĕ bu dơn nau ƀaptem?$b$,false),
('bunong-vn','1CO',1,14,null,$b$Gâp tâm rnê ma Brah Ndu yor lah gâp mâu mâp ƀư ƀaptem ma du huê tâm phung khân may ôh, knŏng ma Y-Krispus jêh ri Y-Gaius yơh.$b$,false),
('bunong-vn','1CO',1,15,null,$b$Pô ri, mâu geh bunuyh dơi lah ma khân may dơn jêh nau ƀaptem ma amoh gâp.$b$,false),
('bunong-vn','1CO',1,16,null,$b$Gâp ƀư ƀaptem jêh lĕ ma mpôl băl Y-Stêphanus. Jêh ri gâp mâu gĭt ôh tơ lah gâp ƀư jêh ƀaptem ma du huê êng.$b$,false),
('bunong-vn','1CO',1,17,null,$b$Mâu di ma nau ƀư ƀaptem ôh, Brah Krist njuăl văch jêh gâp, ƀiă lah ăn mbơh nau mhe mhan ueh, jêh ri mâu di ma nau blau ngơi ôh, klach lah si tâm rkăng Brah Krist mra roh nau brah.$b$,false),
('bunong-vn','1CO',1,18,null,$b$Yor lah nau nti ma si tâm rkăng jêng nau rluk ma phung ntơm rai yot, ƀiă lah păng jêng nau brah, Brah Ndu ma he, phung tâm rklaih jêh.$b$,true),
('bunong-vn','1CO',1,19,null,$b$Yor lah geh nau nchih jêh pô aơ: “Gâp mra ƀư rai nau mĭn phung blau mĭn. Jêh ri gâp mra ƀư roh nau gĭt rbăng, phung gĭt rbăng”.$b$,false),
('bunong-vn','1CO',1,20,null,$b$Bunuyh blau mĭn mbah ntŭk? Kôranh nchih sămƀŭt mbah ntŭk? Nơm blau tâm rlăch rnôk aơ mbah ntŭk? Mâu di hĕ Brah Ndu kơp nau blau mĭn phung neh ntu jêng nau rluk?$b$,true),
('bunong-vn','1CO',1,21,null,$b$Yor Brah Ndu tă tâm nau blau mĭn Păng, hŏ ƀư ma neh ntu mâu dơi dŏng nau blau mĭn êng păng nơm gay gĭt vât nau Păng, yor ri Brah Ndu maak dŏng nau nti lah bu uănh ma hên jêng rluk, gay tâm rklaih phung chroh.$b$,false),
('bunong-vn','1CO',1,22,null,$b$Dôl phung Yuđa joi nau khlay jêh ri phung Grek joi nau blau mĭn.$b$,false),
('bunong-vn','1CO',1,23,null,$b$Bi hên nti Brah Krist khĭt jêh ta si tâm rkăng. Păng jêng nau ƀư chêh jâng ma phung Yuđa jêh ri nau rluk ma phung bu năch,$b$,false),
('bunong-vn','1CO',1,24,null,$b$ƀiă lah Păng jêng nau brah Brah Ndu jêh ri nau blau mĭn Brah Ndu ma lĕ rngôch phung Brah Ndu kuăl jêh, nđâp ma phung Yuđa, nđâp phung Grek.$b$,false),
('bunong-vn','1CO',1,25,null,$b$Yor lah nau bu uănh nâm bu nau rluk Brah Ndu jêng nau blau mĭn lơn ma kon bunuyh, jêh ri nau bu uănh nâm bu nau huơi Brah Ndu jêng ktang lơn ma kon bunuyh.$b$,false),
('bunong-vn','1CO',1,26,null,$b$Hơi oh nâu, ăn khân may rvê mĭn dôl Brah Ndu kuăl, tâm phung khân may mâu geh âk phung blau mĭn kơt nâm bu kon bunuyh, mâu geh âk phung ktang ôh, mâu lĕ geh âk phung ndrŏng.$b$,true),
('bunong-vn','1CO',1,27,null,$b$Ƀiă lah Brah Ndu hŏ săch ndơ rluk neh ntu gay ma bêk phung blau mĭn, Brah Ndu săch jêh ndơ huơi neh ntu gay ma bêk phung ktang,$b$,false),
('bunong-vn','1CO',1,28,null,$b$jêh ri Brah Ndu săch jêh ndơ mâu khlay neh ntu jêh ri ndơ bu rmot, ndơ mâu jêng, gay ma njêng dơm dam ndơ jêng jêh.$b$,false),
('bunong-vn','1CO',1,29,null,$b$Pô ri lơi geh bunuyh tâm rnê ma păng nơm ta năp Brah Ndu.$b$,false),
('bunong-vn','1CO',1,30,null,$b$Yor Păng khân may gŭ jêh tâm Yêsu Krist. Brah Ndu ăn Păng jêng jêh ma he nau blau mĭn, nau sŏng, nau kloh ueh, jêh ri nau tâm chuai.$b$,false),
('bunong-vn','1CO',1,31,null,$b$Pô ri, tâm ban ma nau nchih jêh: “Mbu nơm rnê păng nơm ăn păng tâm rnê tâm Kôranh Brah”.$b$,false),
('bunong-vn','1CO',2,1,null,$b$Hơi phung oh nâu, tơ lah gâp hăn jêh ma khân may, mâu di gâp hăn mbơh ma khân may nau Brah Ndu ma nau blau ngơi mâu lah ma nau blau mĭn ôh.$b$,true),
('bunong-vn','1CO',2,2,null,$b$Yor lah gâp mĭn mâu ŭch gĭt ndơ êng ôh tâm phung khân may knŏng Yêsu Krist, jêh ri Yêsu Krist khĭt ta si tâm rkăng.$b$,false),
('bunong-vn','1CO',2,3,null,$b$Ta năp khân may gâp jêng huơi, geh nau klach jêh ri sâr săk jăn ngăn,$b$,false),
('bunong-vn','1CO',2,4,null,$b$nau gâp ngơi, nau gâp nti lah mâu nsing ma nau blau ngơi bơh nau blau mĭn ôh, ƀiă lah bơh nau Brah Huêng Ueh tâm mpơl jêh ri ma nau brah păng,$b$,false),
('bunong-vn','1CO',2,5,null,$b$gay ma nau chroh khân may mra rdâk mâu di ta klơ nau blau mĭn bunuyh ôh, ƀiă lah ta klơ nau brah Brah Ndu.$b$,false),
('bunong-vn','1CO',2,6,null,$b$Nanê̆ hên nti nau blau mĭn ma phung jêng rah vah jêh, ƀiă lah nau blau mĭn mâu di bơh neh ntu aơ ôh, mâu lĕ tă bơh phung kôranh neh ntu, yor lah khân păng mra rai yot.$b$,true),
('bunong-vn','1CO',2,7,null,$b$Ƀiă lah hên nti nau blau mĭn Brah Ndu, khlay jêh ri nđâp, nau blau mĭn nây Brah Ndu săch prăp jêh ma nau chrêk rmah he bơh lor lĕ rngôch rnôk.$b$,false),
('bunong-vn','1CO',2,8,null,$b$Mâu geh du huê tâm phung kôranh neh ntu aơ mâp gĭt năl nau blau mĭn nây; yor lah tơ lah khân păng gĭt năl jêh nau nây; khân păng mâu mra nkhĭt Kôranh Brah nau chrêk rmah ta si tâm rkăng ôh.$b$,false),
('bunong-vn','1CO',2,9,null,$b$Ƀiă lah tâm ban ma nau nchih jêh: “Ndơ măt mâu mâp saơ, tôr mâu mâp tăng. Jêh ri mâu lĕ mâp vât gĭt tâm nuih n'hâm bunuyh ndơ Brah Ndu prăp ăn jêh ma phung rŏng ma păng”.$b$,false),
('bunong-vn','1CO',2,10,null,$b$Ƀiă lah Brah Ndu tâm mpơl jêh ma he ndơ nây ma Brah Huêng Ueh, yor lah Brah Huêng Ueh sek lĕ, nđâp ma nau jru Brah Ndu.$b$,true),
('bunong-vn','1CO',2,11,null,$b$Yor lah mbu nơm gĭt nau mĭn bunuyh? Knŏng huêng păng nơm gŭ tâm păng yơh. Tâm ban lĕ, mâu geh nơm gĭt năl nau mĭn Brah Ndu ôh, knŏng Brah Huêng Ueh Brah Ndu yơh.$b$,false),
('bunong-vn','1CO',2,12,null,$b$Ƀiă lah he mâu sŏk dơn ôh nau mĭn bơh neh ntu, ƀiă lah Brah Huêng Ueh bơh Brah Ndu pô ri mơ he dơi gĭt rbăng ndơ Brah Ndu ăn ma he ma nau păng yô̆.$b$,false),
('bunong-vn','1CO',2,13,null,$b$Jêh ri hên ngơi nau nây mâu di ma nau ngơi luh bơh nau blau mĭn bunuyh nti ôh, ƀiă lah luh tă bơh Brah Huêng Ueh nti. Hên rblang nau ngăn brah ma nau ngơi brah.$b$,false),
('bunong-vn','1CO',2,14,null,$b$Bunuyh tĭng nâm nglay săk mâu sŏk dơn ôh ndơ tă bơh Brah Huêng Ueh Brah Ndu, yor lah ndơ nây jêng nau rluk ma păng, jêh ri păng mâu gĭt vât ôh, yor lah ma nau mĭn brah yơh bu dơi sek uănh lĕ rngôch ndơ nây.$b$,false),
('bunong-vn','1CO',2,15,null,$b$Bunuyh brah sek uănh lĕ rngôch ndơ, ƀiă lah mâu geh nơm dơi sek uănh păng ôh.$b$,false),
('bunong-vn','1CO',2,16,null,$b$“Yor lah mbu nơm gĭt năl jêh nau mĭn Kôranh Brah, ŭch sâm nti Păng? Ƀiă lah hên geh nau mĭn Brah Krist.$b$,true),
('bunong-vn','1CO',3,1,null,$b$Hơi phung oh nâu, mâu di tâm ban ma bunuyh brah, gâp dơi ngơi ma khân may, ƀiă lah bunuyh tĭng nâm nglay săk nâm bu phung kon jê̆ tâm Brah Krist.$b$,true),
('bunong-vn','1CO',3,2,null,$b$Gâp siăm jêh khân may ma dak toh, mâu di ma ndơ sa dăng ôh. Yor lah khân may mâu dơi dơn ndơ nây ôh; jêh ri nđâp aƀaơ aơ khân may mâu dơi dơn lĕ.$b$,true),
('bunong-vn','1CO',3,3,null,$b$Yor lah khân may ăt jêng phung tĭng nâm nglay săk. Tơ lah geh tâm phung khân may nau mâu nach jêh ri nau tâm jin, mâu di hĕ khân may tĭng nâm nglay săk, jêh ri hăn tĭng nâm bunuyh hĕ?$b$,false),
('bunong-vn','1CO',3,4,null,$b$Tơ lah du huê lah: “Gâp tĭng Y-Pôl”, jêh ri du huê êng: “Gâp tĭng Y-Apôlôs,” mâu di hĕ khân may knŏng jêng bunuyh?$b$,false),
('bunong-vn','1CO',3,5,null,$b$Mbu nơm jêng Y-Apôlôs? Jêh ri mbu jêng Y-Pôl? Khân păng jêng oh mon. Yor khân păng yơh khân may chroh jêh tĭng nâm Kôranh Brah ăn jêh ma ăp nơm.$b$,false),
('bunong-vn','1CO',3,6,null,$b$Gâp tăm jêh, Y-Apôlôs djrah dak jêh, ƀiă lah Brah Ndu ăn hon.$b$,true),
('bunong-vn','1CO',3,7,null,$b$Pô ri, mâu di nơm tăm mâu lah nơm djrah dak ôh jêng khlay, ƀiă lah Brah Ndu, Nơm ăn hon.$b$,false),
('bunong-vn','1CO',3,8,null,$b$Nơm tăm jêh ri nơm djrah dak jêng tâm ban, ƀiă lah ăp nơm mra sŏk dơn nau nkhôm păng tĭng nâm kan păng pah.$b$,false),
('bunong-vn','1CO',3,9,null,$b$Yor lah hên jêng bunuyh pah kan ndrel ma Brah Ndu; khân may jêng mir lŏ Brah Ndu. Khân may jêng ngih Brah Ndu.$b$,false),
('bunong-vn','1CO',3,10,null,$b$Tĭng nâm nau Brah Ndu yô̆ an jêh ma gâp, gâp ƀư jêh ntur tâm ban ma du huê bunuyh ƀư ngih blau mĭn, jêh ri du huê êng ndâk ngih ta klơ ntur gâp ƀư jêh, ƀiă lah ăp nơm njrăng ma nau păng ndâk ta klơ ntur nây.$b$,true),
('bunong-vn','1CO',3,11,null,$b$Yor lah mâu geh bunuyh dơi ƀư ntur êng, knŏng ntur bu ƀư ơm, nâm bu ntĭt, Yêsu Krist.$b$,false),
('bunong-vn','1CO',3,12,null,$b$Tơ lah bu ƀư ngih ta klơ ntur nây ma mah, ma prăk, ma lŭ khlay, ma si, ma gơ̆ kro, ma rhe,$b$,false),
('bunong-vn','1CO',3,13,null,$b$kan ăp nơm mra tâm mpơl; yor lah nar bu ăn bu gĭt năl păng, ŭnh mra tâm mpơl păng, jêh ri ŭnh mra rlong uănh moh ntil kan ăp nơm ƀư jêh.$b$,false),
('bunong-vn','1CO',3,14,null,$b$Tơ lah kan ndâk jêh ta klơ ntur nây ăt hôm, păng mra sŏk dơn nau nkhôm.$b$,false),
('bunong-vn','1CO',3,15,null,$b$Tơ lah kan bu ƀư lĕ ŭnh sa lơi, păng mra roh nau nkhôm ma păng, bi păng nơm mra klaih ƀiă lah nâm bu luh tă bơh ŭnh.$b$,true),
('bunong-vn','1CO',3,16,null,$b$Khân may mâu gĭt hĕ khân may jêng ngih ma Brah Ndu, jêh ri Brah Huêng Ueh Brah Ndu gŭ tâm khân may?$b$,true),
('bunong-vn','1CO',3,17,null,$b$Tơ lah du huê ƀư rai ngih Brah Ndu, Brah Ndu mra ƀư rai păng, yor lah ngih ma Brah Ndu jêng kloh ueh, jêh ri khân may jêng ngih nây.$b$,false),
('bunong-vn','1CO',3,18,null,$b$Lơi ăn du huê ndơm păng nơm tơ lah du huê tâm phung khân may mĭn păng nơm jêng nơm blau mĭn tâm neh ntu aơ, ăn păng jêng rluk, gay ma păng mra blau mĭn.$b$,false),
('bunong-vn','1CO',3,19,null,$b$Yor lah nau blau mĭn neh ntu aơ jêng nau rluk ta năp Brah Ndu. Yor lah geh nau nchih jêh: “Păng sŏk phung blau mĭn tâm nau ƀlăch ƀlêr khân păng”,$b$,false),
('bunong-vn','1CO',3,20,null,$b$jêh ri: “Kôranh Brah gĭt năl nau mĭn phung blau mĭn mâu khlay ôh”.$b$,false),
('bunong-vn','1CO',3,21,null,$b$Pô ri, lơi ăn bu yơk ma bunuyh, yor lah lĕ rngôch mpa jêng ndơ khân may da dê.$b$,true),
('bunong-vn','1CO',3,22,null,$b$Gĭt lah Y-Pôl mâu lah Y-Apôlôs, Y-Sêphas, neh ntu, nau rêh, nau khĭt, ndơ nar aơ, mâu lah ndơ nar kăndơ̆ , lĕ rngôch jêng ndơ khân may da dê;$b$,true),
('bunong-vn','1CO',3,23,null,$b$jêh ri khân may jêng ndơ Brah Krist jêh ri Brah Krist jêng ndơ Brah Ndu.$b$,false),
('bunong-vn','1CO',4,1,null,$b$Pô ri, ăn bu uănh ma hên nâm bu oh mon Brah Krist jêh ri phung tâm pă nau khlay ndâp bơh Brah Ndu.$b$,true),
('bunong-vn','1CO',4,2,null,$b$Geh nau bu ŭch ma phung tâm pă, ăn ăp nơm khân păng jêng răp jăp.$b$,false),
('bunong-vn','1CO',4,3,null,$b$Bi ma gâp, mâu khlay âk ôh tơ lah khân may mâu lah phung phat dôih mra phat dôih gâp. Mâu lĕ gâp phat dôih gâp nơm.$b$,false),
('bunong-vn','1CO',4,4,null,$b$Yor lah gâp mâu saơ du ntil nau tih tâm gâp ôh, ƀiă lah mâu di ma nau nây ôh gâp geh jêh nau kơp sŏng. Nơm phat dôih gâp jêng Kôranh Brah yơh.$b$,false),
('bunong-vn','1CO',4,5,null,$b$Pô ri, lơi ngăch phat dôih lor ma nar mra tât, kŏ Kôranh Brah văch. Păng mra ƀư ang lĕ rngôch moh nau pôn jêh tâm ntŭk ngo jêh ri păng mra tâm mpơl nau nuih n'hâm bu ŭch. Dôl nây ăp nơm mra geh nau Brah Ndu tâm rnê khư ma păng.$b$,false),
('bunong-vn','1CO',4,6,null,$b$Hơi phung oh nâu, yor khân may gâp ƀư jêh nau tâm ntĭt aơ ma gâp nơm jêh ri ma Y-Apôlôs, gay ma khân may nti tâm hên mâu ƀư rlau lơn ma nau nchih jêh, jêh ri lơi ăn geh du huê tâm phung khân may ƀư nau sưr ôh đah du huê nơm êng.$b$,true),
('bunong-vn','1CO',4,7,null,$b$Yor lah mbu nơm njêng khân may êng đah phung ƀa ƀă? Moh ndơ khân may geh jêh ri khân may ê mâp sŏk dơn păng ôh? Jêh ri tơ lah khân may sŏk dơn jêh ndơ nây, mâm ƀư khân may tâm rnê ma khân may nơm, nâm bu khân may mâu mâp sŏk dơn ndơ nây?$b$,false),
('bunong-vn','1CO',4,8,null,$b$Khân may hơm jêh! Khân may jêng ndrŏng jêh! Mâu geh hên, khân may ntơm jêng kôranh chiă uănh jêh! Nanê̆ gâp ŭch ma khân may jêng kôranh chiă uănh, pô nây mơ hên dơi chiă uănh ndrel ma khân may lĕ!$b$,true),
('bunong-vn','1CO',4,9,null,$b$Yor lah gâp mĭn, Brah Ndu tâm mpơl hên, phung kôranh oh mon, jêng phung pa kơi lĕ rngôch bunuyh nâm bu phung bu prăp gay ma nkhĭt, yor lah hên jêng jêh ndơ neh ntu, phung Tông mpăr ueh Brah Ndu, jêh ri phung bunuyh uănh.$b$,false),
('bunong-vn','1CO',4,10,null,$b$Hên jêng rluk yor Brah Krist, ƀiă lah khân may jêng blau mĭn tâm Brah Krist. Hên jêng rdja ƀiă lah khân may jêng ktang. Bu yơk ma khân may, ƀiă lah hên geh nau bu rmot.$b$,true),
('bunong-vn','1CO',4,11,null,$b$N'ho ma aƀaơ aơ, hên dơn nau ji ngot, ji hir, bêch kuh rhôk, bu ƀư mhĭk ma hên, nsong mblêng ăp ntŭk,$b$,false),
('bunong-vn','1CO',4,12,null,$b$hên rgănh pah kan ma ti hên nơm. Bu suai rak, hên tâm rnê, bu ƀư mhĭk, hên dơn;$b$,false),
('bunong-vn','1CO',4,13,null,$b$bu nchơt, hên ngơi ma nau ueh; n'ho ma tât aƀaơ hên jêng nâm bu ndŏk neh ntu, ndơ lĕ rngôch bunuyh tâm rmot.$b$,false),
('bunong-vn','1CO',4,14,null,$b$Gâp mâu nchih nau nây gay ăn bêk khân may ôh, ƀiă lah gâp mbơh ma khân may tâm ban ma phung kon gâp rŏng ngăn ngên.$b$,true),
('bunong-vn','1CO',4,15,null,$b$Yor lah tơ lah khân may geh jât rbăn nuyh kôranh tâm Brah Krist, ƀiă lah khân may mâu geh âk mbơ̆ ôh. Yor lah gâp yơh deh khân may tâm Yêsu Krist ma nau mhe mhan ueh.$b$,false),
('bunong-vn','1CO',4,16,null,$b$Pô ri gâp vơh vơl ma khân may, ăn khân may jêng phung tĭng ndô̆ gâp.$b$,false),
('bunong-vn','1CO',4,17,null,$b$Yor nau nây yơh gâp njuăl jêh Y-Timôthê ma khân may. Păng jêng kon gâp rŏng ngăn ngên jêh ri răp jăp đah Kôranh Brah. Păng mra sâm kah gĭt ma khân may, Mâm ƀư gâp hăn tâm Brah Krist, Mâm ƀư gâp nti lah tâm lĕ rngôch phung ngih Brah Ndu.$b$,false),
('bunong-vn','1CO',4,18,null,$b$Geh ƀa ƀă bêng ma nau sưr, ntôn lah gâp mâu mra hăn ta khân may ôh.$b$,true),
('bunong-vn','1CO',4,19,null,$b$Ƀiă lah tơ lah Kôranh Brah ŭch, mâu ir jŏ gâp mra hăn ta khân may, jêh ri gâp mra joi mâu di knŏng nau ngơi phung sưr nây, ƀiă lah nau brah khân păng đŏng,$b$,false),
('bunong-vn','1CO',4,20,null,$b$yor lah ƀon bri hađăch Brah Ndu mâu di jêng tâm nau ngơi ôh, ƀiă lah tâm nau brah.$b$,false),
('bunong-vn','1CO',4,21,null,$b$Moh nau khân may ŭch? Ŭch gâp djôt mâng hăn dong khân may, mâu lah nau rŏng jêh ri nau rdơ̆ rbăn?$b$,false),
('bunong-vn','1CO',5,1,null,$b$Bu tăng lư ăp ntŭk geh nau văng tĭr tâm phung khân may. Nau văng tĭr tâm ban pô nây bu mâu saơ ôh tâm phung bu năch; Yor lah du huê tâm phung khân may tâm gŭ đah ur mbơ̆ păng.$b$,true),
('bunong-vn','1CO',5,2,null,$b$Jêh ri khân may bêng ma nau sưr! Ueh lơn khân may rngot ma nau nây, gay ma nơm ƀư tih nây bu mra tâm nkhah đah phung khân may.$b$,false),
('bunong-vn','1CO',5,3,null,$b$Gâp ndŭt kơi kđôi lĕ tâm săk jăn, ƀiă lah gâp gŭ ndrel ma khân may tâm huêng, jêh ri nâm bu gâp gŭ ndrel, gâp phat jêh dôih nơm ƀư tih nây.$b$,true),
('bunong-vn','1CO',5,4,null,$b$Tâm amoh Brah Yêsu, Kôranh Brah he, khân may jêh ri huêng gâp tâm rƀŭn ndrel ma nau brah Kôranh Brah he, Brah Yêsu,$b$,false),
('bunong-vn','1CO',5,5,null,$b$ăn jao hom du huê bunuyh ƀư pô nây ma brah Satan ƀư rai nglay săk păng, gay ma huêng păng dơi tâm rklaih nar Kôranh Brah Yêsu.$b$,false),
('bunong-vn','1CO',5,6,null,$b$Nau khân may rnê êng khân may nơm mâu ueh ôh, khân may mâu gĭt hĕ ndrui djê̆ lê̆ dơi ƀư ră rnih lĕ?$b$,true),
('bunong-vn','1CO',5,7,null,$b$Ăn kloh lơi ndrui ơm bơh khân may, ri mơ khân may dơi jêng rnih mhe, yor lah khân may mâu geh ndrui ôh. Yor lah Brah Krist, kon biăp Nau Găn he jêng jêh mpa ƀư brah.$b$,false),
('bunong-vn','1CO',5,8,null,$b$Pô ri, ăn he yơk ma nar maak nây, mâu di ma ndrui ơm ôh, mâu lĕ ma ndrui nau ndơm jêh ri ƀai ƀiă lah ma kapŭng mâu geh ndrui jêng nau kloh ueh jêh ri nau ngăn.$b$,false),
('bunong-vn','1CO',5,9,null,$b$Gâp nchih jêh sămƀŭt njuăl ma khân may, lơi ăn khân may tâm rnglăp đah phung văng tĭr ôh.$b$,true),
('bunong-vn','1CO',5,10,null,$b$Mâu di ma phung văng tĭr tâm neh ntu aơ, mâu lah phung rŏng ma prăk, mâu lah phung ntŭng, mâu lah phung mbah rup brah, tơ lah pô nây khân may mra luh bơh neh ntu yơh.$b$,false),
('bunong-vn','1CO',5,11,null,$b$Ƀiă lah gâp nchih jêh ma khân may, lơi tâm rnglăp ôh ma du huê bunuyh lah păng jêng oh nâu, ƀiă lah păng jêng bunuyh văng tĭr, mâu lah bunuyh rŏng ma prăk, mbah rup brah, dăng suai rak, nhŭl ndrănh mâu lah ntŭng, nchâp bu, mâu dơi sông sa ndrel lĕ ma bunuyh nâm nđĕ.$b$,false),
('bunong-vn','1CO',5,12,null,$b$Moh nau khlay ma gâp phat dôih phung pa dih? Mâu di hĕ ma phung tâm trôm ngih Brah Ndu khân may mra phat dôih?$b$,false),
('bunong-vn','1CO',5,13,null,$b$Bi ma phung pa dih, Brah Ndu mra phat dôih khân păng, “Nkhah lơi bunuyh tih bơh phung khân may.”$b$,false),
('bunong-vn','1CO',6,1,null,$b$Tơ lah du huê tâm phung khân may geh nau đah du huê oh nâu, mâm ƀư păng dơi janh ăn phung tih phat dôih nây, jêh ri mâu ăn ôh phung kloh ueh phat dôih?$b$,true),
('bunong-vn','1CO',6,2,null,$b$Khân may mâu gĭt hĕ phung kloh ueh yơh mra phat dôih neh ntu? Jêh ri khân may yơh mra phat dôih neh ntu, mâu khư hĕ khân may phat nau jê̆ jănh?$b$,true),
('bunong-vn','1CO',6,3,null,$b$Khân may mâu gĭt hĕ, he yơh mra phat dôih phung Tông mpăr ueh Brah Ndu? Nanê̆ he dơi phat dôih tâm nau rêh aơ!$b$,false),
('bunong-vn','1CO',6,4,null,$b$Jêh ri tơ lah khân may geh nau pô nây, mâm ƀư khân may njŭn leo nau nây ta năp phung bu mâu yơk tâm phung ngih Brah Ndu?$b$,false),
('bunong-vn','1CO',6,5,null,$b$Gâp lah pô nây gay ăn bêk khân may. Mâm ƀư mâu geh hĕ du huê tâm phung khân may blau mĭn dơi phat dôih ndrăng oh nâu păng,$b$,false),
('bunong-vn','1CO',6,6,null,$b$ƀiă lah du huê nâu phong oh păng ta năp phung mâu chroh?$b$,false),
('bunong-vn','1CO',6,7,null,$b$Pô ri, tih jêh phung khân may tâm geh nau ndrăng khân may. Mâm ƀư khân may mâu dơn nau bu ƀư kue? Mâm ƀư khân may mâu ăn bu rvan ndơ khân may?$b$,false),
('bunong-vn','1CO',6,8,null,$b$Ƀiă lah khân may yơh ƀư nau kue jêh ri pit rvan ndơ bu, jêh ri khân may ƀư pô nây ndrăng oh nâu.$b$,false),
('bunong-vn','1CO',6,9,null,$b$Khân may mâu gĭt hĕ phung kue mâu mra dơn ƀon bri hađăch Brah Ndu ôh? Lơi ta ndơm khân may nơm tâm nau aơ ôh; phung văng tĭr, phung mbah rup brah, phung tâm lâm, phung ƀư tâm ban ma bu ur, phung ƀơ̆ ƀơch,$b$,true),
('bunong-vn','1CO',6,10,null,$b$phung ntŭng, phung rŏng ma prăk, phung nhŭl ndrănh, phung dăng suai rak, phung nchâp ntŭng, mâu mra dơn ƀon bri hađăch Brah Ndu ôh.$b$,false),
('bunong-vn','1CO',6,11,null,$b$Ƀa ƀă tâm phung khân may jêng tâm ban pô nây yơh kăl e. Ƀiă lah aƀaơ aơ bu rao jêh khân may, khân may jêng kloh ueh jêh, geh nau kơp sŏng jêh tâm amoh Yêsu Krist jêh ri ma Brah Huêng Ueh Brah Ndu he.$b$,false),
('bunong-vn','1CO',6,12,null,$b$Lĕ rngôch ndơ gâp dơi ƀư, ƀiă lah lĕ rngôch mâu khlay ôh. Lĕ rngôch gâp dơi ƀư, ƀiă lah gâp mâu ŭch jêng dĭk ma du ntil ndơ ôh.$b$,true),
('bunong-vn','1CO',6,13,null,$b$“Ndơ sông sa prăp ma ndŭl jêh ri ndŭl prăp ma ndơ sông sa” jêh ri Brah Ndu mra ƀư rai lĕ bar. Ƀiă lah săk jăn mâu geh prăp ma nau văng tĭr ôh, săk jăn prăp ma Kôranh Brah jêh ri Kôranh Brah ma săk jăn.$b$,false),
('bunong-vn','1CO',6,14,null,$b$Jêh ri, Brah Ndu, nơm hŏ rdâk rêh jêh Kôranh Brah, mra rdâk rêh he tâm ban lĕ, ma nau brah păng.$b$,false),
('bunong-vn','1CO',6,15,null,$b$Khân may mâu gĭt hĕ săk jăn khân may jêng jâng ti Brah Krist? Jêh ri dơi lĕ dŏng jâng ti Brah Krist gay njêng jâng ti du huê bu ur văng tĭr? Mâu geh ôh!$b$,false),
('bunong-vn','1CO',6,16,null,$b$Khân may mâu gĭt hĕ ma mbu nơm tâm rnglăp đah bu ur văng tĭr jêng du nglay săk jêh đah păng? Yor lah geh nau nchih jêh pô aơ: “Phung bar hê nây mra jêng du nglay săk”.$b$,false),
('bunong-vn','1CO',6,17,null,$b$Ƀiă lah mbu nơm tâm rnglăp đah Kôranh Brah mra jêng du huêng ndrel ma păng.$b$,true),
('bunong-vn','1CO',6,18,null,$b$Du hom đah nau văng tĭr. Lĕ rngôch nau tih êng, du huê bunuyh ƀư, nau tih nây pa dih săk jăn; ƀiă lah mbu ƀư nau văng tĭr ƀư tih ma săk jăn păng nơm.$b$,true),
('bunong-vn','1CO',6,19,null,$b$Khân may mâu gĭt hĕ săk jăn khân may jêng ngih ma Brah Huêng Ueh gŭ jêh tâm khân may? Khân may sŏk dơn păng jêh bơh Brah Ndu, jêh ri khân may mâu hôm jêng ndơ khân may nơm ôh?$b$,false),
('bunong-vn','1CO',6,20,null,$b$Yor lah Brah Ndu tâm chuai jêh khân may ma rnoh khlay ngăn. Pô ri, tâm rnê hom ma Brah Ndu tâm săk jăn khân may jêh ri tâm huêng khân may jêng jêh ndơ Brah Ndu.$b$,false),
('bunong-vn','1CO',7,1,null,$b$Ma nau khân may nchih jêh ma gâp, gâp mĭn ueh, “Bu klâu mâu pah bi bu ur ôh.”$b$,true),
('bunong-vn','1CO',7,2,null,$b$Ƀiă lah gay ma lơi ăn geh nau văng tĭr, ăn ăp nơm bu klâu geh ur păng jêh ri ăp nơm bu ur geh sai păng.$b$,false),
('bunong-vn','1CO',7,3,null,$b$Ăn sai gŭ ma nau di ndrel ma ur păng, jêh ri ăn ur ƀư tâm ban pô nây lĕ đah sai păng.$b$,false),
('bunong-vn','1CO',7,4,null,$b$Ur mâu jêng kôranh ma săk jăn păng nơm, ƀiă lah sai păng, jêh ri tâm ban lĕ sai mâu jêng kôranh ma săk jăn păng nơm, ƀiă lah ur păng.$b$,false),
('bunong-vn','1CO',7,5,null,$b$Lơi tâm dun ndrăng khân ay may ôh, knŏng tơ lah lĕ bar hê khân ay may du ai prăp mông ma nau mbơh sơm. Jêh lôch nau nây plơ̆ gŭ ndrel klach lah brah Satan ndơm khân ay may ma nau khân ay may mâu dơi ât.$b$,false),
('bunong-vn','1CO',7,6,null,$b$Nau aơ gâp nchih yor lah Brah Ndu ăn, mâu di yor păng ntăm ôh.$b$,true),
('bunong-vn','1CO',7,7,null,$b$Gâp ŭch ma lĕ rngôch bunuyh jêng nâm bu gâp, ƀiă lah ăp nơm geh nau Brah Ndu ăn êng êng, du huê nâm aơ, du huê êng nâm ri.$b$,false),
('bunong-vn','1CO',7,8,null,$b$Gâp lah ma phung mâu geh ur jêh ri ma phung bu ur khĭt sai, ueh lơn khân păng gŭ nâm bu gâp.$b$,false),
('bunong-vn','1CO',7,9,null,$b$Ƀiă lah, tơ lah khân păng mâu dơi gŭ kloh, ăn khân păng tâm gŭ ur sai. Yor lah ueh lơn tâm gŭ hom ur sai lor ma đah nau rŏng kŏ tih.$b$,false),
('bunong-vn','1CO',7,10,null,$b$Ma phung tâm gŭ ur sai jêh gâp ntăm pô aơ, mâu di gâp, ƀiă lah Kôranh Brah, lơi ăn bu ur tâm nkhah đah sai păng ôh.$b$,true),
('bunong-vn','1CO',7,11,null,$b$(Tơ lah păng tâm nkhah jêh đah sai păng, ăn păng gŭ săk rlung, mâu lah ăn păng plơ̆ gŭ sai păng) jêh ri lơi ăn sai cha lơi ur păng ôh.$b$,false),
('bunong-vn','1CO',7,12,null,$b$Bi ma phung êng, mâu geh ôh Kôranh Brah lah, ƀiă lah gâp, tơ lah du huê oh nâu geh ur mâu chroh jêh ri ur nây ŭch gŭ păng, lơi ta cha lơi păng ôh.$b$,false),
('bunong-vn','1CO',7,13,null,$b$Jêh ri tơ lah du huê bu ur geh sai mâu chroh jêh ri sai ŭch gŭ păng, lơi ta cha lơi păng ôh.$b$,false),
('bunong-vn','1CO',7,14,null,$b$Yor lah sai mâu chroh nây geh nau kloh ueh tâm ur păng, jêh ri ur mâu chroh nây geh nau kloh ueh tâm sai păng. Tơ lah mâu di nâm nđĕ phung kon khân may mra ƀơ̆ , ƀiă lah aƀaơ aơ khân păng jêng kloh ueh.$b$,false),
('bunong-vn','1CO',7,15,null,$b$Tơ lah nơm mâu chroh ŭch tâm nkhah, ăn khân păng tâm nkhah hom, tâm nau pô nây nâu mâu lah ruh mâu geh nau tâm iang ôh. Yor lah Brah Ndu kuăl jêh he ăn gŭ rêh tâm nau đăp mpăn.$b$,false),
('bunong-vn','1CO',7,16,null,$b$Hơi bu ur, mâm ay gĭt? Gĭt lah ay mra tâm rklaih sai ay? Mâu lah, hơi bu klâu, mâm may gĭt? Gĭt lah may mra tâm rklaih ur may?$b$,false),
('bunong-vn','1CO',7,17,null,$b$Knŏng pô aơ, ăn ăp nơm ƀư tĭng nâm nau Kôranh Brah tâm pă ma păng jêh, tĭng nâm nau kuăl păng sŏk dơn jêh bơh Brah Ndu. Tâm ban pô nây yơh gâp ntăm jêh ma lĕ rngôch phung ngih Brah Ndu.$b$,true),
('bunong-vn','1CO',7,18,null,$b$Tơ lah Brah Ndu kuăl bu koh ntâu jêh, ăn păng gŭ pô nây. Tơ lah Brah Ndu kuăl bu ê koh ntâu, lơi ăn bu koh ntâu păng ôh.$b$,false),
('bunong-vn','1CO',7,19,null,$b$Nau koh ntâu mâu khlay ôh, jêh ri nau mâu geh koh ntâu mâu khlay lĕ, ƀiă lah tông nau vay Brah Ndu nŭm jêh.$b$,false),
('bunong-vn','1CO',7,20,null,$b$Ăn ăp nơm gŭ tâm ban ma păng jêng ta nar Brah Ndu kuăl păng.$b$,false),
('bunong-vn','1CO',7,21,null,$b$May geh lĕ nau kuăl dôl jêng dĭk? Lơi rngot ma nau nây ôh, ƀiă lah tơ lah may dơi jêng kon me, ăn may dơn hom mông găl.$b$,false),
('bunong-vn','1CO',7,22,null,$b$Yor lah dĭk Kôranh Brah kuăl jêh, păng jêng nơm Kôranh Brah ăn jêng kon me. Tâm ban lĕ nơm kon me Kôranh Brah kuăl jêh, păng jêng dĭk ma Brah Krist.$b$,false),
('bunong-vn','1CO',7,23,null,$b$Brah Ndu tâm chuai jêh khân may ma rnoh khlay ngăn. Lơi hôm jêng dĭk bunuyh ôh.$b$,true),
('bunong-vn','1CO',7,24,null,$b$Pô ri, hơi phung oh nâu, ăn ăp nơm gŭ ta năp Brah Ndu nâm bu păng jêng ta nar Brah Ndu kuăl păng.$b$,false),
('bunong-vn','1CO',7,25,null,$b$Bi ma phung bu ur druh, gâp mâu geh nau Kôranh Brah ntăm ôh, ƀiă lah gâp lah tâm ban ma gâp dơn jêh bơh Kôranh Brah nau yô̆ an gâp jêng răp jăp.$b$,true),
('bunong-vn','1CO',7,26,null,$b$Yor lah rnôk jêr dăch tât, gâp mĭn ueh lơn ma du huê bu klâu gŭ nâm bu păng jêng jêh.$b$,false),
('bunong-vn','1CO',7,27,null,$b$May lĕ geh ur đŏng? Lơi tâm nkhah ôh. May jêng săk rlung ƀơh? Lơi joi bu ur ôh.$b$,false),
('bunong-vn','1CO',7,28,null,$b$Tơ lah may gŭ ur jêh, may mâu ƀư tih ôh, jêh ri tơ lah bu ur druh gŭ sai jêh, păng mâu ƀư tih ôh, ƀiă lah phung nây mra geh nau rŭng răng tâm nglay săk, jêh ri gâp ŭch king khân may bơh nau nây.$b$,false),
('bunong-vn','1CO',7,29,null,$b$Nĕ, pô aơ, gâp lah ma khân may, hơi phung oh nâu, rnôk dăch lôch jêh, ntơm bơh aơ rlet pa kơi phung geh ur tâm ban ma phung mâu geh ôh,$b$,true),
('bunong-vn','1CO',7,30,null,$b$mbu nơm tă nhĭm tâm ban ma mâu mâp nhĭm ôh, mbu nơm mâp geh nau maak, tâm ban ma mâu mâp maak ôh, mbu nơm phung rvăt tâm ban ma mâu mâp geh ôh.$b$,false),
('bunong-vn','1CO',7,31,null,$b$Jêh ri mbu nơm rnơm ma kan neh ntu aơ, tâm ban ma mâu mâp rnơm ôh, yor lah rup neh ntu aơ rlau lôch.$b$,false),
('bunong-vn','1CO',7,32,null,$b$Gâp ŭch ma khân may jêng kon me bơh nau rngot klâng. Mbu nơm săk rlung rngloi mĭn ma ndơ Kôranh Brah, joi nau ƀư maak ma Kôranh Brah.$b$,true),
('bunong-vn','1CO',7,33,null,$b$Ƀiă lah mbu nơm gŭ ur mĭn ma ndơ neh ntu, joi nau ƀư maak ma ur păng,$b$,false),
('bunong-vn','1CO',7,34,null,$b$pô ri nau păng mĭn tâm pă jêh tâm ban pô nây lĕ ma phung bu ur mâu geh sai, jêh ri ma phung bu ur druh, khân păng mĭn ma ndơ Kôranh Brah gay jêng kloh ueh tâm săk jăn jêh ri huêng; ƀiă lah bu ur geh sai mĭn ma ndơ neh ntu, păng joi nau dơi ƀư maak ma sai păng.$b$,false),
('bunong-vn','1CO',7,35,null,$b$Gâp lah nau nây ŭch kơl khân may, mâu di ŭch ƀư jêr khân may ôh, ƀiă lah ŭch njŭn leo khân may ma nau ueh lơn, jêh ri ŭch ma khân may mâu geh nau tâm pă ôh tâm kan ƀư ma Kôranh Brah.$b$,true),
('bunong-vn','1CO',7,36,null,$b$Tơ lah du huê mĭn mâu gop ôh kon bu ur păng gao năm gŭ ur sai; jêh ri păng ŭch ăn kon păng gŭ sai, ăn păng ƀư tĭng nâm păng ŭch, păng mâu ƀư tih ôh, ăn păng gŭ sai yơh.$b$,false),
('bunong-vn','1CO',7,37,null,$b$Ƀiă lah mbu nơm gŭ nâp tâm nau mĭn păng, prăp nau păng nơm ŭch jêh ri tĭng nâm nuih n'hâm păng rŏng, păng ŭch ăn kon bu ur păng gŭ săk rlung, păng ƀư ueh yơh.$b$,false),
('bunong-vn','1CO',7,38,null,$b$Pô nây lĕ, mbu nơm ăn kon bu ur păng gŭ sai, păng ƀư ueh, ƀiă lah mbu nơm mâu ăn kon bu ur păng gŭ sai, păng ƀư ueh lơn đŏng.$b$,false),
('bunong-vn','1CO',7,39,null,$b$Du huê bu ur tâm krêp đah sai păng dôl păng hôm gŭ rêh. Tơ lah sai păng khĭt, păng mpăn dơi gŭ sai êng tĭng nâm păng ŭch, ƀiă lah knŏng tâm Kôranh Brah.$b$,true),
('bunong-vn','1CO',7,40,null,$b$Ƀiă lah păng maak lơn tĭng nâm gâp mĭn, tơ lah păng gŭ nâm bu păng hŏ jêng jêh. Jêh ri gâp mĭn, gâp geh Brah Huêng Ueh Brah Ndu.$b$,false),
('bunong-vn','1CO',8,1,null,$b$Ma ndơ nhhơr ma rup brah; he gĭt lĕ rngôch he geh nau gĭt rbăng. Nau gĭt rbăng ƀư sưr bu, ƀiă lah nau rŏng tâm n'hao nuih.$b$,true),
('bunong-vn','1CO',8,2,null,$b$Tơ lah du huê mĭn păng gĭt ndơ păng mâu mâp gĭt tâm ban ma bu êng gĭt ôh.$b$,false),
('bunong-vn','1CO',8,3,null,$b$Ƀiă lah tơ lah du huê bunuyh rŏng ma Brah Ndu, Brah Ndu gĭt năl jêh nơm nây.$b$,false),
('bunong-vn','1CO',8,4,null,$b$Bi nau sa ndơ nhhơr ma rup brah, he gĭt rup brah mâu jêng khlay ôh tâm neh ntu, jêh ri geh knŏng êng Brah Ndu nơm.$b$,false),
('bunong-vn','1CO',8,5,null,$b$Nđâp tơ lah geh ndơ bu rnha brah gĭt lah tâm trôk, gĭt lah tâm neh ntu, nâm bu geh âk brah jêh ri âk kôranh brah.$b$,false),
('bunong-vn','1CO',8,6,null,$b$Bi ma phung he, geh knŏng du huê Brah Ndu, Mbơ̆ . Tă bơh păng luh lĕ rngôch ndơ jêh ri he jêng ndơ Păng, jêh ri knŏng du huê Kôranh Brah, Yêsu Krist. Păng yơh njêng lĕ rngôch ndơ jêh ri phung he tâm ban lĕ.$b$,false),
('bunong-vn','1CO',8,7,null,$b$Ƀiă lah lĕ rngôch mâu geh ôh nau gĭt rbăng aơ, Ƀa ƀă mơng jêh mĭn ma rup brah jêh ri khân păng sa ndơ nây nâm bu hŏ nhhơr jêh ma rup brah; pô ri nuih n'hâm sŏng khân păng jêng rdja, jêng ƀơ̆ jêh.$b$,true),
('bunong-vn','1CO',8,8,null,$b$Mâu yor ndơ sông sa ôh ƀư dăch he đah Brah Ndu. Tơ lah he sa puăch he mâu jêng ueh lơn ôh. Tơ lah he mâu sa puăch he mâu jêng mhĭk lơn ôh.$b$,true),
('bunong-vn','1CO',8,9,null,$b$Knŏng khân may njrăng, lơi ăn nau mpăn khân may jêng lŭ, geh chêh jâng phung rdja.$b$,false),
('bunong-vn','1CO',8,10,null,$b$Tơ lah du huê saơ may nơm geh nau gĭt rbăng, gŭ sa ndơ tâm ngih rup brah, bunuyh nây geh nuih n'hâm sŏng, rdja mra geh nau ndơm sa puăch bu nhhơr ma rup brah.$b$,false),
('bunong-vn','1CO',8,11,null,$b$Pô ri, nơm rdja mra rai yot yor nau may gĭt rbăng. Jêh ri yor oh nâu Brah Krist khĭt jêh.$b$,false),
('bunong-vn','1CO',8,12,null,$b$Dôl ƀư tih pô nây đah phung oh nâu khân may jêh ri ƀư sôt nuih n'hâm sŏng khân păng rdja, khân may ƀư tih đah Brah Krist yơh.$b$,false),
('bunong-vn','1CO',8,13,null,$b$Yor nây tơ lah du ntil ndơ sa ƀư chêh jâng oh nâu gâp, gâp mâu mra sa puăch ôh klach lah gâp ƀư chêh oh nâu gâp.$b$,false),
('bunong-vn','1CO',9,1,null,$b$Gâp mâu dơi jêng kon me hĕ? Gâp mâu dơi jêng kôranh oh mon hĕ? Gâp mâu mâp saơ Brah Yêsu, Kôranh Brah he hĕ? Mâm khân may mâu jêng kan gâp tâm Kôranh Brah?$b$,true),
('bunong-vn','1CO',9,2,null,$b$Tơ lah ma phung êng, gâp mâu jêng kôranh oh mon, nanê̆ gâp jêng kôranh oh mon ma khân may yơh; yor lah khân may jêng ndơ tâp pŏng kan gâp tâm Kôranh Brah.$b$,false),
('bunong-vn','1CO',9,3,null,$b$Pô ri nau gâp king ma phung phong gâp.$b$,false),
('bunong-vn','1CO',9,4,null,$b$Hên mâu geh nau vay sa mâu lah nhêt hĕ?$b$,false),
('bunong-vn','1CO',9,5,null,$b$Hên mâu geh nau vay njŭn leo ndrel ma hên du huê bu ur chroh jêng ur hên, tâm ban ma phung kôranh oh mon êng jêh ri phung oh Kôranh Brah, nđâp ma Y-Sêphas?$b$,false),
('bunong-vn','1CO',9,6,null,$b$Mâu lah knŏng du huê gâp mâu lah Y-Ƀarnaƀas hĕ mâu geh nau vay lơi kan hên pah?$b$,false),
('bunong-vn','1CO',9,7,null,$b$Mbu nơm hăn jêng ta han dâk mpŭng prăk păng nơm? Mbu nơm tăm tơm play kriăk ƀâu jêh ri mâu sa play păng? Mbu nơm mât phung biăp jêh ri mâu nhêt dak toh păng?$b$,false),
('bunong-vn','1CO',9,8,null,$b$Gâp ngơi pô aơ, tĭng vay bunuyh ngơi lĕ? Mâu di hĕ nau vay lah tâm ban pô nây?$b$,false),
('bunong-vn','1CO',9,9,null,$b$Yor lah geh nau nchih jêh tâm ndrom sămƀŭt nau vay Y-Môis: “Lơi may put lơi mbung ndrôk dôl jot ba”, knŏng ma phung ndrôk hĕ Brah Ndu mĭn?$b$,false),
('bunong-vn','1CO',9,10,null,$b$Mâu lah păng ngơi nau nây yor he? Ơ, yor he yơh geh nau nchih pô nây, ăn mbu nơm kai mir, mra kai ma nau kâp gân jêh ri mbu nơm jot ba mra jot ma nau kâp gân mra geh ma păng ƀă.$b$,true),
('bunong-vn','1CO',9,11,null,$b$Tơ lah hên srih jêh tâm phung khân may drăp brah, jêng nau toyh lĕ tơ lah hên rek drăp ndơ khân may tâm neh ntu aơ?$b$,false),
('bunong-vn','1CO',9,12,null,$b$Tơ lah phung êng dơi ƀư nau vay nây ma khân may, mâu di hĕ hên dơi ƀư rlau lơn? Ƀiă lah hên dơi ƀư rlau lơn? Ƀiă lah hên mâu dŏng nau dơi nây ôh. Hên srôih ma lĕ rngôch ndơ, yor lah mâu ŭch njêng nau bâp ma nau mhe mhan ueh Brah Krist.$b$,false),
('bunong-vn','1CO',9,13,null,$b$Khân may mâu gĭt hĕ ma mbu nơm pah kan tâm ngih brah Yuđa sa ndơ ngih brah Yuđa nây jêh ri mbu nhhơr ndơ ƀư brah ta nơng geh ndơ bơh nơng nây?$b$,false),
('bunong-vn','1CO',9,14,null,$b$Tâm ban lĕ Kôranh Brah ntăm jêh ma phung mbơh nau mhe mhan ueh mra rêh ma nau mhe mhan ueh.$b$,false),
('bunong-vn','1CO',9,15,null,$b$Bi gâp, gâp mâu dŏng nau dơi nây ôh, jêh ri mâu di gâp nchih nau nây gay ma dăn ndơ ôh, yor lah gâp rŏng lơn nau khĭt, ma ăn bu sŏk lơi nau dơi tâm rnê nây bơh gâp.$b$,true),
('bunong-vn','1CO',9,16,null,$b$Tơ lah gâp mbơh nau mhe mhan ueh, nau nây mâu dơi ăn gâp tâm rnê ma gâp nơm ôh. Yor lah nau khlay nây nchâp jêh gâp, jêh ri rêh ni yơh ma gâp tơ lah gâp mâu mbơh nau mhe mhan ueh!$b$,true),
('bunong-vn','1CO',9,17,null,$b$Tơ lah gâp pah kan nây ma nuih n'hâm ueh gâp geh nau nkhôm; tơ lah gâp pah kan nây ma nuih n'hâm nchâp kđôi, ăt kan nây bu jao jêh ma gâp.$b$,false),
('bunong-vn','1CO',9,18,null,$b$Pô ri, moh jêng nau nkhôm gâp? Păng jêng nau gâp mbơh dơm dam nau mhe mhan ueh, mâu dŏng ôh nau gâp dơi ƀư tâm ban nơm nti nau mhe mhan ueh.$b$,false),
('bunong-vn','1CO',9,19,null,$b$Yor lah dôl gâp mpăn gŭ bơh lĕ rngôch bunuyh, gâp njêng gâp nơm jêng dĭk ma lĕ rngôch pô ri gâp dơi njŭn âk lơn bunuyh.$b$,true),
('bunong-vn','1CO',9,20,null,$b$Đah phung Yuđa gâp jêng tâm ban ma du huê Yuđa, pô ri mơ gâp dơi njŭn phung Yuđa, đah phung gŭ tâm dâng nau vay, gâp jêng nâm bu tâm dâng nau vay, ƀiă lah mâu di gâp mâu geh nau vay Brah Ndu ôh, pô ri gâp dơi njŭn leo phung gŭ tâm dâng nau vay.$b$,true),
('bunong-vn','1CO',9,21,null,$b$Đah phung mâu geh nau vay gâp jêng tâm ban ma gâp mâu geh nau vay, ƀiă lah mâu di gâp mâu geh nau vay Brah Ndu ôh, yor lah gâp gŭ tâm dâng nau vay Brah Krist, pô ri mơ gâp dơi njŭn leo phung gŭ tâm dâng nau vay.$b$,false),
('bunong-vn','1CO',9,22,null,$b$Gâp jêng rdja ndrel ma phung rdja, pô ri mơ gâp dơi njŭn leo phung rdja. Gâp jêng jêh lĕ rngôch ndơ ma lĕ rngôch bunuyh, pô ri mơ gâp dơi tâm rklaih ƀa ƀă tâm phung khân păng.$b$,false),
('bunong-vn','1CO',9,23,null,$b$Jêh ri gâp ƀư lĕ rngôch ndơ yor nau mhe mhan ueh, pô ri mơ gâp dơi geh nau ueh uĭn tâm păng.$b$,true),
('bunong-vn','1CO',9,24,null,$b$Khân may mâu gĭt hĕ ma phung tâm rlong nchuăt tâm ntŭk pâl, lĕ rngôch nchuăt da dê, ƀiă lah knŏng du huê geh nau nkhôm? Pô ri, nchuăt hom gay ma geh nau nkhôm.$b$,true),
('bunong-vn','1CO',9,25,null,$b$Lĕ rngôch đơ phung tâm lơh ver ăp ntil ndơ, jêh ri khân păng ƀư nau nây gay geh đon hađăch mâu blau rai yot ôh. Ƀiă lah he ƀư nau nây ŭch geh đon hađăch mâu blau rai lôch ôh.$b$,false),
('bunong-vn','1CO',9,26,null,$b$Pô nây yơh, mâu di gâp nchuăt dơm dam ôh jêh ri mâu di gâp dong tâm sial ôh;$b$,false),
('bunong-vn','1CO',9,27,null,$b$ƀiă lah gâp ăn rêh ni ma săk jăn gâp jêh ri dơi đah păng, klach lah jêh gâp nti ma bu, Brah Ndu mra dun gâp tâm ban lĕ.$b$,false),
('bunong-vn','1CO',10,1,null,$b$Hơi oh nâu, gâp ŭch khân may gĭt ma lĕ rngôch phung mbơ̆ he gŭ jêh tâm ndâr tŭk. Lĕ rngôch khân păng rgăn jêh dak mƀŭt.$b$,true),
('bunong-vn','1CO',10,2,null,$b$Khân păng dơn jêh nau ƀư ƀaptem tâm Y-Môis tâm ndâr tŭk jêh ri tâm dak mƀŭt.$b$,false),
('bunong-vn','1CO',10,3,null,$b$Lĕ rngôch khân păng sa jêh ndơ sông sa brah.$b$,false),
('bunong-vn','1CO',10,4,null,$b$Lĕ rngôch khân păng nhêt jêh du ntŭk dak nau brah yor lah khân păng nhêt jêh ta du ntŭk play lŭ nau brah tĭng groi khân păng, jêh ri lŭ nây jêng Brah Krist.$b$,false),
('bunong-vn','1CO',10,5,null,$b$Ƀiă lah âk ngăn tâm phung khân păng mâu ƀư maak ma Brah Ndu ôh, yor nây khân păng roh hêng tâm bri rdah.$b$,false),
('bunong-vn','1CO',10,6,null,$b$Nau nây tât gay ma tâm nti he, pô nây mơ lơi ăn he geh nau tih mhĭk, nâm bu khân păng.$b$,false),
('bunong-vn','1CO',10,7,null,$b$Lơi he mbah ma rup brah ôh nâm bu geh ƀa ƀă tâm phung khân păng tĭng nâm nau nchih jêh pô aơ: “Phung bunuyh gŭ sông sa nhêt, jêh ri khân păng dâk ŭch pâl”.$b$,false),
('bunong-vn','1CO',10,8,null,$b$Lơi he ƀư nau văng tĭr ôh, nâm bu geh ƀa ƀă tâm phung khân păng, pô ri bar jât ma pe rbăn nuyh khĭt tâm du nar.$b$,true),
('bunong-vn','1CO',10,9,null,$b$Lơi he rlong uănh Kôranh Brah ôh nâm bu geh ƀa ƀă tâm phung khân păng jêh ri khân păng khĭt đah nau bêh chôk.$b$,false),
('bunong-vn','1CO',10,10,null,$b$Lơi ta khân may ngơi ƀŭk dŭk suyh ôh nâm bu phung ƀa ƀă tâm khân păng jêh ri khân păng khĭt đah ti nơm ƀư rai.$b$,false),
('bunong-vn','1CO',10,11,null,$b$Nau nây tât jêh gay tâm ntĭt ma he, jêh ri bu nchih jêh gay nti he yor phung he gŭ êp nar dăch lôch.$b$,true),
('bunong-vn','1CO',10,12,null,$b$Pô ri, mbu nơm mĭn păng gŭ ngao ăn păng njrăng, klach păng cha lôt.$b$,false),
('bunong-vn','1CO',10,13,null,$b$Mâu geh du ntil nau ndơm tât ma khân may êng ngăn đah nau tât ma phung êng. Brah Ndu jêng răp jăp, jêh ri păng mâu ăn ôh nau ndơm tât ma khân may rlau lơn ma n'hâm ktang khân may, ƀiă lah ma nau ndơm păng mra nkra lĕ trong khân may mra luh, pô nây mơ khân may dơi tuy.$b$,false),
('bunong-vn','1CO',10,14,null,$b$Yor ri yơh, hơi phung gâp rŏng ơi, du hom đah nau mbah rup brah.$b$,true),
('bunong-vn','1CO',10,15,null,$b$Gâp ngơi ma khân may tâm ban ma bunuyh gĭt rbăng; ăn khân may sek uănh ma nau gâp lah.$b$,false),
('bunong-vn','1CO',10,16,null,$b$Kchok nau ueh uĭn he mât ton, mâu hĕ păng jêng nau tâm rnglăp ma mham Yêsu Krist? Kapŭng he nkêch nây mâu hĕ păng jêng nau tâm rnglăp ma săk jăn Brah Krist hĕ?$b$,false),
('bunong-vn','1CO',10,17,null,$b$Yor lah geh knŏng du mlâm kapŭng. Pô ri he jêng âk, tâm rnglăp jêng du săk jăn, yor lah lĕ rngôch he sa du mlâm kapŭng nây.$b$,false),
('bunong-vn','1CO',10,18,null,$b$Uănh hom ma phung Israel tĭng nâm nglay săk; mâu di hĕ phung sa ndơ ƀư brah geh nau tâm rnglăp đah nơng ƀư brah?$b$,false),
('bunong-vn','1CO',10,19,null,$b$Pô ri, moh nau gâp lah? Ndơ nhhơr ma rup brah nây jêng khlay lĕ? Mâu lah rup brah nây jêng khlay lĕ?$b$,false),
('bunong-vn','1CO',10,20,null,$b$Mâu! Ƀiă lah, gâp lah ma ndơ phung bu năch nhhơr, khân păng nhhơr ma brah mhĭk, mâu geh ma Brah Ndu ôh. Pô ri, gâp mâu ŭch ôh khân may tâm rnglăp đah brah mhĭk.$b$,false),
('bunong-vn','1CO',10,21,null,$b$Khân may mâu dơi nhêt kchok Kôranh Brah jêh ri kchok brah mhĭk ôh, khân may mâu dơi sa ta sưng Kôranh Brah jêh ri ta sưng brah mhĭk ôh.$b$,false),
('bunong-vn','1CO',10,22,null,$b$He mra ăn Kôranh Brah ntôn lĕ? He jêng ktang lơn ma păng lĕ?$b$,false),
('bunong-vn','1CO',10,23,null,$b$“Lĕ rngôch ndơ gâp dơi ƀư,” ƀiă lah lĕ rngôch mâu geh khlay ôh. “Lĕ rngôch gâp dơi ƀư” ƀiă lah lĕ rngôch mâu n'hao nuih ôh.$b$,true),
('bunong-vn','1CO',10,24,null,$b$Lơi ăn du huê joi nau maak ma păng nơm ôh ƀiă lah nau ueh ma phung chiau meng păng.$b$,false),
('bunong-vn','1CO',10,25,null,$b$Ăn khân may sa ndơ bu tăch ta ngih tăch drăp, mâu geh nau ôp yor nuih n'hâm sŏng ôh.$b$,false),
('bunong-vn','1CO',10,26,null,$b$Yor lah: “Neh ntu jêng ndơ Kôranh Brah jêh ri lĕ rngôch ndơ tâm Păng”.$b$,false),
('bunong-vn','1CO',10,27,null,$b$Tơ lah du huê mâu chroh jă khân may sông sa jêh ri khân may ŭch hăn, sa hom lĕ rngôch ndơ bu mra thai ma khân may mâu geh ôp yor nuih n'hâm sŏng ôh.$b$,false),
('bunong-vn','1CO',10,28,null,$b$Ƀiă lah, tơ lah du huê lah ma khân may: “Aơ jêng ndơ nhhơr jêh ma brah,” lơi ta khân may sa ndơ nây ôh. Yor nơm nây mbơh jêh, jêh ri yor nuih n'hâm sŏng.$b$,false),
('bunong-vn','1CO',10,29,null,$b$Gâp ngơi mâu di ma nuih n'hâm sŏng khân may ôh, ƀiă lah yor nuih n'hâm sŏng păng. Mâm ƀư nau đăp mpăn gâp nkhơng nuih n'hâm sŏng păng phat dôih?$b$,false),
('bunong-vn','1CO',10,30,null,$b$Tơ lah gâp sa ndơ hŏ lah ueh, mâm ƀư gâp nkhơng bu nduyh yor ndơ gâp sa hŏ lah ueh?$b$,true),
('bunong-vn','1CO',10,31,null,$b$Gĭt lah khân may sông, sa, nhêt, mâu lah ƀư ndơ êng, ƀư hom lĕ rngôch gay ma tâm rnê ma Brah Ndu.$b$,false),
('bunong-vn','1CO',10,32,null,$b$Lơi ta chêh phung Grek, phung Yuđa, mâu lah ma phung ngih Brah Ndu ôh.$b$,false),
('bunong-vn','1CO',10,33,null,$b$Nđâp ma gâp lĕ ŭch ƀư maak ma lĕ rngôch bunuyh tâm ăp ntil ndơ gâp ƀư, mâu di joi nau ueh ma gâp nơm ôh, ƀiă lah ma âk bunuyh, gay ma tâm rklaih khân păng.$b$,false),
('bunong-vn','1CO',11,1,null,$b$Ăn khân may jêng phung kơt ƀư nâm bu gâp, jêh ri gâp nơm kơt Brah Krist.$b$,true),
('bunong-vn','1CO',11,2,null,$b$Gâp tâm rnê ma khân may yor lah khân may kah gĭt ma gâp tâm lĕ rngôch ndơ, jêh ri khân may djôt prăp nau nti nâm bu gâp ăn jêh ma khân may.$b$,true),
('bunong-vn','1CO',11,3,null,$b$Ƀiă lah gâp ŭch ăn khân may gĭt Brah Krist jêng Kôranh ma ăp nơm bu klâu, jêh ri bu klâu jêng kôranh ma bu ur jêh ri Brah Ndu jêng Kôranh ma Brah Krist.$b$,false),
('bunong-vn','1CO',11,4,null,$b$Ăp nơm bu klâu mbơh sơm mâu lah mbơh lor jêh ri bôk păng nkŭm, păng mâu yơk ma kôranh păng ôh.$b$,false),
('bunong-vn','1CO',11,5,null,$b$Ƀiă lah ăp nơm bu ur mbơh sơm mâu lah mbơh lor mâu nkŭm bôk, păng mâu yơk ma kôranh păng ôh, nau nây jêng tâm ban ma păng poih jêh sŏk păng.$b$,false),
('bunong-vn','1CO',11,6,null,$b$Yor lah tơ lah du huê bu ur mâu nkŭm ôh bôk păng, ăn păng kreh lơi lĕ sŏk păng; ƀiă lah tơ lah du huê bu ur prêng geh sŏk kreh jêh mâu lah poih lơi, ăn păng nkŭm lơi bôk păng.$b$,false),
('bunong-vn','1CO',11,7,null,$b$Bu klâu mâu vay ôh nkŭm bôk yor lah păng jêng rup jêh ri nau chrêk rmah Brah Ndu; ƀiă lah bu ur jêng nau chrêk rmah bu klâu.$b$,true),
('bunong-vn','1CO',11,8,null,$b$(Yor lah Brah Ndu mâu njêng bu klâu tă bơh bu ur ôh, ƀiă lah bu ur Brah Ndu njêng tă bơh bu klâu.$b$,false),
('bunong-vn','1CO',11,9,null,$b$Jêh ri Brah Ndu rhăk njêng bu klâu mâu di yor bu ur ôh, ƀiă lah Brah Ndu rhăk njêng bu ur yor ma bu klâu).$b$,false),
('bunong-vn','1CO',11,10,null,$b$Yor phung Tông mpăr ueh Brah Ndu bu ur vay geh ta bôk ndơ tâm mbên ma nau dơi păng rnơm.$b$,false),
('bunong-vn','1CO',11,11,null,$b$Ƀiă lah tâm Kôranh Brah bu ur mâu jêng ôh mâu geh bu klâu, jêh ri bu klâu mâu jêng ôh lah mâu geh bu ur;$b$,false),
('bunong-vn','1CO',11,12,null,$b$yor lah tâm ban ma bu ur luh tă bơh bu klâu, pô ri aƀaơ bu ur deh ma bu klâu, ƀiă lah lĕ rngôch luh tă bơh Brah Ndu.$b$,false),
('bunong-vn','1CO',11,13,null,$b$Ăn khân may nơm mĭn, ueh lĕ ma bu ur mbơh sơm ma Brah Ndu mâu nkŭm bôk?$b$,true),
('bunong-vn','1CO',11,14,null,$b$Nau vay neh ntu mâu mâp nti hĕ ma khân ay may jêng nau bêk ma bu klâu om sŏk jong?$b$,true),
('bunong-vn','1CO',11,15,null,$b$Ƀiă lah jêng nau chrêk rmah ma bu ur om sŏk jong, yor lah sŏk păng jêng tâm ban ma bok nkŭm bôk păng.$b$,false),
('bunong-vn','1CO',11,16,null,$b$Tơ lah du huê ŭch tâm rlăch, he mâu vay ôh ƀư pô nây, mâu lah phung ngih Brah Ndu.$b$,false),
('bunong-vn','1CO',11,17,null,$b$Dôl gâp ăn nau mbơh aơ ma khân may, gâp mâu tâm rnê ma khân may ôh, yor lah khân may tâm rƀŭn mâu di ŭch jêng ueh lơn, ƀiă lah jêng mhĭk lơn.$b$,true),
('bunong-vn','1CO',11,18,null,$b$Lor lơn gâp tăng jêh tơ lah khân may tâm rƀŭn tâm Ngih Brah Ndu, geh nau tâm pă tâm phung khân may jêh ri gâp chroh nau nây du n'gul.$b$,false),
('bunong-vn','1CO',11,19,null,$b$Yor lah nanê̆ geh phung êng êng tâm phung khân may, gay ma bu dơi gĭt năl mbu nơm jêng răp jăp đah he.$b$,false),
('bunong-vn','1CO',11,20,null,$b$Tơ lah khân may tâm rƀŭn mâu di khân may sa nhêt tâm êp đah Kôranh Brah ôh.$b$,false),
('bunong-vn','1CO',11,21,null,$b$Tơ lah bu ntơm sa, ăp nơm ndal sa ndơ păng nơm, du huê ji ngot, jêh ri du huê êng nhŭl ndrănh.$b$,false),
('bunong-vn','1CO',11,22,null,$b$Khân may mâu geh hĕ ngih êng prăp ntŭk nhêt sa? Mâu lah khân may tâm rmot ma phung ngih Brah Ndu jêh ri ŭch ƀư bêk phung mâu geh ndơ? Moh ndơ gâp mra lah ma khân may? Gâp mra tâm rnê ma khân may đŏng? Tâm nau nây gâp mâu tâm rnê ma khân may ôh.$b$,false),
('bunong-vn','1CO',11,23,null,$b$Gâp hŏ sŏk jêh nau nti tă bơh Kôranh Brah jêh ri gâp lah đŏng ma khân may pô aơ:$b$,true),
('bunong-vn','1CO',11,24,null,$b$Tâm măng bu jao Brah Yêsu ma bu, Păng sŏk kapŭng lah ueh ma Brah Ndu, jêh ri Păng nkêch kapŭng. Păng lah: “Aơ jêng nglay săk gâp ăn ma khân may. Ƀư pô aơ gay ma khân may kah gĭt ma gâp.”$b$,false),
('bunong-vn','1CO',11,25,null,$b$Tâm ban lĕ, jêh khân păng sa, Brah Yêsu sŏk đŏng kchok jêh ri lah: “Kchok aơ jêng nau tâm nkol mhe khân may đah Brah Ndu ma mham gâp. Ƀư pô aơ gay ma khân may kah gĭt ma gâp tâm ăp tơ̆ khân may nhêt kchok aơ.”$b$,false),
('bunong-vn','1CO',11,26,null,$b$Yor lah ăp tơ̆ khân may sa kapŭng aơ, nhêt kchok aơ, khân may nkoch nau Kôranh Brah khĭt, tât Păng văch tay.$b$,false),
('bunong-vn','1CO',11,27,null,$b$Yor ri mbu nơm sa kapŭng mâu lah nhêt kchok Kôranh Brah mâu tâm gop ma săk păng, nơm nây jêng tih đah nglay săk jêh ri đah mham Kôranh Brah.$b$,true),
('bunong-vn','1CO',11,28,null,$b$Pô ri lĕ rngôch bunuyh mbu nơm nhêt sa, ăn păng sek uănh êng păng nơm lor, ri mơ păng dơi sa kapŭng mâu lah nhêt kchok aơ.$b$,false),
('bunong-vn','1CO',11,29,null,$b$Yor lah mbu nơm sa kapŭng mâu lah nhêt kchok aơ blă blơ, păng mâu kơp ndơ nây jêng săk jăn Kôranh Brah. Pô ri păng dơn nau bu phat dôih dôl păng nhêt sa.$b$,false),
('bunong-vn','1CO',11,30,null,$b$Yor nau nây geh âk tâm phung khân may ji kuet, ji rôi, jêh ri ƀa ƀă tâm phung khân may hŏ khĭt jêh.$b$,false),
('bunong-vn','1CO',11,31,null,$b$Lah he sek uănh êng săk he nơm lor, pô ri bu mâu hôm phat dôih he ôh.$b$,true),
('bunong-vn','1CO',11,32,null,$b$Ƀiă lah tơ lah Kôranh Brah phat dôih he, păng nkra he, gay ma he mâu mra dơn ôh nau tâm rmal ndrel ma neh ntu.$b$,false),
('bunong-vn','1CO',11,33,null,$b$Pô ri, hơi phung oh nâu, tơ lah khân may tâm rƀŭn ma nau nhêt sa tâm êp, tâm kâp hom ndrăng khân may.$b$,false),
('bunong-vn','1CO',11,34,null,$b$Tơ lah du huê ji ngot, ăn păng sông sa, ta ngih păng nơm, klach lah khân may tâm rƀŭn jêh ri sŏk dơn nau phat dôih. Gâp mra nkra nau êng tơ lah gâp tât.$b$,false),
('bunong-vn','1CO',12,1,null,$b$Hơi phung oh nâu, aƀaơ gâp mâu ŭch ôh ma khân may mâu gĭt rbăng ma nau Brah Huêng Ueh ăn.$b$,true),
('bunong-vn','1CO',12,2,null,$b$Khân may gĭt jêh dôl khân may ê chroh, khân may kơt phung rup brah mlo, tĭng nâm bu leo khân may.$b$,false),
('bunong-vn','1CO',12,3,null,$b$Yor ri gâp mbơh, nkoch ma khân may, mâu geh du huê bunuyh, tơ lah păng ngơi ma Brah Huêng Ueh Brah Ndu lah ma Brah Yêsu jêng rtăp rak! Jêh ri mâu geh du huê dơi lah Brah Yêsu jêng Kôranh Brah tơ lah Brah Huêng Ueh mâu mbơh ma păng.$b$,false),
('bunong-vn','1CO',12,4,null,$b$Geh nau ăn êng êng, ƀiă lah geh nguay Brah Huêng Ueh.$b$,true),
('bunong-vn','1CO',12,5,null,$b$Geh kan êng êng, ƀiă lah geh nguay Kôranh Brah.$b$,false),
('bunong-vn','1CO',12,6,null,$b$Geh nau dơi pah kah êng êng, ƀiă lah geh knŏng nguay Brah Ndu dơm ăn nau dơi ma ăp nơm bunuyh kan.$b$,false),
('bunong-vn','1CO',12,7,null,$b$Jêh ri, Brah Huêng Ueh tâm mpơl ma ăp nơm nau dơi kơl ma lĕ rngôch.$b$,false),
('bunong-vn','1CO',12,8,null,$b$Ma du huê aơ Brah Huêng Ueh ăn dơi ngơi nau gĭt mĭn, ma du huê êng dơi ngơi nau gĭt rbăng. Tĭng nâm tă bơh nguay Brah Huêng Ueh.$b$,false),
('bunong-vn','1CO',12,9,null,$b$Ma du huê êng nau chroh tă bơh nguay Brah Huêng Ueh lĕ, ma du huê êng nau dơi ƀư bah nau ji bu tă bơh nguay Brah Huêng Ueh lĕ.$b$,true),
('bunong-vn','1CO',12,10,null,$b$Brah Huêng Ueh ăn nau dơi ƀư nau khlay, păng ri djôt nau Brah Ndu, păng iti gĭt năl nau dơi Brah Huêng Ueh aơ đah nau dơi tă bơh brah êng ri. Păng ăn du huê aơ dơi gĭt nau ngơi êng, du huê ri păng ăn dơi gĭt rblang nau ngơi bu êng.$b$,false),
('bunong-vn','1CO',12,11,null,$b$Ƀiă lah geh knŏng nguay Brah Huêng Ueh dơm ƀư lĕ kan nây. Păng ăn nau dơi êng êng ma ăp nơm bunuyh tĭng nâm păng ŭch.$b$,false),
('bunong-vn','1CO',12,12,null,$b$Tâm Brah Krist jêng du nglay săk geh âk kô̆. Kô̆ nây geh ntil êng êng, ƀiă lah ăt jêng du nglay săk lĕ.$b$,true),
('bunong-vn','1CO',12,13,null,$b$Yor lah đah nguay Brah Huêng Ueh lĕ rngôch phung he, ăn he tâm rnglăp jêng du săk jăn, phung Yuđa, phung Grek, phung dĭk, phung kon me. Jêh ri bu ăn jêh ma phung he dơi dơn knŏng nguay Brah Huêng Ueh dơm.$b$,false),
('bunong-vn','1CO',12,14,null,$b$Tâm nglay săk mâu di ôh geh knŏng du kô̆ dơm, ƀiă lah păng geh âk kô̆.$b$,false),
('bunong-vn','1CO',12,15,null,$b$Lah jâng lah: “Gâp mâu jêng ti ôh, pô ri gâp mâu jêng du kô̆ tâm nglay săk nây lĕ mâm ƀư?” Nanê̆ ăt păng jêng du kô̆ tâm nglay săk nây lĕ.$b$,false),
('bunong-vn','1CO',12,16,null,$b$Lah tôr lah: “Gâp mâu jêng măt ôh, pô ri gâp mâu jêng du kô̆ tâm nglay săk nây lĕ”. Mâm ƀư? Nanê̆ ăt păng jêng du kô̆ tâm nglay săk nây lĕ.$b$,true),
('bunong-vn','1CO',12,17,null,$b$Lah lĕ nglay săk jêng măt da dê, lah pô ri mâm dơi păng tăng? Lah lĕ rngôch jêng tôr da dê, mâm dơi păng n'hơp?$b$,false),
('bunong-vn','1CO',12,18,null,$b$Ƀiă lah lĕ ntil; kô̆ êng êng tâm nglay săk, Brah Ndu hŏ dơm ăn ăp tĭng nâm păng ŭch.$b$,false),
('bunong-vn','1CO',12,19,null,$b$Lah geh knŏng du kô̆ dơm, ntŭk nâm nglay săk gŭ?$b$,false),
('bunong-vn','1CO',12,20,null,$b$Nanê̆ păng geh âk kô̆, ƀiă lah lĕ kô̆ nây jêng du nglay săk.$b$,false),
('bunong-vn','1CO',12,21,null,$b$Pô ri măt mâu dơi lah ma ti: “Gâp mâu ŭch ma may ôh”. Bôk mâu lĕ dơi lah ma jâng: “Gâp mâu ŭch ma may ôh”.$b$,true),
('bunong-vn','1CO',12,22,null,$b$Ƀiă lah mâu di pô nây ôh yor lah lĕ kô̆ uănh tâm ban ma rdja lơn tâm săk jăn jêng khlay,$b$,false),
('bunong-vn','1CO',12,23,null,$b$jêh ri phung kô̆ he mĭn mâu khư geh âk nau yơk tâm săk jăn, ƀiă lah he yơk ngăn ma păng, jêh ri kô̆ mâu ueh uănh jêng kô̆ geh nau yơk âk lơn.$b$,false),
('bunong-vn','1CO',12,24,null,$b$Bi phung ueh uănh, mâu ŭch ma nau yơk ôh. Ƀiă lah Brah Ndu nkra jêh săk jăn ma nau ŭch ăn nau yơk âk lơn ma lĕ kô̆ mâu geh,$b$,false),
('bunong-vn','1CO',12,25,null,$b$Pô ri tâm du nglay săk nây mâu geh nau tâm pă ôh, ƀiă lah kô̆ ri đah kô̆ aơ păng tâm mât tâm mơh tâm ban.$b$,false),
('bunong-vn','1CO',12,26,null,$b$Lah du kô̆ tâm nglay săk mâp nau ji pô ri lĕ kô̆ êng nau ji tâm ban lĕ, lah bu rnê du kô̆, lĕ kô̆ ƀa ƀă geh nau maak tâm ban lĕ.$b$,false),
('bunong-vn','1CO',12,27,null,$b$Pô ri, lĕ rngôch khân may jêng nglay săk Brah Krist, jêh ri ăp nơm bunuyh jêng kô̆ êng êng.$b$,true),
('bunong-vn','1CO',12,28,null,$b$Tâm mpôl phung chroh, Brah Ndu dơm hŏ di jêh lĕ rngôch bunuyh. Lor lơn păng dơm kôranh oh mon, bar, nơm djôt nau Brah Ndu, pe nơm nti, jêh ma nây phung dơi ƀư nau khlay, phung dơi ƀư bah nau ji, phung dơi kơl bu, phung dơi chiă uănh bu, mâu lah dơi ngơi nau bu êng.$b$,false),
('bunong-vn','1CO',12,29,null,$b$Mâu di ôh lĕ rngôch khân păng jêng oh mon, jêng nơm djôt nau Brah Ndu, mâu lah jêng nơm nti.$b$,false),
('bunong-vn','1CO',12,30,null,$b$Jêh ri mâu di ôh lĕ rngôch dơi ƀư nau khlay, dơi ƀư bơh nau ji bu, dơi gĭt ngơi nau bu êng, mâu lah dơi rblang ngơi nau bu.$b$,false),
('bunong-vn','1CO',12,31,null,$b$Pô ri tâm lĕ nau dơi bu ăn nây, ăn khân may nđơr, gay dơi geh nau dơi khlay jêh ri gâp mra ntĭm trong ueh lơn ma khân may.$b$,true),
('bunong-vn','1CO',13,1,null,$b$Tơ lah gâp ngơi âk nau bunuyh jêh ri nau phung Tông mpăr ueh Brah Ndu, ƀiă lah mâu geh nau rŏng, gâp jêng tâm ban ma chĭng bu goh, mâu lah dang nteh.$b$,true),
('bunong-vn','1CO',13,2,null,$b$Tơ lah gâp geh nau ăn dơi mbơh lor, jêh ri gĭt lĕ nau ndâp, jêh ri lĕ nau gĭt rbăng tơ lah gâp geh lĕ nau chroh kŏ dơi ƀư rlâm yôk, ƀiă lah mâu geh nau rŏng, gâp jêng dơm dam.$b$,false),
('bunong-vn','1CO',13,3,null,$b$Tơ lah gâp tâm pă lĕ ndô ndơ gâp ŭch siăm phung o ach, jêh ri tơ lah gâp jao săk jăn gâp ăn bu gŭch tâm ŭnh, ƀiă lah mâu geh nau rŏng, nau nây mâu khlay ma gâp ôh.$b$,false),
('bunong-vn','1CO',13,4,null,$b$Nau rŏng blau srôih jêh ri bêng ma nau ueh, nau rŏng mâu geh tâm mâu nach mâu lah n'hao êng păng nơm ôh.$b$,true),
('bunong-vn','1CO',13,5,null,$b$Păng mâu dơi rlau mâu lah ƀư lă lêng ôh, nau rŏng mâu geh joi nau ueh ma păng nơm ôh, păng mâu blau nuih ôh, păng mâu đing nau mhĭk ôh.$b$,false),
('bunong-vn','1CO',13,6,null,$b$Păng mâu maak ôh ma nau kue, ƀiă lah păng geh nau maak tâm nau nanê̆ ngăn.$b$,true),
('bunong-vn','1CO',13,7,null,$b$Păng dơn lĕ, chroh lĕ, kâp gân lĕ, srôih lĕ.$b$,true),
('bunong-vn','1CO',13,8,null,$b$Nau rŏng mâu blau lôch ôh, ƀiă lah nau mbơh lor mra lôch; nau ngơi nau bu năch mra dŭt, nau gĭt rbăng mra rlau lôch.$b$,true),
('bunong-vn','1CO',13,9,null,$b$Yor lah nau he gĭt ê rah vah, jêh ri nau he mbơh lor ê rah vah;$b$,false),
('bunong-vn','1CO',13,10,null,$b$ƀiă lah tơ lah nau rah vah mra tât, nau ê rah vah mra rlau lôch.$b$,false),
('bunong-vn','1CO',13,11,null,$b$Dôl gâp hôm jêng kon se, gâp ngơi nâm bu kon se gâp mĭn nâm bu kon se, gâp tâm rlăch nâm bu kon se, tơ lah gâp jêng toyh jêh, gâp cha lơi lĕ nau bơh kon se.$b$,false),
('bunong-vn','1CO',13,12,null,$b$Nar aơ he saơ mâu kloh ang nâm bu tâm măt nar, rnôk nây he mra saơ rah vah ta năp. Nar aơ gâp năl mâu nanê̆ ôh, rnôk nây taơ, gâp mra gĭt năl tâm ban ma bu gĭt năl jêh gâp.$b$,false),
('bunong-vn','1CO',13,13,null,$b$Aƀaơ aơ geh pe ntil hôm, nau chroh, nau kâp gân, jêh ri nau rŏng; ƀiă lah toyh lơn, jêng nau rŏng.$b$,true),
('bunong-vn','1CO',14,1,null,$b$Tĭng joi hom nau rŏng. Ŭch tâm ban lĕ, nau ueh lăng bơh Brah Huêng Ueh, ƀiă lah khlay lơn ma nau mbơh lor.$b$,true),
('bunong-vn','1CO',14,2,null,$b$Yor lah mbu nơm ngơi nau bu năch mâu ngơi ma bunuyh ôh, ƀiă lah ma Brah Ndu; yor lah mâu geh nơm gĭt rbăng ôh, ƀiă lah tâm huêng păng ngơi nau ndâp.$b$,false),
('bunong-vn','1CO',14,3,null,$b$Ƀiă lah mbu nơm mbơh lor, păng ngơi ma bunuyh gay kơl khân păng, tâm n'hao nuih khân păng jêh ri bonh leng khân păng$b$,true),
('bunong-vn','1CO',14,4,null,$b$Mbu nơm ngơi nau bu năch kơl păng nơm, ƀiă lah mbu nơm mbơh lor kơl phung ngih Brah Ndu.$b$,false),
('bunong-vn','1CO',14,5,null,$b$Gâp ŭch ma lĕ rngôch khân may ngơi nau bu năch, ƀiă lah gâp ŭch ngăn ăn khân may mbơh lor. Mbu nơm mbơh lor jêng toyh lơn ma ngơi nau bu năch, knŏng tơ lah geh nơm rblang an pô ri phung ngih Brah Ndu geh nau tâm n'hao nuih.$b$,false),
('bunong-vn','1CO',14,6,null,$b$Aƀaơ, hơi phung oh nâu, tơ lah gâp hăn ma khân may ngơi nau bu năch, moh nau gâp jêng khlay ma khân may, tơ lah gâp mâu ngơi ma nau tâm mpơl ma nau gĭt rbăng, ma nau mbơh lor, mâu lah ma nau nti lah?$b$,false),
('bunong-vn','1CO',14,7,null,$b$Tơ lah ndơ mâu rêh ôh tâm ban ma n'hôm, mâu lah kreh gong rêng, mâu rah vah, mâm bu mra gĭt năl ma bu uh n'hôm, mâu lah kreh gong rêng?$b$,false),
('bunong-vn','1CO',14,8,null,$b$Jêh ri tơ lah bâr nŭng mâu rah vah ôh, mbu nơm mra?$b$,false),
('bunong-vn','1CO',14,9,null,$b$Khân may tâm ban lĕ, tơ lah ma mpiăt khân may, khân may ngơi mâu rah vah, mâm bu dơi gĭt ma nau khân may ngơi? Yor lah khân may ngơi tâm n'hâm sial.$b$,false),
('bunong-vn','1CO',14,10,null,$b$Tâm neh ntu geh âk nau ngơi êng êng, jêh ri ăp rplay ngơi geh nau rblang.$b$,false),
('bunong-vn','1CO',14,11,null,$b$Tơ lah gâp mâu gĭt rbăng nau bu ngơi, gâp mra jêng bu năch ma nơm ngơi, jêh ri nơm ngơi mra jêng bu năch đah gâp.$b$,true),
('bunong-vn','1CO',14,12,null,$b$Tâm ban lĕ khân may, yor lah khân may ŭch nau Brah Huêng Ueh ăn, joi hom gay ma âk dơi kơl phung ngih Brah Ndu.$b$,true),
('bunong-vn','1CO',14,13,null,$b$Yor nây, mbu nơm ngơi nau bu năch, ăn păng mbơh sơm gay geh nau dơi rblang.$b$,true),
('bunong-vn','1CO',14,14,null,$b$Yor lah tơ lah gâp mbơh sơm tâm nau bu năch, huêng gâp gŭ mbơh sơm, ƀiă lah nau gĭt rbăng gâp gŭ dơm dam.$b$,true),
('bunong-vn','1CO',14,15,null,$b$Moh gâp mra ƀư? Gâp mra mbơh sơm ma huêng jêh ri ma nau gĭt rbăng lĕ; gâp mra mprơ ma huêng jêh ri gâp mra mprơ ma nau gĭt rbăng lĕ.$b$,false),
('bunong-vn','1CO',14,16,null,$b$Mâu lah, tơ lah may tâm rnê ma huêng mâm ƀư nơm mâu geh nau ăn tâm phung tâm rƀŭn dơi lah: “Amen” ma nau may mbơh sơm tâm rnê yor lah păng mâu gĭt rbăng nau may ngơi?$b$,false),
('bunong-vn','1CO',14,17,null,$b$Yor lah may mbơh sơm tâm rnê ueh hâu ngăn, ƀiă lah du huê êng mâu geh nau tâm n'hao nuih ôh.$b$,false),
('bunong-vn','1CO',14,18,null,$b$Gâp tâm rnê ma Brah Ndu yor gâp dơi ngơi nau bu năch âk lơn ma lĕ rngôch khân may,$b$,false),
('bunong-vn','1CO',14,19,null,$b$ƀiă lah tâm phung ngih Brah Ndu gâp rŏng lơn ngơi prăm rplay ma nau gĭt rbăng, gay ma nti phung êng, ma jât rbăn rplay tâm nau bu năch.$b$,false),
('bunong-vn','1CO',14,20,null,$b$Hơi phung oh nâu, lơi ta jêng nâm bu kon se ôh tâm nau blau mĭn. Ăn khân may jêng kon se tâm nau mhĭk, ƀiă lah tâm nau blau mĭn ăn khân may jêng bunuyh toyh jêh.$b$,true),
('bunong-vn','1CO',14,21,null,$b$Geh nau nchih jêh tâm nau vay: “Ma phung bunuyh ngơi nau êng jêh ri ma mbung phung bu năch gâp mra ngơi ma phung ƀon lan aơ, jêh ri mâu lĕ khân păng mra gŭ iăt gâp, Kôranh Brah lah”.$b$,false),
('bunong-vn','1CO',14,22,null,$b$Pô ri, nau dơi ngơi nau bu năch jêng ndơ tâm mbên, mâu di ma phung chroh ôh, ƀiă lah ma phung mâu chroh, ƀiă lah nau dơi mbơh lor jêng ndơ tâm mbên mâu di ma phung mâu chroh ôh, ƀiă lah ma phung chroh.$b$,true),
('bunong-vn','1CO',14,23,null,$b$Tơ lah phung ngih Brah Ndu tâm rƀŭn lĕ rngôch ngơi nau bu năch jêh ri phung ê nti mâu lah phung ê lăp chroh, mâm khân păng dĭng mâu lah khân may jêng rluk?$b$,false),
('bunong-vn','1CO',14,24,null,$b$Ƀiă lah tơ lah lĕ rngôch mbơh lor, jêh ri geh du huê ê nti mâu lah du huê ê sĭt chroh păng geh nau phong bơh lĕ rngôch, păng geh nau phat dôih tă bơh lĕ rngôch.$b$,false),
('bunong-vn','1CO',14,25,null,$b$Nau ndâp tâm nuih n'hâm păng mra tâm mpơl; pô ri păng mra kŭp muh măt ta neh yơk mbơh ma Brah Ndu jêh ri mbơh ma Brah Ndu gŭ ndrel ma khân may ngăn ngên.$b$,false),
('bunong-vn','1CO',14,26,null,$b$Hơi phung oh nâu, moh mra ƀư? Tơ lah khân may tâm rƀŭn ăp nơm geh nau mprơh, nau nti, nau tâm mpơl, nau ngơi nau bu năch, mâu lah nau gĭt rblang. Ăn ƀư lĕ ma nau ŭch tâm n'hao nuih.$b$,true),
('bunong-vn','1CO',14,27,null,$b$Tơ lah bu ngơi nau bu năch, ăn geh knŏng bar mâu lah pe nuyh ngơi, jêh ri ăp nơm ngơi tâm groi lor nglĕ, jêh ri ăn geh du huê rblang.$b$,false),
('bunong-vn','1CO',14,28,null,$b$Ƀiă lah tơ lah mâu geh nơm rblang, ăn bu gŭ rklăk tâm phung Ngih Brah Ndu, jêh ri ngơi ma păng nơm jêh ri ma Brah Ndu.$b$,true),
('bunong-vn','1CO',14,29,null,$b$Ăn bar pe nuyh kôranh nơm mbơh lor ngơi, jêh ri ăn bu êng sek uănh nau khân păng ngơi.$b$,true),
('bunong-vn','1CO',14,30,null,$b$Tơ lah du huê gŭ geh nau tâm mpơl, ăn nơm ngơi mra gŭ rklăk.$b$,false),
('bunong-vn','1CO',14,31,null,$b$Yor lah lĕ rngôch khân may dơi mbơh lor du huê du huê, gay ma nti jêh ri n'hao nuih lĕ rngôch.$b$,false),
('bunong-vn','1CO',14,32,null,$b$Jêh ri huêng phung kôranh nơm mbơh lor tông ma phung kôranh nơm mbơh lor.$b$,true),
('bunong-vn','1CO',14,33,null,$b$Yor lah Brah Ndu mâu jêng Brah Ndu nau uh ah ôh, ƀiă lah nau đăp mpăn. Tâm ban ma lĕ ngih Brah Ndu phung kloh ueh,$b$,true),
('bunong-vn','1CO',14,34,null,$b$ăn phung bu ur gŭ rklăk tâm phung ngih Brah Ndu. Yor lah khân păng mâu vay ngơi ôh dôl tâm rƀŭn, ƀiă lah ăn khân păng tông yơk tĭng nâm nau vay lah tâm ban lĕ.$b$,false),
('bunong-vn','1CO',14,35,null,$b$Tơ lah khân păng ŭch gĭt du ntil nau, ăn khân păng ôp sai khân păng ta ngih, yor lah mâu ueh ôh bu ur ngơi tâm ngih Brah Ndu.$b$,false),
('bunong-vn','1CO',14,36,null,$b$Mâm ƀư? Nau Brah Ndu Ngơi luh tă bơh ngih khân ay may hĕ? Mâu lah knŏng ma êng phung khân ay may păng văch tât?$b$,false),
('bunong-vn','1CO',14,37,null,$b$Tơ lah du huê mĭn, păng jêng kôranh nơm mbơh lor mâu lah gĭt năl bâr Brah Ndu, ăn khân păng gĭt năl ma nau gâp nchih ma khân ay may jêng du nau ntăm tă bơh Kôranh Brah.$b$,true),
('bunong-vn','1CO',14,38,null,$b$Ƀiă lah tơ lah du huê mâu gĭt năl ôh, lơi ăn bu năl păng ôh.$b$,false),
('bunong-vn','1CO',14,39,null,$b$Pô ri, hơi phung oh nâu gâp, ŭch hom ma nau dơi mbơh lor, jêh ri lơi ta buay bu ngơi nau bu năch ôh,$b$,true),
('bunong-vn','1CO',14,40,null,$b$ƀiă lah ăn ƀư lĕ rngôch ndơ ma nau sŏng jêh ri ma nau di.$b$,false),
('bunong-vn','1CO',15,1,null,$b$Hơi phung oh nâu, gâp nkah khân may nau mhe mhan gâp mbơh jêh, nau khân may sŏk dơn jêh, tâm nau nây lĕ khân may gŭ rjăp,$b$,true),
('bunong-vn','1CO',15,2,null,$b$jêh ri ma nau nây khân may klaih jêh, tơ lah khân may djôt prăp nau gâp mbơh jêh tơ lah mâu di pô nây, nau khân may chroh jêng dơm dam.$b$,false),
('bunong-vn','1CO',15,3,null,$b$Yor lah gâp ăn ma khân may lor lơn ma lĕ rngôch nâm bu gâp nơm sŏk dơn jêh, pô nây Brah Krist khĭt jêh yor nau tih he, tĭng nâm nau nchih jêh,$b$,true),
('bunong-vn','1CO',15,4,null,$b$bu tâp jêh Păng, tăch pe nar Păng hŏ dâk rêh, tĭng nâm nau nchih jêh,$b$,false),
('bunong-vn','1CO',15,5,null,$b$Păng tâm mpơl jêh Păng nơm ma Y-Sêphas, jêh ri ma phung jât ma bar nuyh.$b$,false),
('bunong-vn','1CO',15,6,null,$b$Jêh ma nây Păng tâm mpơl ma rmeh prăm rhiăng nuyh phung oh nâu tâm du tơ̆ . Âk tâm phung nây hôm rêh, ƀiă lah ƀa ƀă hŏ khĭt jêh.$b$,true),
('bunong-vn','1CO',15,7,null,$b$Jêh ri Păng tâm mpơl ma Y-Yakơ, jêh ri ma lĕ rngôch phung kôranh oh mon.$b$,false),
('bunong-vn','1CO',15,8,null,$b$Jêh ma nây Păng ăt tâm mpơl ma gâp đŏng nâm bu du huê kon bu deh gao nar.$b$,true),
('bunong-vn','1CO',15,9,null,$b$Yor lah gâp jêng kôranh oh mon jê̆ lơn ma lĕ rngôch, gâp mâu khư ôh bu kuăl gâp kôranh oh mon yor lah gâp ƀư mhĭk jêh ma phung Ngih Brah Ndu.$b$,true),
('bunong-vn','1CO',15,10,null,$b$Ma nau Brah Ndu yô̆ gâp dơi jêng nâm bu pô aơ, jêh ri nau păng yô̆ mâu jêng dơm dam ôh ma gâp. Yor lah gâp pah kan âk lơn ma lĕ rngôch khân păng mâu di gâp nơm ôh, ƀiă lah nau yô̆ Brah Ndu gŭ ndrel ma gâp.$b$,false),
('bunong-vn','1CO',15,11,null,$b$Pô nây yơh, gĭt lah gâp, gĭt lah khân păng, nau nây yơh hên nti, jêh ri khân may chroh jêh.$b$,false),
('bunong-vn','1CO',15,12,null,$b$Pô ri tơ lah bu nti ma Brah Krist dâk rêh tă bơh khĭt, mâm ƀư geh ƀa ƀă tâm phung khân may lah mâu geh nau dâk rêh?$b$,true),
('bunong-vn','1CO',15,13,null,$b$Tơ lah mâu geh ôh nau dâk rêh tă bơh phung khĭt, pô ri Brah Krist mâu hôm mâp dâk rêh ôh.$b$,true),
('bunong-vn','1CO',15,14,null,$b$Tơ lah Brah Krist, mâu hôm dâk rêh ôh, nau hên nti jêng dơm dam, jêh ri nau khân may chroh jêng dơm dam lĕ.$b$,false),
('bunong-vn','1CO',15,15,null,$b$Pô ri he jêng phung mbơh tih nau Brah Ndu; yor lah he mbơh ma nau Brah Ndu ăn Brah Yêsu dâk rêh. Ƀiă lah păng mâu hôm ndâk rêh ôh tơ lah nanê̆ phung khĭt mâu hôm dâk rêh.$b$,true),
('bunong-vn','1CO',15,16,null,$b$Tơ lah phung khĭt mâu hôm dâk rêh, Brah Krist mâu hôm dâk rêh ôh.$b$,false),
('bunong-vn','1CO',15,17,null,$b$Jêh ri tơ lah Brah Krist mâu hôm dâk rêh nau chroh khân may jêng dơm dam, khân may ăt hôm gŭ tâm nau tih khân may yơh.$b$,true),
('bunong-vn','1CO',15,18,null,$b$Pô nây lĕ phung khĭt jêh tâm Brah Krist jêng roh jêh.$b$,true),
('bunong-vn','1CO',15,19,null,$b$Tơ lah knŏng tâm nau rêh aơ he geh nau kâp gân tâm Brah Krist, he jêng phung rêh ni lơn ma lĕ rngôch bunuyh yơh.$b$,false),
('bunong-vn','1CO',15,20,null,$b$Ƀiă lah aƀaơ Brah Krist dâk rêh jêh bơh phung khĭt. Păng jêng play lor ma phung khĭt jêh.$b$,true),
('bunong-vn','1CO',15,21,null,$b$Pô ri, nau khĭt tât jêh yor ma du huê bunuyh, jêh ri yor du huê bunuyh lĕ nau dâk rêh bơh phung khĭt tât jêh.$b$,false),
('bunong-vn','1CO',15,22,null,$b$Yor lah tâm ban ma Y-Ađam lĕ rngôch khĭt, tâm ban lĕ rngôch mra dâk rêh tâm Brah Krist.$b$,false),
('bunong-vn','1CO',15,23,null,$b$Ƀiă lah ăp nơm dăp rep êng păng. Brah Krist nâm bu play lor lơn, jêh ri phung jêng ndơ Brah Krist ta nar păng mra văch.$b$,false),
('bunong-vn','1CO',15,24,null,$b$Rnôk nây mra tât nar lôch, tơ lah păng jao ƀon bri hađăch ma Brah Ndu, Mbơ̆ , jêh păng ƀư rai lĕ nau chiă uănh, lĕ nau dơi toyh, jêh ri lĕ nau brah.$b$,true),
('bunong-vn','1CO',15,25,null,$b$Yor lah păng chiă uănh tât păng dơm lĕ phung rlăng păng tâm dâng jâng păng.$b$,false),
('bunong-vn','1CO',15,26,null,$b$Nơm rlăng dăch dŭt păng mra ƀư rai jêng nau khĭt.$b$,false),
('bunong-vn','1CO',15,27,null,$b$Yor lah Brah Ndu dơm jêh lĕ rngôch ndơ tâm dâng jâng păng. Tơ lah, bu lah: “Lĕ rngôch mpa lăp păng da dê jêh”. Pô ri mâu kơp ôh nđâp ma nơm nglăp lĕ rngôch mpa nây ma păng.$b$,false),
('bunong-vn','1CO',15,28,null,$b$Tơ lah lĕ rngôch mpa lăp păng da dê jêh, dôl nây Kon Păng nơm lĕ mra lăp Nơm hŏ nglăp ma păng lĕ rngôch mpa, pô nây mơ Brah Ndu mra jêng lĕ ma lĕ rngôch.$b$,false),
('bunong-vn','1CO',15,29,null,$b$Tơ lah mâu di pô nây, mâm dơi rblang nau bu dơn nau ƀaptem yor phung khĭt? Tơ lah phung khĭt mâu hôm dâk rêh ôh, mâm ƀư bu dơn ƀaptem yor ma khân păng?$b$,true),
('bunong-vn','1CO',15,30,null,$b$Mâm ƀư hên gŭ tâm nau rêh ni ăp mông?$b$,true),
('bunong-vn','1CO',15,31,null,$b$Hơi oh nâu, gâp mbơh ma khân may jêng nau chrêk rmah ma gâp tâm Yêsu Krist, Kôranh Brah he, ăp nar gâp gŭ dăch nau khĭt!$b$,true),
('bunong-vn','1CO',15,32,null,$b$Tơ lah ta năp măt bunuyh gâp tâm lơh đah phung jun ta ƀon Êphêsô moh nau khlay ma gâp tơ lah phung khĭt mâu hôm dâk rêh ôh? “Ăn he sông sa jêh ri nhêt yor lah ôi taơ he mra khĭt”.$b$,false),
('bunong-vn','1CO',15,33,null,$b$Lơi ndơm khân may nơm ma nau nây ôh. “Phung mĭt jiăng mhĭk ƀư rai nau gŭ ngao krao sach ueh”.$b$,true),
('bunong-vn','1CO',15,34,null,$b$Ăn plơ̆ sĭt ma nau di jêh ri lơi ƀư tih ôh. Yor lah ƀa ƀă mâu gĭt năl Brah Ndu ôh. Gâp lah nau aơ gay ƀư bêk khân may.$b$,false),
('bunong-vn','1CO',15,35,null,$b$Klăp lah geh lĕ tâm khân may mra ôp: “Mâm ƀư phung khĭt dơi dâk rêh đŏng? Moh ntil săk jăn khân păng mra njêng đŏng?”$b$,true),
('bunong-vn','1CO',15,36,null,$b$Hơi bunuyh rluk? Găr may tuch mâu dơi rêh đŏng ôh tơ lah păng mâu khĭt.$b$,true),
('bunong-vn','1CO',15,37,null,$b$Ndơ may tuch nây, găr ba mâu lah găr êng êng mra hon, jêng găr dơm, nâm bu găr ba me mâu lah ntil găr êng.$b$,false),
('bunong-vn','1CO',15,38,null,$b$Ƀiă lah Brah Ndu nsrom an găr nây ăn geh săk tĭng nâm păng ŭch, ăp ntil găr geh săk êng êng tĭng nâm ntil păng.$b$,false),
('bunong-vn','1CO',15,39,null,$b$Lĕ rngôch nglay săk mâu geh tâm ban ôh, nglay săk bunuyh êng, nglay mpô mpa êng, nglay phung sĭm êng, nglay ka êng.$b$,false),
('bunong-vn','1CO',15,40,null,$b$Geh lĕ nglay tâm trôk jêh ri săk jăn ta neh ntu, ƀiă lah nau chrêk rmah săk jăn tâm trôk êng đah nau chrêk rmah săk jăn ta neh ntu.$b$,false),
('bunong-vn','1CO',15,41,null,$b$Nau chrêk rmah nar êng, nau chrêk rmah khay êng jêh ri nau chrêk rmah mănh êng, nđâp nau chrêk rmah du rplay mănh aơ, êng lĕ đah nau chrêk rmah du rplay mănh êng êng.$b$,false),
('bunong-vn','1CO',15,42,null,$b$Tâm ban lĕ tâm nau dâk rêh đŏng tă bơh khĭt. Săk jăn bu tuch tâm neh mra ôm rai, ƀiă lah săk jăn dâk rêh nây mâu blau ôm rai ôh.$b$,true),
('bunong-vn','1CO',15,43,null,$b$Bu tuch păng ƀơ̆ ƀơch păng dâk rêh jêng chrêk rmah Bu tuch păng rdja, păng dâk rêh jêng ktang.$b$,false),
('bunong-vn','1CO',15,44,null,$b$Bu tuch păng ma nglay săk păng dâk rêh jêng săk brah. Tơ lah geh nglay săk, mra geh đŏng nglay săk brah.$b$,false),
('bunong-vn','1CO',15,45,null,$b$Yor nây geh nau nchih jêh pô aơ: “Bunuyh lor lơn Y-Ađam, jêng huêng rêh”. Y-Ađam dăch dŭt jêng huêng dơi ăn rêh.$b$,false),
('bunong-vn','1CO',15,46,null,$b$Mâu di huêng brah văch lor, ƀiă lah nglay săk huêng brah văch pa kơi.$b$,true),
('bunong-vn','1CO',15,47,null,$b$Bunuyh lor, luh tă bơh neh, jêng ndruyh neh, bunuyh pa kơi luh tă bơh trôk.$b$,true),
('bunong-vn','1CO',15,48,null,$b$Tâm ban ma nơm tă bơh neh, pô nây, lĕ phung bơh neh jêh ri tâm ban ma nơm tă bơh trôk, nâm nđĕ lĕ phung bơh trôk.$b$,false),
('bunong-vn','1CO',15,49,null,$b$Jêh ri nâm bu he djôt jêh rup tă bơh neh, he mra djôt tâm ban lĕ rup tă bơh trôk.$b$,false),
('bunong-vn','1CO',15,50,null,$b$Hơi phung oh nâu, gâp lah ma khân may, nglay săk jêh ri mham mâu dơi dơn bri hađăch Brah Ndu ôh. Nau ôm, rai mâu lĕ dơi dơn nau mâu blau ôm rai.$b$,true),
('bunong-vn','1CO',15,51,null,$b$Aơ, gâp mbơh nau khlay nđâp aơ ma khân may. He mâu mra khĭt lĕ rngôch ôh, ƀiă lah lĕ rngôch he mra rgâl,$b$,false),
('bunong-vn','1CO',15,52,null,$b$ƀât lât nâm bu mƀrêh măt, tâm mông bu uh nŭng nglĕ dŭt pô ri lah bu uh nŭng nây phung khĭt mra dâk rêh mâu hôm blau ôm ôh, jêh ri lĕ rngôch phung he mra rgâl. Pô ri săk jăn he blau khĭt, păng nsrom ndơ mâu blau khĭt, săk jăn he blau ôm, păng nsrom ndơ mâu blau ôm.$b$,false),
('bunong-vn','1CO',15,53,null,$b$Pô ri săk jăn blau ôm aơ, mra nsrom ndơ mâu blau ôm, jêh ri tơ lah săk jăn blau khĭt, mra nsrom ndơ mâu blau khĭt.$b$,false),
('bunong-vn','1CO',15,54,null,$b$Tơ lah săk jăn blau ôm aơ, mra nsrom ndơ mâu blau ôm, jêh ri tơ lah săk jăn blau khĭt aơ, mra nsrom ndơ mâu blau khĭt, ri mơ nau bu nchih jêh jêng di ngăn pô aơ: “Nau dơi rvăn jêh nau khĭt”.$b$,false),
('bunong-vn','1CO',15,55,null,$b$Hơi nau khĭt, hŏ nau dơi may? Hơi nau khĭt, hŏ mpôch may?$b$,true),
('bunong-vn','1CO',15,56,null,$b$Nau tih jêng mpôch ma nau khĭt, jêh ri nau vay, jêng nau brah ma nau tih.$b$,true),
('bunong-vn','1CO',15,57,null,$b$Ƀiă lah ăn he tâm rnê ma Brah Ndu, păng ăn nau dơi ma he tâm Kôranh he, Yêsu Krist.$b$,false),
('bunong-vn','1CO',15,58,null,$b$Pô ri, hơi phung oh nâu gâp rŏng ngăn ngên, ăn khân may gŭ răp jăp, lơi mpât n'gơ jêh ri pah kan ăn ktang ƀa ƀơ ma Kôranh Brah, dôl khân may gĭt kan khân may pah mâu mra jêng dơm dam ôh tâm Kôranh Brah.$b$,true),
('bunong-vn','1CO',16,1,null,$b$Bi nau nhhơr gay kơl phung kloh ueh nâm bu gâp ntăm jêh ma phung ngih Brah Ndu ta n'gor Galati, ăn khân may ƀư tâm ban lĕ.$b$,true),
('bunong-vn','1CO',16,2,null,$b$Ta nar nguay, ăp nar pơh ăn ăp nơm khân may prăp tĭng nâm dơi geh tâm ngih nơm jêh ri bu mâu kâp tât gâp ôh gay ma dơn ndơ bu ăn.$b$,false),
('bunong-vn','1CO',16,3,null,$b$Jêh ri tơ lah gâp tât gâp mra njuăl hăn bunuyh khân may săch ndrel ma sămƀŭt gâp hăn, gay ma ndơ̆ ndơ khân may nhhơr ma ƀon Yêrusalem.$b$,false),
('bunong-vn','1CO',16,4,null,$b$Jêh ri tơ lah khlay nđâp ma gâp nơm mra hăn, khân păng mra hăn ndrel ma gâp.$b$,false),
('bunong-vn','1CO',16,5,null,$b$Gâp mra hăn ta khân may jêh ri gâp rgăn n'gor Masêđôn, yor lah gâp ŭch rgăn n'gor Masêđôn.$b$,true),
('bunong-vn','1CO',16,6,null,$b$Klăp lah gâp mra gŭ ndrel ma khân may, mâu lah rgăn yan sĭt puh ndrel ma khân may, gay ma khân may dơi njŭn gâp, ta ntŭk gâp mra hăn.$b$,false),
('bunong-vn','1CO',16,7,null,$b$Yor lah gâp mâu ŭch ôh saơ khân may knŏng dôl gâp hăn rgăn ta nĕ; gâp gay ŭch mra gŭ ndrel ma khân may jŏ nar, tơ lah Kôranh Brah ăn.$b$,false),
('bunong-vn','1CO',16,8,null,$b$Ƀiă lah gâp mra gŭ ta ƀon Êphêsô tât nar Pantơkôt.$b$,false),
('bunong-vn','1CO',16,9,null,$b$Yor lah mpông pêr toyh pơk jêh ma gâp dơi pah kan khlay, jêh ri phung rlăng jêng âk.$b$,false),
('bunong-vn','1CO',16,10,null,$b$Tơ lah Y-Timôthê tât, ăn khân may rom păng ma nau nơih, yor lah păng pah kan ma Kôranh Brah, tâm ban ma gâp.$b$,true),
('bunong-vn','1CO',16,11,null,$b$Lơi ăn bu tâm rmot ma păng ôh. Njŭn leo păng ma nau đăp mpăn gay ma păng plơ̆ sĭt ta gâp, yor lah gâp gŭ kâp păng ndrel ma phung oh nâu.$b$,false),
('bunong-vn','1CO',16,12,null,$b$Bi nâu he, Y-Apôlôs, gâp ntăm jêh, ăn păng hăn ta khân may ndrel ma phung oh nâu, ƀiă lah mâu di păng ŭch hăn aƀaơ ôh păng mra hăn tơ lah păng ru.$b$,true),
('bunong-vn','1CO',16,13,null,$b$Gŭ njrăng ƀa ƀơ. Gŭ nâp tâm nau chroh. Ăn khân may jêng bunuyh janh ktang.$b$,true),
('bunong-vn','1CO',16,14,null,$b$Ăn khân may ƀư lĕ rngôch ndơ ma nau rŏng.$b$,false),
('bunong-vn','1CO',16,15,null,$b$Hơi phung oh nâu, aƀaơ khân may gĭt ngih Y-Stêphanas jêng phung chroh lor lơn tâm n'gor Akai, jêh ri khân păng pah kan sân săk jăn ma phung kloh ueh.$b$,true),
('bunong-vn','1CO',16,16,null,$b$Ăn khân may yơk ma phung bunuyh nâm nđĕ, jêh ri ma ăp nơm pah kan nâm nđĕ.$b$,false),
('bunong-vn','1CO',16,17,null,$b$Gâp maak saơ Y-Stêphanas Y-Pôrtunatus jêh ri Y-Akaikus. Khân păng ntrok ndŭt kơi khân may.$b$,false),
('bunong-vn','1CO',16,18,null,$b$Yor lah khân păng bonh jêh huêng gâp jêh ri huêng khân may. Ăn khân may tâm rnê ma phung bunuyh nâm bu pô nây.$b$,false),
('bunong-vn','1CO',16,19,null,$b$Phung ngih Brah Ndu n'gor Asi njuăl nau khâl đah khân may Y-Akilas jêh ri H'Prisil ndrel ma phung ngih Brah Ndu tâm ngih khân păng njuăl âk nau khâl ma khân may tâm Kôranh Brah.$b$,true),
('bunong-vn','1CO',16,20,null,$b$Lĕ rngôch phung oh nâu njuăl nau khâl đah khân may. Ăn khân may tâm khâl ndrăng khân may ma nau chŭm kloh ueh.$b$,false),
('bunong-vn','1CO',16,21,null,$b$Gâp nơm, Y-Pôl, khâl đah khân may ma ti gâp nơm.$b$,true),
('bunong-vn','1CO',16,22,null,$b$Tơ lah du huê mâu rŏng ôh ma Kôranh Brah ăn nau rtăp rak tât ma păng. Văch hom, Ơ Kôranh Brah!$b$,true),
('bunong-vn','1CO',16,23,null,$b$Ăn nau Kôranh Brah Yêsu yô̆ gŭ ndrel ma khân may.$b$,false),
('bunong-vn','1CO',16,24,null,$b$Nau gâp rŏng gŭ ndrel ma lĕ rngôch khân may tâm Yêsu Krist. Amen!$b$,false);
insert into public.bible_headings (translation_id, book_code, chapter, before_verse, position, kind, text) values
('bunong-vn','1CO',1,1,0,'heading',$b$Ntŭk Dơn Sămƀŭt Jêh Ri Nau Khâl$b$),
('bunong-vn','1CO',1,4,1,'heading',$b$Nau Tâm Rnê$b$),
('bunong-vn','1CO',1,10,2,'heading',$b$Nau Nti Ma Nau Tâm Rnglăp$b$),
('bunong-vn','1CO',1,18,3,'heading',$b$Nau Gĭt Mĭn Neh Ntu Jêh Ri Nau Gĭt Mĭn Brah Ndu$b$),
('bunong-vn','1CO',2,1,0,'heading',$b$Mâm Ƀư Y-Pôl Nti Lah$b$),
('bunong-vn','1CO',3,1,0,'heading',$b$Nau Tâm Pă Tâm Ngih Brah Ndu Ta Ƀon Kôrintô$b$),
('bunong-vn','1CO',4,1,0,'heading',$b$Knŏng Kôranh Brah Geh Nau Dơi Phat Dôih$b$),
('bunong-vn','1CO',5,1,0,'heading',$b$Nau Mhĭk Tâm Ƀon Kôrintô$b$),
('bunong-vn','1CO',6,1,0,'heading',$b$Nau Phat Dôih Ndrăng Phung Chroh$b$),
('bunong-vn','1CO',7,1,0,'heading',$b$Nau Plơ̆ Lah Ma Phung Kôrintô Ôp Nau Tâm Gŭ Ur Sai$b$),
('bunong-vn','1CO',8,1,0,'heading',$b$Nau Mplơ̆ Lah Ma Phung Kôrintô Ôp Nau Sa Ndơ Ƀư Brah$b$),
('bunong-vn','1CO',9,1,0,'heading',$b$Kan Khlay Phung Kôranh Oh Mon$b$),
('bunong-vn','1CO',10,1,0,'heading',$b$Nau Nti Tă Bơh Ƀon Lan Israel$b$),
('bunong-vn','1CO',11,2,0,'heading',$b$Ndơ Nkrơ̆ Phung Bu Ur Dôl Tâm Rƀŭn$b$),
('bunong-vn','1CO',11,17,1,'heading',$b$Nau Nhêt Sa Tâm Êp Ma Nau Chroh$b$),
('bunong-vn','1CO',12,1,0,'heading',$b$Nau Brah Huêng Ueh Ăn$b$),
('bunong-vn','1CO',13,1,0,'heading',$b$Nau Rŏng$b$),
('bunong-vn','1CO',14,1,0,'heading',$b$Nau Dơi Ăn Ngơi Nau Bu Năch Jêh Ri Nau Dơi Ăn Mbơh Lor$b$),
('bunong-vn','1CO',15,1,0,'heading',$b$Nau Dâk Rêh$b$),
('bunong-vn','1CO',16,1,0,'heading',$b$Nau Nhhơr Ma Brah Ndu Nau Nti Êng Jêh Ri Nau Khâl$b$);
insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', '2CO', $b$II Kôrintô$b$, $b$["Sămƀŭt Rơh Bar Y-Pôl Njuăl Ma Phung", "KÔRINTÔ"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','2CO',1,1,null,$b$Y-Pôl, du huê kôranh oh mon Yêsu Krist, tĭng nâm nau Brah Ndu ŭch, jêh ri Y-Timôthê, oh he. Nchih ma phung ngih Brah Ndu ta ƀon Kôrintô, njuăl ma lĕ rngôch phung kloh ueh gŭ tâm n'gor Akai:$b$,true),
('bunong-vn','2CO',1,2,null,$b$Ăn khân may geh nau yô̆ jêh ri nau đăp mpăn bơh Brah Ndu, Mbơ̆ he, jêh ri Yêsu Krist, Kôranh Brah he.$b$,false),
('bunong-vn','2CO',1,3,null,$b$Mât ton ma Brah Ndu, Mbơ̆ Kôranh Brah he, Brah Yêsu, gĭt nau yô̆ jêh ri Brah Ndu ma lĕ nau bonh.$b$,true),
('bunong-vn','2CO',1,4,null,$b$Păng bonh he tâm lĕ nau rêh ni he, pô ri he dơi tâm bonh mbu nơm gŭ tâm nau rêh ni ma nau bonh Brah Ndu dŏng ŭch tâm bonh ndrăng he.$b$,false),
('bunong-vn','2CO',1,5,null,$b$Yor lah nâm bu nau rêh ni Brah Krist mbêng tâm he, tâm ban lĕ ma Brah Krist nau tâm bonh nuih he jêng âk rmeh.$b$,false),
('bunong-vn','2CO',1,6,null,$b$Tơ lah he geh nau rêh ni, nau nây jêng nau tâm bonh jêh ri tâm rklaih khân may; tơ lah hên geh nau bonh, nau nây jêng nau bonh nuih khân may. Păng jêng nau ngăn ma nau khân may srôih nau rêh ni nâm bu hên geh.$b$,false),
('bunong-vn','2CO',1,7,null,$b$Jêh ri nau hên kâp gân ma khân may jêng nâp jêh; yor lah hên gĭt tơ lah khân may dơn nau rêh ni ndrel ma hên, khân may mra geh nau tâm bonh nuih ndrel ma hên.$b$,false),
('bunong-vn','2CO',1,8,null,$b$Hơi phung oh nâu hên mâu ŭch ôh ma khân may mâu gĭt nau rêh ni tât jêh ma hên tâm n'gor Asi. Yor lah hên geh nau jâk ngăn rlau ma hên dơi dơn, tât hên rdja nuih n'hâm mâu hôm ŭch gŭ rêh ôh.$b$,true),
('bunong-vn','2CO',1,9,null,$b$Pô ri hên mĭn ma hên sŏk dơn jêh nau phat dôih ăn khĭt, gay ma hên rnơm, mâu di ma hên nơm ôh, ƀiă lah ma Brah Ndu, Nơm ăn dâk rêh phung khĭt.$b$,false),
('bunong-vn','2CO',1,10,null,$b$Păng yơh tâm rklaih jêh he bơh nau khĭt toyh, jêh ri Păng mra tâm rklaih he; jêh ri he kâp gân ma Păng mra tâm rklaih tay he.$b$,false),
('bunong-vn','2CO',1,11,null,$b$Khân may tâm ban lĕ kơl hên tâm nau mbơh sơm, gay ma nau yô̆ hên geh jêh yor âk bunuyh mbơh sơm, pô ri âk bunuyh mra tâm rnê ma Brah Ndu yor hên.$b$,false),
('bunong-vn','2CO',1,12,null,$b$Yor lah hên geh nau tâm rnê ma hên nơm tâm nau mbơh bơh nuih n'hâm sŏng hên ma nau hên gŭ ngao krao sach tâm neh ntu jêh ri ta năp khân may ma nau kloh ueh jêh ri nau răp jăp bơh Brah Ndu, mâu di nau blau mĭn tâm nglay săk ôh, lah ma nau yô̆ bơh Brah Ndu.$b$,true),
('bunong-vn','2CO',1,13,null,$b$Yor lah hên nchih ma khân may knŏng nau khân may dơi uănh jêh ri gĭt rbăng, jêh ri gâp kâp gân ma khân may mra gĭt rbăng lĕ.$b$,false),
('bunong-vn','2CO',1,14,null,$b$Nâm bu khân may gĭt rbăng jêh du kô̆, gay ma khân may dơi geh nau tâm rnê yor hên, jêh ri hên geh nau tâm rnê yor khân may ta nar Kôranh Brah Yêsu.$b$,false),
('bunong-vn','2CO',1,15,null,$b$Yor lah gâp gĭt nau aơ ngăn, gâp ŭch hăn ta khân may lor, gay khân may mra dơi geh nau Brah Ndu yô̆ bar tơ̆ .$b$,true),
('bunong-vn','2CO',1,16,null,$b$Gâp ŭch veh khâl khân may dôl gâp hăn ta n'gor Masêđôn, jêh nây plơ̆ tă bơh n'gor Masêđôn sĭt đŏng ta khân may, jêh ri khân may mra kơl gâp hăn tât ta n'gor Yuđa.$b$,false),
('bunong-vn','2CO',1,17,null,$b$Lah gâp ƀư pô nây, gâp ƀư vât vâng đŏng? Mâu lah nau gâp mĭn nây mra jêng tĭng nâm nglay săk lah geh tâm gâp geh tơ̆ lah “Ơ”, geh tơ̆ lah “Mâu” ôh?$b$,false),
('bunong-vn','2CO',1,18,null,$b$Nanê̆ nâm bu nau Brah Ndu jêng răp jăp, nau hên ngơi jêh ma khân may, geh tơ̆ lah “Ơ”, geh tơ̆ lah “Mâu” ôh!$b$,false),
('bunong-vn','2CO',1,19,null,$b$Yor lah Yêsu Krist, Kon Brah Ndu, tâm Păng hên nti lah ta nklang khân may, gâp, Y-Silvan, jêh ri Y-Timôthê, mâu ôh geh tơ̆ lah “Ơ”, geh tơ̆ lah “Mâu”, ƀiă lah tâm Păng “Ơ” mro.$b$,false),
('bunong-vn','2CO',1,20,null,$b$Yor lah tâm Păng, lĕ rngôch nau Brah Ndu ton “Ơ” ngăn. Yor lah nây he lah: “Amen”, gay tâm rnê ma Brah Ndu.$b$,false),
('bunong-vn','2CO',1,21,null,$b$Brah Ndu yơh jêng nơm ƀư nâp hên đah khân may tâm Brah Krist, jêh ri troch jêh dak ngi ta he.$b$,false),
('bunong-vn','2CO',1,22,null,$b$Păng yơh tâp pŏng he, jêh ri ăn Brah Huêng Ueh păng gŭ tâm nuih n'hâm he jêng play dak bôk.$b$,false),
('bunong-vn','2CO',1,23,null,$b$Gâp kuăl Brah Ndu jêng nơm mbơh huêng gâp. Gâp mâu hăn ôh ma ƀon Kôrintô yor gâp ŭch yô̆ khân may.$b$,true),
('bunong-vn','2CO',1,24,null,$b$Mâu di hên ŭch jêng kôranh ma nau chroh khân may ôh, ƀiă lah hên pah kan ŭch kơl khân may geh nau maak, yor lah khân may gŭ nâp tâm nau chroh.$b$,false),
('bunong-vn','2CO',2,1,null,$b$Gâp mĭn jêh tâm gâp nơm mâu ŭch plơ̆ sĭt ma khân may ma nau rngot ôh.$b$,true),
('bunong-vn','2CO',2,2,null,$b$Tơ lah gâp ƀư rngot khân may, mbu dơi ƀư maak gâp, knŏng nơm gâp rngot jêh?$b$,true),
('bunong-vn','2CO',2,3,null,$b$Gâp nchih tâm ban ma gâp ƀư jêh pô ri tơ lah gâp tât gâp mâu mra geh nau rngot bơh phung gâp ŭch geh nau maak. Gâp geh nau rnơm tâm lĕ rngôch khân may, gay ma nau maak gâp mra jêng nau maak lĕ rngôch khân may.$b$,true),
('bunong-vn','2CO',2,4,null,$b$Yor lah gâp nchih jêh ma khân may bơh lĕ nau rêh ni, ma nuih n'hâm rngot ngăn, jêh ri ma âk dak măt, mâu di gay ƀư ma rngot khân may ôh, ƀiă lah gay ma khân may gĭt nau gâp rŏng ngăn ngên ma khân may.$b$,false),
('bunong-vn','2CO',2,5,null,$b$Tơ lah du huê ƀư nau rngot, mâu di păng ƀư rngot ma gâp ôh, ƀiă lah du kô̆ ma lĕ rngôch khân may (Gâp mâu ŭch ngơi rlau keh ôh).$b$,true),
('bunong-vn','2CO',2,6,null,$b$Nau tâm rmal bơh lĕ bunuyh jêng tŏng jêh ma du huê nâm bu pô nây.$b$,false),
('bunong-vn','2CO',2,7,null,$b$Aƀaơ ri ueh lơn khân may yô̆ nau tih jêh ri bonh nuih păng, klach lah păng jêng jâk ma nau rngot ir.$b$,false),
('bunong-vn','2CO',2,8,null,$b$Pô ri gâp vơh vơl ma khân may tâm mpơl nau rŏng ma păng.$b$,false),
('bunong-vn','2CO',2,9,null,$b$Yor nây gâp nchih jêh sămƀŭt ma khân may, gay rlong uănh khân may, gĭt lah khân may tông bâr tâm lĕ rngôch ndơ.$b$,false),
('bunong-vn','2CO',2,10,null,$b$Ƀiă lah mbu nơm khân may yô̆ an, gâp yô̆ an lĕ. Tơ lah moh ndơ gâp yô̆ an jêh, gâp ƀư pô nây yor khân may ta năp Brah Krist,$b$,true),
('bunong-vn','2CO',2,11,null,$b$gay lơi ăn Satan dơi đah he; yor lah he gĭt jêh nau păng ŭch ƀư.$b$,false),
('bunong-vn','2CO',2,12,null,$b$Tơ lah gâp tât ta ƀon Trôas gay nti lah nau mhe mhan ueh Brah Krist, geh du mlâm mpông sâng ta nây Kôranh Brah pơk jêh ma gâp,$b$,true),
('bunong-vn','2CO',2,13,null,$b$ƀiă lah nau mĭn gâp mâu dơi gŭ rlu ôh yor lah gâp mâu saơ oh gâp, Y-Tit, ta nây. Yor nây jêh gâp khâl ta phung khân păng, gâp du hăn ma n'gor Masêđôn nau dơi tâm Brah Krist.$b$,false),
('bunong-vn','2CO',2,14,null,$b$Ƀiă lah tâm rnê ma Brah Ndu, nơm njŭn hên ma nau dơi ƀa ƀơ tâm Brah Krist, jêh ri tâm he păng nkhŭt lam ntŭk ndơ ƀâu kah nau gĭt năl păng.$b$,true),
('bunong-vn','2CO',2,15,null,$b$Yor lah hên jêng ndơ ƀâu kah Brah Krist ma Brah Ndu tâm phung klaih jêh, jêh ri phung rai yot.$b$,false),
('bunong-vn','2CO',2,16,null,$b$Ma du phung aơ jêng ndơ ƀâu nau khĭt, ăn nau khĭt, ma du phung êng jêng ndơ rêh ăn nau rêh. Mbu nơm dơi gĭt rbăng nau aơ?$b$,false),
('bunong-vn','2CO',2,17,null,$b$Yor lah hên mâu ƀư tih ma Nau Brah Ndu Ngơi ôh, nâm bu âk bunuyh ƀư, ƀiă lah hên jêng bunuyh răp jăp ngơi tă bơh Brah Ndu ta năp Brah Ndu tâm Brah Krist.$b$,false),
('bunong-vn','2CO',3,1,null,$b$Mâm ƀư hên plơ̆ tâm rnê ma hên nơm? Mâu lah hên ŭch nâm bu phung êng lĕ sămƀŭt tâm rnê ma hên, ndơ̆ ma khân may, mâu lah tă bơh khân may?$b$,true),
('bunong-vn','2CO',3,2,null,$b$Khân may yơh jêng sămƀŭt tâm rnê ma hên, nchih jêh tâm nuih n'hâm hên, lĕ rngôch bunuyh gĭt năl jêh ri uănh;$b$,true),
('bunong-vn','2CO',3,3,null,$b$jêh ri khân may tâm mpơl khân may jêng sămƀŭt bơh Brah Krist, nchih jêh ma kan hên, mâu di ma dak ôch, ƀiă lah ma Brah Huêng Ueh Brah Ndu rêh, mâu ta lŭ mpơng ƀiă lah ta kđar nuih n'hâm bunuyh.$b$,false),
('bunong-vn','2CO',3,4,null,$b$Pô nây yơh nau rnơm hên geh tâm Brah Krist ta năp Brah Ndu.$b$,true),
('bunong-vn','2CO',3,5,null,$b$Mâu di hên dơi mĭn ma du ntil nau dơi luh bơh hên nơm ôh, ƀiă lah nau dơi hên luh bơh Brah Ndu.$b$,false),
('bunong-vn','2CO',3,6,null,$b$Păng ăn hên dơi jêng oh mon ktang ma nau tâm rnglăp mhe, mâu geh tă bơh sămƀŭt ôh, ƀiă lah bơh Brah Huêng Ueh, yor lah sămƀŭt ƀư ăn khĭt, ƀiă lah Brah Huêng Ueh ăn rêh.$b$,false),
('bunong-vn','2CO',3,7,null,$b$Pô ri tơ lah kan nau khĭt, bu nchih tor ta lŭ jêh, tât ma nau chrêk rmah tât phung Israel mâu dơi uănh ta muh măt Y-Môis yor nau ral, nđâp tơ lah nau rmah nây gŭ ƀât lât kđôi lĕ.$b$,true),
('bunong-vn','2CO',3,8,null,$b$Mâm ƀư kan bơh Brah Huêng Ueh mâu mra geh nau chrêk rmah lơn ma nây?$b$,false),
('bunong-vn','2CO',3,9,null,$b$Yor lah tơ lah kan nau tâm rmah geh nau chrêk rmah, pô ri kan kơp sŏng geh nau chrêk rmah rlau lơn.$b$,false),
('bunong-vn','2CO',3,10,null,$b$Jêh ri nanê̆ nau chrêk rmah tât jêh mâu hôm jêng chrêk rmah ôh yor nau chrêk rmah aơ jêng rlau lơn ma nây$b$,false),
('bunong-vn','2CO',3,11,null,$b$Tơ lah ndơ gŭ ƀât lât geh nau chrêk rmah, pô ri ndơ gŭ mro mra geh nau chrêk rmah lơn.$b$,false),
('bunong-vn','2CO',3,12,null,$b$Yor he geh nau kâp gân nâm nđĕ geh nau janh ngơi,$b$,true),
('bunong-vn','2CO',3,13,null,$b$jêh ri he mâu mra ƀư nâm bu Y-Môis ôh, yor lah păng nkŭm lơi muh măt păng ma bok, gay ma phung Israel mâu dơi uănh ôh ma nau ral gŭ knŏng ƀât lât.$b$,false),
('bunong-vn','2CO',3,14,null,$b$Ƀiă lah nau mĭn păng jêng dăng jêh; yor lah tât ta nar aơ tơ lah khân păng uănh nau tâm rnglăp ơm, bok nây ăt hôm, yor lah knŏng tâm Brah Krist yơh dơi sŏk lơi bok nây.$b$,false),
('bunong-vn','2CO',3,15,null,$b$Tât ta nar aơ lĕ tơ lah bu uănh ndrom sămƀŭt Y-Môis, bok nkŭm lơi nuih n'hâm khân păng.$b$,false),
('bunong-vn','2CO',3,16,null,$b$Tơ lah bu sĭt ma Kôranh Brah, bok nây bu sŏk lơi.$b$,false),
('bunong-vn','2CO',3,17,null,$b$Pô ri Kôranh Brah jêng Brah Huêng Ueh, jêh ri ta ntŭk Brah Huêng Ueh Kôranh Brah gŭ, ta nây geh nau đăp mpăn.$b$,false),
('bunong-vn','2CO',3,18,null,$b$Jêh ri lĕ rngôch he ma muh măt mâu nkŭm, he uănh nâm bu tâm măt nar nau chrêk rmah Kôranh Brah, jêh ri he geh nau tâm rgâl tĭng nâm rup păng bơh du ntil nau chrêk rmah ma nau chrêk rmah êng. Nau aơ luh bơh Kôranh Brah nơm jêng Brah Huêng Ueh.$b$,false),
('bunong-vn','2CO',4,1,null,$b$Yor nây hên geh kan aơ tĭng nâm nau Brah Ndu yô̆ hên mâu rdja nuih n'hâm ôh.$b$,true),
('bunong-vn','2CO',4,2,null,$b$Ƀiă lah hên dun jêh ndơ ƀư bêk bu ƀư ma nau ndâp. Hên dun nau ndơm jêh ri mâu rgâl Nau Brah Ndu Ngơi ôh, ƀiă lah dôl hên rblang rah vah ma nau nanê̆, hên tâm mpơl hên nơm ma nuih n'hâm sŏng lĕ rngôch bunuyh ta năp Brah Ndu.$b$,false),
('bunong-vn','2CO',4,3,null,$b$Tơ lah nau mhe mhan ueh he ăt nkŭm, păng geh bok nkŭm knŏng ma phung roh.$b$,false),
('bunong-vn','2CO',4,4,null,$b$Ma phung mâu chroh nây, brah rnôk aơ nkŭm lơi nau gĭt rbăng khân păng, gay lơi ăn khân păng saơ nau chrêk rmah nau mhe mhan ueh sol tâm Brah Krist, nơm jêng rup Brah Ndu.$b$,false),
('bunong-vn','2CO',4,5,null,$b$Hên mâu nti nau hên nơm ôh, ƀiă lah hên nti nau Brah Krist, Kôranh Brah, jêh ri hên nơm jêng tâm ban ma oh mon khân may yor Brah Yêsu.$b$,true),
('bunong-vn','2CO',4,6,null,$b$Yor lah Brah Ndu lah jêh: “Ăn nau ang sol bơh nau ngo”. Păng sol jêh tâm nuih n'hâm he ŭch ăn nau ang bơh nau gĭt rbăng ma nau chrêk rmah Brah Ndu ta muh măt Brah Krist.$b$,false),
('bunong-vn','2CO',4,7,null,$b$Ƀiă lah hên prăp ndơ khlay aơ tâm yăng neh, pô ri mơ nau brah toyh ngăn jêng ndơ Brah Ndu, mâu di ndơ he ôh.$b$,true),
('bunong-vn','2CO',4,8,null,$b$Lĕ rngôch nau mpet hên, ƀiă lah mâu tât lêk ôh; hên geh nau rŭng, ƀiă lah mâu djoh nuih n'hâm ôh;$b$,false),
('bunong-vn','2CO',4,9,null,$b$bu ƀư mhĭk ma hên; ƀiă lah hên mâu gŭ êng ôh; bu dong hên tât cha lôt, ƀiă lah mâu roh ôh;$b$,false),
('bunong-vn','2CO',4,10,null,$b$hên djôt mro tâm săk jăn hên nau khĭt Brah Yêsu, gay ma nau rêh Brah Yêsu mra tâm mpơl lĕ tâm săk jăn hên.$b$,false),
('bunong-vn','2CO',4,11,null,$b$Yor lah phung hên gŭ rêh jêng phung bu jao mro ma nau khĭt yor Brah Yêsu, gay ma nau rêh Brah Yêsu mra tâm mpơl lĕ tâm săk jăn hên blau khĭt.$b$,false),
('bunong-vn','2CO',4,12,null,$b$Pô ri, nau khĭt pah kan tâm hên, ƀiă lah nau rêh pah kan tâm khân may.$b$,false),
('bunong-vn','2CO',4,13,null,$b$Yor hên geh nau mĭn chroh nâm bu nơm nchih jêh pô aơ: “Gâp chroh jêh, pô nây gâp ngơi,” hên tâm ban lĕ chroh, pô nây yơh hên ngơi.$b$,false),
('bunong-vn','2CO',4,14,null,$b$Dôl hên gĭt ma Nơm hŏ ƀư rêh jêh Brah Yêsu, mra rêh hên ndrel ma Brah Yêsu lĕ, jêh ri Păng mra tâm mpơl hên ndrel ma khân may ta năp păng.$b$,false),
('bunong-vn','2CO',4,15,null,$b$Lĕ nau nây tât yor khân may, gay ma nau yô̆ mra jêng rmeh ler âk bunuyh dôl tâm n'hao nau rnê ma nau chrêk rmah Brah Ndu.$b$,false),
('bunong-vn','2CO',4,16,null,$b$Yor nây hên mâu djoh nuih ôh. Nđâp tơ lah săk jăn ntơm rai grĕ grĕ, tâm dâng hên jêng mhe ăp nar.$b$,true),
('bunong-vn','2CO',4,17,null,$b$Yor lah nau rêh ni hên n'gơch aƀaơ nkra ma hên nau jâk chrêk rmah n'ho ro rlau ma lĕ rnâng.$b$,false),
('bunong-vn','2CO',4,18,null,$b$Yor lah hên mâu uănh ôh ma ndơ dơi saơ ƀiă lah ma ndơ mâu dơi saơ, yor lah ndơ dơi saơ gŭ ƀât lât, ƀiă lah ndơ mâu dơi saơ ôh gŭ n'ho ro.$b$,false),
('bunong-vn','2CO',5,1,null,$b$Yor lah he gĭt tơ lah ngih he gŭ njơh ƀât lât ta neh ntu aơ rai jêh, he mra geh ngih tâm trôk gŭ ƀa ƀơ n'ho ro tâm ƀon ueh klơ, jêng ngih Brah Ndu ƀư, mâu di ti bunuyh ƀư ôh.$b$,true),
('bunong-vn','2CO',5,2,null,$b$Pô nây lĕ he nđêng tâm ngih bok aơ, ŭch ngăn gŭ tâm ngih tâm trôk.$b$,false),
('bunong-vn','2CO',5,3,null,$b$Pô ri, jêh he nsoh ngih nây he mâu mra gŭ săk kuh ôh.$b$,false),
('bunong-vn','2CO',5,4,null,$b$Yor lah dôl he gŭ tâm ngih bok aơ, he rđêng, anh jâk, mâu di he ŭch doh lơi ôh ngih bok, ƀiă lah he ŭch nsoh ngih mhe, pô ri mơ nau rêh mra rvăn ndơ blau khĭt.$b$,false),
('bunong-vn','2CO',5,5,null,$b$Brah Ndu jêng nơm nkra he ma nau nây, jêh ri păng ăn jêh Brah Huêng Ueh jêng nâm bu play lor.$b$,false),
('bunong-vn','2CO',5,6,null,$b$Pô ri he bêng ma nau rnơm mro. He gĭt dôl he gŭ tâm săk jăn aơ, he gŭ ngai đah Kôranh Brah.$b$,false),
('bunong-vn','2CO',5,7,null,$b$Yor lah he hăn ma nau chroh, mâu di ma nau saơ ôh.$b$,true),
('bunong-vn','2CO',5,8,null,$b$He bêng ma nau rnơm jêh ri he rŏng lơn luh tă bơh săk jăn aơ gŭ dăch Kôranh Brah.$b$,false),
('bunong-vn','2CO',5,9,null,$b$Pô ri, gĭt lah he gŭ tâm săk jăn aơ, mâu lah luh, he ŭch ngăn ƀư maak ma păng.$b$,false),
('bunong-vn','2CO',5,10,null,$b$Yor lah lĕ rngôch he mra tâm mpơl ta năp sưng phat dôih Brah Krist, pô ri ăp nơm mra sŏk dơn tĭng nâm nau ueh mâu lah nau mhĭk păng ƀư jêh dôl păng gŭ tâm săk jăn aơ.$b$,false),
('bunong-vn','2CO',5,11,null,$b$Yor lah he gĭt jêh nau klach ma Kôranh Brah, he nchâp bunuyh, Brah Ndu gĭt năl he, jêh ri gâp kâp gân ma nuih n'hâm sŏng khân may gĭt năl hên lĕ.$b$,true),
('bunong-vn','2CO',5,12,null,$b$Mâu di hên tâm rnê ma hên nơm đŏng ôh, ƀiă lah hên ăn khân may dơi tâm rnê ma khân may nơm yor hên, gay ma khân may dơi plơ̆ lah ma phung tâm rnê khân păng nơm yor nau bunuyh jêng, jêh ri mâu di tâm nuih n'hâm khân păng ôh.$b$,false),
('bunong-vn','2CO',5,13,null,$b$Tơ lah hên jêng rluk, hên jêng pô nây yơh yor Brah Ndu, tơ lah hên geh nau mĭn ueh nây jêng yor khân may.$b$,false),
('bunong-vn','2CO',5,14,null,$b$Nau rŏng Brah Krist mpet hên, yor lah hên gĭt, tơ lah du huê khĭt jêh ma lĕ rngôch pô nây, lĕ rngôch khĭt jêh da dê.$b$,true),
('bunong-vn','2CO',5,15,null,$b$Jêh ri păng khĭt ma lĕ rngôch, gay ma mbu nơm gŭ rêh mâu mra gŭ rêh ma păng nơm ôh, ƀiă lah ma nơm khĭt jêh ri dâk rêh jêh yor khân păng.$b$,false),
('bunong-vn','2CO',5,16,null,$b$Pô ri, ntơm aơ pa năp, he mâu hôm gĭt năl bunuyh tĭng nâm nglay săk ôh, jêh ri nđâp tơ lah he gĭt năl jêh Brah Krist tĭng nâm nglay săk, aƀaơ aơ he mâu hôm gĭt năl păng tâm ban pô nây ôh.$b$,false),
('bunong-vn','2CO',5,17,null,$b$Tơ lah du huê gŭ tâm Brah Krist, păng jêng bunuyh rhăk njêng mhe jêh, ndơ ơm rlau lôch jêh, aơ, lĕ rngôch ndơ jêng mhe jêh da dê.$b$,true),
('bunong-vn','2CO',5,18,null,$b$Jêh ri lĕ nau nây luh bơh Brah Ndu, nơm hŏ nsĭr jêh he đah păng tâm Brah Krist, jêh ri jao ma he kan nau tâm njĭr.$b$,false),
('bunong-vn','2CO',5,19,null,$b$Yor lah Brah Ndu gŭ jêh tâm Brah Krist, tâm njĭr jêh neh ntu đah Păng Nơm. Păng mâu hôm kơp nau tih khân păng ôh, jêh ri Păng jao ma he nau nti ma nau tâm njĭr.$b$,false),
('bunong-vn','2CO',5,20,null,$b$Pô ri, hên jêng oh mon ktang ma Brah Krist, nâm bu Brah Ndu vơh vơl ma bu đah hên, hên vơh vơl ma khân may ma amoh Brah Krist, ăn tâm njĭr hom khân may đah Brah Ndu.$b$,false),
('bunong-vn','2CO',5,21,null,$b$Pô ri nơm mâu mâp gĭt nau tih ôh, Brah Ndu njêng Păng tih yor he, gay ma he mra jêng nau sŏng Brah Ndu tâm Păng.$b$,false),
('bunong-vn','2CO',6,1,null,$b$Pô ri, yor lah he pah kan ndrel ma Brah Ndu, hên vơh vơl ma khân may, lơi sŏk dơn nau Brah Ndu yô̆ dơm dam ôh.$b$,true),
('bunong-vn','2CO',6,2,null,$b$Yor lah păng lah: “Gâp tăng jêh may nar găl, gâp kơl may jêh ta nar tâm rklaih. Nôk aơ, jêng nar găl; nôk aơ jêng nar tâm rklaih”.$b$,true),
('bunong-vn','2CO',6,3,null,$b$Hên mâu ƀư du ntil ƀư chêh ôh, pô ri, bu mâu dơi nduyh ôh ma kan hên ƀư,$b$,true),
('bunong-vn','2CO',6,4,null,$b$ƀiă lah tâm lĕ rngôch nau, hên tâm mpơl hên jêng oh mon Brah Ndu răp jăp ngăn; ma nau srôih nau rêh ni, tâm nau djơh mhĭk, tâm nau rngot,$b$,false),
('bunong-vn','2CO',6,5,null,$b$tâm nau bu dong, tâm nau bu krŭng, nau uh ah, tâm nau pah kan, tâm nau gŭ njrăng, tâm nau ver sông sa;$b$,false),
('bunong-vn','2CO',6,6,null,$b$ma nau kloh, ma nau gĭt rbăng, ma nau srôih dơn nau mhĭk, ma nau ueh, ma Brah Huêng Ueh, ma nau rŏng răp jăp,$b$,false),
('bunong-vn','2CO',6,7,null,$b$ma nau ngơi nau n'hêl nanê̆, ma nau brah Brah Ndu; ma ndơ tâm lơh bơh nau sŏng, mpeh pa ma jêh ri mpeh pa chiau.$b$,false),
('bunong-vn','2CO',6,8,null,$b$Ta nau bu yơk, mâu lah nau bêk, tâm nklang nau bu tâm rmot mâu lah nau bu tâm rnê. Bu uănh ma hên nâm bu nau ngơi mƀruh; ƀiă lah hên ngơi ngăn;$b$,false),
('bunong-vn','2CO',6,9,null,$b$tâm ban ma bu mâu gĭt năl, ƀiă lah bu gĭt năl nanê̆ jêh, nâm bu khĭt, ƀiă lah ăt gŭ rêh, nâm bu hŏ rmal jêh, ƀiă lah bu mâu nkhĭt ôh.$b$,false),
('bunong-vn','2CO',6,10,null,$b$Nâm bu rngot, ƀiă lah hên răm maak mro; nâm bu o ach, ƀiă lah hên ƀư ndrŏng âk bunuyh, nâm bu mâu geh ndơ ôh, ƀiă lah hên geh lĕ rngôch ndơ.$b$,false),
('bunong-vn','2CO',6,11,null,$b$Hơi phung Kôrintô, mbung hên hă jêh ma khân may; nuih n'hâm hên jêng toyh jêh ma khân may.$b$,true),
('bunong-vn','2CO',6,12,null,$b$Khân may mâu jêng rhăt tâm hên ôh, ƀiă lah khân may jêng rhăt tâm nau khân may nơm rŏng.$b$,false),
('bunong-vn','2CO',6,13,null,$b$Mplơ̆ hom ma hên nau tâm ban gâp ngơi ma khân may nâm bu ma phung kon se ăn toyh hom nuih n'hâm khân may.$b$,false),
('bunong-vn','2CO',6,14,null,$b$Lơi ta ndô mbăk ndrel đah phung ê chroh ôh. Yor lah moh nau tâm rnglăp dơi geh nau sŏng đah nau kue? Mâu lah moh nau tâm rnglăp nau ang dơi geh đah nau ngo?$b$,true),
('bunong-vn','2CO',6,15,null,$b$Moh nau tâm rnglăp Brah Krist dơi geh đah brah Bêlial? Mâu lah moh phung chroh dơi geh ndrel ma phung mâu chroh?$b$,false),
('bunong-vn','2CO',6,16,null,$b$Moh nau tâm rnglăp ntŭk kloh Brah Ndu dơi geh đah ngih rup brah? Yor lah he jêng ntŭk kloh ma Brah Ndu rêh; nâm bu Brah Ndu lah jêh: “Gâp mra gŭ tâm khân păng jêh ri sak nsong tâm khân păng, gâp mra jêng Brah Ndu khân păng, jêh ri khân păng mra jêng phung ƀon lan gâp”.$b$,true),
('bunong-vn','2CO',6,17,null,$b$“Yor nây luh du hom khân may tă bơh tâm nklang khân păng. Jêh ri tâm nkhah hom khân may. Kôranh Brah lah, lơi pah ôh ndơ ƀơ̆ , jêh ri gâp mra rom khân may.$b$,true),
('bunong-vn','2CO',6,18,null,$b$Gâp mra jêng du huê mbơ̆ ma khân may. Jêh ri khân may mra jêng phung kon bu klâu jêh ri kon bu ur gâp. Pô ri Kôranh Brah, Nơm Brah lơn, lah”.$b$,true),
('bunong-vn','2CO',7,1,null,$b$Hơi phung gâp rŏng, yor lah he geh nau ton aơ, ăn he ƀư kloh hom he nơm bơh lĕ rngôch nau ƀơ̆ ƀơch tâm nglay săk, jêh ri huêng, jêh ri ƀư rah vah nau kloh ueh he tâm nau klach yơk ma Brah Ndu.$b$,true),
('bunong-vn','2CO',7,2,null,$b$Pơk hom nuih n'hâm khân may ma hên; hên mâu mâp ƀư mhĭk ma bu ôh, hên mâu mâp ƀư rai bu ôh, hên mâu mâp sa ndô ndơ bu ôh.$b$,true),
('bunong-vn','2CO',7,3,null,$b$Gâp mâu lah nau aơ gay ma tâm rmal khân may ôh, yor lah gâp lah jêh ma khân may gŭ tâm nuih n'hâm hên, gay rêh ndrel jêh ri khĭt ndrel.$b$,false),
('bunong-vn','2CO',7,4,null,$b$Gâp geh rnơm ngăn ma khân may, gâp rnê ma gâp nơm âk ngăn yor khân may; gâp bêng ma nau răm maak. Gâp bêng ma nau hâk ta nklang nau rngot hên.$b$,false),
('bunong-vn','2CO',7,5,null,$b$Yor lah ntơm bơh nar hên tât ta n'gor Masêđôn, săk jăn hên mâu mâp geh rlu ôh, ƀiă lah hên geh nau rngot ăp ntil, nau tâm lơh pa dih nau klach tâm trôm.$b$,false),
('bunong-vn','2CO',7,6,null,$b$Ƀiă lah Brah Ndu nơm bonh nuih mbu nơm rdja nuih n'hâm, bonh jêh hên yor Y-Tit tât jêh.$b$,false),
('bunong-vn','2CO',7,7,null,$b$Jêh ri mâu di knŏng yor păng tât jêh, ƀiă lah ma nau bonh nuih păng nơm geh jêh bơh khân may. Păng nkoch bri ma hên jêh nau khân may klâng, dak măt khân may, nau khân may duh nđơr ma gâp, pô ri gâp geh nau răm maak âk lơn.$b$,true),
('bunong-vn','2CO',7,8,null,$b$Tơ lah gâp ƀư rngot jêh khân may ma sămƀŭt gâp njuăl ma khân may, gâp mâu nduyh tôr ôh ma nau nây (nđâp tơ lah gâp nduyh tôr jêh ma nau nây), yor lah gâp saơ sămƀŭt nây ƀư rngot khân may knŏng ƀât lât.$b$,true),
('bunong-vn','2CO',7,9,null,$b$Aƀaơ ri gâp maak, mâu di yor khân may geh nau rngot ôh, ƀiă lah yor nau rngot khân may nĕ njŭn jêh khân may ma nau rmal nau tih; yor lah khân may geh nau rngot, tĭng nâm Brah Ndu ŭch pô ri khân may mâu sŏk dơn nau roh bơh hên ôh.$b$,false),
('bunong-vn','2CO',7,10,null,$b$Yor lah nau rngot tĭng nâm Brah Ndu ŭch njêng nau rmal nau tih, njŭn ma nau tâm rklaih, jêh ri bu mâu mâp nduyh ôh ma nau nây, bi nau rngot tĭng nâm neh ntu njêng nau khĭt.$b$,false),
('bunong-vn','2CO',7,11,null,$b$Pô ri ăn khân may uănh moh nau duh nđơr nau rngot nây tĭng nâm Brah Ndu ŭch njêng jêh tâm khân may, moh nau ŭch dơi ƀư kloh khân may nơm, moh nau nuih, moh nau klach, moh nau ŭch ngăn, moh nau duh nđơr, moh nau tâm rmal! Khân may tâm mpơl jêh tâm lĕ rngôch nau ma khân may jêng kloh jêh tâm kan nây.$b$,false),
('bunong-vn','2CO',7,12,null,$b$Pô ri tơ lah gâp nchih jêh ma khân may, gâp nchih mâu di yor nơm sŏk dơn tih nây ôh, mâu di ma nơm sŏk dơn lĕ, ƀiă lah gay ma nau duh nđơr khân may yor hên mra tâm mpơl tâm phung khân may ta năp Brah Ndu.$b$,true),
('bunong-vn','2CO',7,13,null,$b$Yor nây he geh nau bonh jêh. Jêh ri rlau ma nau bonh hên nơm, hên maak âk lơn yor nau Y-Tit maak. Păng geh nuih n'hâm đăp mpăn yor lĕ rngôch khân may.$b$,false),
('bunong-vn','2CO',7,14,null,$b$Tơ lah gâp tâm rnê jêh ma gâp nơm yor khân may ta năp păng gâp mâu geh nau bêk ôh; ƀiă lah nâm bu hên ngơi nau ngăn mro ma khân may, pô ri nau hên tâm rnê ma khân may ta năp Y-Tit bu saơ jêng nau nanê̆ tâm ban lĕ.$b$,true),
('bunong-vn','2CO',7,15,null,$b$Pô ri păng rŏng ma khân may bar tơ̆ âk lơn tơ lah păng kah gĭt ma nau lĕ rngôch khân may tông bâr, jêh ri nau khân may rom păng ma nau klach jêh ri sâr săk jăn.$b$,false),
('bunong-vn','2CO',7,16,null,$b$Gâp maak yor lah gâp dơi rnơm ma khân may tâm lĕ rngôch nau.$b$,false),
('bunong-vn','2CO',8,1,null,$b$Hơi phung oh nâu, hên ăn may gĭt nau yô̆ Brah Ndu tâm mpơl jêh ma phung Ngih Brah Ndu tâm n'gor Masêđôn.$b$,true),
('bunong-vn','2CO',8,2,null,$b$Tâm nklang âk nau rlong uănh rêh ni, nau maak bêng ler khân păng, jêh ri nau khân păng o ach ngăn njêng nau lŏng âk ngăn tâm khân păng.$b$,true),
('bunong-vn','2CO',8,3,null,$b$Gâp mbơh nanê̆ ma khân păng nhhơr ma nau khân păng ŭch tĭng nâm nau khân păng dơi, jêh ri rlau lơn lĕ.$b$,false),
('bunong-vn','2CO',8,4,null,$b$Khân păng dăn ma hên ma nau ŭch ngăn ăn khân păng dơi kơl phung kloh ueh,$b$,true),
('bunong-vn','2CO',8,5,null,$b$jêh ri nau aơ mâu di nâm bu hên kâp gân, ƀiă lah khân păng jao lor jêh khân păng nơm ma Kôranh Brah, jêh ri ma hên, tĭng nâm nau Brah Ndu ŭch.$b$,false),
('bunong-vn','2CO',8,6,null,$b$Pô ri hên ntrôl jêh Y-Tit, ăn păng ƀư lĕ kan nau yô̆ nâm bu păng ntơm ƀư jêh tâm phung khân may.$b$,false),
('bunong-vn','2CO',8,7,null,$b$Yor lah nâm bu khân may jêng ueh ngăn tâm lĕ rngôch nau tâm nau chroh, tâm nau ngơi, tâm nau gĭt rbăng, tâm nau duh nđơr ma lĕ rngôch nau jêh ri tâm nau khân may rŏng ma hên. Pô ri ăn khân may jêng ueh ngăn tâm kan nau yô̆ aơ.$b$,true),
('bunong-vn','2CO',8,8,null,$b$Gâp lah nau aơ mâu di ŭch ntăm ma khân may ôh, ƀiă lah ŭch ăn saơ nau răp jăp bơh nau khân may rŏng ma nau duh nđơr phung êng.$b$,false),
('bunong-vn','2CO',8,9,null,$b$Yor lah khân may gĭt jêh nau yô̆ Kôranh Brah he, Brah Yêsu Krist, nơm jêng ndrŏng jêh, ƀiă lah ƀư trơi păng nơm yor khân may, pô ri yor nau o ach păng khân may dơi jêng ndrŏng.$b$,false),
('bunong-vn','2CO',8,10,null,$b$Tâm nau aơ gâp dơi tâm mpơl nau mĭn gâp nơm: Nau aơ jêng ueh ma khân may, ƀư jêh kan khân may ntơm jêh, jêh ri ŭch ƀư bơh năm e.$b$,false),
('bunong-vn','2CO',8,11,null,$b$Aƀaơ ƀư lĕ hom kan khân may ƀư, pô ri nau khân may ŭch, khân may dơi ăn nanê̆ tĭng nâm nau khân may geh.$b$,false),
('bunong-vn','2CO',8,12,null,$b$Tơ lah geh nau ŭch ƀư ueh, bu ndơn tĭng nâm ndơ bu geh, mâu di tĭng nâm ndơ bu mâu geh ôh.$b$,false),
('bunong-vn','2CO',8,13,null,$b$Gâp mâu ŭch ôh ƀư n'gơch bu êng, ƀiă lah ƀư jâk khân may.$b$,false),
('bunong-vn','2CO',8,14,null,$b$Ƀiă lah ŭch tĭng nau vay tâm ban, nâm bu aƀaơ nau khân may geh rmeh mra kơl nau khân păng pưt, jêh ri gay ma nau khân păng âk rmeh mra kơl khân may tâm ban lĕ. Pô ri mra geh nau tâm ban.$b$,false),
('bunong-vn','2CO',8,15,null,$b$Nâm bu geh nau nchih jêh: “Mbu nơm bun âk jêh, mâu geh rmeh ôh, jêh ri mbu nơm bun djê̆, mâu geh pưt ôh”.$b$,false),
('bunong-vn','2CO',8,16,null,$b$Tâm rnê, ma Brah Ndu yor lah păng dơn jêh tâm nuih n'hâm Y-Tit nau duh nđơr pô nây ma khân may.$b$,true),
('bunong-vn','2CO',8,17,null,$b$Yor lah păng dơn jêh nau hên dăn, jêh ri ma nau duh nđơr mhe păng ŭch ngăn hăn ma khân may.$b$,false),
('bunong-vn','2CO',8,18,null,$b$Ndrel ma păng hên njuăl du huê nau geh jêh nau lư n'găr tâm lĕ rngôch phung ngih Brah Ndu yor nau păng nti lah nau mhe mhan ueh.$b$,true),
('bunong-vn','2CO',8,19,null,$b$Mâu di knŏng dŭm nĕ, ƀiă lah phung ngih Brah Ndu săch păng jêh, ăn nsong ndrel ma hên tâm kan nau yô̆ aơ hên ƀư ŭch ăn nau chrêk rmah ma Kôranh Brah, jêh ri gay tâm mpơl nau hên ŭch ueh.$b$,false),
('bunong-vn','2CO',8,20,null,$b$Hên ƀư pô nây gay lơi geh bunuyh nduyh hên yor nau hên chiă uănh ndơ ăn yô̆ âk rmeh aơ,$b$,false),
('bunong-vn','2CO',8,21,null,$b$yor lah hên tĭng joi nau ueh, mâu di knŏng ta năp Kôranh Brah ôh, ƀiă lah nđâp ta năp bunuyh lĕ.$b$,false),
('bunong-vn','2CO',8,22,null,$b$Ndrel ma khân păng hên njuăl nâu hên, nơm hên rlong uănh jêh âk tơ̆ nau păng duh nđơr tâm ăp ntil ndơ, ƀiă lah aƀaơ păng duh nđơr lơn yor lah păng rnơm ma khân may âk ngăn.$b$,false),
('bunong-vn','2CO',8,23,null,$b$Bi Y-Tit, păng jêng băl gâp jêh ri nơm pah kan ma khân may ndrel ma gâp, bi ma phung nâu he nây, khân păng jêng phung ngih Brah Ndu njuăl hăn, phung tâm rnê ma Brah Krist.$b$,false),
('bunong-vn','2CO',8,24,null,$b$Pô ri, tâm mpơl hom ta năp phung ngih Brah Ndu nau khân may rŏng, jêh ri ma nau hên tâm rnê ma hên nơm yor khân may ta năp khân păng.$b$,false),
('bunong-vn','2CO',9,1,null,$b$Aƀaơ aơ mâu khlay ôh gâp nchih tay ma khân may ma nau nhhơr ndơ kơl phung kloh ueh.$b$,true),
('bunong-vn','2CO',9,2,null,$b$Yor lah gâp gĭt jêh ma nau khân may ŭch ueh. Pô ri, gâp tâm rnê ma gâp nơm yor khân may ta năp phung Masêđôn, dôl gâp mbơh nkoch n'gor Akai nkra jêh ndơ kơl bơh năm e, jêh ri nau khân may duh nđơr tâm n'hao nuih âk phung khân păng.$b$,false),
('bunong-vn','2CO',9,3,null,$b$Ƀiă lah gâp njuăl jêh phung nâu khân may, pô ri nau hên tâm rnê ma khân may mâu mra jêng dơm dam ôh tâm nau nây, jêh ri gay ma khân may mra nkra nâm bu gâp lah jêh;$b$,false),
('bunong-vn','2CO',9,4,null,$b$Klach lah tơ lah phung Masêđôn njŭn gâp, jêh ri saơ khân may mâu geh nkra ôh, hên mra bêk yor nau hên ngơi, ƀiă lah hên mâu ŭch lah ma khân may ôh.$b$,false),
('bunong-vn','2CO',9,5,null,$b$Pô ri gâp mĭn khlay jă phung nâu, ăn khân păng hăn lor ma khân may, jêh ri nkra ndơ khân may ton jêh, ŭch geh nau ndrăp jêng nau lŏng, jêh ri mâu geh nau nchâp ôh.$b$,false),
('bunong-vn','2CO',9,6,null,$b$Ăn khân may kah gĭt nau aơ; mbu nơm srih djê̆ mra rek djê̆, mbu nơm srih âk mra rek âk.$b$,true),
('bunong-vn','2CO',9,7,null,$b$Pô ri ăn ăp nơm nhhơr tĭng nâm nau păng hŏ mĭn jêh tâm nuih n'hâm, mâu geh lah ăn ma nau rngot, mâu lah ma nau nchâp ôh, yor lah Brah Ndu rŏng ma mbu nơm nhhơr ma nau maak.$b$,false),
('bunong-vn','2CO',9,8,null,$b$Jêh ri Brah Ndu dơi ăn âk rmeh ma khân may, tât khân may geh âk rmeh đŏng tâm ăp ntil kan ueh.$b$,false),
('bunong-vn','2CO',9,9,null,$b$Tĭng nâm nau nchih jêh: “Păng tâm pă âk jêh, păng ăn jêh ma phung o ach. Nau sŏng păng gŭ ƀa ƀơ n'ho ro”.$b$,true),
('bunong-vn','2CO',9,10,null,$b$Mbu nơm ăn ntil ma nơm srih jêh ri kapŭng ma păng sa păng mra ăn jêh ri ƀư bĭk lĕ ntil khân may, jêh ri păng mra n'hao âk play ma nau sŏng khân may.$b$,true),
('bunong-vn','2CO',9,11,null,$b$Pô ri khân may mra jêng ndrŏng tâm ăp ntil ndơ ma nau ƀư ueh âk, jêh ri nau nây tâm hên mra jêng nau tâm rnê Brah Ndu.$b$,false),
('bunong-vn','2CO',9,12,null,$b$Yor lah nau kơl ma nau nhhơr nây mâu di knŏng kơl phung kloh ueh ôh, ƀiă lah păng jêng âk rmeh tâm nau tâm rnê ma Brah Ndu.$b$,false),
('bunong-vn','2CO',9,13,null,$b$Ma nau rlong uănh tâm nau khân may kơl aơ khân may mra tâm rnê ma Brah Ndu yor nau tông bâr ma nau mbơh nau mhe mhan ueh Brah Krist, jêh ri tâm nau lŏng khân may nhhơr ma khân păng jêh ri ma lĕ rngôch,$b$,true),
('bunong-vn','2CO',9,14,null,$b$dôl khân păng klâng jêh ri mbơh sơm ma khân may yor khân păng saơ nau yô̆ toyh ngăn Brah Ndu ăn jêh ma khân may.$b$,false),
('bunong-vn','2CO',9,15,null,$b$Tâm rnê ma Brah Ndu yor nau păng ăn ma he mâu dơi kơp!$b$,false),
('bunong-vn','2CO',10,1,null,$b$Gâp yơh, Y-Pôl, vơh vơl ma khân may ma nau rdơ̆ jêh ri nau ueh bơh Brah Krist. Gâp yơh nơm tông bâr tơ lah gâp gŭ ndrel ma khân may, ƀiă lah bêng ma nau janh đah khân may tơ lah gâp gŭ ngai!$b$,true),
('bunong-vn','2CO',10,2,null,$b$Gâp vơh vơl ma khân may, tơ lah gâp mra gŭ ta năp khân may, lơi nchâp gâp dŏng nau janh gâp mĭn dŏng tâm rdâng đah phung uănh ma hên tâm ban ma hăn tĭng nâm nglay săk.$b$,false),
('bunong-vn','2CO',10,3,null,$b$Yor lah tơ lah hên hăn tâm nglay săk hên mâu tâm lơh tĭng nglay săk ôh,$b$,false),
('bunong-vn','2CO',10,4,null,$b$yor lah ndơ tâm lơh hên dŏng mâu jêng ndơ nglay săk ôh, ƀiă lah khân păng geh nau brah ta năp Brah Ndu dơi ƀư rai mpêr n'gar nâp rjăp.$b$,false),
('bunong-vn','2CO',10,5,null,$b$Hên ƀư rai nau tâm dun jêh ri ăp ntil nau buay sưr tâm rdâng đah nau gĭt năl Brah Ndu, jêh ri njŭn leo lĕ rngôch nau mĭn jêng bu nă ăn tông ma Brah Krist.$b$,false),
('bunong-vn','2CO',10,6,null,$b$Jêh ri hên kâp tâm rmal lĕ nau mâu tông bâr tơ lah nau khân may tông bâr jêng rah vah jêh.$b$,false),
('bunong-vn','2CO',10,7,null,$b$Uănh hom ma nau khân may saơ ta năp măt khân may! Tơ lah du huê mĭn păng tă bơh Brah Krist, ăn păng kah gĭt nâm bu păng jêng bơh Brah Krist, hên jêng bơh Brah Krist tâm ban lĕ.$b$,true),
('bunong-vn','2CO',10,8,null,$b$Tơ lah gâp tâm rnê ma gâp nơm rlau keh djê̆ lê̆ yor nau dơi Kôranh Brah ăn jêh ma hên gay ma n'hao khân may, mâu di gay ma ƀư rai khân may ôh, gâp mâu mra bêk ôh.$b$,false),
('bunong-vn','2CO',10,9,null,$b$Gâp mâu ŭch bu mĭn gâp nhhu khân may ma sămƀŭt gâp ôh.$b$,false),
('bunong-vn','2CO',10,10,null,$b$Yor lah bu lah: “Sămƀŭt păng dăng jêh ri ktang, ƀiă lah tơ lah saơ păng nơm, păng jêng rdja, jêh ri nau păng ngơi mâu khlay ôh”.$b$,false),
('bunong-vn','2CO',10,11,null,$b$Ăn mbu nơm ngơi pô nây gĭt rbăng ma nau hên lah tâm sămƀŭt dôl hên ndŭt kơi, hên jêng tâm ban lĕ tâm nau ƀư tơ lah ta năp măt hên.$b$,false),
('bunong-vn','2CO',10,12,null,$b$Hên mâu janh ƀư tâm ndăng hên nơm, mâu lah tâm ban hên nơm đah phung vay tâm rnê ma khân păng nơm ôh. Ƀiă lah tơ lah khân păng tâm veh khân păng nơm đah du huê nơm êng, jêh ri tơ lah khân păng ăn tâm ban đah du huê êng, khân păng mâu geh nau gĭt rbăng ôh.$b$,true),
('bunong-vn','2CO',10,13,null,$b$Ƀiă lah hên mâu tâm rnê ma hên nơm rlau ma ndơ Brah Ndu tâm nal ôh, ƀiă lah di ma keh Brah Ndu tâm nal jêh. Pô ri păng ăn hên văch tât ta khân may lĕ.$b$,false),
('bunong-vn','2CO',10,14,null,$b$Yor lah hên mâu ăn rlau keh hên nơm ôh, nâm bu hên mâu hăn tât ma khân may yor lah ma nau mhe mhan ueh Brah Krist hên hăn tât ma khân may jêh.$b$,false),
('bunong-vn','2CO',10,15,null,$b$Hên mâu tâm rnê ma hên nơm rlau keh ôh tâm kan bu êng, ƀiă lah nau hên kâp gân tơ lah nau chroh khân may văch ma toyh, kan hên mra văch ma toyh tâm ban lĕ tâm phung khân may.$b$,true),
('bunong-vn','2CO',10,16,null,$b$Gay ma hên dơi nti nau mhe mhan ueh tâm n'gor rlau lơn ma khân may. Pô ri hên mâu tâm rnê ma hên nơm tâm kan jao ma bu êng.$b$,false),
('bunong-vn','2CO',10,17,null,$b$“Ăn nơm tâm rnê mra tâm rnê ma Kôranh Brah.”$b$,false),
('bunong-vn','2CO',10,18,null,$b$Yor lah mâu di bunuyh tâm rnê ma păng nơm ôh bu dơn, ƀiă lah nơm Kôranh Brah rnê.$b$,false),
('bunong-vn','2CO',11,1,null,$b$Gâp ŭch ma khân may dơi tuy ndrel djê̆ lê̆ nau rluk gâp. Ăn khân may tuy ndrel ma gâp!$b$,true),
('bunong-vn','2CO',11,2,null,$b$Gâp geh nau ntôn khân may bơh Brah Ndu, yor lah gâp mbloh văng jêh khân ay ma du huê sai, gay ma tâm mpơl khân ay jêng du huê bu ur druh kloh ta năp Brah Krist.$b$,false),
('bunong-vn','2CO',11,3,null,$b$Ƀiă lah gâp klach nâm bu bêh ndơm H'Êvơ ma nau păng blau rlăm, păng mra ƀư teng nau mĭn khân may bơh nau răp jăp jêh ri nau yơk kloh tâm Brah Krist.$b$,false),
('bunong-vn','2CO',11,4,null,$b$Yor lah tơ lah bu văch nti khân may Brah Yêsu êng ma Brah Yêsu hên nti jêh, mâu lah tơ lah khân may sŏk dơn jêh Brah Huêng êng đah Brah Huêng Ueh khân may sŏk dơn jêh mâu lah tơ lah khân may sŏk dơn nau mhe mhan ueh êng ma nau khân may sŏk dơn jêh, pô ri khân may dơn nau ndơm ăp jêh.$b$,false),
('bunong-vn','2CO',11,5,null,$b$Gâp mĭn gâp mâu jêng jê̆ lơn ma phung kôranh oh mon toyh nây ôh.$b$,false),
('bunong-vn','2CO',11,6,null,$b$Nđâp tơ lah gâp mâu blau ngơi ueh kđôi, ăt gâp geh nau gĭt rbăng; hên rblang jêh nau nây ma khân may tâm lĕ rngôch ndơ.$b$,true),
('bunong-vn','2CO',11,7,null,$b$Mâu lah gâp ƀư tih jêh hĕ dôl gâp ntrŭnh gâp nơm tâm dâng, gay ma n'hao khân may, yor gâp mbơh jêh dơm dam nau mhe mhan ueh Brah Ndu ma khân may?$b$,true),
('bunong-vn','2CO',11,8,null,$b$Gâp huai sŏk lơi jêh bơh phung ngih Brah Ndu êng, tâm nau gâp dơn nau nkhôm bơh khân păng gay pah kan ma khân may.$b$,true),
('bunong-vn','2CO',11,9,null,$b$Tơ lah gâp gŭ ndrel jêh đah khân may jêh ri gâp pưt ndơ, gâp mâu mâp ƀư jêr bu ôh, yor lah phung oh nâu văch tă bơh n'gor Masêđôn ăn jêh ndơ gâp pưt. Tâm lĕ ndơ gâp njrăng mâu ŭch ƀư jêr ma khân may ôh, jêh ri gâp ăt mra njrăng.$b$,false),
('bunong-vn','2CO',11,10,null,$b$Ma nau nanê̆ Brah Krist gŭ jêh tâm gâp, gâp mbơh ma nau tâm rnê nây mâu mra gŭ rklăk ôh tâm n'gor Akai.$b$,false),
('bunong-vn','2CO',11,11,null,$b$Mâm ƀư? Yor lah gâp mâu rŏng ma khân may hĕ? Brah Ndu gĭt nau nây.$b$,false),
('bunong-vn','2CO',11,12,null,$b$Ƀiă lah nau gâp ƀư, gâp mra ƀư pô nây, gay buay lơi nau tâm rlăch tă bơh phung vay joi nau tâm rlăch, pô ri mơ bu saơ khân păng jêng tâm ban ma hên tâm ndơ khân păng tâm rnê ma khân păng nơm.$b$,false),
('bunong-vn','2CO',11,13,null,$b$Yor lah phung nây jêng phung kôranh oh mon tih, phung pah kan ndơm jan lah ƀư jêng tâm ban ma kôranh oh mon Brah Krist.$b$,true),
('bunong-vn','2CO',11,14,null,$b$Nau nây mâu dơi hih rhâl ôh, yor lah nđâp ma Satan nơm jan lah njêng tâm ban ma Tông mpăr ueh nau ang.$b$,false),
('bunong-vn','2CO',11,15,null,$b$Pô ri mâu geh hih rhâl ôh tơ lah phung oh mon păng jan jêng nâm bu oh mon nau sŏng. Nau lôch khân păng mra jêng tĭng nâm kan khân păng.$b$,false),
('bunong-vn','2CO',11,16,null,$b$Gâp rkêch đŏng, lơi ăn bu mĭn ma gâp nâm bu du huê bunuyh rluk ôh; ƀiă lah tơ lah khân may mĭn pô ri, ăn khân may rom gâp nâm bu du huê bunuyh rluk, gay ma gâp dơi tâm rnê djê̆ lê̆ ma gâp nơm.$b$,true),
('bunong-vn','2CO',11,17,null,$b$(Moh nau gâp lah, gâp mâu lah ôh tĭng nau dơi bơh Kôranh Brah, ƀiă lah nâm bu du huê rluk ma nau janh tâm rnê ma gâp nơm;$b$,true),
('bunong-vn','2CO',11,18,null,$b$Yor lah âk bunuyh tâm rnê ma khân păng nơm tĭng nâm nglay săk, gâp tâm ban lĕ mra tâm rnê).$b$,false),
('bunong-vn','2CO',11,19,null,$b$Yor lah khân may maak tuy ndrel ma phung rluk dôl khân may nơm jêng blau mĭn!$b$,false),
('bunong-vn','2CO',11,20,null,$b$Yor lah! Khân may dơn jêh nau bu njêng khân may jêng dĭk, nau bu rvăn sa khân may, nau bu pit lơi ndơ khân may, nau bu ƀư sưr ma khân may, nau bu tap muh măt may.$b$,false),
('bunong-vn','2CO',11,21,null,$b$Gâp prêng lah nau nây, hên tâm mpơl jêh nau rdja hên. Ƀiă lah tơ lah bu janh tâm rnê ma păng nơm. Gâp ngơi nâm bu du huê rluk Gâp janh tâm ban lĕ tâm rnê ma gâp nơm.$b$,false),
('bunong-vn','2CO',11,22,null,$b$Khân păng jêng phung Hêbrơ ƀơh? Gâp tâm ban đŏng. Khân păng jêng phung Israel ƀơh? Gâp tâm ban lĕ. Khân păng jêng phung kon sau Y-Abraham ƀơh? Gâp pô nây đŏng.$b$,true),
('bunong-vn','2CO',11,23,null,$b$Khân păng jêng oh mon ma Brah Krist ƀơh? Gâp jêng oh mon ueh lơn gâp ngơi nâm bu du huê bunuyh rluk gâp pah kan âk lơn ma khân păng bu krŭng gâp âk tơ̆ ngăn. Bu dong gâp âk lơn ƀa ƀơ gâp gŭ tâm nau dăch khĭt.$b$,false),
('bunong-vn','2CO',11,24,null,$b$Prăm tơ̆ phung Yuđa dong gâp pe jât ma sĭn tong, hôm du tong tât puăn jât tơ̆ .$b$,false),
('bunong-vn','2CO',11,25,null,$b$Ăp tơ̆ pe tong bu dong ma mâng, du tơ̆ bu klŭp ma lŭ ta gâp. Pe tơ̆ tâm kŭmpăn ngâm jêh; gâp gŭ jêh du măng du nar tâm dak mƀŭt khôm rdu.$b$,false),
('bunong-vn','2CO',11,26,null,$b$Gâp nsong ƀa ƀơ. Gâp mâp nau djơh mhĭk ta dak krong, ndrel phung ntŭng, ndrel phung mpôl băl gâp, ndrel phung bu năch, tâm ƀon toyh, tâm bri rdah, ta dak mƀŭt, ndrel phung oh nâu tih.$b$,false),
('bunong-vn','2CO',11,27,null,$b$Gâp mâp pah kan ma nau jêr, âk tơ̆ gâp mâu dơi bêch, ji ngot, ji hir, ât sông sa ƀa ƀơ, ji kăt jêh ri gŭ săk lưn.$b$,false),
('bunong-vn','2CO',11,28,null,$b$Jêh ri mâu ngơi ma nau êng, ăp nar gâp geh nau jâk rngot ma lĕ rngôch phung ngih Brah Ndu.$b$,false),
('bunong-vn','2CO',11,29,null,$b$Mbu nơm jêng rdja, gâp mâu jêng rdja ôh? Mbu nơm ăn prah bu, gâp mâu ji nuih ôh?$b$,false),
('bunong-vn','2CO',11,30,null,$b$Tơ lah gâp tâm rnê ma gâp nơm, gâp mra tâm rnê ma nau gâp nơm jêng rdja.$b$,true),
('bunong-vn','2CO',11,31,null,$b$Brah Ndu jêng Mbơ̆ ma Brah Yêsu geh nau tâm rnê ƀa ƀơ n'ho ro gâp mâu mƀruh ôh.$b$,true),
('bunong-vn','2CO',11,32,null,$b$Ta ƀon Đamas kôranh toyh tâm dâng hađăch Arêtas ăn bu chiă ƀon Đamas ăn ueh gay ăn bu nhŭp gâp,$b$,false),
('bunong-vn','2CO',11,33,null,$b$ƀiă lah bu ntrŭnh gâp ta mpông bloh jê̆ tâm bĭ rŏ mpêr, pô ri gâp klaih bơh ti khân păng.$b$,false),
('bunong-vn','2CO',12,1,null,$b$Ăn gâp tâm rnê ma gâp nơm, nau nây mâu khlay ôh, ƀiă lah gâp ăt mra ngơi ma nau ăn saơ jêh ri ma nau tâm mpơl bơh Kôranh Brah.$b$,true),
('bunong-vn','2CO',12,2,null,$b$Gâp gĭt năl du huê bunuyh tâm Brah Krist geh jât ma puăn năm rlau jêh. Bu chông păng hao klơ trôk rơh pe, gĭt lah tâm săk jăn mâu lah pa dih săk jăn gâp mâu gĭt, Brah Ndu gĭt.$b$,false),
('bunong-vn','2CO',12,3,null,$b$Jêh ri gâp gĭt ma bunuyh nây, gĭt lah tâm săk jăn mâu lah pa dih săk jăn gâp mâu gĭt, Brah Ndu gĭt.$b$,false),
('bunong-vn','2CO',12,4,null,$b$Bu chông păng tât ta Parađi, jêh ri păng tăng nau ngơi, mâu hôm dơi lah, mâu vay ma bunuyh ngơi ôh.$b$,false),
('bunong-vn','2CO',12,5,null,$b$Ma bunuyh nâm bu pô nây gâp dơi tâm rnê, ƀiă lah ma gâp nơm, gâp mâu tâm rnê ôh, knŏng gâp rnê ma nau rdja gâp.$b$,true),
('bunong-vn','2CO',12,6,null,$b$Tơ lah gâp ŭch tâm rnê ma gâp nơm, gâp mâu mra jêng bunuyh rluk ôh, yor lah gâp mra lah nau ngăn. Ƀiă lah gâp mâu ƀư pô nây ôh, gay lơi ăn geh bunuyh mĭn ma gâp rlau lơn ma nau khân may saơ tâm gâp, mâu lah nau khân păng tăng bơh gâp.$b$,false),
('bunong-vn','2CO',12,7,null,$b$Jêh ri klach ma gâp jêng sưr yor âk nau tâm mpơl khlay nây, bu dơm du njăr lok tâm nglay săk gâp jêng oh mon ma Satan gay ma ăn gâp geh nau rêh ni klach gâp jêng sưr.$b$,false),
('bunong-vn','2CO',12,8,null,$b$Pe tơ̆ gâp vơh vơl ma Kôranh Brah mprơh lơi ndơ nây đah gâp;$b$,false),
('bunong-vn','2CO',12,9,null,$b$ƀiă lah păng lah ma gâp: Nau gâp yô̆ ăp jêh ma may, yor lah nau brah gâp jêng rah vah jêh tâm nau rdja. Pô ri gâp tâm rnê ma âk nau răm ma nau rdja gâp, gay ma nau Brah Krist gŭ tâm gâp.$b$,false),
('bunong-vn','2CO',12,10,null,$b$Pô ri, yor Brah Krist gâp dơn nau rdja, nau bu suai rak, nau rêh ni, nau bu ƀư mhĭk, jêh ri nau djơh mhĭk; yor lah tơ lah gâp jêng rdja, dôl nây gâp jêng ktang.$b$,false),
('bunong-vn','2CO',12,11,null,$b$Gâp jêng rluk jêh! Khân may nchâp gâp ma nau nây, tơ lah di khân may yơh mra tâm rnê ma gâp. Yor lah gâp mâu jêng tâm dâng lơn ma phung kôranh oh mon khlay nây, nđâp tơ lah gâp jêng dơm dam kđôi lĕ.$b$,true),
('bunong-vn','2CO',12,12,null,$b$Nau tâm mbên ma kan du huê kôranh oh mon tâm mpơl jêh ta nklang khân may ma nau srôih, ma nau tâm mbên, ma nau khlay jêh ri ma kan brah.$b$,false),
('bunong-vn','2CO',12,13,null,$b$Yor lah tâm moh nau mhĭk lơn ma phung ngih Brah Ndu êng khân may geh, knŏng tơ lah gâp mâu ƀư nau ƀư jâk ma khân may lĕ? Yô̆ an nau tih nây ma gâp!$b$,false),
('bunong-vn','2CO',12,14,null,$b$Aơ jêng tơ̆ pe gâp nkra gay hăn ma khân may. Jêh ri gâp mâu mra ƀư jâk khân may ôh, yor lah gâp mâu joi ndơ khân may ôh, ƀiă lah khân may nơm. Mâu di phung kon ôh bun prăp drăp khlay ma mbơ̆ mê̆ khân păng, ƀiă lah mê̆ mbơ̆ bun prăp drăp ma oh kon khân păng.$b$,true),
('bunong-vn','2CO',12,15,null,$b$Gâp maak ngăn dŏng mpŭng moh ndơ gâp geh jêh ri gâp nơm yor huêng khân may. Tơ lah gâp rŏng ma khân may âk lơn, mâm khân may rŏng djê̆ dơm ma gâp?$b$,false),
('bunong-vn','2CO',12,16,null,$b$Ƀiă lah nđâp tơ lah gâp mâu mâp ƀư jâk khân may kđôi, khân may lah gâp jêng bunuyh ndơm êng khân may ma nau rlăm.$b$,false),
('bunong-vn','2CO',12,17,null,$b$Gâp mâp sa ndơ khân may lĕ đah bunuyh gâp njuăl jêh ma khân may?$b$,false),
('bunong-vn','2CO',12,18,null,$b$Gâp ăn Y-Tit hăn ta khân may, jêh ri ndrel ma păng gâp njuăl du huê tâm phung oh nâu. Y-Tit mâp sa ndơ khân ay mâu? Mâu di hĕ hên hăn tâm nau mĭn tâm ban jêh ri tă têl tâm ban?$b$,true),
('bunong-vn','2CO',12,19,null,$b$Bơh jŏ jêh khân may mĭn ma hên kơp hên nơm sŏng ta năp khân may. Ta năp Brah Ndu tâm Brah Krist yơh hên ngơi, jêh ri lĕ nau nây gay ma tâm n'hao nuih khân may, hơi phung gâp rŏng ngăn ngên.$b$,true),
('bunong-vn','2CO',12,20,null,$b$Yor lah gâp klach tơ lah gâp tât gâp mâu mra saơ khân may nâm bu gâp ŭch, jêh ri khân may mra saơ gâp mâu di nâm bu khân may ŭch. Gâp klach mra saơ nau tâm lah tâm jin, nau mô nach, nau nuih, nau mbeh, nau ngơi ndjơh, nau nchơt, nau sưr, nau uh ah.$b$,false),
('bunong-vn','2CO',12,21,null,$b$Gâp klach tơ lah gâp tât tay. Brah Ndu gâp mra ăn gâp dêh rhêt ta năp khân may, jêh ri gâp mra nhĭm ma âk phung ƀư tih jêh bơh lor jêh ri khân păng mâu tâm rmal ma nau ƀơ̆ , nau văng tĭr jêh ri ma nau ƀai khân păng ƀư.$b$,true),
('bunong-vn','2CO',13,1,null,$b$Pe tơ̆ ma aơ jêh gâp hăn khâl khân may. “Lĕ nau phong mra jêng ngăn tă bơh bar mâu lah pe nuyh mbơh.”$b$,true),
('bunong-vn','2CO',13,2,null,$b$Gâp mbơh nau nây ma phung ƀư tih jêh bơh lor, jêh ri ma lĕ rngôch phung êng, jêh ri gâp mbơh ma khân păng aƀaơ dôl gâp ndŭt kơi, nâm bu gâp mbơh dôl gâp hăn khâl ma khân may rơh bar, tơ lah gâp hăn tay ma khân may gâp mâu mra yô̆ ma khân păng ôh.$b$,false),
('bunong-vn','2CO',13,3,null,$b$Yor lah khân may ŭch gĭt nanê̆ ma Brah Krist ngơi tâm gâp. Păng mâu jêng rdja ôh đah khân may ƀiă lah jêng nau brah tâm khân may.$b$,false),
('bunong-vn','2CO',13,4,null,$b$Bu pâng Păng ta si tâm rkăng yor nau Păng huơi, ƀiă lah Păng rêh ma nau brah Brah Ndu. Tâm nau hên ƀư ma khân may, hên tâm ban lĕ jêng huơi tâm Păng, ƀiă lah hên mra gŭ rêh đah păng tâm nau brah Brah Ndu.$b$,false),
('bunong-vn','2CO',13,5,null,$b$Sek uănh hom khân may nơm gĭt lah khân may gŭ tâm nau chroh. Rlong uănh hom khân may nơm. Khân may mâu gĭt hĕ ma Brah Krist gŭ tâm khân may? Knŏng tơ lah bu mâu dun ma khân may ôh.$b$,true),
('bunong-vn','2CO',13,6,null,$b$Gâp kâp gân ma khân may mra gĭt bu mâu dun ma hên ôh.$b$,false),
('bunong-vn','2CO',13,7,null,$b$Ƀiă lah hên mbơh sơm ma Brah Ndu gay ma khân may mâu ƀư du ntil nau tih ôh. Mâu di gay ma bu saơ hên nơm dơi tâm nau rlong uănh ôh, ƀiă lah ŭch ma khân may ƀư nau ueh, nđâp tơ lah bu dun ma hên kđôi.$b$,false),
('bunong-vn','2CO',13,8,null,$b$Yor lah hên mâu geh nau brah tâm rdâng ma nau ngăn ôh, ƀiă lah knŏng ma nau ngăn.$b$,false),
('bunong-vn','2CO',13,9,null,$b$Yor lah hên maak tơ lah hên jêng huơi, ƀiă lah khân may jêng ktang. Jêh ri dôl hên mbơh sơm hên dăn ăn khân may jêng rah vah.$b$,false),
('bunong-vn','2CO',13,10,null,$b$Gâp nchih nau aơ dôl gâp ndŭt kơi khân may gay ma tơ lah, gâp hăn ta khân may gâp mâu mra ngơi ktang ôh, tĭng nâm nau dơi Kôranh Brah ăn jêh ma gâp gay ma n'hao khân may, jêh ri mâu di ŭch ƀư rai ôh.$b$,false),
('bunong-vn','2CO',13,11,null,$b$Pô ri, hơi phung oh, nâu ăn khân may răm maak. Ăn khân may jêng rah vah, tâm bonh nuih khân may jêng du ai nau. Ăn khân may gŭ đăp mpăn, jêh ri Brah Ndu nau rŏng jêh ri nau đăp mpăn mra gŭ ndrel ma khân may.$b$,true),
('bunong-vn','2CO',13,12,null,$b$Ăn khân may tâm khâl ndrăng khân may, ma nau chŭm kloh.$b$,false),
('bunong-vn','2CO',13,13,null,$b$Lĕ rngôch phung kloh ueh tâm khâl đah khân may. Ăn nau yô̆ bơh Brah Yêsu Krist, nau rŏng bơh Brah Ndu, jêh ri nau tâm rnglăp bơh Brah Huêng Ueh gŭ ndrel ma lĕ rngôch khân may.$b$,true);
insert into public.bible_headings (translation_id, book_code, chapter, before_verse, position, kind, text) values
('bunong-vn','2CO',1,1,0,'heading',$b$Ntŭk Dơn Sămƀŭt Jêh Ri Nau Khâl$b$),
