('bunong-vn','2CO',3,1,0,'heading',$b$Nau Kan Bơh Nau Tâm Rnglăp Mhe Jêh Ri Nau Kan Bơh Nau Tâm Rnglăp Ơm$b$),
('bunong-vn','2CO',4,1,0,'heading',$b$Nau Mhe Mhan Ueh Ăn Ma Lĕ Rngôch Bunuyh$b$),
('bunong-vn','2CO',5,1,0,'heading',$b$Ngih Tâm Trôk$b$),
('bunong-vn','2CO',6,1,0,'heading',$b$Y-Pôl Răp Jăp Ngăn Đah Kan Păng$b$),
('bunong-vn','2CO',6,14,1,'heading',$b$Brah Krist Jêh Ri Bêlial$b$),
('bunong-vn','2CO',8,1,0,'heading',$b$Nau Nhhơr Kơl Ngih Brah Yêrusalem$b$),
('bunong-vn','2CO',9,1,0,'heading',$b$Nau Ƀư Ueh Ma Bu Jêng Ueh Lơn$b$),
('bunong-vn','2CO',10,1,0,'heading',$b$Y-Pôl N'gang Kan Păng$b$),
('bunong-vn','2CO',11,1,0,'heading',$b$Y-Pôl Jêh Ri Đah Phung Kôranh Oh Mon Tih$b$),
