('bunong-vn','2CO',13,1,0,'heading',$b$Nau Mbơh Dăch Dŭt Ma Phung Kôrintô Nau Khâl$b$);
insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', 'GAL', $b$Galati$b$, $b$["Sămƀŭt Y-Pôl Njuăl Ma Phung", "GALATI"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','GAL',1,1,null,$b$Y-Pôl, jêng du huê kôranh oh mon, mâu di bơh phung bunuyh, mâu lah du huê bunuyh ăn jêng, ƀiă lah bơh Yêsu Krist, jêh ri Brah Ndu, Mbơ̆ , Nơm ăn dâk rêh jêh Păng bơh phung khĭt,$b$,true),
('bunong-vn','GAL',1,2,null,$b$jêh ri lĕ rngôch phung oh nâu gŭ ndrel gâp, njuăl ma phung ngih Brah Ndu ta n'gor Galati.$b$,false),
('bunong-vn','GAL',1,3,null,$b$Ăn khân may geh nau yô̆ jêh ri nau đăp mpăn bơh Brah Ndu, Mbơ̆ , jêh ri bơh Yêsu Krist Kôranh Brah he,$b$,true),
('bunong-vn','GAL',1,4,null,$b$Nơm jao jêh săk jăn Păng nơm yor nau tih he, gay ma tâm rklaih he bơh neh ntu tih mhĭk aơ, tĭng nâm nau Brah Ndu, Mbơ̆ he, ŭch;$b$,false),
('bunong-vn','GAL',1,5,null,$b$ma Păng yơh nau chrêk rmah ƀa ƀơ ƀa ƀơ n'ho ro. Amen.$b$,false),
('bunong-vn','GAL',1,6,null,$b$Gâp hih rhâl ngăn khân may ngăch cha lơi nơm kuăl khân may ma nau yô̆ bơh Brah Krist, gay tĭng nau mhe mhan êng.$b$,true),
('bunong-vn','GAL',1,7,null,$b$Mâu di geh nau mhe mhan êng ôh, ƀiă lah geh ƀa ƀă bunuyh ƀư rsuak nau mĭn khân may jêh ri khân păng ŭch nsak lơi nau mhe mhan ueh Brah Krist.$b$,true),
('bunong-vn','GAL',1,8,null,$b$Ƀiă lah hên nơm mâu lah du huê Tông mpăr ueh tă bơh trôk kđôi lĕ, mbu nơm mra mbơh ma khân may du ntil nau mhe mhan ueh êng, mha đah nau mhe mhan ueh hên mbơh jêh ma khân may, păng nây khư ma nau bu rtăp rak.$b$,false),
('bunong-vn','GAL',1,9,null,$b$Nâm bu hên lah jêh bơh lor, aƀaơ aơ gâp rkêch đŏng, tơ lah geh du huê bunuyh mra mbơh ma khân may du nau mhe mhan ueh êng mha đah nau mhe mhan ueh khân may dơn jêh, nơm nây khư ma nau bu rtăp rak yơh.$b$,false),
('bunong-vn','GAL',1,10,null,$b$Bi aƀaơ gâp tĭng joi nau bunuyh dơn, mâu lah nau Brah Ndu dơn? Mâu lah gâp ŭch ƀư maak ma bunuyh? Tơ lah gâp ŭch ƀư maak ma bunuyh, gâp mâu jêng oh mon ma Brah Krist ôh.$b$,false),
('bunong-vn','GAL',1,11,null,$b$Hơi phung oh nâu, gâp ŭch ăn khân may gĭt rah vah pô aơ, nau mhe mhan ueh gâp mbơh jêh ma khân may mâu di păng luh bơh bunuyh ôh.$b$,true),
('bunong-vn','GAL',1,12,null,$b$Yor lah gâp mâu mâp dơn, mâu lĕ mâp nti tă bơh bunuyh, ƀiă lah păng luh tă bơh nau Yêsu Krist tâm mpơl jêh ma gâp.$b$,false),
('bunong-vn','GAL',1,13,null,$b$Yor lah khân may tăng lư jêh mâm gâp jêng rnôk kăl e dôl gâp kơt nau phung Yuđa chroh. Gâp ƀư mhĭk hâu ngăn jêh ri ƀư rai phung ngih Brah Ndu.$b$,true),
('bunong-vn','GAL',1,14,null,$b$Gâp chroh jru lơn tâm nau phung Yuđa chroh rlau lơn ma phung rnôk ndrel ma gâp. Đơ phung tâm ƀon lan gâp, gâp jêng du huê geh nau duh nđơr rlau keh tĭng nau vay ơm phung u che gâp.$b$,false),
('bunong-vn','GAL',1,15,null,$b$Ƀiă lah tơ lah Brah Ndu, nơm njrăng prăp jêh gâp bơh ndŭl mê̆ gâp, kuăl gâp ma nau yô̆.$b$,false),
('bunong-vn','GAL',1,16,null,$b$Gay ma mpơl Kon Păng tâm gâp, ăn gâp mbơh Kon nây tâm phung bu năch, gâp tông ro, mâu hôm tâm nchră đah nglay săk jêh ri mham ôh.$b$,false),
('bunong-vn','GAL',1,17,null,$b$Mâu lĕ gâp hăn ta ƀon Yêrusalem gay ma tâm mâp đah phung kôranh oh mon lor lơn ma gâp, ƀiă lah gâp hăn ta n'gor Arabi; jêh ri gâp lĕ sĭt ta ƀon Đamas.$b$,false),
('bunong-vn','GAL',1,18,null,$b$Pe năm jêh ma nây, gâp hăn ta ƀon Yêrusalem gay tâm khâl đah Y-Sêphas, jêh ri gâp gŭ ndrel ma păng jât ma prăm nar.$b$,false),
('bunong-vn','GAL',1,19,null,$b$Ƀiă lah gâp ê mâp saơ kôranh oh mon êng ôh knŏng du huê Y-Yakơ, oh Kôranh Brah.$b$,false),
('bunong-vn','GAL',1,20,null,$b$(Gâp mbơh nanê̆ ta năp Kôranh Brah, nau gâp nchih ta aơ, mâu geh mƀruh ôh!)$b$,false),
('bunong-vn','GAL',1,21,null,$b$Jêh ri gâp hăn ta n'gor Siri jêh ri Silisi.$b$,false),
('bunong-vn','GAL',1,22,null,$b$Rnôk nây phung ngih Brah Krist tâm n'gor Yuđa ê gĭt năl muh măt gâp ôh.$b$,false),
('bunong-vn','GAL',1,23,null,$b$Knŏng khân păng tăng lư pô aơ: “Nơm ƀư mhĭk ma he kăl e, aƀaơ păng mbơh nau chroh, rnôk lor ri păng ŭch ƀư rai.”$b$,true),
('bunong-vn','GAL',1,24,null,$b$Pô ri khân păng tâm rnê ma Brah Ndu yor gâp.$b$,false),
('bunong-vn','GAL',2,1,null,$b$Jât ma puăn năm jêh ma nây, gâp hăn tay ta ƀon Yêrusalem ndrel ma Y-Ƀarnaƀas, nđâp ma Y-Tit lĕ.$b$,true),
('bunong-vn','GAL',2,2,null,$b$Tĭng nâm nau tâm mpơl, gâp hăn ta nây, mbơh ma phung oh nâu (ƀiă lah gâp ngơi êng đah phung kôranh toyh) gĭt nau mhe mhan ueh gâp nti ma phung bu năch, klach lah nau gâp mra nchuăt nsong, mâu lah nchuăt nsong jêh mra jêng dơm dam.$b$,false),
('bunong-vn','GAL',2,3,null,$b$Y-Tit, nơm hăn ndrel ma gâp, jêng kon phung Grek kđôi lĕ, ƀiă lah bu mâu nchâp păng koh ntâu ôh.$b$,false),
('bunong-vn','GAL',2,4,null,$b$Yor lah geh ƀa ƀă phung oh nâu mâu jêng ngăn, khân păng mŭt ntŭng tâm phung he, ŭch kâp uănh nau đăp mpăn kon mê̆ phung he geh jêh tâm Brah Krist gay ăn he jêng dĭk,$b$,false),
('bunong-vn','GAL',2,5,null,$b$djê̆ kŏ he tĭt lĕ ma khân păng, hên dun mâu ŭch tông nau khân păng ôh, gay ma nau ngăn bơh nau mhe mhan ueh gŭ nâp tâm khân may.$b$,false),
('bunong-vn','GAL',2,6,null,$b$Bi ma phung kôranh toyh (moh khân păng jêng kăl e mâu khlay ôh ma gâp; Brah Ndu mâu kơp bunuyh jêng êng êng ôh) gâp lah, phung nây jêng kôranh toyh kđôi lĕ, mâu dơi n'hao nau ueh lơn ma gâp ôh.$b$,true),
('bunong-vn','GAL',2,7,null,$b$Ƀiă lah mâu di pô nây ôh, tơ lah khân păng saơ nau mbơh nau mhe mhan ueh ma phung mâu koh ntâu jao jêh ma gâp, nâm bu nau mbơh jêh nau mhe mhan ueh ma phung koh ntâu jao jêh ma Y-Pêtrôs.$b$,true),
('bunong-vn','GAL',2,8,null,$b$Yor lah Brah Ndu, Nơm pah kan tâm Y-Pêtrôs, njuăl păng nsong ăn jêng kôranh oh mon ma phung koh ntâu, nơm nây pah kan tâm gâp nâm bu ŭch njuăl gâp nsong ăn jêng kôranh oh mon ma phung bu năch,$b$,false),
('bunong-vn','GAL',2,9,null,$b$jêh ri tơ lah khân păng gĭt năl jêh nau yô̆ bơh Brah Ndu ăn jêh ma gâp, Y-Yakơ Y-Sêphas, jêh ri Y-Yôhan, phung bu yơk uănh ma khân păng, tâm ban ma khân păng jêng phung meh ngih Brah Ndu, khân păng jao ti tâm rnglăp ma gâp jêh ri ma Y-Ƀarnaƀas, gay ăn hên hăn ta phung bu năch, bi phung khân păng, hăn ta phung koh ntâu.$b$,false),
('bunong-vn','GAL',2,10,null,$b$Knŏng khân păng ntăm ma hên ăn kah gĭt ma phung o ach, ƀiă lah nau nây gâp ŭch ƀư ngăn.$b$,false),
('bunong-vn','GAL',2,11,null,$b$Ƀiă lah dôl Y-Sêphas tât ta ƀon Antiôs, gâp tâm rdâng đah păng ta năp, yor lah păng khư ma nau bu nduyh.$b$,true),
('bunong-vn','GAL',2,12,null,$b$Yor lah lor phung bơh Y-Yakơ njuăl hăn ê tât, păng sông sa ndrel ma phung bu năch, ƀiă lah tơ lah khân păng tât, păng du gŭ êng, yor lah klach ma phung koh ntâu.$b$,false),
('bunong-vn','GAL',2,13,null,$b$Phung Yuđa êng ƀư nau ngăn tâm ban lĕ, nđâp ma Y-Ƀarnaƀas nơm lĕ kơt ƀư nau nuih n'hâm ndâp ndrel ma khân păng.$b$,false),
('bunong-vn','GAL',2,14,null,$b$Ƀiă lah tơ lah gâp saơ khân păng mâu hăn sŏng tĭng nâm nau ngăn bơh nau mhe mhan ueh, gâp lah ma Y-Sêphas ta năp lĕ rngôch bunuyh pô aơ: “Tơ lah may jêng kon Yuđa ƀiă lah ƀư nau gŭ ngao tĭng nâm phung bu năch, mâu kơt nâm bu phung kon Yuđa ôh, mâm ƀư may nchâp phung bu năch tĭng nâm phung Yuđa?”$b$,false),
('bunong-vn','GAL',2,15,null,$b$Bi hên, hên jêng kon Yuđa bơh ndŭl mê̆ hên, mâu geh jêng bunuyh tih tă bơh phung bu năch ôh.$b$,true),
('bunong-vn','GAL',2,16,null,$b$Ƀiă lah he gĭt jêh Brah Ndu yô̆ bunuyh sŏng mâu di yor kan bơh nau vay ôh, ƀiă lah ma nau chroh tâm Yêsu Krist, yor nây hên nơm chroh jêh ma Brah Krist gay dơi geh nau kơp sŏng ma nau chroh tâm păng, mâu di ma kan bơh nau vay ôh, yor lah bu mâu dơi geh nau kơp sŏng ma kan bơh nau vay ôh.$b$,false),
('bunong-vn','GAL',2,17,null,$b$Ƀiă lah tơ lah dôl hên joi nau kơp sŏng tâm Brah Krist, jêh ri bu kơp hên nơm jêng bunuyh tih, pô ri, di lĕ Brah Krist, jêng oh mon ma nau tih? Mâu! Mâu di ôh.$b$,false),
('bunong-vn','GAL',2,18,null,$b$Nanê̆ tơ lah gâp rdâk tay nau gâp hŏ ƀư rai jêh, gâp tâm mpơl ma gâp nơm jêng du huê nơm ƀư tih.$b$,false),
('bunong-vn','GAL',2,19,null,$b$Yor lah ma nau vay yơh gâp khĭt jêh ma nau vay nây gay gŭ rêh ma Brah Ndu.$b$,false),
('bunong-vn','GAL',2,20,null,$b$Bu pâng jêh gâp ta si tâm rkăng ndrel ma Brah Krist; jêh ri gâp ăt gŭ rêh, mâu di gâp ăt hôm gŭ rêh, mâu di gâp nơm ôh, ƀiă lah Brah Krist gŭ rêh tâm gâp; jêh ri aƀaơ gâp gŭ rêh tâm nglay săk, gâp gŭ rêh tâm nau chroh ma Kon Brah Ndu, nơm rŏng ma gâp jêh ri jao jêh păng nơm yor gâp.$b$,false),
('bunong-vn','GAL',2,21,null,$b$Gâp mâu ŭch ôh ƀư nau Brah Ndu yô̆ jêng dơm dam; yor lah tơ lah bu dơi geh nau kơp sŏng ma nau vay, nau Brah Krist khĭt jêng dơm dam yơh.$b$,false),
('bunong-vn','GAL',3,1,null,$b$Hơi phung Galati rluk mâl! Mbu moh ndơm khân may, ta năp măt khân may bu tâm mpơl jêh Yêsu Krist bu pâng jêh ta si tâm rkăng?$b$,true),
('bunong-vn','GAL',3,2,null,$b$Knŏng gâp ŭch ôp khân may nau aơ; ma kan bơh nau vay hĕ, mâu lah ma nau tăng jêh ri chroh khân may sŏk dơn jêh Brah Huêng Ueh?$b$,false),
('bunong-vn','GAL',3,3,null,$b$Mâm ƀư khân may jêng rluk mâl nâm bu pô nây? Jêh khân may ntơm bơh Brah Huêng Ueh, aƀaơ khân may ŭch geh nau rah vah ma nglay săk hĕ?$b$,false),
('bunong-vn','GAL',3,4,null,$b$Khân may dơn âk nau rêh ni jêng dơm dam hĕ? Tơ lah păng jêng dơm dam ngăn.$b$,false),
('bunong-vn','GAL',3,5,null,$b$Nơm ăn Brah Huêng Ueh jêh ri ƀư âk nau khlay ta nklang khân may, păng ƀư nau nây ma kan bơh nau vay, mâu lah nau hŏ mâp tăng jêh, jêh ri chroh?$b$,false),
('bunong-vn','GAL',3,6,null,$b$Nâm bu Y-Abraham: “Chroh ma Brah Ndu, nau nây kơp păng jêng sŏng”.$b$,false),
('bunong-vn','GAL',3,7,null,$b$Pô ri khân may gĭt yơh phung geh nau chroh jêng kon sau Y-Abraham ngăn.$b$,false),
('bunong-vn','GAL',3,8,null,$b$Nau nchih hŏ gĭt lor jêh lĕ ma Brah Ndu mra kơp sŏng phung bu năch ma nau chroh, pô ri hŏ mbơh lor jêh lĕ ma Y-Abraham nau mhe mhan ueh aơ: “Tâm may yơh lĕ rngôch mpôl băl bunuyh mra geh nau ueh maak”.$b$,true),
('bunong-vn','GAL',3,9,null,$b$Pô ri mbu nơm chroh, nơm nây geh nau ueh maak ndrel ma Y-Abraham, nơm hŏ geh nau chroh.$b$,false),
('bunong-vn','GAL',3,10,null,$b$Yor lah lĕ rngôch bunuyh rnơm ma kan bơh nau vay gŭ tâm dâng nau rtăp rak; yor lah geh nau nchih jêh pô aơ: “Bu hŏ rtăp jêh yơh ma mbu nơm mâu geh nau nâp jêh ri mâu tông lĕ tĭng nâm nau nchih tâm Ndrom Sămƀŭt Nau Vay”.$b$,false),
('bunong-vn','GAL',3,11,null,$b$Jêh ri nanê̆ mâu mâp geh du huê bunuyh ta năp Brah Ndu geh nau kơp sŏng ma nau vay, yor lah: “Bunuyh sŏng mra gŭ rêh yor nau chroh”.$b$,false),
('bunong-vn','GAL',3,12,null,$b$Jêh ri nau vay mâu jêng nâm bu nau chroh ôh, yor lah: “Mbu nơm tông nau vay mra gŭ rêh ma nau vay”.$b$,false),
('bunong-vn','GAL',3,13,null,$b$Brah Krist tâm chuai jêh he bơh nau vay rtăp rak, yor lah păng jêng jêh nơm bu rtăp rak yor he. Yor lah geh nau nchih jêh pô aơ: “Bu rtăp rak jêh ma du huê bunuyh bu pâng ta du n'gâng tơm si”.$b$,true),
('bunong-vn','GAL',3,14,null,$b$Gay ma nau ueh lăng ăn jêh ma Y-Abraham mra tâm pă ma phung bu năch tâm Yêsu Krist, jêh ri ma nau chroh he dơi sŏk dơn nau ton bơh Brah Huêng Ueh.$b$,false),
('bunong-vn','GAL',3,15,null,$b$Hơi phung oh nâu, gâp ngơi nâm bu, bu vay ngơi pô aơ; tơ lah du huê ƀư jêh nau tâm rnglăp, mâu geh bunuyh dơi jut ôh, mâu dơi ntop lĕ.$b$,true),
('bunong-vn','GAL',3,16,null,$b$Pô ri bu ton ăn jêh ma Y-Abraham jêh ri ma sau se păng. Păng mâu lah ôh: “Ma phung mpôl băl”, tâm ban ma âk bunuyh, ƀiă lah păng lah: “Ma sau se may, tâm ban ma du huê bunuyh, nâm bu ntĭt Brah Krist”.$b$,false),
('bunong-vn','GAL',3,17,null,$b$Pô ri gâp lah: Nau vay geh puăn rhiăng pe jât năm geh pa kơi, mâu dơi jut ôh nau tâm rnglăp Brah Ndu ƀư jêh bơh lor, mâu lĕ dơi ăn nau ton jêng dơm dam.$b$,false),
('bunong-vn','GAL',3,18,null,$b$Yor lah tơ lah ma nau vay, Brah Ndu ăn nau ndơn drăp, păng mâu jêng di ma nau ton ôh, ƀiă lah Brah Ndu ăn nau ndơn drăp ma Y-Abraham ma nau ton yơh.$b$,false),
('bunong-vn','GAL',3,19,null,$b$Pô ri, mâm ƀư geh nau vay? Bu ntop jêh nau vay yor nau ƀư tih, kŏ tât nar bunuyh luh bơh sau se, ma nơm nây yơh geh nau ton jêh; nau vay nây jao jêh ma phung Tông mpăr ueh Brah Ndu, jêh ri ăn ma du huê nơm tâm nklang mbơh ma bu.$b$,true),
('bunong-vn','GAL',3,20,null,$b$Pô ri du huê nơm ta nklang mâu di jêng knŏng ma du đah ôh; ƀiă lah Brah Ndu jêng du huê.$b$,false),
('bunong-vn','GAL',3,21,null,$b$Pô ri, nau vay tâm rdâng đah nau Brah Ndu ton? Mâu! Mâu di ôh! Yor lah tơ lah geh jêh du nau vay dơi ăn nau rêh, nanê̆ nau sŏng mra luh tă bơh nau vay nây.$b$,true),
('bunong-vn','GAL',3,22,null,$b$Ƀiă lah nau nchih: Nchăng lơi lĕ rngôch ndơ tâm dâng nau tih gay ma nau chroh tâm Yêsu Krist bu mra ăn nau ton ma phung chroh.$b$,false),
('bunong-vn','GAL',3,23,null,$b$Lor ma nau chroh tât bu krung he tâm dâng nau vay kŏ tât nau chroh tâm mpơl pa kơi.$b$,false),
('bunong-vn','GAL',3,24,null,$b$Pô ri nau vay jêng nâm bu nơm nti njŭn leo he ma Yêsu Krist, gay ma he dơi geh nau kơp sŏng ma nau chroh.$b$,false),
('bunong-vn','GAL',3,25,null,$b$Ƀiă lah tơ lah nau chroh tât jêh, he mâu hôm tông ma nơm nti nây ôh,$b$,true),
('bunong-vn','GAL',3,26,null,$b$yor lah lĕ rngôch khân may jêng kon Brah Ndu ma nau chroh tâm Yêsu Krist.$b$,false),
('bunong-vn','GAL',3,27,null,$b$Yor lah dŭm âk tâm phung khân may dơn jêh nau ƀaptem tâm Brah Krist jêng nsoh Brah Krist yơh.$b$,false),
('bunong-vn','GAL',3,28,null,$b$Ta aơ mâu geh nau êng phung Yuđa đah phung Grek ôh, mâu geh phung dĭk mâu lah phung kon me, mâu geh phung bu klâu mâu lah phung bu ur ôh; yor lah lĕ rngôch khân may jêng nguay tâm Yêsu Krist.$b$,true),
('bunong-vn','GAL',3,29,null,$b$Jêh ri tơ lah khân may jêng phung Brah Krist khân may jêng ndŭl mpôl Y-Abraham tâm ban lĕ, jêng phung dơi dơn ndơn drăp tĭng nâm nau ton jêh.$b$,false),
('bunong-vn','GAL',4,1,null,$b$Gâp lah, dôl nơm dơi ndơn drăp jêng kon se, păng mâu jêng êng êng đah dĭk ôh, nđâp tơ lah păng jêng kôranh ma lĕ rngôch drăp păng.$b$,true),
('bunong-vn','GAL',4,2,null,$b$Păng gŭ tâm dâng nơm n'gang păng jêh ri nơm chiă uănh păng, kŏ tât nar mbơ̆ păng tâm nal jêh.$b$,false),
('bunong-vn','GAL',4,3,null,$b$He jêng nâm bu pô nây lĕ, dôl he hôm jê̆ he jêng dĭk ma nau ta neh ntu mơng ƀư jêh.$b$,false),
('bunong-vn','GAL',4,4,null,$b$Ƀiă lah tơ lah tât jêh nar tâm nal, Brah Ndu njuăl Kon Păng, ăn ma du huê bu ur deh, deh tâm dâng nau vay,$b$,false),
('bunong-vn','GAL',4,5,null,$b$gay ma tâm chuai lĕ phung gŭ tâm dâng nau vay, pô ri he dơi jêng kon bu rong an.$b$,false),
('bunong-vn','GAL',4,6,null,$b$Jêh ri khân may jêng kon, Brah Ndu njuăl tâm nuih n'hâm he Brah Huêng Ueh Kon Păng, lah pô aơ: “Abba! Mbơ̆ !”$b$,false),
('bunong-vn','GAL',4,7,null,$b$Pô nây yơh khân may mâu hôm jêng dĭk ôh, ƀiă lah jêng kon, jêh ri tơ lah khân may jêng kon, khân may dơi jêng phung dơi ndơn drăp Brah Ndu.$b$,false),
('bunong-vn','GAL',4,8,null,$b$Kăl e ri khân may mâu gĭt năl Brah Ndu ôh, khân may jêng dĭk ma brah mâu khlay ôh;$b$,true),
('bunong-vn','GAL',4,9,null,$b$ƀiă lah aƀaơ khân may gĭt năl jêh Brah Ndu; mâu lah nanê̆ ngăn Brah Ndu gĭt năl jêh khân may, mâm ƀư khân may ŭch plơ̆ sĭt ma nau vay rdja jêh ri o ach jêh ri ŭch plơ̆ jêng dĭk?$b$,false),
('bunong-vn','GAL',4,10,null,$b$Khân may săch nar, khay, yan jêh ri năm.$b$,false),
('bunong-vn','GAL',4,11,null,$b$Gâp klach kan gâp pah jêng dơm dam jêh tâm phung khân may.$b$,false),
('bunong-vn','GAL',4,12,null,$b$Hơi oh nâu, gâp vơh vơl ma khân may ăn khân may jêng nâm bu gâp, yor lah gâp jêng nâm bu khân may. Khân may mâu ƀư mhĭk ma gâp ôh;$b$,true),
('bunong-vn','GAL',4,13,null,$b$ƀiă lah khân may gĭt jêh yor lah gâp geh nau rdja tâm săk jăn gâp mbơh jêh nau mhe mhan ueh ma khân may rnôk lor ri,$b$,false),
('bunong-vn','GAL',4,14,null,$b$jêh ri săk jăn gâp ra ai jêng nau rlong uănh ma khân may kđôi lĕ, khân may mâu mưch, mâu dun gâp ôh, ƀiă lah khân may rom gâp nâm bu du huê oh mon ueh Brah Ndu ngăn, nâm bu khân may rom Yêsu Krist nơm.$b$,false),
('bunong-vn','GAL',4,15,null,$b$Mbah ntŭk nau ueh maak khân may geh? Yor lah gâp dơi mbơh ma khân may pô aơ, rnôk nây, tơ lah dơi kŏ bơi ma khân may vĕk măt khân may nơm ăn ma gâp.$b$,false),
('bunong-vn','GAL',4,16,null,$b$Ƀiă lah mâm ƀư gâp jêng rlăng tay đah khân may yor lah gâp nti nau ngăn ma khân may?$b$,false),
('bunong-vn','GAL',4,17,null,$b$Phung nây geh nau duh nđơr yor khân may, ƀiă lah mâu di khân păng geh nuih n'hâm ueh ôh; ƀiă lah khân păng ŭch khân may cha lơi hên, jêh ri duh nđơr đah khân păng.$b$,false),
('bunong-vn','GAL',4,18,null,$b$Ueh lĕ geh nuih n'hâm duh nđơr ma nau ueh. Ăn khân may geh ƀa ƀơ, mâu di knŏng dôl gâp gŭ ndrel ma khân may ôh.$b$,false),
('bunong-vn','GAL',4,19,null,$b$Hơi phung kon jê̆ gâp, yor phung khân may gâp dơn nau rêh ni tâm ban ma nau ji deh kon, kŏ nau Brah Krist jêng tâm khân may!$b$,false),
('bunong-vn','GAL',4,20,null,$b$Gâp ŭch gŭ ndrel ma khân may jêh ri tâm rgâl nau gâp ngơi, yor lah gâp gŭ rngot uh ah yor khân may.$b$,false),
('bunong-vn','GAL',4,21,null,$b$Lah hom ma gâp, hơi phung ŭch gŭ tâm dâng nau vay, khân may mâu mâp tăng nau vay hĕ?$b$,true),
('bunong-vn','GAL',4,22,null,$b$Yor lah geh nau nchih jêh ma Y-Abraham geh bar hê kon bu klâu, du huê jêng kon bu ur dĭk bu, du huê jêng kon bu ur kon me.$b$,false),
('bunong-vn','GAL',4,23,null,$b$Kon bu ur dĭk bu deh tĭng nâm nglay săk, ƀiă lah kon bu ur kon me deh tĭng nâm nau ton jêh.$b$,false),
('bunong-vn','GAL',4,24,null,$b$Lĕ bar hê nây geh nau hôr pô aơ; bar hê bu ur nây jêng nau tâm ntĭt ma bar nau tâm rnglăp. Du nau tâm rnglăp tă bơh yôk Sinai, deh ma kon ăn jêng dĭk; păng nây jêng H'Agar,$b$,false),
('bunong-vn','GAL',4,25,null,$b$H'Agar nâm bu ntĭt yôk Sinai tâm n'gor Arabi, nâm bu ƀon Yêrusalem aƀaơ aơ, gŭ jêng dĭk ndrel ma kon păng.$b$,false),
('bunong-vn','GAL',4,26,null,$b$Ƀiă lah ƀon Yêrusalem ta klơ jêng kon me, jêh ri păng jêng me he.$b$,false),
('bunong-vn','GAL',4,27,null,$b$Yor lah geh nau nchih jêh pô aơ: “Maak hom! Hơi bu ur ndrô gâng. Bu ur mâu mâp deh kon Răm maak hom ay jêh ri gơm đah Hom. Nơm mâu mâp ji nau n'gơch nkeng ôh. Yor lah phung bơh kon tă bơh bu ur bu dun lơi mra jêng âk lơn ma kon bơh bu ur geh sai”.$b$,false),
('bunong-vn','GAL',4,28,null,$b$Hơi oh nâu, he jêng tâm ban ma Y-Isăk, jêng kon bơh nau ton.$b$,true),
('bunong-vn','GAL',4,29,null,$b$Ƀiă lah tâm ban ma rnôk nây, kon bu deh tĭng nâm nglay săk ƀư mhĭk ma nơm bu deh tĭng nâm Brah Huêng Ueh, aƀaơ ăt tâm ban pô nây lĕ.$b$,false),
('bunong-vn','GAL',4,30,null,$b$Moh nau nchih lah jêh? “Mprơh lơi bu ur dĭk bu jêh ri kon bu klâu păng; yor lah ma kon bu ur dĭk bu mâu dơi ndơn drăp ndrel ma kon bu ur kon me ôh”.$b$,false),
('bunong-vn','GAL',4,31,null,$b$Pô ri, hơi phung oh nâu, he mâu jêng kon bu ur dĭk bu ôh, ƀiă lah ăn jêng kon bu ur kon me.$b$,false),
('bunong-vn','GAL',5,1,null,$b$Brah Krist hŏ tâm rklaih jêh he. Ăn he jêng kon me. Pô ri gŭ nâp rjăp hom, lơi hôm tung mbăk mâng mbăk jêng dĭk bu ôh.$b$,true),
('bunong-vn','GAL',5,2,null,$b$Gâp jêng Y-Pôl, lah ma khân may pô aơ, tơ lah khân may ƀư nau koh ntâu. Brah Krist mâu jêng khlay ma khân may ôh.$b$,false),
('bunong-vn','GAL',5,3,null,$b$Gâp mbơh tay ma lĕ rngôch bunuyh, ƀư nau koh ntâu gĭt pô aơ; Ăn khân păng tông lĕ rngôch nau vay tâm ban lĕ.$b$,false),
('bunong-vn','GAL',5,4,null,$b$Tơ lah khân may ŭch geh nau kơp sŏng ma nau vay khân may tâm nkhah jêh đah Brah Krist, khân may roh nau yô̆ jêh.$b$,false),
('bunong-vn','GAL',5,5,null,$b$Ƀiă lah tâm Brah Huêng Ueh hên geh nau kâp gân dơi kơp sŏng yor ma nau chroh.$b$,false),
('bunong-vn','GAL',5,6,null,$b$Yor lah tâm Yêsu Krist nau khlay mâu di ƀư nau koh ntâu, mâu lah, mâu lĕ yor nau mâu koh ntâu, ƀiă lah nau chroh tâm mpơl tâm nau rŏng.$b$,false),
('bunong-vn','GAL',5,7,null,$b$Khân may nchuăt ueh jêh, mbu nơm nkân khân may, mâu ăn khân may tông nau ngăn?$b$,true),
('bunong-vn','GAL',5,8,null,$b$Nau ntrŭt nây mâu geh luh tă bơh nơm kuăl khân may ôh.$b$,false),
('bunong-vn','GAL',5,9,null,$b$Ndrui djê̆ lê̆ dơi ƀư ră lĕ rnih.$b$,false),
('bunong-vn','GAL',5,10,null,$b$Tâm Kôranh Brah gâp geh nau rnơm ma khân may mâu geh nau mĭn êng ôh, ƀiă lah nơm ƀư rsuak nau mĭn khân may, moh ndơ păng jêng kđôi lĕ, păng mra dơn nau tâm rmal.$b$,false),
('bunong-vn','GAL',5,11,null,$b$Hơi phung oh nâu, bi gâp, tơ lah gâp ăt nti nau koh ntâu, mâm nau bu, ƀư mhĭk ma gâp? Tơ lah pô nây nau chêh nchênh yor si tâm rkăng roh jêh.$b$,false),
('bunong-vn','GAL',5,12,null,$b$Ma phung ƀư rŭng khân may, ueh lơn ăn khân păng tâm nkhah lơi khân păng nơm ngai đah khân may!$b$,true),
('bunong-vn','GAL',5,13,null,$b$Hơi phung oh nâu, bu kuăl jêh may ma nau kon me; ƀiă lah lơi ăn kon me jêng trong ăn khân may gŭ tĭng nâm nglay săk ôh, ƀiă lah ma nuih n'hâm rŏng ăn khân may jêng oh mon ndrăng khân may nơm.$b$,true),
('bunong-vn','GAL',5,14,null,$b$Yor lah lĕ rngôch nau vay geh nau ăn nanê̆ pô aơ: “Rŏng hom ma phung chiau meng may, tâm ban ma may nơm.”$b$,true),
('bunong-vn','GAL',5,15,null,$b$Ƀiă lah, tơ lah may tâm kăp, tâm rvăn ndrăng phung khân may, njrăng hom klach lah phung aơ mra ƀư roh rai phung êng.$b$,false),
('bunong-vn','GAL',5,16,null,$b$Ƀiă lah gâp lah pô aơ: Hăn nsong hom tĭng nâm Brah Huêng Ueh, jêh ri khân may mâu mra ƀư tĭng nâm nglay săk ŭch ôh.$b$,true),
('bunong-vn','GAL',5,17,null,$b$Yor lah nglay săk geh nau ŭch êng ngăn đah nau Brah Huêng Ueh. Brah Huêng Ueh geh nau ŭch êng lĕ đah nglay săk ŭch. Yor lah bar ntil nau nây tâm rdâng, pô ri khân may mâu dơi ƀư ôh tĭng nâm nau khân may ŭch.$b$,true),
('bunong-vn','GAL',5,18,null,$b$Ƀiă lah tơ lah Brah Huêng Ueh njŭn leo khân may, khân may mâu gŭ tâm dâng nau vay ôh.$b$,false),
('bunong-vn','GAL',5,19,null,$b$Pô aơ kan bơh nglay săk rah vah jêh; nau văng tĭr, nau ƀơ̆ ƀơch, nau blă blơ,$b$,false),
('bunong-vn','GAL',5,20,null,$b$nau mbah rup brah, nau rƀên, nau tâm ƀư rlăng, nau tâm ji nuih janh nau tâm nach, nau tâm nuih, nau tâm djrel, nau tâm rnglah nau tâm nkhah pă mpôl,$b$,false),
('bunong-vn','GAL',5,21,null,$b$nau keh nach, nau nhŭl ndrănh, nau hay sa, jêh ri lĕ rngôch nau êng tâm ban lĕ. Gâp lah ma khân may, lor ri, mbu nơm ƀư tih pô nây mâu dơi dơn ƀon bri hađăch Brah Ndu.$b$,false),
('bunong-vn','GAL',5,22,null,$b$Ƀiă lah play bơh Brah Huêng Ueh pô aơ: Nau rŏng, nau maak, nau đăp mpăn, nau srôih, nau rah rơch, nau blau ƀư ueh, nau răp jăp, nau rdơ̆ rbăn, nau di keh,$b$,true),
('bunong-vn','GAL',5,23,null,$b$mâu mâp geh nau vay dơi buay nau nây ôh.$b$,false),
('bunong-vn','GAL',5,24,null,$b$Mbu nơm jêng ndơ Yêsu Krist pâng jêh nglay săk ndrel ma nau păng kơnh, jêh ri nau păng ŭch ta si tâm rkăng.$b$,false),
('bunong-vn','GAL',5,25,null,$b$Tơ lah he gŭ rêh ndrel Brah Huêng Ueh, ăn he hăn tĭng nâm Brah Huêng Ueh lĕ.$b$,false),
('bunong-vn','GAL',5,26,null,$b$Lơi joi nau lư n'găr mâu nanê̆ gay ma tâm mâu nach ndrăng băl ôh, jêh ri lơi gơnh nuih ndrăng nơm ôh.$b$,false),
('bunong-vn','GAL',6,1,null,$b$Hơi oh nâu, tơ lah du huê rhuh tâm nau tih, khân may nơm jêng phung hăn tĭng nâm Brah Huêng Ueh, ăn khân may nkra păng ma nau rdơ̆ rbăn. Bi khân may nơm njrăng lĕ, klach lah geh nau ndơm tât ma khân may tâm ban lĕ.$b$,true),
('bunong-vn','GAL',6,2,null,$b$Kơl tâm anh nau jâk ndrăng khân may, pô ri khân may ăn tâm di nanê̆ jêh nau vay bơh Brah Krist.$b$,false),
('bunong-vn','GAL',6,3,null,$b$Yor lah tơ lah du huê bunuyh mĭn păng nơm geh nau khư, ƀiă lah mâu, păng mâu khư ôh, pô ri, păng ndơm păng nơm yơh.$b$,false),
('bunong-vn','GAL',6,4,null,$b$Ƀiă lah ăn ăp nơm sek uănh ma kan păng nơm pô ri păng mra geh nau tâm rnê knŏng êng tâm păng nơm, mâu di tă bơh bu êng ôh.$b$,false),
('bunong-vn','GAL',6,5,null,$b$Yor lah ăp nơm mra anh nau jâk păng nơm.$b$,false),
('bunong-vn','GAL',6,6,null,$b$Mbu nơm tăng bu nti nau ngơi, ăn khân păng sŏk bơh lĕ ndơ khân păng geh tâm pă ăn ma nơm nti lah ma khân păng.$b$,true),
('bunong-vn','GAL',6,7,null,$b$Lơi ta ndơm khân may nơm ôh; Brah Ndu mâu dơn nau bu mưch ôh, yor lah moh ntil găr bu srih jêh, bu mra rek play păng.$b$,false),
('bunong-vn','GAL',6,8,null,$b$Mbu nơm srih ma nglay săk mra rek bơh nglay săk nau rai yot, ƀiă lah mbu nơm srih ma Brah Huêng Ueh mra rek bơh Brah Huêng Ueh nau rêh ƀa ƀơ n'ho ro.$b$,false),
('bunong-vn','GAL',6,9,null,$b$Lơi ăn he jêng rgănh tâm nau ƀư ueh, yor lah tơ lah he mâu rdja nuih n'hâm ôh, he mra rek tât ta yan găl.$b$,false),
('bunong-vn','GAL',6,10,null,$b$Pô ri dôl nar găl, ăn he ƀư nau ueh ma lĕ rngôch bunuyh, play nanê̆ ngăn ma phung oh nâu tâm nau chroh.$b$,false),
('bunong-vn','GAL',6,11,null,$b$Uănh hom sămƀŭt aơ ti gâp nơm nchih ma khân may, rplay sămƀŭt rhêh rhên.$b$,true),
('bunong-vn','GAL',6,12,null,$b$Lĕ rngôch mbu nơm ŭch ƀư maak ma bunuyh tĭng nâm nglay săk, khân păng nchâp khân may ƀư nau koh ntâu, gay ma khân păng mâu dơn nau bu ƀư mhĭk yor si tâm rkăng Brah Krist yơh.$b$,true),
('bunong-vn','GAL',6,13,null,$b$Yor lah phung nây ƀư nau koh ntâu jêh ƀiă lah mâu tông nau vay ôh. Khân păng ŭch ma khân may ƀư nau koh ntâu gay geh nau tâm rnê tâm nglay săk khân may.$b$,false),
('bunong-vn','GAL',6,14,null,$b$Bi ma gâp, gâp mâu tâm rnê ma gâp nơm ôh, knŏng tâm rnê ma si tâm rkăng Kôranh Brah he, Yêsu Krist. Yor si tâm rkăng nây neh ntu jêng khĭt jêh ma gâp tâm ban lĕ.$b$,false),
('bunong-vn','GAL',6,15,null,$b$Yor lah nau khlay mâu di nau koh ntâu, mâu di lĕ yor nau mâu koh ntâu, ƀiă lah nau jêng bunuyh mhe.$b$,false),
('bunong-vn','GAL',6,16,null,$b$Ăn nau đăp mpăn jêh ri nau yô̆ jŭr ta phung hăn tâm nau aơ, jêh ri ta phung Israel tă bơh Brah Ndu.$b$,false),
('bunong-vn','GAL',6,17,null,$b$Ntơm bơh aƀaơ rlet pa năp lơi ăn du huê bunuyh ƀư rsuak gâp ôh; yor lah gâp djôt ta săk jăn gâp nơm têl Brah Yêsu.$b$,true),
('bunong-vn','GAL',6,18,null,$b$Hơi phung oh nâu, ăn nau yô̆ bơh Kôranh Brah he, Yêsu Krist, gŭ ndrel ma huêng khân may. Amen.$b$,false);
insert into public.bible_headings (translation_id, book_code, chapter, before_verse, position, kind, text) values
