('bunong-vn','GAL',2,11,1,'heading',$b$Y-Pôl Nduyh Y-Pêtrôs$b$),
('bunong-vn','GAL',2,15,2,'heading',$b$Nau Kơp Sŏng Ma Nau Chroh Nau Gŭ Tâm Brah Krist$b$),
('bunong-vn','GAL',3,1,0,'heading',$b$Bunuyh Geh Nau Kơp Sŏng Ma Nau Chroh Mâu Di Ma Nau Vay Ôh$b$),
('bunong-vn','GAL',3,15,1,'heading',$b$Geh Nau Brah Ndu Ton Lor Ma Nau Vay$b$),
('bunong-vn','GAL',3,21,2,'heading',$b$Nau Vay Njŭn Leo Bunuyh Ma Yêsu Krist$b$),
('bunong-vn','GAL',4,1,0,'heading',$b$Bunuyh Gŭ Tâm Nau Vay Jêh Ri Tâm Nau Yô̆$b$),
('bunong-vn','GAL',4,12,1,'heading',$b$Phung Galati Rgâl Nau Mĭn Khân Păng$b$),
('bunong-vn','GAL',4,21,2,'heading',$b$H'Agar Jêh Ri H'Sara Tâm Ntĭt Ma Bar Ntil Nau Tâm Rnglăp$b$),
('bunong-vn','GAL',5,1,0,'heading',$b$Nau Kon Me Phung Chroh Geh$b$),
('bunong-vn','GAL',5,13,1,'heading',$b$Kan Bơh Nglay Săk Jêh Ri Play Bơh Brah Huêng Ueh$b$),
('bunong-vn','GAL',6,1,0,'heading',$b$Nau Srôih Jêh Ri Nau Tông Bâr$b$),
('bunong-vn','GAL',6,6,1,'heading',$b$Nau Srih Jêh Ri Nau Rek$b$),
('bunong-vn','GAL',6,11,2,'heading',$b$Nau Koh Ntâu Si Tâm Rkăng Brah Krist$b$);
insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', 'EPH', $b$Êphêsô$b$, $b$["Sămƀŭt Y-Pôl Njuăl Ma Phung", "ÊPHÊSÔ"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','EPH',1,1,null,$b$Y-Pôl, du huê kôranh oh mon Yêsu Krist, tĭng nâm nau Brah Ndu ŭch. Nchih njuăl ma lĕ rngôch phung kloh ueh gŭ ta ƀon Êphêsô jêh ri ma phung răp jăp tâm Yêsu Krist.$b$,true),
('bunong-vn','EPH',1,2,null,$b$Ăn khân may geh nau yô̆ jêh ri nau đăp mpăn luh bơh Brah Ndu, Mbơ̆ he, jêh ri Kôranh Brah he, Yêsu Krist.$b$,false),
('bunong-vn','EPH',1,3,null,$b$Mât ton ma Brah Ndu, Mbơ̆ Yêsu Krist, Kôranh Brah he; Păng Nơm ăn ma he tâm Brah Krist ăp ntil nau ueh maak brah tâm trôk ta klơ.$b$,true),
('bunong-vn','EPH',1,4,null,$b$Păng săch jêh he tâm Brah Krist bơh lor lơn ma nau rhăk njêng neh ntu, gay ma he jêng kloh ueh jêh ri mâu geh nau nduyh ôh ta năp păng.$b$,false),
('bunong-vn','EPH',1,5,null,$b$Yor nau Păng rŏng ma he, Păng săch jêh he bơh lor, gay ma he jêng kon mât rong tâm Brah Yêsu Krist. Nau nây Păng ƀư tĭng nâm nau mĭn ueh Păng,$b$,false),
('bunong-vn','EPH',1,6,null,$b$gay ma bu tâm rnê ma nau chrêk rmah nau păng yô̆, ăn jêh ma he dơm dam tâm Kon Păng rŏng ngăn ngên.$b$,false),
('bunong-vn','EPH',1,7,null,$b$Tâm Păng yơh he geh nau tâm chuai ma mham Păng, geh nau yô̆ an nau tih, tĭng nâm nau Păng ndrŏng ma nau yô̆ ,$b$,true),
('bunong-vn','EPH',1,8,null,$b$jêh ri Brah Ndu nkhŭt rmeh rmai jêh ma he ăp ntil nau blau mĭn jêh ri nau gĭt rbăng.$b$,false),
('bunong-vn','EPH',1,9,null,$b$Păng ăn he gĭt nau khlay ndâp tâm nau Păng ŭch tĭng nâm nau săch ueh Păng njêng êng tâm Păng nơm bơh lor,$b$,true),
('bunong-vn','EPH',1,10,null,$b$Gay ma nanê̆ nau Păng săch nây tâm nar mra tât, tâm rƀŭn lĕ rngôch ndơ tâm Brah Krist, nđâp ndơ tâm trôk jêh ri ndơ tâm neh ntu.$b$,false),
('bunong-vn','EPH',1,11,null,$b$Tâm Păng lĕ he jêng phung ndơn drăp tĭng nâm Păng săch jêh ma he nau nây bơh lor, tĭng nâm nau nơm njêng lĕ rngôch ndơ di ma nau Păng ŭch,$b$,false),
('bunong-vn','EPH',1,12,null,$b$gay ma he, phung kâp gân tâm Brah Krist lor lơn, yơk tâm rnê ma nau chrêk rmah Păng.$b$,false),
('bunong-vn','EPH',1,13,null,$b$Tâm Păng yơh khân may tâm ban lĕ, jêh khân may tăng nau ngơi ngăn, nâm bu ntĭt nau mhe mhan ueh ma nau tâm rklaih khân may tâm Păng khân may chroh jêh, jêh ri tâp pŏng jêh ma Brah Huêng Ueh, Păng ton jêh.$b$,true),
('bunong-vn','EPH',1,14,null,$b$Brah Huêng Ueh nây jêng tâm ban ma ndơ ton ma nau he ndơn drăp, kŏ tât nau tâm chuai ma phung păng geh jêh, gay tâm rnê ma nau chrêk rmah Păng.$b$,false),
('bunong-vn','EPH',1,15,null,$b$Yor nây, jêh gâp tăng nau khân may chroh ma Brah Yêsu Krist, jêh ri ma nau khân may rŏng ma phung kloh ueh lĕ rngôch.$b$,true),
('bunong-vn','EPH',1,16,null,$b$Gâp tâm ban lĕ lah ueh ma Brah Ndu ƀa ƀơ yor khân may, kah gĭt ma khân may ƀa ƀơ tơ lah gâp mbơh sơm.$b$,false),
('bunong-vn','EPH',1,17,null,$b$Gâp dăn ma Brah Ndu Yêsu Krist, Kôranh Brah he, Mbơ̆ nau chrêk rmah, gay ăn ma khân may nuih n'hâm mĭn ang jêh ri nau tâm mpơl, gay gĭt năl păng,$b$,false),
('bunong-vn','EPH',1,18,null,$b$jêh ri gay ma ang măt, nuih n'hâm khân may, pô ri mơ khân may gĭt moh jêng nau kâp gân nau păng kuăl jêh ri moh nau ndrŏng ma nau ndơn nau chrêk rmah prăp ma phung kloh ueh,$b$,false),
('bunong-vn','EPH',1,19,null,$b$jêh ri moh nau brah toyh mâu blau dŭt ma he, phung chroh.$b$,false),
('bunong-vn','EPH',1,20,null,$b$Ma nau brah nây yơh păng ăn Brah Krist rêh bơh phung khĭt jêh ri ăn Păng gŭ mpeh pa ma Păng tâm trôk,$b$,false),
('bunong-vn','EPH',1,21,null,$b$ta klơ lơn ma lĕ rngôch nau dơi, nau chiă uănh, nau ktang, nau chrêk rmah jêh ri ma lĕ rngôch amoh bu dơi mbơh, mâu di knŏng rnôk aƀaơ ôh, ƀiă lah nđâp ma rnôk kăndơ̆ .$b$,false),
('bunong-vn','EPH',1,22,null,$b$Păng dơm jêh lĕ rngôch ndơ tâm dâng Brah Krist jêh ri ăn păng jêng kôranh toyh ma phung ngih Brah Ndu.$b$,false),
('bunong-vn','EPH',1,23,null,$b$Phung ngih Brah Ndu nây jêng săk jăn Brah Krist, nâm bu ntĭt nau bêng rĭng păng, nơm mbêng rĭng lĕ tâm lĕ rngôch.$b$,false),
('bunong-vn','EPH',2,1,null,$b$Dôl khân may khĭt jêh yor gao nau vay jêh ri nau tih,$b$,true),
('bunong-vn','EPH',2,2,null,$b$nau khân may tĭng tông kăl e, tĭng nâm nau mơng ta neh ntu aơ, tĭng nâm hađăch brah mhĭk tâm ndâr tŭk, brah nây gŭ pah kan aƀaơ aơ tâm phung kon ƀư rlăng.$b$,false),
('bunong-vn','EPH',2,3,null,$b$Kăl e lĕ rngôch he jêng tâm ban pô nây lĕ. He gŭ rêh tĭng nâm nau nglay săk kơnh. He ƀư tĭng nâm nau nglay săk jêh ri nau mĭn rŏng. Pô ri he jêng kon ma nau hăt janh da dê nâm bu lĕ rngôch bunuyh êng.$b$,false),
('bunong-vn','EPH',2,4,null,$b$Ƀiă lah Brah Ndu, ndrŏng nau yô̆ , yor nau Păng rŏng ma he toyh ngăn.$b$,false),
('bunong-vn','EPH',2,5,null,$b$Dôl he khĭt yor nau tih he, Păng ăn he dâk rêh tay tâm Brah Krist (pô ri ma nau yô̆ yơh khân may hŏ tâm rklaih jêh khân may).$b$,false),
('bunong-vn','EPH',2,6,null,$b$Păng hŏ ăn rêh jêh he ndrel ma Brah Krist, jêh ri ăn he gŭ tâm trôk tâm Yêsu Krist,$b$,false),
('bunong-vn','EPH',2,7,null,$b$gay ma tâm mpơl tâm rnôk kăndơ̆ nau păng yô̆ mâu blau dŭt, ma nuih n'hâm ueh păng ăn jêh ma he tâm Yêsu Krist.$b$,false),
('bunong-vn','EPH',2,8,null,$b$Pô ri, yor nau yô̆ ma chroh yơh khân may rklaih jêh nau tih. Nau nây mâu di luh tă bơh khân may ôh, ƀiă lah bơh Brah Ndu ăn;$b$,false),
('bunong-vn','EPH',2,9,null,$b$mâu di yor kan he ôh; pô nây mơ lơi ăn geh bunuyh tâm rnê ma păng nơm.$b$,false),
('bunong-vn','EPH',2,10,null,$b$Yor lah he jêng kan păng. Păng rhăk njêng jêh he tâm Yêsu Krist ma kan ueh Brah Ndu nkra jêh bơh lor, gay ma he kơt ƀư. Yor si tâm rkăng Yêsu Krist phung bu năch jêh ri phung Yuđa tâm rnglăp jêng ngih ma Brah Ndu$b$,false),
('bunong-vn','EPH',2,11,null,$b$Pô ri kah gĭt hom nau khân may jêng phung bu năch tĭng nâm nglay săk dôl nây, jêh ri phung koh ntâu ma ti bunuyh tâm nglay săk kuăl khân may phung mâu koh ntâu.$b$,false),
('bunong-vn','EPH',2,12,null,$b$Rnôk nây khân may mâu geh Brah Krist ôh; mâu geh nau vay dơi jêng phung ƀon lan Israel ôh; jêng bu năch ma nau tâm rnglăp bơh nau ton tâm neh ntu mâu geh nau kâp gân jêh ri mâu geh Brah Ndu ôh.$b$,false),
('bunong-vn','EPH',2,13,null,$b$Kăl e ri khân may gŭ ngai, ƀiă lah aƀaơ aơ tâm Yêsu Krist khân may gŭ dăch jêh yor mham Yêsu Krist.$b$,true),
('bunong-vn','EPH',2,14,null,$b$Yor Păng jêng nau đăp mpăn ndrăng he. Păng yơh ăn bar mpôl băl jêng nguay. Păng ƀư rai jêh mpêr king nau tâm nkhah nkhat he.$b$,false),
('bunong-vn','EPH',2,15,null,$b$Păng ƀư rai nau rlăng tâm pă nkhah. Ma mham Păng nơm Păng ƀư rai nau vay Păng ntăm jêh. Pô ri yơh Păng ăn nau đăp mpăn dôl Păng njêng bar mpôl băl jêng du mpôl bunuyh mhe tâm Păng nơm.$b$,false),
('bunong-vn','EPH',2,16,null,$b$Jêh ri Păng tâm rnglăp ăn jêng nguay săk jăn đah Brah Ndu yor si tâm rkăng; ta nây Păng ƀư rai lơi nau rlăng ndrăng khân păng nơm.$b$,false),
('bunong-vn','EPH',2,17,null,$b$Păng văch jêh mbơh nau đăp mpăn ma khân may phung gŭ ngai, jêh ri ma phung gŭ dăch.$b$,false),
('bunong-vn','EPH',2,18,null,$b$Yor lah ma Păng yơh phung he bar dơi hăn dăch Mbơ̆ tâm nguay Brah Huêng Ueh.$b$,false),
('bunong-vn','EPH',2,19,null,$b$Pô ri yơh, khân may mâu hôm jêng phung bu năch ôh, mâu lĕ jêng bunuyh bơh pa dih, ƀiă lah khân may jêng phung ƀon lan ndrel ma phung kloh ueh, jêh ri jêng mpôl băl Brah Ndu.$b$,false),
('bunong-vn','EPH',2,20,null,$b$Bu rdâk khân may ta klơ ntur phung kôranh oh mon jêh ri phung kôranh nơm mbơh lor, Yêsu Krist Nơm lĕ jêng lŭ njônh ngih,$b$,false),
('bunong-vn','EPH',2,21,null,$b$lĕ du mlâm ngih rdâk ta klơ lŭ nây tâm khan ueh jêh, gay ma jêng du mlâm ngih kloh ueh tâm Kôranh Brah.$b$,false),
('bunong-vn','EPH',2,22,null,$b$Ma Păng yơh, khân may tâm ban lĕ rdâk ndrel, gay ma jêng du mlâm ngih ma Brah Ndu tâm Brah Huêng Ueh.$b$,true),
('bunong-vn','EPH',3,1,null,$b$Yor nau nây yơh, gâp Y-Pôl, jêng dĭk Yêsu Krist yor khân may, phung bu năch.$b$,true),
('bunong-vn','EPH',3,2,null,$b$Tơ lah khân may gĭt jêh Brah Ndu ăn ma gâp kan ma nau păng yô̆, yor khân may,$b$,false),
('bunong-vn','EPH',3,3,null,$b$ma nau tâm mpơl jêh gâp gĭt rbăng nau khlay ndâp gâp nkoch bri ma khân may tâm bar pe rplay nau.$b$,false),
('bunong-vn','EPH',3,4,null,$b$Dôl khân may uănh, khân may dơi gĭt nau gâp gĭt rbăng ma nau khlay ndâp nây tâm Brah Krist,$b$,false),
('bunong-vn','EPH',3,5,null,$b$nau khlay ndâp nây ê mâp tâm mpơl tâm rnôk êng ma phung kon bunuyh nâm bu păng tâm mpơl jêh aƀaơ đah Brah Huêng Ueh ma phung kôranh oh mon kloh ueh jêh ri ma phung kôranh nơm mbơh lor păng;$b$,false),
('bunong-vn','EPH',3,6,null,$b$nau khlay ndâp nây nâm bu ntĭt, phung bu năch jêng phung ndơn ndrel, jêng jâng ti tâm du săk jăn, jêh ri geh ndrel ma hên nau ton Brah Ndu ntăm jêh tâm Yêsu Krist ma nau mhe mhan ueh.$b$,false),
('bunong-vn','EPH',3,7,null,$b$Jêh ri gâp jêng jêh du huê oh mon ktang tĭng nâm nau ăn tă bơh nau Brah Ndu yô̆. Păng ăn ma gâp ma kan brah păng.$b$,false),
('bunong-vn','EPH',3,8,null,$b$Nanê̆ gâp jêng du huê jê̆ lơn tâm phung kloh ueh. Păng ăn jêh nau yô̆ nây ma gâp, gay ăn gâp mbơh ma phung bu năch nau Brah Krist ndrŏng mâu dơi kơp.$b$,false),
('bunong-vn','EPH',3,9,null,$b$Jêh ri ăn ang ma lĕ rngôch bunuyh gĭt ma kan nau khlay ndâp Brah Ndu, pôn tâm păng nơm bơh lĕ rngôch rnôk lor ri, Brah Ndu nơm njêng lĕ rngôch ndơ.$b$,false),
('bunong-vn','EPH',3,10,null,$b$Ŭch ma nau blau mĭn Brah Ndu mâu blau lôch mra tâm mpơl ma nau chiă uănh jêh ri ma nau brah tâm trôk klơ yor phung ngih Brah Ndu,$b$,false),
('bunong-vn','EPH',3,11,null,$b$tĭng nâm nau păng săch bơh lor nanê̆ jêh tâm Yêsu Krist, Kôranh Brah he;$b$,false),
('bunong-vn','EPH',3,12,null,$b$tâm păng he geh nau kon me yor nau chroh ma păng; dơi hăn dăch Brah Ndu ma nau rnơm.$b$,false),
('bunong-vn','EPH',3,13,null,$b$Pô ri gâp ntăm ma khân may, lơi rdja nuih n'hâm ôh yor nau rêh ni gâp dơn an ma khân may. Nau nây jêng nau chrêk rmah ma khân may.$b$,false),
('bunong-vn','EPH',3,14,null,$b$Yor nau nây yơh gâp chon kômâk ta năp Mbơ̆ .$b$,true),
('bunong-vn','EPH',3,15,null,$b$Bơh păng yơh lĕ rngôch mpôl băl tâm trôk jêh ri ta neh ntu geh amoh,$b$,false),
('bunong-vn','EPH',3,16,null,$b$gay ma păng ăn ma khân may tĭng nâm nau ndrŏng ma nau chrêk rmah, ăn khân may jêng ktang tâm nuih n'hâm đah Brah Huêng Ueh Păng;$b$,false),
('bunong-vn','EPH',3,17,null,$b$kŏ Brah Krist gŭ tâm nuih n'hâm khân may ma nau chroh; pô ri ăn reh khân may ăn lăp nâp tâm nau rŏng,$b$,false),
('bunong-vn','EPH',3,18,null,$b$gay ma nâu oh dôl khân may sŏr reh nâp mbon tâm trong nau rŏng, dơi gĭt năl ndrel phung chroh gay gĭt rbăng nau huy, ndah prêh, ndah jong ndah nau jru păng mâm,$b$,false),
('bunong-vn','EPH',3,19,null,$b$jêh ri dơi gĭt năl nau Yêsu Krist rŏng rlau lơn ma lĕ rngôch nau blau mĭn; pô nây mơ khân may mra bêng ma lĕ nau rmeh rmai bơh Brah Ndu.$b$,false),
('bunong-vn','EPH',3,20,null,$b$Pô nây yơh Brah Ndu Nơm dơi ƀư rlau lơn đŏng ma lĕ nau he dăn mâu lah he mĭn, tĭng nâm nau brah pah kan tâm he.$b$,true),
('bunong-vn','EPH',3,21,null,$b$Ăn păng geh nau chrêk rmah tâm phung ngih Brah Ndu jêh ri tâm Yêsu Krist tâm lĕ rngôch rnôk ƀa ƀơ n'ho ro! Amen.$b$,true),
('bunong-vn','EPH',4,1,null,$b$Pô ri gâp, du huê jêng bu nă yor Kôranh Brah vơh vơl ma khân may ăn hăn khư ma kan Brah Ndu kuăl jêh khân may,$b$,true),
('bunong-vn','EPH',4,2,null,$b$ma nau tông bâr ngăn ngên, jêh ri rdơ̆ rbăn, ma nau srôih ăn khân may tâm dơn ndrăng khân may ma nau rŏng,$b$,false),
('bunong-vn','EPH',4,3,null,$b$ma nau đăp mpăn ăn khân may srôih djôt prăp nau Brah Huêng Ueh tâm rnglăp.$b$,false),
('bunong-vn','EPH',4,4,null,$b$Geh knŏng du săk jăn jêh ri du Brah Huêng Ueh nâm bu Brah Ndu kuăl jêh khân may ma kan khân may ma knŏng du nau kâp gân.$b$,true),
('bunong-vn','EPH',4,5,null,$b$Geh knŏng du huê Kôranh Brah, du ntil nau chroh, du ntil nau ƀaptem.$b$,false),
('bunong-vn','EPH',4,6,null,$b$Geh knŏng nguay Brah Ndu jêh ri Mbơ̆ ma lĕ rngôch, păng gŭ ta klơ lơn ma lĕ rngôch, ndrel ma lĕ rngôch, jêh ri tâm lĕ rngôch.$b$,false),
('bunong-vn','EPH',4,7,null,$b$Ăp nơm tâm phung he hŏ geh jêh nau dơi êng êng tĭng nâm Brah Krist ăn.$b$,true),
('bunong-vn','EPH',4,8,null,$b$Yor nây bu lah jêh pô aơ: “Dôl hao klơ, Păng chông leo âk bu nă jêh ri Păng ăn nau yô̆ ma âk bunuyh”.$b$,false),
('bunong-vn','EPH',4,9,null,$b$(Pô ri, nâm bu ntĭt nau “Păng hao klơ jêh?” Di lĕ nâm bu ntĭt păng jŭr jêh lĕ tâm ntŭk tâm dâng neh?$b$,true),
('bunong-vn','EPH',4,10,null,$b$Nơm jŭr jêh jêng Nơm hao jêh lĕ ta klơ lơn ma lĕ rngôch trôk, pô ri gay ma mbêng lĕ rngôch).$b$,false),
('bunong-vn','EPH',4,11,null,$b$Păng yơh ăn nau dơi ma phung kon bunuyh ma phung aơ păng jêng kôranh oh mon, ma phung ri jêng nơm mbơh lor ma phung iti jêng nơm mbơh nau mhe mhan ueh, ma phung ito jêng Kôranh nơm nti, jêh ri nơm nti.$b$,true),
('bunong-vn','EPH',4,12,null,$b$Păng ƀư pô nây ŭch nkra lơi lĕ rngôch phung chroh gay ma dơi pah kan ma Brah Ndu tât dơi rdâk njêng săk jăn Brah Krist.$b$,false),
('bunong-vn','EPH',4,13,null,$b$Pô ri lĕ rngôch phung he dơi rnglăp jêng nguay tâm nau chroh jêh ri tâm nau gĭt năl Kon Brah Ndu, kŏ he tât văch ma toyh, ăn nŭm nau dăng ktang tâm ban ma Brah Krist nơm.$b$,false),
('bunong-vn','EPH',4,14,null,$b$Ri he mâu hôm jêng kon se ôh. Lah tât bunuyh blau nkra nau ndơm gay ƀư vĭ lơi he, ŭch đŏt rdu he nâm bu dak njach mâu lah sial khôm leo pa chiau pa ma, he mâu iăt ôh nau khân păng nti nklă nây.$b$,false),
('bunong-vn','EPH',4,15,null,$b$Ƀiă lah he ngơi ngăn ma nuih n'hâm rŏng, dĭng he văch ma toyh ăp kô̆ tâm Brah Krist.$b$,false),
('bunong-vn','EPH',4,16,null,$b$Păng jêng bôk, păng chiă uănh lĕ săk jăn, ăn ăp kô̆ tâm gop ăn di, tâm khan ăn nâp đah ryôk păng. Pô ri lah ăp kô̆ êng êng dơi jêng ăn di, ri mơ săk jăn mra văch ma toyh, tâm n'hao tâm njêng êng păng nơm tâm nau rŏng.$b$,false),
('bunong-vn','EPH',4,17,null,$b$Pô aơ nau gâp lah jêh ri mbơh ma amoh Kôranh Brah, lơi ăn khân may hăn nâm bu phung bu năch ôh. Phung nây tĭng ndô̆ nau mĭn sưr khân păng nơm.$b$,true),
('bunong-vn','EPH',4,18,null,$b$Nau khân păng gĭt rbăng jêng ngo gŭ ngai đah nau rêh Brah Ndu, yor nau rluk tâm nuih n'hâm luh tă bơh nau dăng nuih n'hâm khân păng.$b$,false),
('bunong-vn','EPH',4,19,null,$b$Khân păng roh lĕ nuih n'hâm mĭn jêh ri jao khân păng nơm tâm nau blă blơ, ŭch ƀư ăp ntil nau ƀơ̆ .$b$,true),
('bunong-vn','EPH',4,20,null,$b$Ƀiă lah mâu di pô nây ôh phung khân may nti gay ma gĭt năl Brah Krist!$b$,false),
('bunong-vn','EPH',4,21,null,$b$Tơ lah khân may tăng jêh nau Păng ngơi jêh ri khân may nti jêh tâm Păng, tĭng nâm nau ngăn tâm Yêsu Krist.$b$,false),
('bunong-vn','EPH',4,22,null,$b$Ăn khân may cha lơi hom nau gŭ ngao krao sach ơm, bunuyh ơm jêng tih mhĭk jêh yor nau kơnh ndơm.$b$,false),
('bunong-vn','EPH',4,23,null,$b$Ăn khân may ƀư tay ăn mhe tâm nau mĭn khân may.$b$,false),
('bunong-vn','EPH',4,24,null,$b$Jêh ri ăn khân may soh bunuyh mhe rhăk njêng jêh tĭng nâm bu rup Brah Ndu nơm tâm nau sŏng jêh ri nau kloh ueh luh bơh nau ngăn.$b$,false),
('bunong-vn','EPH',4,25,null,$b$Pô ri yơh, ăn ăp nơm khân may cha lơi nau mƀruh, “Ngơi ngăn ma phung chiau meng păng,” yor lah he jêng kômâk jâng jon ndrăng he.$b$,true),
('bunong-vn','EPH',4,26,null,$b$Tơ lah khân may ji nuih, lơi ƀư tih ôh; lơi iang nuih tât nar nhâp ôh.$b$,true),
('bunong-vn','EPH',4,27,null,$b$Jêh ri lơi trơn ntŭk ăn brah mhĭk ôh.$b$,false),
('bunong-vn','EPH',4,28,null,$b$Mbu nơm vay ntŭng, lơi hôm ntŭng ôh; ƀiă lah ueh lơn ăn păng pah kan sŏng srăng ma ti păng nơm, gay ma geh ndơ ăn ma nơm pưt ndơ.$b$,false),
('bunong-vn','EPH',4,29,null,$b$Lơi ăn du ntil nau ngơi mhĭk luh tă bơh trôm mbung khân may ôh, ƀiă lah tơ lah geh nau khlay, ăn khân may ngơi bar pe rplay kơl tâm n'hao nuih, jêh ri jêng ueh ma phung gŭ iăt.$b$,true),
('bunong-vn','EPH',4,30,null,$b$Lơi ăn rngot Brah Huêng Ueh Brah Ndu ôh, yor ma Păng, Brah Ndu tâp pŏng jêh khân may gay prăp ma nar tâm chuai.$b$,true),
('bunong-vn','EPH',4,31,null,$b$Ngroh lơi nau tăng bơh khân may, nau tâm nuih, nau ji nuih biănh, nau nter, nau suai rak, jêh ri nau djơh mhĭk.$b$,true),
('bunong-vn','EPH',4,32,null,$b$Ăn khân may gŭ ueh ndrăng khân may nơm, bêng ma nau blau yô̆, tâm yô̆ an ndrăng khân may nâm bu Brah Ndu yô̆ an jêh ma khân may tâm Brah Krist.$b$,false),
('bunong-vn','EPH',5,1,null,$b$Ăn khân may jêng phung tĭng Brah Ndu nâm bu phung kon Păng rŏng ngăn ngên.$b$,true),
('bunong-vn','EPH',5,2,null,$b$Hăn hom tâm nau rŏng nâm bu Brah Krist rŏng jêh ma he, jêh ri Păng jao Păng nơm ma Brah Ndu yor he, jêng nâm bu ndơ nhhơr ndơ ƀư brah ƀâu kah ma Brah Ndu.$b$,false),
('bunong-vn','EPH',5,3,null,$b$Ma nau văng tĭr, nau ƀơ̆ , nau kơnh, lơi tâm ngơi ndrăng khân may ôh, pô ri khư ma phung kloh ueh.$b$,false),
('bunong-vn','EPH',5,4,null,$b$Lơi ngơi mƀruh ôh, lơi ngơi lă lêng, lơi ăn geh nau pâl lôr blă blơ, yor nau nây mâu ueh ôh, ƀiă lah ueh lơn ăn khân may tâm rnê ma Brah Ndu.$b$,false),
('bunong-vn','EPH',5,5,null,$b$Yor lah ăn khân may gĭt ma phung bunuyh văng tĭr, phung bunuyh ƀơ̆ , phung kơnh, (phung nây jêng tâm ban ma phung mbah rup) khân păng mâu dơi ndơn drăp tâm ƀon bri hađăch Brah Krist jêh ri Brah Ndu ôh.$b$,false),
('bunong-vn','EPH',5,6,null,$b$Lơi ăn bu ndơm khân may ma nau mƀruh ôh, yor bơh nau nây yơh nau Brah Ndu ji nuih tŭp ta phung kon ƀư rlăng.$b$,false),
('bunong-vn','EPH',5,7,null,$b$Lơi tâm rnglăp đah phung nây ôh.$b$,true),
('bunong-vn','EPH',5,8,null,$b$Kăl e, khân may gŭ tâm nau ngo, ƀiă lah aƀaơ khân may jêng ang tâm Kôranh Brah. Hăn hom tâm ban ma phung kon nau ang,$b$,true),
('bunong-vn','EPH',5,9,null,$b$yor lah nau ang jêng nau ueh, nau sŏng, jêh ri nau nanê̆.$b$,false),
('bunong-vn','EPH',5,10,null,$b$Joi hom moh nau ƀư maak ma Kôranh Brah,$b$,false),
('bunong-vn','EPH',5,11,null,$b$jêh ri lơi pah ndrel ôh kan mâu ueh bơh nau ngo, ƀiă lah ueh lơn ăn khân may nduyh khân păng.$b$,false),
('bunong-vn','EPH',5,12,null,$b$Yor lah bu prêng jêh ngơi ma kan phung nây ƀư tâm nau ndâp.$b$,false),
('bunong-vn','EPH',5,13,null,$b$Ƀiă lah lĕ rngôch nau nduyh nây tâm mpơl jêh ma nau ang, yor lah lĕ rngôch nau tâm mpơl jêh jêng ang,$b$,false),
('bunong-vn','EPH',5,14,null,$b$yor nây bu lah jêh: “Hơi nơm dôl bêch, kah rngăl hom may, dâk hom may bơh phung khĭt, jêh ri Brah Krist mra ƀư ang may”.$b$,false),
('bunong-vn','EPH',5,15,null,$b$Pô ri njrăng hom khân may ma nau gŭ ngao krao sach. Lơi jêng nâm bu phung rluk ôh, ƀiă lah ăn jêng nâm bu phung gĭt mleh.$b$,true),
('bunong-vn','EPH',5,16,null,$b$Dŏng nar khân may ăn ueh, yor lah rnôk mhĭk.$b$,false),
('bunong-vn','EPH',5,17,null,$b$Yor nây, lơi ƀư jêng nâm bu phung rluk mâl ôh, ƀiă lah ăn khân may gĭt vât moh nau Kôranh Brah ŭch.$b$,false),
('bunong-vn','EPH',5,18,null,$b$Lơi ta khân may nhŭl ndrănh ôh, yor lah ndrănh ƀư rluk khân may, ƀiă lah ăn khân may bêng ma Brah Huêng Ueh.$b$,false),
('bunong-vn','EPH',5,19,null,$b$Ăn khân may tâm n'hao nuih khân may nơm ma nau mprơ ơm, ma nau mât ton, jêh ri ma nau tâm rnê. Ăn khân may mprơ tâm rnê ma Kôranh Brah ma lĕ nuih n'hâm.$b$,false),
('bunong-vn','EPH',5,20,null,$b$Ăn khân may lah ueh ƀa ƀơ ma Brah Ndu, Mbơ̆ , ma lĕ rngôch ndơ ma amoh Kôranh Brah he Yêsu Krist.$b$,false),
('bunong-vn','EPH',5,21,null,$b$Ăn khân ay may tâm tông ndrăng nơm tâm nau klach yơk mbah ma Yêsu Krist.$b$,true),
('bunong-vn','EPH',5,22,null,$b$Hơi phung bu ur, ăn khân ay tông ma sai khân ay nâm bu ma Kôranh Brah yơh.$b$,true),
('bunong-vn','EPH',5,23,null,$b$Yor lah sai jêng kôranh ma ur păng, tâm ban ma Brah Krist jêng kôranh ma phung ngih Brah Ndu. Phung ngih Brah Ndu jêng săk jăn păng jêh ri păng jêng Nơm Tâm Rklaih ma săk jăn.$b$,true),
('bunong-vn','EPH',5,24,null,$b$Pô nây tâm ban ma phung ngih Brah Ndu tông ma Brah Krist, ăn phung bu ur tông ma sai khân păng tâm lĕ ndơ tâm ban lĕ.$b$,false),
('bunong-vn','EPH',5,25,null,$b$Hơi phung sai, ăn khân may rŏng ma ur khân may nâm bu Brah Krist rŏng jêh ma phung ngih Brah Ndu jêh ri jao ăn păng nơm yor ma phung kloh ueh.$b$,false),
('bunong-vn','EPH',5,26,null,$b$Ŭch prăp an păng tơ lah păng ƀư kloh ma dak nau păng ngơi;$b$,false),
('bunong-vn','EPH',5,27,null,$b$gay ma tâm mpơl ta năp păng phung ngih Brah Ndu aơ bêng ma nau chrêk rmah, mâu geh ntŭk ƀơ̆ , mâu geh ntŭk nsŭn, mâu geh ndơ tâm ban pô nây ôh, ƀiă lah kloh ueh jêh ri mâu geh ndơ bu dơi nduyh ôh.$b$,false),
('bunong-vn','EPH',5,28,null,$b$Ăn phung sai rŏng ma ur khân păng nơm, nâm bu rŏng ma săk jăn păng nơm lĕ. Mbu nơm rŏng ma ur, jêng tâm ban rŏng ma păng nơm lĕ.$b$,false),
('bunong-vn','EPH',5,29,null,$b$Mâu mâp geh ôh du huê bunuyh tâm rmot êng ma săk păng nơm, ƀiă lah păng mât siăm săk păng nơm ăn ueh, tâm ban ma Brah Krist mât uănh mpôl phung chroh.$b$,false),
('bunong-vn','EPH',5,30,null,$b$Yor lah he jêng kômâk jâng jon tâm săk jăn păng.$b$,false),
('bunong-vn','EPH',5,31,null,$b$“Yor nây bu klâu mra cha lơi mê̆ mbơ̆ păng, hăn gŭ ndrel ma ur păng, jêh ri lĕ bar hê khân păng du nglay săk.”$b$,false),
('bunong-vn','EPH',5,32,null,$b$Nau khlay ndâp aơ toyh ngăn, gâp lah nau aơ tâm ntĭt ma Brah Krist jêh ri phung ngih Brah Ndu.$b$,false),
('bunong-vn','EPH',5,33,null,$b$Pô nây yơh, ăn ăp nơm khân may rŏng ma ur păng nâm bu păng rŏng ma păng nơm, jêh ri ăn ur yơk ma sai păng.$b$,false),
('bunong-vn','EPH',6,1,null,$b$Hơi phung kon, tông hom ma mê̆ mbơ̆ tĭng nâm Kôranh Brah, yor lah nau nây sŏng.$b$,true),
('bunong-vn','EPH',6,2,null,$b$“Yơk hom ma mbơ̆ mê̆ ay may.” (Aơ nau vay mrô nguay geh nau ton ndrel).$b$,false),
('bunong-vn','EPH',6,3,null,$b$“Pô nây mơ ay may gŭ maak jêh ri gŭ rêh jŏ ta neh ntu aơ.”$b$,false),
('bunong-vn','EPH',6,4,null,$b$Jêh ri hơi phung mbơ̆ , lơi ta khân may lŏk lôr oh kon khân may ôh ƀiă lah mât rong khân păng ma nau nkra jêh ri nau sâm nti tâm Kôranh Brah.$b$,true),
('bunong-vn','EPH',6,5,null,$b$Hơi phung oh mon, ăn khân may tông ma nơm jêng kôranh khân may tâm nglay săk ma nau klach, ma nau yơk jêh ri ma nuih n'hâm sŏng, nâm bu ma Brah Krist lĕ;$b$,true),
('bunong-vn','EPH',6,6,null,$b$mâu di tông knŏng ta năp măt ôh, nâm bu khân may joi nau maak ma bunuyh, ƀiă lah nâm bu phung oh mon Brah Krist ƀư tĭng nâm nau Brah Ndu ŭch ma nuih n'hâm ueh.$b$,false),
('bunong-vn','EPH',6,7,null,$b$Pah kan ma khân păng ma nau rŏng nâm bu khân may pah kan ma Kôranh Brah nơm, mâu di nâm bu ma bunuyh ôh,$b$,false),
('bunong-vn','EPH',6,8,null,$b$khân may gĭt jêh geh tơ̆ jêng dĭk, geh tơ̆ jêng kon me, ăp nơm mra geh nau nkhôm bơh Kôranh Brah tĭng nâm nau ueh păng ƀư jêh.$b$,false),
('bunong-vn','EPH',6,9,null,$b$Hơi phung kôranh, ăn khân may ƀư tâm ban lĕ đah khân păng, jêh ri lơi thăm rmat ma khân păng ôh. Khân may gĭt jêh khân may nơm jêh ri khân păng geh du huê kôranh ndrel tâm trôk, jêh ri ta năp păng lĕ rngôch bunuyh tâm ban.$b$,true),
('bunong-vn','EPH',6,10,null,$b$Pô nây yơh, ăn ktang hom khân may tâm Kôranh Brah ma nau ktang brah păng.$b$,true),
('bunong-vn','EPH',6,11,null,$b$Ăn khân may sŏk bơh Brah Ndu lĕ rngôch ndơ tâm lơh, gay ma khân may dơi gŭ rjăp rdâng đah nau brah mhĭk ndơm.$b$,true),
('bunong-vn','EPH',6,12,null,$b$Yor lah nau tâm lơh mâu di ma nglay săk, ma mham ôh, ƀiă lah ma nau tŭn jot, ma nau chiă uănh, ma phung kôranh hađăch neh ntu ngo aơ, ma phung brah mhĭk gŭ tâm trôk.$b$,false),
('bunong-vn','EPH',6,13,null,$b$Yor nây sŏk hom bơh Brah Ndu jêng ndơ tâm lơh, gay ma khân may dơi rdâng tâm nar mhĭk, jêh ri tơ lah jêh khân may dơi lĕ rngôch, khân may mra gŭ nâp.$b$,false),
('bunong-vn','EPH',6,14,null,$b$Gŭ nâp hom, sŏk nau ngăn jêng rse bŭt khân may, nsoh nau sŏng jêng ao loih.$b$,true),
('bunong-vn','EPH',6,15,null,$b$Ndrăp bơh nau mhe mhan ueh đăp mpăn jêng ndrom jâng khân may.$b$,true),
('bunong-vn','EPH',6,16,null,$b$Sŏk nau chroh jêng nâm bu khêl. Ma ndơ nây khân may dơi nhhât lĕ rngôch hăr ŭnh nơm mhĭk.$b$,false),
('bunong-vn','EPH',6,17,null,$b$Tâm ban lĕ ndô hom nau tâm rklaih jêng đon, jêh ri djôt đao gưm Brah Huêng Ueh, nâm bu ntĭt, Nau Brah Ndu Ngơi.$b$,false),
('bunong-vn','EPH',6,18,null,$b$Ma Brah Huêng Ueh mbơh sơm ƀa ƀơ jêh ri vơh vơl. Njrăng mro nau nĕ ma nau srôih, jêh ri mbơh sơm ma lĕ rngôch phung kloh ueh.$b$,false),
('bunong-vn','EPH',6,19,null,$b$Mbơh sơm an ma gâp ƀă, gay ma Brah Ndu ăn ma gâp, tơ lah gâp hă bâr nti lah, nơih mbơh nau khlay ndâp bơh nau mhe mhan ueh.$b$,false),
('bunong-vn','EPH',6,20,null,$b$Yor kan nây gâp jêng oh mon ktang bu kât ma rse rvăk, gay ma gâp dơi ngơi ma nau janh, nau bu ăn gâp ngơi.$b$,false),
('bunong-vn','EPH',6,21,null,$b$Gay ma khân may tâm ban lĕ gĭt nau gâp, jêh ri kan gâp. Y-Tisik oh nâu he rŏng ngăn ngên, du huê oh mon răp jăp ma Kôranh Brah, mra ăn khân may gĭt lĕ.$b$,true),
('bunong-vn','EPH',6,22,null,$b$Gâp njuăl păng hăn ma khân may gay ma khân may gĭt mâm nau tât ma hên aƀaơ aơ, jêh ri gay păng bonh leng nuih n'hâm khân may.$b$,true),
('bunong-vn','EPH',6,23,null,$b$Ăn Brah Ndu, Mbơ̆ , jêh ri Yêsu Krist Kôranh Brah, ăn nau đăp mpăn jêh ri nau rŏng ma nau chroh phung oh nâu.$b$,true),
('bunong-vn','EPH',6,24,null,$b$Ăn nau yô̆ gŭ ndrel ma lĕ rngôch phung rŏng ma Kôranh Brah he, Yêsu Krist, ma nau rŏng mâu geh rgâl ôh.$b$,false);
insert into public.bible_headings (translation_id, book_code, chapter, before_verse, position, kind, text) values
('bunong-vn','EPH',1,1,0,'heading',$b$Ntŭk Dơn Sămƀŭt Jêh Ri Nau Khâl$b$),
('bunong-vn','EPH',1,3,1,'heading',$b$Nau Ueh Maak Brah Ndu Ăn Jêh Tâm Yêsu Krist Ma Phung Păng Săch Jêh$b$),
('bunong-vn','EPH',1,15,2,'heading',$b$Y-Pôl Mbơh Sơm Ma Phung Êphêsô Gay Ma Khân Păng Gĭt Rah Vah Nau Tâm Rklaih Tâm Brah Krist$b$),
('bunong-vn','EPH',2,1,0,'heading',$b$Nau Tâm Rklaih Ma Nau Yô̆ Bơh Brah Ndu$b$),
('bunong-vn','EPH',3,1,0,'heading',$b$Nau Khlay Ndâp Ma Nau Brah Ndu Kuăl Phung Bu Năch$b$),
('bunong-vn','EPH',3,14,1,'heading',$b$Nau Yêsu Krist Rŏng Mâu Geh Dŭt$b$),
('bunong-vn','EPH',4,1,0,'heading',$b$Phung Chroh Jêng Nguay$b$),
('bunong-vn','EPH',4,17,1,'heading',$b$Nau Nti Ăn Blau Du Đah Nau Tih Djơh Mhĭk Neh Ntu Jêh Ri Ăn Nsoh Bunuyh Mhe$b$),
('bunong-vn','EPH',5,1,0,'heading',$b$Nau Phung Kon Brah Ndu Blau Rŏng Gŭ Kloh Ueh Jêh Ri Blau Njrăng$b$),
('bunong-vn','EPH',5,21,1,'heading',$b$Nau Vay Ndrăng Ur Sai$b$),
('bunong-vn','EPH',6,1,0,'heading',$b$Nau Vay Phung Kon Jêh Ri Phung Mbơ̆ Mê̆$b$),
('bunong-vn','EPH',6,5,1,'heading',$b$Nau Vay Phung Oh Mon Jêh Ri Phung Kôranh$b$),
