('bunong-vn','EPH',6,21,3,'heading',$b$Kan Njuăl Y-Tisik Nsong Nau Khâl$b$);
insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', 'PHP', $b$Philip$b$, $b$["Sămƀŭt Y-Pôl Njuăl Ma Phung", "PHILIP"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','PHP',1,1,null,$b$Y-Pôl jêh ri Y-Timôthê, oh mon Yêsu Krist, nchih njuăl ma lĕ rngôch phung kloh ueh tâm Yêsu Krist ta ƀon Philip, nđâp ma phung bu bŭnh bu ranh jêh ri ma phung kôranh ngih Brah Ndu.$b$,true),
('bunong-vn','PHP',1,2,null,$b$Ăn khân may geh nau yô̆ jêh ri nau đăp mpăn bơh Brah Ndu, Mbơ̆ he, jêh ri Kôranh Brah he, Yêsu Krist.$b$,false),
('bunong-vn','PHP',1,3,null,$b$Gâp tâm rnê ma Brah Ndu ăp tơ̆ gâp kah gĭt ma khân may,$b$,true),
('bunong-vn','PHP',1,4,null,$b$jêh ri ăp tơ̆ gâp mbơh sơm ma lĕ rngôch khân may, ăt gâp mbơh sơm ma nau răm maak,$b$,false),
('bunong-vn','PHP',1,5,null,$b$yor lah khân may kơl pah kan jêh ma nau mhe mhan ueh bơh nar khân may ntơm tăng tât aƀaơ.$b$,false),
('bunong-vn','PHP',1,6,null,$b$Gâp chroh ngăn ma nơm ntơm kan ueh tâm phung khân may mra ăn rah vah kan nây kŏ tât nar Yêsu Krist.$b$,false),
('bunong-vn','PHP',1,7,null,$b$Di jêh nau gâp mĭn pô nây ma lĕ rngôch khân may, yor lah gâp prăp khân may tâm nuih n'hâm gâp. Geh tơ̆ tâm nau kât gâp mâu lah tâm nau n'gang jêh ri nau ƀư nanê̆ nau mhe mhan ueh, khân may geh jêh ndrel ma gâp nau yô̆ bơh Brah Ndu.$b$,true),
('bunong-vn','PHP',1,8,null,$b$Yor lah Brah Ndu jêng nơm mbơh ma gâp tâm nau gâp rŏng ngăn ngên ma lĕ rngôch khân may ma nau rŏng rdơ̆ rbăn bơh Yêsu Krist.$b$,true),
('bunong-vn','PHP',1,9,null,$b$Tâm nau gâp mbơh sơm, gâp dăn gay ma nau rŏng khân may tâm n'hao âk lơn ƀrư̆ ƀrư̆ tâm nau gĭt rbăng jêh ri bêng ma nau gĭt mĭn;$b$,false),
('bunong-vn','PHP',1,10,null,$b$gay ma khân may gĭt n'hêl nanê̆ nau ueh lơn, ăn khân may jêng kloh ueh jêh ri mâu geh nau bu nduyh ôh ta nar Brah Krist;$b$,false),
('bunong-vn','PHP',1,11,null,$b$bêng ma play nau sŏng bơh Yêsu Krist ma nau chrêk rmah jêh ri nau tâm rnê ma Brah Ndu.$b$,false),
('bunong-vn','PHP',1,12,null,$b$Hơi oh nâu, gâp ŭch ma khân may gĭt nau tât jêh ma gâp jêng nau kơl tâm n'hao kan nau mhe mhan ueh;$b$,true),
('bunong-vn','PHP',1,13,null,$b$kŏ tâm lĕ rngôch ngih phat dôih jêh ri lam ntŭk êng gĭt jêh bu kât gâp yor Brah Krist;$b$,false),
('bunong-vn','PHP',1,14,null,$b$jêh ri âk phung oh nâu tâm Kôranh Brah n'hao nuih yor nau bu kât gâp, jêh ri geh nau janh lơn mbơh Nau Brah Ndu Ngơi mâu geh nau klach ôh.$b$,false),
('bunong-vn','PHP',1,15,null,$b$Nanê̆ geh ƀa ƀă nti Brah Krist ma nau mô nach, jêh ri nau tâm rlăch, ƀiă lah geh phung êng nti ma nau ueh.$b$,true),
('bunong-vn','PHP',1,16,null,$b$Phung aơ ƀư ma nuih n'hâm rŏng yor khân păng gĭt bu njêng gâp gay n'gang nau mhe mhan ueh,$b$,false),
('bunong-vn','PHP',1,17,null,$b$bi phung nây geh nau mĭn tâm nkhah nchâp. Khân păng mbơh Brah Krist ma nau ŭch mâu sŏng ôh, mĭn ntop nau rêh ni âk lơn ma nau bu kât gâp.$b$,false),
('bunong-vn','PHP',1,18,null,$b$Moh khlay? Ăp ntil nau khân păng ƀư ma nau jan lah mâu lah ma nau ngăn amoh Brah Krist ăt bu mbơh mro lĕ; yor nau nây gâp maak, jêh ri ăt gâp mra maak mro.$b$,false),
('bunong-vn','PHP',1,19,null,$b$Yor lah gâp gĭt nau khân may mbơh sơm jêh ri Brah Huêng Ueh Yêsu Krist kơl, nau nây mra plăch nau tâm rklaih gâp,$b$,false),
('bunong-vn','PHP',1,20,null,$b$tĭng nâm nau gâp kâp nanê̆ jêh ri nau kâp gân, mâu bêk ôh ƀiă lah ma nau janh ngăn, aƀaơ jêh ri ƀa ƀơ, Brah Krist mra geh nau chrêk rmah tâm săk jăn gâp gĭt lah ma nau rêh gâp mâu lah ma nau gâp khĭt.$b$,false),
('bunong-vn','PHP',1,21,null,$b$Yor lah Brah Krist jêng nau rêh gâp, jêh ri nau khĭt jêng nau ueh lơn ma gâp.$b$,false),
('bunong-vn','PHP',1,22,null,$b$Ƀiă lah tơ lah gâp hôm gŭ rêh tâm nglay săk jêng khlay lơn ma kan gâp, gâp mâu gĭt ôh moh nau gâp mra săch.$b$,false),
('bunong-vn','PHP',1,23,null,$b$Geh bar đah nau mpet gâp; gâp ŭch ngăn hăn gŭ ndrel ma Brah Krist jêng nau ueh lơn.$b$,true),
('bunong-vn','PHP',1,24,null,$b$Ƀiă lah khlay lơn ma khân may tơ lah gâp hôm gŭ rêh tâm nglay săk.$b$,false),
('bunong-vn','PHP',1,25,null,$b$Jêh ri gâp chroh ngăn, gâp gĭt ma gâp ăt mra gŭ rêh, jêh ri gŭ ndrel đah lĕ rngôch khân may gay tâm n'hao jêh ri ƀư maak khân may tâm nau chroh,$b$,false),
('bunong-vn','PHP',1,26,null,$b$gay ma tơ lah gâp plơ̆ sĭt ma khân may, yor gâp khân may mra geh âk nau dơi tâm rnê tâm Yêsu Krist.$b$,false),
('bunong-vn','PHP',1,27,null,$b$Pô ri ăn khân may gŭ ngao krao sach khư ma nau mhe mhan ueh Brah Krist, gay ma gĭt lah gâp hăn khâl khân may, mâu lah gâp ndŭt kơi; gâp mra gĭt ma khân may gŭ nâp du ai, tâm lơh ma du nau mĭn yor nau chroh ma nau mhe mhan ueh,$b$,true),
('bunong-vn','PHP',1,28,null,$b$jêh ri lơi ăn ôh du ntil ndơ phung rlăng nhhu khân may, nau nây jêng nau khân păng tâm mbên ma nau rai yot, ƀiă lah nau tâm rklaih khân may, jêh ri nau nây luh bơh Brah Ndu.$b$,false),
('bunong-vn','PHP',1,29,null,$b$Yor Brah Krist ăn jêh ma khân may mâu di knŏng chroh, ƀiă lah ăn khân may dơn nau rêh ni yor păng tâm ban lĕ.$b$,false),
('bunong-vn','PHP',1,30,null,$b$Khân may dơn nau tâm lơh nâm bu khân may saơ jêh tâm gâp, jêh ri aƀaơ khân may gĭt, gâp ăt dơn.$b$,true),
('bunong-vn','PHP',2,1,null,$b$Tơ lah geh nau tâm bonh tâm Brah Krist, tơ lah geh nau n'hao nuih tâm nau rŏng tơ lah geh tâm rnglăp tâm Brah Huêng Ueh, tơ lah geh nuih n'hâm rŏng jêh ri nau yô̆,$b$,true),
('bunong-vn','PHP',2,2,null,$b$ăn khân may ƀư rah vah nau maak gâp tâm nau khân may gŭ du ai, du nau rŏng, du nau dơn, jêh ri du nau mĭn.$b$,false),
('bunong-vn','PHP',2,3,null,$b$Lơi ƀư ôh du ntil ndơ ma nau mĭn tâm nkhah mâu lah ma nau lư n'găr gơnh roh, ƀiă lah ma nau dêh rhêt ăn khân may uănh ma phung êng jêng toyh lơn ma khân may.$b$,false),
('bunong-vn','PHP',2,4,null,$b$Ăn ăp nơm tâm phung khân may lơi mĭn ma nau khlay ma păng nơm ôh, ƀiă lah mĭn nđâp ma bu êng tâm ban lĕ.$b$,false),
('bunong-vn','PHP',2,5,null,$b$Ăn khân may geh nau mĭn tâm ban ma Brah Yêsu hŏ geh jêh.$b$,false),
('bunong-vn','PHP',2,6,null,$b$Păng jêng tâm ban ma Brah Ndu, ƀiă lah păng mâu prăp kuan nau jêng tâm ban nây ôh.$b$,true),
('bunong-vn','PHP',2,7,null,$b$Păng doh êng Păng nơm, cha lơi nau tâm ban nây, Păng njêng Păng nơm tâm ban ma bunuyh dĭk bu.$b$,true),
('bunong-vn','PHP',2,8,null,$b$Păng njêng tâm ban ma săk kon bunuyh, tâm nglay săk kon bunuyh Păng ƀư dêh rhêt lơn đŏng. Păng dơn nau khĭt, tông bâr kŏ tât khĭt ta si tâm rkăng nâm bu geh dôih jru.$b$,true),
('bunong-vn','PHP',2,9,null,$b$Yor ri Brah Ndu n'hao Păng tâm ntŭk dŭt prêh klơ jêh ri ăn bu yơk ma amoh Păng jêng nơm toyh ta klơ lơn tâm lĕ amoh êng êng.$b$,true),
('bunong-vn','PHP',2,10,null,$b$Lĕ phung tâm trôk, tâm neh ntu, jêh ri tâm dâng neh mra chon mon yơk mbah ma amoh Brah Yêsu,$b$,true),
('bunong-vn','PHP',2,11,null,$b$jêh ri ăp ntil bâr ngơi khân păng mra mbơh Yêsu Krist jêng Kôranh, gay tâm rnê ma Brah Ndu Mbơ̆ .$b$,false),
('bunong-vn','PHP',2,12,null,$b$Pô ri, hơi phung oh nâu gâp rŏng ngăn ngên nâm bu khân may vay tông ƀa ƀơ, mâu di knŏng ta năp gâp ôh, ƀiă lah tông âk lơn aƀaơ dôl gâp ndŭt kơi, pah kan hom ma nau tâm rklaih khân may ma nau klach jêh ri nau râm sâr.$b$,true),
('bunong-vn','PHP',2,13,null,$b$Yor lah Brah Ndu gŭ pah kan tâm khân may, njêng tâm khân may nđâp nau ŭch jêh ri nau dơi ƀư nau maak ma Păng.$b$,false),
('bunong-vn','PHP',2,14,null,$b$Ăp ntil kan khân may ƀư, lơi ngơi ƀŭk dŭk suyh mâu lah vât vâng ôh,$b$,false),
('bunong-vn','PHP',2,15,null,$b$gay ma ta nklang phung tih jêh ri mhĭk ngăn, khân may jêng rsang jêh ri kloh, jêng kon Brah Ndu, mâu têl, mâu rsŭn, mâu geh nau bu dơi nduyh ôh. Ta nklang khân păng khân may sol tâm ban ma ŭnh rdo tâm neh ntu.$b$,false),
('bunong-vn','PHP',2,16,null,$b$Djôt nau ngơi rêh. Pô ri ta nar Brah Krist, gâp dơi tâm rnê ma gâp nơm yor lah gâp mâu nchuăt dơm dam ôh, mâu lĕ pah kan dơm dam.$b$,false),
('bunong-vn','PHP',2,17,null,$b$Nđâp tơ lah mham gâp nkhŭt ta klơ ndơ nhhơr jêh ri kan nau chroh khân may, gâp maak lĕ jêh ri maak ndrel ma khân may lĕ rngôch.$b$,false),
('bunong-vn','PHP',2,18,null,$b$Khân may tâm ban lĕ, maak hom ma nau nây jêh ri maak ndrel ma gâp.$b$,false),
('bunong-vn','PHP',2,19,null,$b$Pô ri gâp kâp gân tâm Brah Yêsu mra njuăl gơnh Y-Timôthê ma khân may, gay ma gâp nơm geh nau n'hao nuih dôl tăng nau mhe mhan tă bơh khân may.$b$,true),
('bunong-vn','PHP',2,20,null,$b$Yor lah gâp mâu geh du huê ta aơ geh nau mĭn tâm ban ma păng, gay mĭn ma kan khân may ma nuih n'hâm răp jăp.$b$,false),
('bunong-vn','PHP',2,21,null,$b$Nanê̆ lĕ rngôch joi nau khân păng nơm ŭch, mâu di nau Yêsu Krist ŭch ôh.$b$,false),
('bunong-vn','PHP',2,22,null,$b$Ƀiă lah khân may gĭt jêh păng geh nau rlong uănh jêh ri păng pah kan ma nau mhe mhan ueh ndrel ma gâp nâm bu kon đah Mbơ̆ păng.$b$,false),
('bunong-vn','PHP',2,23,null,$b$Pô ri, gâp mĭn njuăl păng ma khân may tơ lah gâp gĭt nanê̆ nau tât ma gâp;$b$,false),
('bunong-vn','PHP',2,24,null,$b$ƀiă lah gâp geh nau rnơm tâm Kôranh Brah gâp nơm mra hăn gơnh lĕ ma khân may.$b$,false),
('bunong-vn','PHP',2,25,null,$b$Gâp mĭn, khlay lĕ njuăl Y-Êpaphôdit ma khân may, oh gâp, nơm pah kan jêh ri tâm lơh ndrel ma gâp, nơm khân may njuăl văch jêh ma gâp prăp dŏng tâm kan gâp ŭch,$b$,true),
('bunong-vn','PHP',2,26,null,$b$yor lah păng ŭch ngăn saơ lĕ rngôch khân may, jêh ri păng geh nau rŭng yor khân may tăng jêh nau păng ji.$b$,false),
('bunong-vn','PHP',2,27,null,$b$Nanê̆ păng ji jêh, bơi ma khĭt. Ƀiă lah Brah Ndu yô̆ ma păng, jêh ri mâu di knŏng ma păng, ƀiă lah nđâp ma gâp tâm ban lĕ, gay ma lơi ăn gâp geh nau rngot klâng âk ir.$b$,false),
('bunong-vn','PHP',2,28,null,$b$Pô ri gâp ndal njuăl păng hăn, gay ma khân may geh nau maak saơ păng, jêh ri gay ma gâp lơi hôm ir geh nau rngot ôh.$b$,false),
('bunong-vn','PHP',2,29,null,$b$Pô ri ăn khân may rom păng tâm Kôranh Brah ma nau maak ngăn; jêh ri yơk ma bunuyh nâm nđĕ,$b$,false),
('bunong-vn','PHP',2,30,null,$b$yor kan Brah Krist yơh păng bơi ma khĭt. Păng sân săk ŭch nsro ntrok khân may tâm kan khân may mâu dơi kơl gâp.$b$,false),
('bunong-vn','PHP',3,1,null,$b$Jêh ri hơi phung oh nâu, maak hom khân may tâm Kôranh Brah. Gâp mâu chrê ôh ma nau jêr nchih tay nau tâm ban ma khân may, yor nau nây khlay ma khân may.$b$,true),
('bunong-vn','PHP',3,2,null,$b$Njrăng hom ma phung so, ma phung pah kan mhĭk, jêh ri ma phung jan lah koh ntâu.$b$,true),
('bunong-vn','PHP',3,3,null,$b$Yor lah he yơh jêng phung koh ntâu ngăn, phung yơk ma Brah Ndu, ma Brah Huêng Ueh. He tâm rnê tâm Yêsu Krist, jêh ri mâu mâp rnơm ma nglay săk ôh.$b$,true),
('bunong-vn','PHP',3,4,null,$b$Nđâp tơ lah gâp geh nau dơi rnơm ma nglay săk lĕ. Tơ lah bu mĭn dơi rnơm tâm nglay săk, gâp tâm ban lĕ dơi rnơm âk lơn.$b$,true),
('bunong-vn','PHP',3,5,null,$b$Tâm nar pham bu koh ntâu gâp, du huê bơh phung Israel, mpôl băl Y-Benjamin, phung Hêbrơ, kon phung Hêbrơ, tĭng nâm nau vay gâp jêng băl phung Pharisi,$b$,true),
('bunong-vn','PHP',3,6,null,$b$ma nau duh nđơr gâp ƀư mhĭk ma phung ngih Brah Ndu, bi ma nau jêng sŏng tĭng nâm nau vay gâp mâu geh nau bu dơi nduyh ôh.$b$,false),
('bunong-vn','PHP',3,7,null,$b$Ƀiă lah moh nau khlay ma gâp sa ơm ri, gâp kơp păng tâm ban ma nau roh rai yor Brah Krist.$b$,false),
('bunong-vn','PHP',3,8,null,$b$Nanê̆ gâp kơp lĕ ntil nau jêng tâm ban ma nau roh rai yor nau gĭt năl Yêsu Krist, Kôranh Brah gâp jêng khlay lơn. Yor Păng gâp dun lĕ rngôch nau ueh nây, jêh ri gâp kơp khân păng nâm bu neh bŏk, gay geh Brah Krist,$b$,false),
('bunong-vn','PHP',3,9,null,$b$jêh ri dơi gŭ tâm Păng, geh nau sŏng, mâu di nau sŏng gâp nơm luh bơh nau vay, ƀiă lah nau sŏng luh bơh nau chroh tâm Brah Krist, nau sŏng nây luh bơh Brah Ndu ma nau chroh,$b$,false),
('bunong-vn','PHP',3,10,null,$b$gay ma gâp dơi gĭt năl Brah Krist jêh ri nau brah bơh nau păng khĭt dâk rêh, jêh ri nau tâm rnglăp tâm nau Păng rêh ni, dôl gâp jêng tâm ban ma Păng tâm nau păng khĭt,$b$,false),
('bunong-vn','PHP',3,11,null,$b$Tơ lah gâp dơi tât ma nau dâk rêh bơh phung khĭt.$b$,false),
('bunong-vn','PHP',3,12,null,$b$Mâu di gâp hŏ sŏk jêh ôh nau nkhôm, mâu lah tât jêh ma nau ueh rah vah ôh, ƀiă lah gâp ăt nchuăt, gay dơi sŏk. Yor nây Yêsu Krist sŏk jêh gâp.$b$,true),
('bunong-vn','PHP',3,13,null,$b$Hơi oh nâu, gâp mâu mĭn ôh gâp lĕ sŏk jêh;$b$,false),
('bunong-vn','PHP',3,14,null,$b$ƀiă lah gâp ƀư du ntil nau, gâp chuêl lơi ndơ pa kơi gâp jêh ri rduh ran ma ndơ pa năp. Gâp nchuăt ta ntŭk tâm nal, gay sŏk nau nkhôm ma nau Brah Ndu kuăl bơh klơ tâm Yêsu Krist.$b$,false),
('bunong-vn','PHP',3,15,null,$b$Pô ri, đơ phung rah vah tâm phung he, ăn geh nau mĭn nâm nđĕ, jêh ri tơ lah khân may mĭn ma nau êng, Brah Ndu mra ƀư ang rah vah ma khân may tâm nau nây lĕ.$b$,false),
('bunong-vn','PHP',3,16,null,$b$Knŏng ntŭk he tât jêh, ăn he ăt hăn ndrel n'grŭp.$b$,false),
('bunong-vn','PHP',3,17,null,$b$Hơi phung oh nâu, ăn khân may jêng phung kơt ƀư tâm ban ma gâp, jêh ri ăn khân may uănh ma phung hăn tĭng nâm nau tâm ntĭt nau khân may saơ tâm hên.$b$,true),
('bunong-vn','PHP',3,18,null,$b$Gâp ngơi ƀa ƀơ jêh ma khân may, jêh ri gâp ngơi lĕ aƀaơ ma nau nhĭm, yor lah geh âk phung ƀư rlăng đah si tâm rkăng Brah Krist.$b$,true),
('bunong-vn','PHP',3,19,null,$b$Nau dăch ma lôch jêng nau khân păng jêng nau roh. Khân păng uănh ndŭl khân păng nơm jêng brah. Khân păng tâm rnê ma nau bêk prêng khân păng. Khân păng mĭn knŏng ma ndơ tâm neh ntu.$b$,false),
('bunong-vn','PHP',3,20,null,$b$Ƀiă lah ƀon he gŭ tâm trôk. Bơh nây lĕ he kâp Nơm Tâm Rklaih, Brah Yêsu Krist.$b$,false),
('bunong-vn','PHP',3,21,null,$b$Păng mra tâm rgâl săk jăn mâu khlay he jêng nâm bu săk jăn chrêk rmah Păng, ma nau brah Păng dơi ăn lĕ rngôch mpô mpa tông ma Păng.$b$,false),
('bunong-vn','PHP',4,1,null,$b$Pô nây, hơi oh nâu phung gâp rŏng ngăn, phung jêng nau maak, jêh ri đon hađăch ma gâp, gŭ nâp hom tâm Kôranh Brah, hơi phung gâp rŏng ơi.$b$,true),
('bunong-vn','PHP',4,2,null,$b$Gâp vơh vơl ma H'Êvôdi jêh ri H'Sintich ăn gŭ du ai nau tâm Kôranh Brah,$b$,false),
('bunong-vn','PHP',4,3,null,$b$nđâp ma may, hơi nơm pah kan răp jăp đah gâp, gâp dăn ma may kơl bar hê bu ur nây, yor lah khân păng kơl tâm lơh jêh ndrel ma gâp tâm nau mhe mhan ueh, đah Y-Klêmăng jêh ri phung băl êng pah kan ndrel ma gâp. Amoh khân păng Brah Ndu nchih jêh tâm ndrom sămƀŭt nau rêh.$b$,false),
('bunong-vn','PHP',4,4,null,$b$Maak mro hom khân may tâm Kôranh Brah, gâp rkêch đŏng, maak hom khân may.$b$,true),
('bunong-vn','PHP',4,5,null,$b$Ăn lĕ rngôch bunuyh gĭt nau rdơ̆ rbăn khân may. Kôranh Brah dăch jêh.$b$,true),
('bunong-vn','PHP',4,6,null,$b$Lơi ta khân may rngot rvê ma du ntil ndơ ôh, ƀiă lah tâm lĕ ndơ ma nau mbơh sơm, nau vơh vơl, jêh ri nau tâm rnê, tâm mpơl hom nau khân may dăn ma Brah Ndu.$b$,false),
('bunong-vn','PHP',4,7,null,$b$Jêh ri nau đăp mpăn Brah Ndu rlau lơn ma lĕ rngôch nau blau mĭn, mra chiă uănh nuih n'hâm jêh ri nau mĭn khân may tâm Yêsu Krist.$b$,false),
('bunong-vn','PHP',4,8,null,$b$Pô nây mơ, hơi oh nâu, ma lĕ nau nanê̆, ma lĕ nau khư yơk, ma lĕ nau kloh, ma lĕ nau khư rŏng, ma lĕ nau geh lư n'găr ueh, tơ lah geh nau ueh, jêh ri nau khư tâm rnê, ăn khân may mĭn ma nau nây.$b$,true),
('bunong-vn','PHP',4,9,null,$b$Moh nau khân may nti jêh, dơn jêh, tăng jêh, jêh ri saơ jêh tâm gâp, ăn khân may ƀư tâm ban lĕ, jêh ri Brah Ndu nơm đăp mpăn mra gŭ ndrel ma khân may.$b$,false),
('bunong-vn','PHP',4,10,null,$b$Gâp maak ngăn tâm Kôranh Brah yor lah aƀaơ khân may ntơm mĭn ma gâp du tơ̆ . Khân may ăt mĭn ma nau nây, ƀiă lah khân may mâu ru ôh.$b$,true),
('bunong-vn','PHP',4,11,null,$b$Mâu di gâp ŭch ngơi ma ndơ gâp pưt ôh; yor lah gâp nti jêh dơn ma nau maak moh nau tât ma gâp.$b$,false),
('bunong-vn','PHP',4,12,null,$b$Gâp gĭt gŭ tâm nau rêh ni, gâp gĭt gŭ tâm nau rmeh ler. Tâm lĕ rngôch nau jêh ri lĕ rngôch lam ntŭk gâp nti jêh gŭ tâm nau hơm jêh ri nau ji ngot, tâm nau rmeh jêh ri tâm nau sa sât ji ngot.$b$,true),
('bunong-vn','PHP',4,13,null,$b$Gâp dơi ƀư lĕ tâm Brah Krist, Nơm ƀư ăn ktang gâp.$b$,false),
('bunong-vn','PHP',4,14,null,$b$Pô ri khân may ƀư ueh jêh yor lah khân may kơl gâp tâm nau rêh ni.$b$,true),
('bunong-vn','PHP',4,15,null,$b$Hơi phung Philip, khân may gĭt jêh dôl gâp ntơm nti nau mhe mhan ueh, dôl gâp du tă bơh n'gor Masêđôn, mâu geh phung ngih Brah Ndu êng tâm rnglăp đah gâp tâm nau ăn jêh ri nau sŏk dơn, knŏng phung khân may yơh.$b$,true),
('bunong-vn','PHP',4,16,null,$b$Yor lah ta ƀon Têsalônik bar tơ̆ jêh khân may njuăl ndơ ŭch kơl gâp.$b$,false),
('bunong-vn','PHP',4,17,null,$b$Mâu di gâp joi ndơ bu nhhơr ôh, ƀiă lah gâp joi play dơi n'hao nau nkhôm ma khân may.$b$,true),
('bunong-vn','PHP',4,18,null,$b$Gâp geh sŏk jêh lĕ rngôch ndơ jêh ri gâp geh rmeh ler. Gâp geh âk jêh, yor lah sŏk dơn bơh Y-Êpaphodit ndơ khân may njuăl ma gâp nâm bu ndơ ƀâu kah, ndơ nhhơr nây Brah Ndu dơn jêng nau ƀư maak ma Păng.$b$,false),
('bunong-vn','PHP',4,19,null,$b$Brah Ndu gâp mra ăn ma khân may ăp ntil ndơ khân may pưt tĭng nâm nau păng ndrŏng tâm nau chrêk rmah tâm Yêsu Krist.$b$,false),
('bunong-vn','PHP',4,20,null,$b$Ma Brah Ndu, Mbơ̆ he yơh nau chrêk rmah ƀa ƀơ n'ho ro. Amen.$b$,false),
('bunong-vn','PHP',4,21,null,$b$Ăn khân may tâm khâl đah phung kloh ueh tâm Yêsu Krist. Phung oh nâu gŭ ndrel ma gâp tâm khâl đah khân may.$b$,true),
('bunong-vn','PHP',4,22,null,$b$Lĕ rngôch phung kloh ueh tâm khâl đah khân may jêh ri phung tâm ngih Sêsar.$b$,false),
('bunong-vn','PHP',4,23,null,$b$Ăn nau yô̆ bơh Brah Yêsu Krist gŭ ndrel ma huêng khân may.$b$,true);
insert into public.bible_headings (translation_id, book_code, chapter, before_verse, position, kind, text) values
('bunong-vn','PHP',1,1,0,'heading',$b$Ntŭk Dơn Sămƀŭt Jêh Ri Nau Khâl$b$),
