('bunong-vn','PHP',1,12,2,'heading',$b$Nau Y-Pôl Jêng Bu Nă Jêng Nau Kơl Tâm N'hao Kan Nau Mhe Mhan Ueh$b$),
('bunong-vn','PHP',1,27,3,'heading',$b$Nau Nti Ma Nau Srôih$b$),
('bunong-vn','PHP',2,1,0,'heading',$b$Yêsu Krist Jêng Nơm Tâm Mpơl Nau Tông Bâr$b$),
('bunong-vn','PHP',2,12,1,'heading',$b$Ăn Srôih Gay Tât Ma Nau Ueh Nanê̆$b$),
('bunong-vn','PHP',2,19,2,'heading',$b$Y-Pôl Ton Njuăl Y-Timôthê Jêh Ri Y-Êpbaphôdit Hăn Ta Phung Philip$b$),
