insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', 'COL', $b$Kôlôs$b$, $b$["Sămƀŭt Y-Pôl Njuăl Ma Phung", "KÔLÔS"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','COL',1,1,null,$b$Y-Pôl, jêng du huê kôranh oh mon Yêsu Krist tĭng nâm nau Brah Ndu ŭch, jêh ri Y-Timôthê, oh mon he.$b$,true),
('bunong-vn','COL',1,2,null,$b$Njuăl ma phung kloh ueh jêh ri ma phung oh nâu răp jăp tâm Brah Krist tâm ƀon Kôlôs: Ăn khân may geh nau yô̆ jêh ri nau đăp mpăn bơh Brah Ndu Mbơ̆ he.$b$,false),
('bunong-vn','COL',1,3,null,$b$Hên tâm Rnê ma Brah Ndu, Mbơ̆ Kôranh Brah he, Yêsu Krist, jêh ri ăt mbơh sơm yor khân may,$b$,true),
('bunong-vn','COL',1,4,null,$b$yor lah hên tăng nanê̆ jêh nau khân may chroh tâm Yêsu Krist jêh ri nau khân may rŏng ma lĕ rngôch phung kloh ueh.$b$,false),
('bunong-vn','COL',1,5,null,$b$Yor lah nau kâp gân prăp jêh ma khân may tâm trôk, jêh ri nau ngơi n'hêl nanê̆ bơh nau mhe mhan ueh khân may gĭt jêh lor.$b$,false),
('bunong-vn','COL',1,6,null,$b$Nau Mhe Mhan Ueh nây, tât jêh ta nklang khân may tâm ban ma tâm lam bri neh, gay play jêh ri văch ma toyh, nâm bu tâm phung khân, bơh nar khân may tăng jêh ri gĭt rbăng nau yô̆ bơh Brah Ndu tĭng nâm nau nanê̆.$b$,false),
('bunong-vn','COL',1,7,null,$b$Nâm bu khân may nti jêh bơh Y-Êphapra, du huê băl pah kan ndrel ma hên, păng kơl hên nâm bu du huê oh mon ktang răp jăp ma Brah Krist.$b$,false),
('bunong-vn','COL',1,8,null,$b$Jêh ri păng mbơh ma hên gĭt mâm nau nuih n'gân khân may rŏng tâm Brah Huêng Ueh.$b$,false),
('bunong-vn','COL',1,9,null,$b$Yor nây, hên tâm ban lĕ, bơh nar hên gĭt nanê̆ nau nây, hên mâu blau hŭnh ôh tâm nau mbơh sơm yor khân may, dăn Brah Ndu mbêng khân may, ma nau gĭt năl ma nau păng ŭch, tâm lĕ nau blau mĭn jêh ri gĭt rbăng brah.$b$,true),
('bunong-vn','COL',1,10,null,$b$Gay ma khân may hăn di đah nau Kôranh Brah ƀư maak ma Păng tâm lĕ kan, ăn geh play tâm lĕ rngôch nau ƀư ueh, ăn bĭk tâm nau gĭt năl Brah Ndu.$b$,false),
('bunong-vn','COL',1,11,null,$b$Ăn khân may jêng ktang tâm ban lĕ rngôch nau, ma nau brah chrêk rmah Păng, gay ma khân may dơi dơn lĕ nau rêh ni ma nau răm maak, jêh ri nau nsrôih.$b$,false),
('bunong-vn','COL',1,12,null,$b$Khân may tâm rnê hom ma Mbơ̆ , Nơm ăn ma khân may dơi ndơn drăp ndrel đah phung kloh ueh tâm nau ang.$b$,false),
('bunong-vn','COL',1,13,null,$b$Păng rklaih jêh he bơh nau ktang nau ngo, jêh ri njŭn leo he ma ƀon bri hađăch kon păng rŏng ngăn ngên.$b$,false),
('bunong-vn','COL',1,14,null,$b$Tâm Păng nây he geh nau tâm chuai, nau yô̆ an ma nau tih.$b$,true),
('bunong-vn','COL',1,15,null,$b$Păng jêng rup ma Brah Ndu, Nơm bu mâu blau saơ Păng jêng nơm deh lor lơn ma lĕ rngôch mpa rhăk njêng.$b$,true),
('bunong-vn','COL',1,16,null,$b$Yor lah tâm păng lĕ rngôch mpa rhăk njêng, nđâp ma mpa tâm trôk, nđâp mpa ta neh ntu, nđâp mpa bu mâu blau saơ, ndơ saơ, nau jêng hađăch, nau chiă uănh, mâu lah nau jêng toyh, nau jêng kôranh, lĕ rngôch yor Păng njêng da dê jêh, jêh ri prăp ma păng lĕ.$b$,false),
('bunong-vn','COL',1,17,null,$b$Păng jêng lor lơn ma lĕ rngôch mpa, jêh ri lĕ rngôch mpa ăt gŭ da dê tâm Păng.$b$,false),
('bunong-vn','COL',1,18,null,$b$Păng jêng bôk ma săk jăn, nâm bu ntĭt phung Ngih Brah Ndu, Păng jêng nau ntơm, Păng jêng Nơm deh lor lơn bơh phung khĭt, gay ma Păng jêng Kôranh tâm lĕ rngôch mpa.$b$,true),
('bunong-vn','COL',1,19,null,$b$Yor lah Brah Ndu gay ăn nau bêng ler Brah Ndu gŭ tâm păng.$b$,false),
('bunong-vn','COL',1,20,null,$b$Jêh ri ma mham Păng hoch jêh ta si tâm rkăng, Brah Ndu ăn nau đăp mpăn jêh ri tâm njĭr lĕ rngôch mpa ta neh ntu jêh ri tâm trôk ăn tâm rnglăp đah Păng Nơm.$b$,false),
('bunong-vn','COL',1,21,null,$b$Bi phung khân may, ntơm sa ơm khân may jêng bu năch, jêh ri jêng rlăng tâm nau mĭn, jêh ri tâm kan mâu ueh.$b$,true),
('bunong-vn','COL',1,22,null,$b$Ƀiă lah aƀaơ khân may tâm njĭr jêh đah Păng ma nau khĭt kon Păng tâm săk jăn nglay săk Păng gay ma khân may dơi gŭ ta năp, Păng kloh ueh, mâu geh nau dơi nduyh, mâu geh têl rup mhĭk ôh.$b$,false),
('bunong-vn','COL',1,23,null,$b$Tơ lah khân may ăt gŭ nâp tâm nau chroh, mâu rơih mâu trơn nau kâp gân, bơh nau Mhe Mhan Ueh khân may tăng jêh, nau nây mbơh jêh ma lĕ rngôch mpa tâm trôk, jêh ri gâp Y-Pôl jêng du huê ktang ma nau nây.$b$,false),
('bunong-vn','COL',1,24,null,$b$Aƀaơ gâp gŭ maak tâm nau rêh ni, gâp dơi jêh yor khân may, jêh ri đơ nau rêh ni hôm bơh Brah Krist gâp ƀư lôch jêh tă rnglay săk gâp, yor phung ngih Brah Ndu săk jăn păng.$b$,true),
('bunong-vn','COL',1,25,null,$b$Ma ngih Brah Ndu nây yơh, gâp jêng oh mon ktang tĭng nâm nau Kôranh Brah Ndu đă jêh ŭch jao ma gâp, ăn gâp mbơh rah vah ma khân may nau Brah Ndu Ngơi.$b$,false),
('bunong-vn','COL',1,26,null,$b$Nau khlay ndâp nây, pôn jêh tâm lĕ rngôch ƀiă lah aƀaơ tâm mpơl jêh ma phung kloh ueh păng.$b$,false),
('bunong-vn','COL',1,27,null,$b$Ma khân păng Brah Ndu ŭch ăn gĭt nau ndrŏng chrêk rmah ma nau khlay ndâp nây tâm phung bu năch, nâm bu ntĭt, Brah Krist tâm khân may, jêng nau kâp gân ma nau chrêk rmah.$b$,false),
('bunong-vn','COL',1,28,null,$b$Ma păng yơh hên mbơh hên nkra ma lĕ rngôch bunuyh ma lĕ nau blau mĭn, gay tâm mpơl lĕ rngôch bunuyh jêng rah vah ngăn tâm Brah Krist.$b$,false),
('bunong-vn','COL',1,29,null,$b$Ma nau nây blau pah kan dôl tâm lơh dŏng nau ktang păng, nau ktang nây pah kan tâm gâp ma nau Brah.$b$,false),
('bunong-vn','COL',2,1,null,$b$Jêh ri gâp ŭch ăn khân may gĭt mâm nau gâp tâm lơh ma lĕ nuih n'hâm yor khân may, yor phung ta ƀon Laođisê, jêh ri yor lĕ rngôch phung mâu mâp saơ muh măt gâp.$b$,true),
('bunong-vn','COL',2,2,null,$b$Gay ma khân păng geh nau bonh leng tâm rnglăp tâm nau rŏng, gay geh âk nau gĭt mĭn, gay ma gĭt năl nau khlay ndâp Brah Ndu, nâm bu ntĭt Brah Krist.$b$,false),
('bunong-vn','COL',2,3,null,$b$Lĕ rngôch nau khlay ndâp, bơh nau blau mĭn jêh ri nau gĭt rbăng jêh tâm Păng.$b$,false),
('bunong-vn','COL',2,4,null,$b$Gâp lah pô aơ gay lơi ăn geh bunuyh ƀư vĭ khân may ma nau ngơi ndơm.$b$,false),
('bunong-vn','COL',2,5,null,$b$Yor lah săk jăn gâp ndŭt kơi kđôi lĕ ƀiă lah huêng gâp ăt hôm gŭ ndrel ma khân may, gâp maak ngăn saơ oh nâu geh nau gŭ rêh tâm rnglăp tâm phung khân may, jêh ri nau nâp khân may Chroh ma Brah Krist.$b$,false),
('bunong-vn','COL',2,6,null,$b$Pô ri, tâm ban ma khân may rom jêh Yêsu Krist, Kôranh Brah hăn hom tâm Păng.$b$,true),
('bunong-vn','COL',2,7,null,$b$Sŏr reh rdâk tâm Păng jêh ri gŭ nâp hom ma nau Chroh tĭng nâm nau khân may nti jêh ăn khân may bêng ler tâm nau tâm rnê.$b$,true),
('bunong-vn','COL',2,8,null,$b$Njrăng hom klach geh bunuyh ndơm khân may ma nau blao nti âk jêh ri ma nau ngơi ndơm dơm dam, tĭng nâm nau bunuyh nkoch bri, nau neh ntu mơng mâu di tĭng nâm nau Brah Krist nti ôh.$b$,true),
('bunong-vn','COL',2,9,null,$b$Yor lah lĕ bêng ler Brah Ndu gŭ tâm păng nâm bu geh săk jăn.$b$,false),
('bunong-vn','COL',2,10,null,$b$Jêh ri khân may geh bêng nŭm tâm Păng, Păng jêng Kôranh lĕ rngôch nau chiă uănh jêh ri nau dơi toyh.$b$,false),
('bunong-vn','COL',2,11,null,$b$Tâm păng lĕ khân may ƀư nau koh ntâu, mâu di nau koh ntâu ma ti bunuyh ƀiă lah nau koh ntâu bơh Brah Krist, nâm bu ntĭt, plôk lơi nau nglai săk he ŭch tâm săk jăn.$b$,false),
('bunong-vn','COL',2,12,null,$b$Ma nau ƀaptem bu brôi jêh khân may ndrel ma Păng, ma nau Chroh tâm nau Brah Ndu, Nơm hŏ ăn rêh jêh păng bơh phung khĭt.$b$,false),
('bunong-vn','COL',2,13,null,$b$Jêh ri dôl khân may khĭt jêh tâm nau tih jêh ri tâm rnglay săk mâu koh ntâu, Brah Ndu ăn rêh khân may ndrel ma Brah Krist, Păng yô̆ an jêh lĕ nau tih he.$b$,true),
('bunong-vn','COL',2,14,null,$b$Păng jut jêh sămƀŭt rnon he djang đah păng, lĕ nau vay dơi ƀư ma he, Păng jut lơi lĕ dôl bu pâng Păng ta si tâm rkăng.$b$,false),
('bunong-vn','COL',2,15,null,$b$Păng ƀư rai lĕ nau chiă uănh jêh ri nau dơi toyh, jêh ri tâm mpơl ma lĕ rngôch bunuyh gĭt ma si tâm rkăng Păng dơi jêh đah phung nây.$b$,false),
('bunong-vn','COL',2,16,null,$b$Pô ri, lơi ăn bu phat dôih khân may yor nau sa nhêt, mâu lah yor nau nar ƀư nau maak, nar khlay luh mâu lah nar sa ƀat.$b$,true),
('bunong-vn','COL',2,17,null,$b$Lĕ nau nây knŏng jêng gui n'hâm ma nau mra tât, ƀiă lah săk jăn gŭ tâm Brah Krist.$b$,true),
('bunong-vn','COL',2,18,null,$b$Lơi ăn du huê bunuyh ma nau păng jan lah ƀư nau tông bâr gay mbah ma Tông mpăr Ueh Brah Ndu, ƀư roh nau nkhôm khân may, khân păng rnơm ma nau khân păng tâm saơ, khân păng sưr dơm dam ma nau mĭn tĭng nâm nglay săk khân păng kơnh.$b$,true),
('bunong-vn','COL',2,19,null,$b$Khân păng mâu tâm rnglăp đah bôk, bơh nây lĕ săk jăn geh nau tâm rnglăp jêh, nâp đah phung suan tâm ntrŭp, jêh ri văch ma toyh tâm nau Brah Ndu.$b$,false),
('bunong-vn','COL',2,20,null,$b$Tơ lah khân may khĭt jêh ndrel Brah Krist ma nau vay neh ntu, mâm ƀư nau vay aơ? Mâm ƀư nchâp khân may nâm bu khân may ăt hôm rêh tâm neh ntu:$b$,true),
('bunong-vn','COL',2,21,null,$b$“Lơi sŏk dơn, lơi ler, lơi pah bi.”?$b$,false),
('bunong-vn','COL',2,22,null,$b$Lĕ ndơ nây tơ lah khân may dŏng, khân păng mra rai lôch tĭng nâm nau vay bơh bunuyh, jêh ri nau bunuyh chroh.$b$,false),
('bunong-vn','COL',2,23,null,$b$Nanê̆ khân păng mra geh nau tâm mpơl pa dih nâm bu blau mĭn, dôl nchâp nau mbah tĭng nâm nau mĭn khân păng nơm, nau ƀư tông bâr jêh ri nau ƀư rêh ni ma săk jăn, ƀiă lah mâu khlay ôh rdâng đah nglay săk ŭch.$b$,false),
('bunong-vn','COL',3,1,null,$b$Pô ri tơ lah khân may rêh jêh ndrel ma Brah Krist, joi hom ndơ tâm trôk, ta nây Brah Krist gŭ mpeh pa ma Brah Ndu.$b$,true),
('bunong-vn','COL',3,2,null,$b$Rŏng mĭn hom ndơ tâm trôk, mâu di ma ndơ neh ntu ôh.$b$,true),
('bunong-vn','COL',3,3,null,$b$Yor lah khân may khĭt jêh, jêh ri nau rêh khân may pôn jêh ndrel ma Brah Krist tâm Brah Ndu.$b$,false),
('bunong-vn','COL',3,4,null,$b$Tơ lah Brah Krist, nau rêh khân may mra tâm mpơl, dôl nây lĕ khân may mra tâm mpơl ndrel ma Păng tâm nau chrêk rmah.$b$,false),
('bunong-vn','COL',3,5,null,$b$Pô ri nkhĭt lơi jâng ti luh bơh neh ntu gŭ tâm khân may, nâm bu ntĭt: Nau văng tĭr, nau ƀơ̆ ƀơch, nau nglay săk ŭch, nau ŭch mhĭk jêh ri nau kơnh ir, nau kơnh ir jêng tâm ban ma nau mbah rup brah.$b$,true),
('bunong-vn','COL',3,6,null,$b$Yor lĕ nau nây nau ji nuih Brah Ndu njŭr tâm klơ khân may mâu tông.$b$,false),
('bunong-vn','COL',3,7,null,$b$Kăl e ri dôl khân may hôm hăn tâm nau nây, khân may ƀư tâm ban pô nây lĕ.$b$,false),
('bunong-vn','COL',3,8,null,$b$Ƀiă lah aƀaơ doh mƀăr lơi lĕ nau aơ, nau ji nuih, nau mhĭk djơh jêh ri nau janh. Lơi ngơi nchơt tâm phong, nau ngơi ƀơ̆ ƀơch bơh trôm mbung khân may.$b$,false),
('bunong-vn','COL',3,9,null,$b$Lơi ƀư nau mƀruh ndrăng khân may nơm, yor lah khân may doh mƀăr lơi jêh bunuyh ơm nđâp ka păng.$b$,false),
('bunong-vn','COL',3,10,null,$b$Jêh ri nsoh bunuyh mhe, păng ntơm jêng mhe tâm nau gĭt năl tĭng nâm rup Nơm rhăk păng.$b$,false),
('bunong-vn','COL',3,11,null,$b$Ta aơ mâu geh phung Grek, mâu lah phung Yuđa, bunuyh koh ntâu, mâu lah bunuyh mâu geh koh ntâu, bunuyh bri mâu lah phung Syth, phung dĭk bu mâu lah kon me, ƀiă lah Brah Krist jêng lĕ rngôch jêh ri ma lĕ rngôch.$b$,false),
('bunong-vn','COL',3,12,null,$b$Pô ri yor lah khân păng jêng Brah Ndu săch, jêng phung kloh ueh, jêh ri phung Brah Ndu rŏng, nsoh hom nau blau yô̆ nuih n'hâm ueh, nau tông bâr, nau rdơ̆ rbăn jêh ri nau nsrôih.$b$,true),
('bunong-vn','COL',3,13,null,$b$Tơ lah du huê tâm khân may geh nau tâm keh đah bu êng, ăn khân may yơh an ma bu jêh ri yô̆ an: Nâm bu Kôranh Brah hŏ yô̆ an jêh ma khân may, pô ri ăn khân may tâm yô̆ ndrăng khân may nơm tâm ban lĕ.$b$,false),
('bunong-vn','COL',3,14,null,$b$Ƀiă lah rlau lơn ma nau nây, ăn khân may nsoh nau rŏng, yor lah păng jêng nau tâm rnglăp tâm nau ueh rah vah.$b$,false),
('bunong-vn','COL',3,15,null,$b$Ăn nau đăp mpăn bơh Brah Krist chiă uănh tâm nuih n'hâm khân may, ma nau nây Brah Ndu kuăl jêh khân may gay tâm rnglăp jêng knŏng du săk jăn jêh ri ăn khân may kah gĭt tôr.$b$,true),
('bunong-vn','COL',3,16,null,$b$Dăn nau ngơi Brah Krist gŭ tâm nuih n'hâm khân may jêh ri khân may bêng ler tâm lĕ rngôch nau blau mĭn. Ăn khân may dŏng hom ma lĕ nau mprơ, nau mprơ kloh ueh, nau mprơ Brah chrêk rmah, nau mprơ aơ ăn he nti jêh ri nsŭk nsôr ndrel, yor dơi nau Kôranh Brah ăn, yor nây ăn he lĕ nuih n'hâm mprơ tâm rnê ma Brah Ndu.$b$,false),
('bunong-vn','COL',3,17,null,$b$Nđâp tơ lah khân may ngơi mâu lah ƀư, ăn khân may ma amoh Kôranh Brah Yêsu tâm ban lĕ, dơi ƀư lĕ rngôch nau, yor tă Păng he lah ueh Brah Ndu jêng Brah Ndu Mbơ̆ .$b$,false),
('bunong-vn','COL',3,18,null,$b$Hơi phung jêng ur bu tông hom ma sai khân ay yor lah nau nây jêng di tâm Kôranh Brah.$b$,true),
('bunong-vn','COL',3,19,null,$b$Hơi phung sai bu rŏng hom ma ur khân may, lơi ngơi ji nuih đah khân păng ôh.$b$,false),
('bunong-vn','COL',3,20,null,$b$Hơi phung kon, tông hom ma mbơ̆ mê̆ khân may, tâm lĕ ntil nau, yor lah nau nây ƀư maak ma Kôranh Brah.$b$,true),
('bunong-vn','COL',3,21,null,$b$Hơi phung jêng mbơ̆ , lơi lŏk lôr phung kon khân may, klach lah khân păng rdja nuih n'hâm.$b$,false),
('bunong-vn','COL',3,22,null,$b$Hơi phung jêng oh mon bu tông hom ma kôranh khân may ta neh ntu aơ tâm lĕ rngôch ndơ, mâu di ta năp măt khân păng dơm ôh nâm bu he ŭch ƀư maak ma bu, ƀiă lah ăn he klach yơk yor ma Kôranh Brah, ăn sŏk nuih n'hâm pah kan răp jăp.$b$,true),
('bunong-vn','COL',3,23,null,$b$Moh ntil khân may ƀư, ƀư hom ma lĕ nuih n'hâm nâm bu he ƀư ma Kôranh Brah lĕ, mâu di ma bunuyh ôh.$b$,false),
('bunong-vn','COL',3,24,null,$b$Yor lah gĭt jêh ma khân may mra sŏk dơn bơh Kôranh Brah nau ndơn drăp jêng nau nkhôm. Ăn khân may pah kan ma Brah Krist jêng Kôranh Brah.$b$,false),
('bunong-vn','COL',3,25,null,$b$Mbu nơm gŭ ngao mâu di mra sŏk dơm nau kue păng nơm: Mâu geh nuyh koh dŏng ôh.$b$,true),
('bunong-vn','COL',4,1,null,$b$Hơi phung kôranh, ƀư ma phung oh mon khân may ma sŏng jêh ri nau di, yor lah khân may gĭt jêh khân may geh du huê Kôranh ta klơ trôk.$b$,true),
('bunong-vn','COL',4,2,null,$b$Ăn khân may srôih nâp, njrăng ma nau mbơh sơm jêh ri kah gĭt tôr.$b$,true),
('bunong-vn','COL',4,3,null,$b$Mbơh sơm an nđâp ma hên ƀă, dăn ma Brah Ndu pơk mpông nti nau ngơi Păng, gay ma gâp dơi mbơh nau khlay ndâp bơh Brah Krist, yor nau nây bu nkông gâp ma rse rvăk,$b$,false),
('bunong-vn','COL',4,4,null,$b$jêh ri gâp mra ăn bu gĭt rah vah tĭng nâm gâp mra ngơi.$b$,false),
('bunong-vn','COL',4,5,null,$b$Ăn khân may gŭ ngao blau mĭn ta năp phung bu năch jêh ri blau ndăn mông nar.$b$,false),
('bunong-vn','COL',4,6,null,$b$Ăn nau khân may ngơi geh nau yô̆ ƀa ƀơ jêh ri ngơi kan nâm bu boh gay ma khân păng gĭt mâm nau plơ̆ lah ma ăp nơm bu.$b$,false),
('bunong-vn','COL',4,7,null,$b$Y-Tisik jêng nâu oh hên rŏng ngăn, du huê oh mon răp jăp Kôranh Brah jêh ri băl pah kan ndrel ma gâp, păng mra mbơh ma khân may gĭt lĕ nau tât ma gâp.$b$,true),
('bunong-vn','COL',4,8,null,$b$Gâp ŭch prơh păng ŭch tât ma khân may, gay ma khân may gĭt nau tât ma hên jêh ri gay ma păng bonh nuih n'hâm khân may.$b$,false),
('bunong-vn','COL',4,9,null,$b$Gâp prơh păng hăn ndrel ma Y-Ônêsim, nơm răp jăp jêh ri oh nâu hên rŏng ngăn păng bunuyh ƀon ndrel khân may nơm. Bar hê nây mra mbơh ăn ma khân may gĭt lĕ rngôch ntil nau tât jêh ta aơ.$b$,true),
('bunong-vn','COL',4,10,null,$b$Y-Aristar, băl jêng bu nă ndrel ma gâp njuăl nau khâl ma khân may, nđâp ma Y-Markôs, băl gâp Y-Ƀarnaƀas tâm ban lĕ. Bơh Y-Markôs khân may hŏ dơi geh nau ntĭm nti jêh; tơ lah păng hăn tât ta khân may ăn khân may rom păng ăn ueh.$b$,true),
('bunong-vn','COL',4,11,null,$b$Nđâp ma Y-Yêsu bu ntơ amoh păng Y-Yustus, ăt geh lĕ nau njuăl khâl may khân may. Tâm phung koh ntâu, knŏng pe nuyh nây ndrel ma gâp pah kan ma ƀon bri hađăch Brah Ndu, yor khân păng nĕ jêng nau bonh leng an nuih n'hâm gâp.$b$,false),
('bunong-vn','COL',4,12,null,$b$Y-Êpapras, bunuyh ƀon ndrel khân may, jêng oh mon ma Yêsu Krist, njuăl khâl ma khân may; păng tâm lơh tâm nau mbơh sơm ƀa ƀơ, yor phung khân may gay ma khân may jêng n'hêl nanê̆ jêh ri gĭt ngăn lĕ nau Brah Ndu ŭch.$b$,true),
('bunong-vn','COL',4,13,null,$b$Yor lah gâp mbơh păng jêng bunuyh pah kan dŭt hŏt ra ah hâu ngăn yor ma khân may, jêh ri yor phung Laođisê nđâp ma phung Hiêrapôlis.$b$,false),
('bunong-vn','COL',4,14,null,$b$Y-Luk kôranh dak si, nơm gâp rŏng ngăn nđâp ma Y-Đêmas.$b$,true),
('bunong-vn','COL',4,15,null,$b$Njuăl hom nau khâl ma phung nâu oh gŭ ta Laođisê jêh ri H'Nimpas, ndrel ma phung ngih Brah Ndu mpôl gŭ rƀŭn tâm ngih păng.$b$,true),
('bunong-vn','COL',4,16,null,$b$Jêh khân may răk uănh sămƀŭt ndơ̆ hom ăn ma ngih Brah Ndu Laođisê uănh đŏng, khân may tâm ban lĕ ăn khân may uănh sămƀŭt Laođisê njuăl tay.$b$,false),
('bunong-vn','COL',4,17,null,$b$Jêh ri ntĭnh nglĕ dŭt, sâm mbơh Y-Archip pô aơ: “Ăn may njrăng ma nau kan may ma amoh Kôranh Brah hŏ sŏk dơn, gay ƀư rĭng n'hêl nanê̆ ngăn.”$b$,false),
('bunong-vn','COL',4,18,null,$b$Gâp jêng Y-Pôl ti gâp nơm yơh nchih nau khâl ma khân may. Ăn khân may kah gĭt ma rse rvăk bu nkông gâp, dăn nau yô̆ Brah Ndu gŭ ndrel ma khân may. Amen.$b$,false);
insert into public.bible_headings (translation_id, book_code, chapter, before_verse, position, kind, text) values
('bunong-vn','COL',1,1,0,'heading',$b$Ntŭk Dơn Sămƀŭt Jêh Ri Nau Khâl$b$),
('bunong-vn','COL',1,3,1,'heading',$b$Y-Pôl Tâm Rnê Ma Brah Ndu Jêh Ri Mbơh Sơm Yor Nau Chroh Tâm Phung Kôlôs$b$),
('bunong-vn','COL',1,15,2,'heading',$b$Brah Krist Jêng Tâm Ban Ma Brah Ndu$b$),
('bunong-vn','COL',1,24,3,'heading',$b$Kan Jêh Ri Nau Rêh Ni Y-Pôl$b$),
('bunong-vn','COL',2,8,0,'heading',$b$Nau Yêsu Krist Tâm Chuai Jêng Khlay Ngăn Ngên$b$),
('bunong-vn','COL',2,16,1,'heading',$b$Âk Ntil Nau Chroh Jêh Ri Nau Vay Bơh Bunuyh$b$),
('bunong-vn','COL',3,1,0,'heading',$b$Nau Kloh Ueh Nau Gĭt Yô̆$b$),
('bunong-vn','COL',3,18,1,'heading',$b$Nau Vay Tâm Ngih Vâl$b$),
('bunong-vn','COL',4,2,0,'heading',$b$Nti Ma Nau Mbơh Sơm Jêh Ri Blau Mĭn$b$),
('bunong-vn','COL',4,7,1,'heading',$b$Nau Đă Hăn Y-Tisik Jêh Ri Y-Ônisim$b$),
('bunong-vn','COL',4,10,2,'heading',$b$Nau Khâl Jêh Ri Nau Ntĭnh Ntăn$b$);
insert into public.bible_book_names (translation_id, book_code, name, title_block) values ('bunong-vn', '1TH', $b$I Têsalônik$b$, $b$["Sămƀŭt Rơh Nguay Y-Pôl Njuăl Ma Phung", "TÊSALÔNIK"]$b$::jsonb) on conflict (translation_id, book_code) do update set name = excluded.name, title_block = excluded.title_block;
insert into public.bible_verses (translation_id, book_code, chapter, verse, verse_end, text, para) values
('bunong-vn','1TH',1,1,null,$b$Y-Pôl, Y-Silvan jêh ri Y-Timôthê, nchih njuăl sămƀŭt ma phung ngih Brah Ndu ta ƀon Têsalônik, phung gŭ tâm Brah Ndu, Mbơ̆ jêh ri tâm Yêsu Krist, Kôranh Brah: Ăn nau yô̆ jêh ri nau đăp mpăn gŭ ndrel ma khân may.$b$,true),
('bunong-vn','1TH',1,2,null,$b$Hên tâm rnê ma Brah Ndu ƀa ƀơ yor khân may dôl hên mbơh sơm ma khân may.$b$,true),
('bunong-vn','1TH',1,3,null,$b$Hên kah gĭt ƀa ƀơ ta năp Brah Ndu, Mbơ̆ he, ma kan nau chroh khân may, ma kan nau rŏng khân may jêh ri nau khân may gŭ nâp tâm nau kâp gân tâm Kôranh Brah he, Yêsu Krist.$b$,false),
('bunong-vn','1TH',1,4,null,$b$Hên gĭt, hơi phung oh nâu Brah Ndu rŏng, khân may jêng phung Brah Ndu săch jêh.$b$,false),
('bunong-vn','1TH',1,5,null,$b$Nau mhe mhan ueh hên nti jêh ma khân may, mâu di knŏng tâm nau ngơi ôh, ƀiă lah ma nau brah, ma Brah Huêng Ueh, jêh ri ma nau gĭt nanê̆. Yor lah khân may gĭt jêh nau hên gŭ ngao krao sach ndrel ma khân may yor khân may.$b$,false),
('bunong-vn','1TH',1,6,null,$b$Jêh ri khân may nơm jêng jêh phung tĭng ndô̆ hên jêh ri Kôranh Brah, dôl khân may sŏk dơn Nau Ngơi ta nklang âk nau rêh ni, ma nau răm bơh Brah Huêng ueh;$b$,true),
('bunong-vn','1TH',1,7,null,$b$pô ri khân may jêng nau tâm ntĭt ma lĕ rngôch phung chroh tâm n'gor Masêđôn jêh ri n'gor Akai.$b$,false),
('bunong-vn','1TH',1,8,null,$b$Yor lah bu tăng lư jêh Nau Kôranh Brah Ngơi bơh khân may, mâu di knŏng n'gor Masêđôn jêh ri Akai, ƀiă lah lam ntŭk bu gĭt jêh ma nau khân may chroh ma Brah Ndu, kŏ mâu hôm khlay ôh ma hên ngơi.$b$,false),
('bunong-vn','1TH',1,9,null,$b$Yor lah bu nkoch bri nau khân may rom hên jêh ri ma nau khân may chroh ma Brah Ndu, cha lơi jêh rup brah mhĭk jêh ri pah kan ma Brah Ndu rêh jêh ri nanê̆,$b$,false),
('bunong-vn','1TH',1,10,null,$b$jêh ri gŭ kâp Kon Păng bơh trôk, Nơm Păng dâk rêh jêh bơh phung khĭt, Brah Yêsu, Nơm Tâm Rklaih he ma nau ji nuih mra tât.$b$,false),
('bunong-vn','1TH',2,1,null,$b$Hơi phung oh nâu, khân may nơm gĭt jêh ma nau hên tât ta khân may mâu jêng dơm dam ôh;$b$,true),
('bunong-vn','1TH',2,2,null,$b$ƀiă lah jêh dơn nau rêh ni jêh ri nau bu ƀư mhĭk ta ƀon Philip, nâm bu khân may hŏ gĭt jêh, hên ăt rnơm ma Brah Ndu hên, gay mbơh ma khân may nau mhe mhan ueh Brah Ndu ta nklang âk nau tâm lơh.$b$,false),
('bunong-vn','1TH',2,3,null,$b$Yor lah nau hên nti mâu luh bơh nau vĭ ôh, bơh nau ƀơ̆ , mâu lah bơh nau ndơm ôh,$b$,false),
('bunong-vn','1TH',2,4,null,$b$ƀiă lah tĭng nâm Brah Ndu kơp hên khư, dơi jao ma hên nau mhe mhan ueh, pô nây hên ngơi, mâu di ŭch ƀư maak ma bunuyh ôh, ƀiă lah ŭch ƀư maak ma Brah Ndu, nơm sek uănh nuih n'hâm he.$b$,false),
('bunong-vn','1TH',2,5,null,$b$Yor lah khân may gĭt hên mâu mâp dŏng nau ngơi ndơm ôh, mâu lah hên mâu mâp kơnh ma drăp ndơ ôh, Brah Ndu jêng nơm mbơh.$b$,false),
('bunong-vn','1TH',2,6,null,$b$Mâu lĕ hên mâp joi nau tâm rnê bơh bunuyh, bơh khân may mâu lah bơh phung êng,$b$,false),
('bunong-vn','1TH',2,7,null,$b$nđâp tơ lah dơi dăn ndơ nâm bu du huê bu ur rong kon, chiă uănh phung kon păng nơm.$b$,false),
('bunong-vn','1TH',2,8,null,$b$Ma nau hên rŏng ngăn ma khân may hên ŭch mâu di knŏng ăn ma khân may nau mhe mhan ueh Brah Ndu ôh, ƀiă lah nđâp nau rêh hên nơm yor lah khân may jêng khlay ngăn ma hên.$b$,false),
('bunong-vn','1TH',2,9,null,$b$Hơi phung oh nâu, ăn khân may kah gĭt ma kan jêh ri ma nau jêr hên. Hên pah kan măng jêh ri nar yơh, mâu ŭch ƀư jâk du huê tâm phung khân may ôh dôl hên nti nau mhe mhan ueh Brah Ndu ma khân may.$b$,false),
('bunong-vn','1TH',2,10,null,$b$Khân may jêng phung mbơh jêh ri Brah Ndu tâm ban lĕ, ma hên gŭ ngao krao sach jêh ta năp khân may, phung chroh nau kloh ueh, nau sŏng, jêh ri ma nau bu mâu dơi nduyh ôh.$b$,false),
('bunong-vn','1TH',2,11,null,$b$Jêh ri khân may gĭt tâm ban lĕ ma hên jêng ma ăp nơm khân may nâm bu du huê mbơ̆ đah phung kon păng. Hên tâm n'hao nuih, tâm bonh khân may,$b$,false),
('bunong-vn','1TH',2,12,null,$b$jêh ri nchâp khân may hăn khư ma nau Brah Ndu ŭch, nơm kuăl khân may ma ƀon bri hađăch jêh ri ma nau chrêk rmah Păng.$b$,false),
('bunong-vn','1TH',2,13,null,$b$Hên tâm rnê ma Brah Ndu ƀa ƀơ yor khân may sŏk dơn jêh Nau Brah Ndu Ngơi hên nti jêh ma khân may, mâu di tâm ban nau bunuyh ngơi, ƀiă lah tâm ban ma Nau Brah Ndu Ngơi nanê̆, pah kan tâm nuih n'hâm khân may, phung chroh jêh.$b$,true),
('bunong-vn','1TH',2,14,null,$b$Hơi phung oh nâu, khân may jêng phung tĭng ndô̆ phung ngih Brah Ndu tâm Yêsu Krist ta n'gor Yuđa, yor lah khân may tâm ban lĕ, dơn nau rêh ni bơh phung ƀon lan khân may nơm, nâm bu khân păng dơn jêh bơh phung Yuđa.$b$,false),
('bunong-vn','1TH',2,15,null,$b$Phung nây yơh nkhĭt jêh Brah Yêsu, nđâp phung kôranh nơm mbơh lor. Khân păng ƀư mhĭk ma hên. Khân păng mâu ƀư maak ma Brah Ndu ôh, jêh ri khân păng jêng rlăng đah lĕ rngôch bunuyh.$b$,false),
('bunong-vn','1TH',2,16,null,$b$Khân păng buay hên nti ma phung bu năch, gay tâm rklaih khân păng. Pô ri khân păng ƀư tih mro kŏ rmeh ler, ƀiă lah nau Brah Ndu ji nuih tât jêh ma khân păng.$b$,true),
('bunong-vn','1TH',2,17,null,$b$Hơi phung oh nâu, bi hên jêh hên ndŭt ƀât lât tâm săk jăn, ƀiă lah mâu di tâm nuih n'hâm ôh, hên ŭch ngăn ngên saơ tay khân may.$b$,true),
('bunong-vn','1TH',2,18,null,$b$Pô nây lĕ, hên ŭch hăn ma khân may, gâp Y-Pôl, du tơ̆ bar tơ̆ jêh, ƀiă lah Satan buay jêh hên.$b$,false),
('bunong-vn','1TH',2,19,null,$b$Yor lah mbu jêng nau kâp gân hên, nau răm maak hên, mâu lah đon hađăch nau chrêk rmah hên? Mâu di hĕ khân may yơh ta năp Kôranh Brah he, Brah Yêsu, ta nar păng plơ̆ văch?$b$,false),
('bunong-vn','1TH',2,20,null,$b$Yor lah khân may jêng nau chrêk rmah hên jêh ri nau răm maak hên.$b$,false),
('bunong-vn','1TH',3,1,null,$b$Yor nây tơ lah hên mâu hôm dơi srôih ôh, hên rŏng gŭ êng ta ƀon Athen.$b$,true),
('bunong-vn','1TH',3,2,null,$b$Hên njuăl Y-Timôthê hăn, oh he, oh mon Brah Ndu tâm nau mhe mhan ueh Krist, gay ƀư nâp khân may jêh ri tâm n'hao nuih tâm nau khân may chroh,$b$,true),
('bunong-vn','1TH',3,3,null,$b$pô nây mơ, lơi geh bunuyh rŭch plơ̆ yor nau rêh ni aƀaơ aơ. Yor lah khân may nơm gĭt jêh ma nau nây rơm jêh ma he.$b$,false),
('bunong-vn','1TH',3,4,null,$b$Jêh ri dôl hên gŭ jêh ndrel ma khân may, hên mbơh jêh bơh lor ma he mra dơn nau rêh ni nâm bu nau nây tât jêh, jêh ri nâm bu khân may gĭt jêh.$b$,false),
('bunong-vn','1TH',3,5,null,$b$Pô ri, yor gâp mâu dơi srôih gâp njuăl bu hăn gay ma gĭt nau khân may chroh, klach lah nơm ndơm jêh khân may, jêh ri klach ma kan hên pah jêng dơm dam.$b$,true),
('bunong-vn','1TH',3,6,null,$b$Ƀiă lah Y-Timôthê mhe sĭt tă bơh khân may, mbơh nau mhe mhan neh ma nau khân may chroh, jêh ri ma nau khân may rŏng. Păng mbơh ma khân may kah gĭt ma hên ƀa ƀơ, ŭch saơ hên nâm bu hên ŭch saơ khân may lĕ.$b$,false),
('bunong-vn','1TH',3,7,null,$b$Pô ri, hơi phung oh nâu, dôl hên geh nau uh ah jêh ri nau rêh ni, hên geh nau tâm bonh leng bơh khân may yor nau khân may chroh.$b$,false),
('bunong-vn','1TH',3,8,null,$b$Yor lah aƀaơ aơ hên gŭ rêh tơ lah khân may gŭ nâp tâm Kôranh Brah.$b$,false),
('bunong-vn','1TH',3,9,null,$b$Moh nau hên dơi tâm rnê ma Brah Ndu yor khân may, ma lĕ rngôch nau răm maak hên geh yor khân may, ta năp Brah Ndu?$b$,true),
('bunong-vn','1TH',3,10,null,$b$Nar jêh ri măng hên mbơh sơm ma nau duh nđơr ngăn, gay păng ăn hên dơi saơ khân may, jêh ri gay ma ăp moh nau pưt kƀah ma nau khân may chroh.$b$,true),
('bunong-vn','1TH',3,11,null,$b$Ăn Brah Ndu nơm, Mbơ̆ he jêh ri Kôranh Brah he, Brah Yêsu, nkra trong hên dơi hăn ta khân may.$b$,false),
('bunong-vn','1TH',3,12,null,$b$Jêh ri ăn Kôranh Brah sâm n'hao âk lơn tâm phung khân may, jêh ri ma lĕ rngôch, nau rŏng aơ, nâm bu hên rŏng jêh ma khân may,$b$,false),
('bunong-vn','1TH',3,13,null,$b$Pô ri dơi ƀư nâp nuih n'hâm khân may, lơi ăn geh nau nduyh ôh tâm nau kloh ueh ta năp Brah Ndu, Mbơ̆ he, tơ lah Kôranh Brah he, Brah Yêsu, mra văch ndrel ma lĕ rngôch phung kloh ueh Păng.$b$,false),
('bunong-vn','1TH',4,1,null,$b$Pô ri, hơi phung oh nâu, hên vơh vơl jêh ri nchâp khân may tâm Kôranh Brah, Brah Yêsu nâm bu khân may nti jêh bơh hên mâm ƀư khân may mra gŭ ngao krao sach jêh ri ƀư maak ma Brah Ndu, nâm bu khân may hŏ ƀư jêh, ăn khân may ƀư pô nây rlau lơn.$b$,true),
('bunong-vn','1TH',4,2,null,$b$Yor lah khân may gĭt moh nau ntăm hên ăn jêh ma khân may bơh Kôranh Brah Yêsu.$b$,false),
('bunong-vn','1TH',4,3,null,$b$Yor lah pô aơ nau Brah Ndu ŭch, nau khân may jêng kloh ueh, nau khân may dun nau văng tĭr:$b$,false),
('bunong-vn','1TH',4,4,null,$b$Jêh ri ăn ăp nơm khân may blau chiă uănh săk jăn păng tâm nau kloh ueh, jêh ri tâm nau sŏng srăng,$b$,false),
('bunong-vn','1TH',4,5,null,$b$mâu di tông ma nau kơnh ngăn nâm bu phung bu năch mâu gĭt năl Brah Ndu.$b$,false),
('bunong-vn','1TH',4,6,null,$b$Lơi ăn geh bunuyh ndơm mâu lah ƀư tih oh nâu păng tâm nau nây ôh, yor lah Kôranh Brah mra plơng bôk ma lĕ nau nây, nâm bu hên lah jêh ri mbơh jêh ma khân may.$b$,false),
('bunong-vn','1TH',4,7,null,$b$Yor lah Brah Ndu mâu kuăl he ma nau ƀơ̆ ôh, ƀiă lah ma nau kloh ueh.$b$,false),
('bunong-vn','1TH',4,8,null,$b$Pô ri, mbu nơm dun nau ntăm aơ, păng mâu dun bunuyh ôh, ƀiă lah Brah Ndu, nơm ăn jêh ma khân may Brah Huêng Ueh păng.$b$,false),
('bunong-vn','1TH',4,9,null,$b$Bi ma nau rŏng ndrăng oh nâu, khân may mâu hôm ŭch ôh bu nchih ma khân may, yor lah khân may nơm nti jêh bơh Brah Ndu nau tâm rŏng ndrăng khân may.$b$,true),
('bunong-vn','1TH',4,10,null,$b$Jêh ri nanê̆ khân may rŏng ma lĕ rngôch phung oh nâu tâm n'gor Masêđôn. Ƀiă lah, hơi oh nâu, hên vơh vơl ma khân may ăn tâm rŏng âk lơn ƀa ƀơ.$b$,true),
('bunong-vn','1TH',4,11,null,$b$Jêh ri ăn khân may ŭch ngăn gŭ đăp mpăn, mĭn ma kan khân may nơm jêh ri pah kan ma ti khân may nơm nâm bu hên ntăm jêh ma khân may,$b$,false),
('bunong-vn','1TH',4,12,null,$b$gay ma khân may gŭ ngao krao sach sŏng srăng đah phung pa dih, jêh ri mâu rnơm ma bu ôh.$b$,false),
('bunong-vn','1TH',4,13,null,$b$Hơi phung oh nâu, hên mâu ŭch ôh ma khân may mâu gĭt rbăng ma nau phung bêch jêh, ŭch ma khân may lơi rngot, nâm bu phung êng mâu geh nau kâp gân.$b$,true),
('bunong-vn','1TH',4,14,null,$b$Tơ lah he chroh ma Brah Yêsu khĭt jêh ri dâk rêh jêh, ăn he chroh tâm ban lĕ đah Brah Yêsu, Brah Ndu mra njŭn leo phung bêch jêh,$b$,false),
('bunong-vn','1TH',4,15,null,$b$Ma yor lah nau aơ hên mbơh ma khân may tĭng nâm Nau Kôranh Brah Ngơi, ma phung he hôm gŭ rêh tât ta nar Kôranh Brah plơ̆ văch, he mâu mra rlet lor ôh ma phung bêch jêh.$b$,false),
('bunong-vn','1TH',4,16,null,$b$Yor lah Kôranh Brah Nơm mra jŭr bơh trôk geh nau nter toyh, đah bâr kôranh Tông mpăr ueh Brah Ndu, jêh ri đah bâr nŭng Brah Ndu, jêh ri phung khĭt tâm Brah Krist mra dâk rêh lor lơn.$b$,false),
('bunong-vn','1TH',4,17,null,$b$Jêh ta nây phung he, hôm gŭ rêh ta aơ, bu mra chông ndrel đah khân păng tâm ndâr tŭk, tâm mâp đah Kôranh Brah tâm sial ndăng. Pô nây he mra gŭ ndrel ƀa ƀơ đah Kôranh Brah.$b$,true),
('bunong-vn','1TH',4,18,null,$b$Pô ri ăn khân may tâm bonh leng ndrăng khân may đah nau ngơi aơ.$b$,false),
('bunong-vn','1TH',5,1,null,$b$Hơi phung oh nâu, bi ma rnôk jêh ri yan, mâu khlay ôh bu nchih ma khân may.$b$,true),
('bunong-vn','1TH',5,2,null,$b$Yor lah khân may nơm gĭt rah vah jêh ma nar Kôranh Brah mra tât nâm bu du huê nơm ntŭng dôl măng.$b$,false),
('bunong-vn','1TH',5,3,null,$b$Tơ lah phung bunuyh lah: “Đăp mpăn jêh ri mâu hôm klach ôh”, ƀât lât dôl nây ro nau ƀư rai mra tât ma khân păng nâm bu nau ji deh tât ma du huê bu ur ntreo, jêh ri khân păng mâu dơi klaih ôh.$b$,false),
('bunong-vn','1TH',5,4,null,$b$Ƀiă lah, hơi phung oh nâu, khân may mâu gŭ tâm nau ngo ôh, kŏ tât nar nây mra tât ƀư ndrŏt khân may nâm bu du huê nơm ntŭng.$b$,true),
('bunong-vn','1TH',5,5,null,$b$Lĕ rngôch khân may jêng kon nau ang jêh ri kon nar; he mâu jêng kon măng mâu lah ngo ôh.$b$,false),
('bunong-vn','1TH',5,6,null,$b$Lơi ăn he bêch nâm bu phung êng ôh, ƀiă lah ăn he gŭ njrăng jêh ri ăn jêng măt rngăl.$b$,false),
('bunong-vn','1TH',5,7,null,$b$Yor lah mbu nơm bêch, bêch dôl măng, jêh ri mbu nơm nhŭl ndrănh, nhŭl ndrănh dôl măng.$b$,false),
('bunong-vn','1TH',5,8,null,$b$Ƀiă lah he jêng kon nôk nar. Ăn he gŭ rngăl, jêh ri soh ao loih nau chroh, jêh ri ndô đon nau kâp gân ma nau tâm rklaih.$b$,false),
('bunong-vn','1TH',5,9,null,$b$Yor lah Brah Ndu mâu săch he ma nau ji nuih ôh, ƀiă lah ma nau dơi geh nau tâm rklaih tâm Kôranh Brah he, Yêsu Krist.$b$,false),
('bunong-vn','1TH',5,10,null,$b$Păng nơm khĭt jêh ma he, pô ri, gĭt lah, he gŭ njrăng mâu lah bêch jêh, he dơi gŭ rêh ndrel ma Păng.$b$,false),
('bunong-vn','1TH',5,11,null,$b$Pô ri tâm n'hao nuih jêh ri ăn nâp ndrăng khân may nâm bu khân may vay ƀư ƀa ƀơ.$b$,false),
('bunong-vn','1TH',5,12,null,$b$Hơi phung oh nâu, hên dăn ma khân may ăn khân may yơk ma phung gŭ pah kan tâm nklang khân may, jêng phung chiă uănh, phung nti lah khân may tâm kan Kôranh Brah.$b$,true),
('bunong-vn','1TH',5,13,null,$b$Ăn khân may yơk jêh ri rŏng ma khân păng âk ngăn ngên yor kan khân păng pah.$b$,false),
('bunong-vn','1TH',5,14,null,$b$Ăn khân may gŭ đăp mpăn ndrăng khân may nơm hơi oh nâu, ăn khân may lah phung ƀlao kan, nsŭk nsôr phung mâu jo, kơl phung rdja, jêh ri jong nuih đah lĕ rngôch.$b$,true),
('bunong-vn','1TH',5,15,null,$b$Khân may njrăng, lơi ta ăn geh bunuyh mplơ̆ nau mhĭk ma nau mhĭk bu ôh, ƀiă lah rlong nâl joi nau ƀư ueh ƀa ƀơ ndrăng khân may jêh ri ma lĕ rngôch bunuyh.$b$,false),
('bunong-vn','1TH',5,16,null,$b$Gŭ răm ƀa ƀơ,$b$,true),
('bunong-vn','1TH',5,17,null,$b$mbơh sơm mâu rlu,$b$,false),
('bunong-vn','1TH',5,18,null,$b$Kah gĭt tâm rnê ma Brah Ndu tâm lĕ nau tât, yor lah nâm bu pô nây Brah Ndu ŭch khân may ƀư tâm Yêsu Krist.$b$,false),
('bunong-vn','1TH',5,19,null,$b$Lơi ta khân may nhhât Brah Huêng Ueh ôh.$b$,true),
('bunong-vn','1TH',5,20,null,$b$Lơi ta khân may mưch nau bu nti lah ôh.$b$,false),
('bunong-vn','1TH',5,21,null,$b$Rlong sek lĕ nau bu nti, tih mâu lah di, jêh ri djôt prăp moh nau di.$b$,false),
('bunong-vn','1TH',5,22,null,$b$Ăn khân may der lĕ rngôch nau mhĭk.$b$,false),
('bunong-vn','1TH',5,23,null,$b$Ăn Brah Ndu nau đăp mpăn ƀư kloh ueh khân may ăn lam; jêh ri ăn huêng, nuih n'hâm mĭn, jêh ri săk jăn khân may prăp mâu geh nau dơi nduyh kŏ tât, Kôranh Brah he Yêsu Krist mra văch.$b$,true),
('bunong-vn','1TH',5,24,null,$b$Nơm kuăl jêh khân may gŭ răp jăp, jêh ri păng yơh mra ƀư nau nây.$b$,false),
('bunong-vn','1TH',5,25,null,$b$Hơi phung oh nâu mbơh sơm an ma hên ƀă.$b$,true),
('bunong-vn','1TH',5,26,null,$b$Khâl đah lĕ rngôch oh nâu ma nau chŭm kloh.$b$,false),
('bunong-vn','1TH',5,27,null,$b$Ma Kôranh Brah gâp nchâp khân may ăn uănh sămƀŭt aơ ma lĕ rngôch phung oh nâu.$b$,false),
('bunong-vn','1TH',5,28,null,$b$Ăn nau yô̆ bơh Kôranh Brah he, Yêsu Krist, gŭ ndrel đah khân ay may.$b$,true);
insert into public.bible_headings (translation_id, book_code, chapter, before_verse, position, kind, text) values
('bunong-vn','1TH',1,1,0,'heading',$b$Ntŭk Dơn Sămƀŭt Jêh Ri Nau Khâl$b$),
('bunong-vn','1TH',1,2,1,'heading',$b$Phung Têsalônik Dơn Nau Mhe Mhan Ueh Jêh Ri Gŭ Răp Jăp$b$),
('bunong-vn','1TH',2,1,0,'heading',$b$Mâm Ƀư Y-Pôl Pah Kan Tâm Phung Têsalônik$b$),
('bunong-vn','1TH',2,17,1,'heading',$b$Nau Y-Pôl Ŭch Saơ Tay Phung Têsalônik$b$),
('bunong-vn','1TH',3,1,0,'heading',$b$Nau Păng Maak Saơ Tay Y-Timôthê Djôt Nau Mhe Mhan Ueh$b$),
('bunong-vn','1TH',4,1,0,'heading',$b$Nau Nti Ma Nau Kloh Ueh, Ma Nau Rŏng Jêh Ri Ma Nau Pah Kan$b$),
('bunong-vn','1TH',4,13,1,'heading',$b$Nau Phung Khĭt Dâk Rêh Jêh Ri Nau Kôranh Brah Mra Plơ̆ Văch$b$),
('bunong-vn','1TH',5,1,0,'heading',$b$Nar Kôranh Brah Jêh Ri Nau Rngeh Njrăng$b$),
('bunong-vn','1TH',5,12,1,'heading',$b$Nau Nti Êng Êng$b$);
